INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('2e783e1a-db2e-49c8-ae80-a722fbc9e716', 'Rouleaux de poulet avec fromage feta et arugula', 'Rouleau de poulet avec Feta Cheese et Arugulan est un hors-d''oeuvre qui sert 60. Tu regardes ta figure ? Cette recette sans gluten, sans lait, paléolithique et primal contient 18 calories, 3g de protéines et 0g de graisse par portion. Pour 22 cents par portion, cette recette couvre 2 % de vos besoins quotidiens en vitamines et minéraux. Si vous avez des côtes de poulet, de l''huile d''olive, du fromage feta et quelques autres ingrédients à la main, vous pouvez le faire. 2 personnes ont fait cette recette et la feraient à nouveau. Il vous est apporté par Foodista. De la préparation à l''assiette, cette recette prend environ 45 minutes. Dans l''ensemble, cette recette rapporte un score assez mauvais de cuilleraculaire de 19%. Les utilisateurs qui ont aimé cette recette ont aussi aimé Poulet Roll-ups avec fromage à chèvre et arugula, Poulet Roll-ups avec fromage à chèvre et arugula, et Poulet Roll-ups avec fromage à chèvre et arugula.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["cure-dents"], "ingredients": ["chèvre", "roquette", "poulet", "rouleau"], "instruction": "Coucher chaque coupe avec de la roquette; crumble fromage de chèvre au centre. En commençant par l''extrémité étroite, rouler le poulet étroitement; sceller avec un cure-dent.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 1}, "equipment": ["poêle à frire"], "ingredients": ["poulet", "huile de cuisson"], "instruction": "Dans une grande poêle antiadhésive, faire chauffer l''huile à feu moyen-vif; tourner pour enrober le fond de la poêle. Cuire sur le côté, jusqu''à ce qu''il soit doré, de 1 à 2 minutes. Tourne le poulet.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 10}, "equipment": ["poêle à frire", "four"], "ingredients": ["poulet"], "instruction": "Transférer la poêle au four. Cuire jusqu''à ce que le poulet soit opaque, 10 à 12 minutes.", "step_number": 3}, {"duration": null, "equipment": ["cure-dents"], "ingredients": ["poulet"], "instruction": "Retirer les cure-dents et trancher le poulet dans le sens transversal avant de servir, si désiré.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/638288-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.361734', '2026-01-19 18:23:17.361734', '{"vegan": false, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '638288');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('4754ab5f-a0eb-4af5-a889-ffcf8a420e9a', 'Bacon Wrapped Filet Mignon', 'Vous ne pouvez jamais avoir trop de recettes de plat d''appoint, alors essayez Bacon Wrapped Filet Mignon. Cette recette sert 4 et coûte 39 cents par portion. Tu regardes ta figure ? Cette recette sans gluten, sans lait, paléolithique et primal contient 98 calories, 3g de protéines et 9g de graisse par portion. Allez au magasin et prenez du sel et du poivre, du bacon, de l''ail et quelques autres choses pour le faire aujourd''hui. 61 personnes ont fait cette recette et la referaient. De la préparation à l''assiette, cette recette prend environ 45 minutes. Il vous est apporté par Foodista. En tenant compte de tous les facteurs, cette recette gagne un score cuilleré de 13%, ce qui n''est pas si exceptionnel. Les utilisateurs qui ont aimé cette recette ont également aimé Bacon Wrapped Filet Mignon, Bacon Wrapped Filet Mignon et Bacon Wrapped Filet Mignon.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["cure-dents"], "ingredients": ["bacon", "enveloppe"], "instruction": "Placer les filets sur un grand plat et envelopper une tranche de bacon à température ambiante autour de chaque filet, en étirant doucement le bacon si nécessaire. Sécurisez les extrémités du bacon avec un cure-dent.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["sel et poivre", "gousses d''ail entières", "ail", "broyage sec"], "instruction": "Couper les gousses d''ail en deux et frotter les deux côtés de chaque filet avec les extrémités coupées de l''ail. Assaisonner bien avec du sel et du poivre des deux côtés.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 4}, "equipment": ["grille", "pinces"], "ingredients": ["steak"], "instruction": "Préchauffer le gril à très chaud. Avec des pinces, placez chaque steak sur le grill et faites cuire 3-4 minutes à mi-chemin pour obtenir de belles marques de grill.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 4}, "equipment": [], "ingredients": ["steak"], "instruction": "Retournez les steaks et faites cuire encore 3-4 minutes.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 5}, "equipment": ["cure-dents", "grille"], "ingredients": [], "instruction": "Retirer du gril et laisser reposer abondamment couvert pendant 5 minutes avant d''enlever les cure-dents et de servir.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["champignons", "ail"], "instruction": "Servir tel quel ou avec des champignons d''ail salés", "step_number": 6}]', 'https://img.spoonacular.com/recipes/633338-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.290315', '2026-01-19 18:23:17.290315', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '633338');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('cb578284-f2d6-4ed5-9189-cc0e54d0ed71', 'Morceau de pain en croûte', 'Culotte de pain La morue prend environ 45 minutes du début à la fin. Une portion de ce plat contient environ 3g de protéines, 3g de graisses et un total de 94 calories. Cette recette sert 6 $ et coûte 11 cents par portion. Cette recette est appréciée par 1 foodies et cuisiniers. Cette recette de Foodista nécessite de l''huile d''olive, des miettes de pain, du cerveau, du sel et du poivre. C''est une bonne option si vous suivez un régime sans lait et pescatarien. Il fonctionne bien comme un hor d''oeuvre bon marché. Avec un score cuilleraculaire de 42%, ce plat est solide. Si vous aimez cette recette, vous aimerez peut-être aussi des recettes telles que Sole croûte, Tilapie croûte et Clams croûte.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["miettes de pain fraîches", "sel et poivre", "cerveau"], "instruction": "Assaisonner le pain frais miettes avec le cervil, sel et poivre.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Mettez de côté.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["morue", "huile de cuisson", "broyage sec"], "instruction": "Frotter la morue avec de l''huile d''olive.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["sel et poivre"], "instruction": "Assaisonner de sel et de poivre.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["miettes de pain assaisonnées", "morue"], "instruction": "Appuyez seulement sur le côté supérieur de la morue dans les miettes de pain assaisonnées.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "C''est dur à enrober généreusement.", "step_number": 6}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["huile d''olive"], "instruction": "Chauffer une grande poêle antiadhésive sur une poêle moyenne-élevée et ajouter 2 cuillères à soupe d''huile d''olive.", "step_number": 7}, {"duration": {"unit": "minutes", "number": 5}, "equipment": [], "ingredients": ["chapelure", "poisson"], "instruction": "Placer le côté de la chapelure vers le bas, faire revenir le poisson pendant environ 3 à 5 minutes.", "step_number": 8}, {"duration": null, "equipment": [], "ingredients": ["poisson"], "instruction": "Vous verrez le poisson commencer à tourner de cru à un blanc opaque, ce qui vous permet de savoir quand le tourner.", "step_number": 9}, {"duration": {"unit": "minutes", "number": 3}, "equipment": [], "ingredients": ["poisson"], "instruction": "Retournez doucement le poisson et sachez encore 3 minutes.", "step_number": 10}]', 'https://img.spoonacular.com/recipes/635944-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.300241', '2026-01-19 18:23:17.300241', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '635944');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('771de213-e20f-41da-bee7-8cced715e547', 'Lemon Pepper Steak', 'Lemon Pepper Steak est une recette sans gluten, sans lait, paléolithique et primal avec 36 portions. Cet hor d''oeuvre a 35 calories, 3g de protéines et 2g de graisse par portion. Pour 24 cents par portion, cette recette couvre 2 % de vos besoins quotidiens en vitamines et minéraux. Peu de gens ont fait cette recette, et je dirais qu''elle a atteint l''endroit. Il vous est apporté par Foodista. Il peut être apprécié à tout moment, mais il est particulièrement bon pour le jour de valentin. De la préparation à l''assiette, cette recette prend environ 45 minutes. Si vous avez du sel, de l''eau, du jus de citron et quelques autres ingrédients, vous pouvez le faire. Dans l''ensemble, cette recette gagne un très mauvais score (mais encore fixable) cuilleraculaire de 10%. Des recettes similaires comprennent le citron pepper Steak, le citron-pepper Flank Steak Tacos et les enrobes de poulet au citron poivré avec sauce au citron poivré.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 480}, "equipment": ["sacs ziploc"], "ingredients": ["steak de poulet", "jus de citron", "aneth", "marinade", "bœuf", "sel"], "instruction": "Mélanger le jus de citron, le sel et l''herbe d''aneth. Trim tous les gras visibles et placer le steak de bœuf dans un sac ou un plat en plastique; ajouter la marinade, en se tournant vers le manteau. Sachet d''attache solidement ou couvrir le plat et mariner au réfrigérateur 6 à 8 heures ou toute la nuit, en tournant au moins une fois.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["marinade", "poivre", "steak", "viande"], "instruction": "Retirer le steak de la marinade, presser le poivre dans la surface des deux côtés de la viande.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 10}, "equipment": ["poêle à griller"], "ingredients": ["steak"], "instruction": "Déposer le steak sur la poêle à griller et faire griller 10 à 12 minutes de chaque côté. Couper le steak en tranches fines.", "step_number": 3}]', 'https://img.spoonacular.com/recipes/649722-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.304505', '2026-01-19 18:23:17.304505', '{"vegan": false, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '649722');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('f299eae1-eab0-4efd-a03a-676b2168060d', 'Steak avec la sauce au sherry au fromage bleu', 'Steak With Blue Cheese Sherry Sauce est un plat principal sans gluten. Cette recette fait 2 portions avec 368 calories, 37g de protéines et 22g de graisse chacune. Pour 1,76 $ par portion, cette recette couvre 20% de vos besoins quotidiens en vitamines et minéraux. valentin jour sera encore plus spécial avec cette recette. Un mélange de top round, sherry, persil et une poignée d''autres ingrédients sont tout ce qu''il faut pour rendre cette recette si somptueuse. 2 personnes ont été impressionnées par cette recette. De la préparation à l''assiette, cette recette prend environ 45 minutes. Il vous est apporté par Foodista. Dans l''ensemble, cette recette gagne une note super cuilleraculaire de 80%. Des recettes similaires sont Steak avec sauce au fromage bleu brandie, Marinated Flank Steak avec sauce au fromage bleu, et grillé Steak et champignons Kabobs avec sauce au fromage bleu.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"step": 1, "instruction": "<ol><li>Préparer les steaks:</li><li> Couper le steak en deux. Avec un filet de viande ou des steaks de maillet texturés à environ 1/4 pouce d''épaisseur. Réserver et faire la sauce avant de griller.</li><li> Préparer la sauce :</li><li> Combiner Sherry et huile dans une petite casserole. Porter à ébullition et cuire jusqu''à ce que l''alcool ait brûlé.</li><li> Réduire le feu à mijoter et ajouter le fromage bleu; fouetter jusqu''à crème. Retirer du feu et faire griller les steaks.</li><li> Grill Steaks:</li><li> Badigeonner les steaks d''huile d''olive et faire griller 1 minute - 90 secondes de chaque côté.</li><li> Chauffer la sauce et ajouter le persil haché. Verser la sauce sur les steaks et servir.</li></ol>"}]', 'https://img.spoonacular.com/recipes/661522-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.307769', '2026-01-19 18:23:17.307769', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '661522');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('8b5ba05e-5d08-435c-b022-d1226f219b35', 'Pomme Highball', 'Si vous voulez ajouter plus de recettes sans gluten, sans produits laitiers et fodmap à votre répertoire, Apple Highball pourrait être une recette que vous devriez essayer. Cette recette fait 1 portion de 517 calories, 46g de protéines et 13g de graisse chacune. Pour 6,81 $ par portion, cette recette couvre 27 % de vos besoins quotidiens en vitamines et minéraux. Si vous avez de la chaux, des schnaps de pomme, du cognac et quelques autres ingrédients, vous pouvez le faire. De la préparation à l''assiette, cette recette prend environ 45 minutes. Il vous est apporté par l''utilisateur de cuilleraculaire boire. Des recettes similaires sont Apple Or Peach Strudel, Apple Cinnamon Blondies, et Appétissant Apple et Almond Soupe.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["citron vert", "glace", "broyage sec"], "instruction": "Ajouter de la glace dans un verre à haute boule. Frotter un coin de lime fraîche autour du bord et le placer dans le verre.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["ale au gingembre", "schnaps", "pomme", "tir"], "instruction": "Ajoutez un schnaps de pomme, un shot de Courvoisier et ajoutez de l''ale au gingembre.", "step_number": 2}]', 'https://img.spoonacular.com/recipes/1956010-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.310388', '2026-01-19 18:23:17.310388', '{"vegan": false, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '1956010');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('1af5359c-6bd3-4d8b-b50d-89cbb99ea8eb', 'Épinards et Gorgonzola Steak à flancs farcis', 'Épinards et Gorgonzola Stuffed Flank Steak pourrait être juste le cours principal que vous recherchez. Pour 4,27 $ par portion, cette recette couvre 39% de vos besoins quotidiens en vitamines et minéraux. Une portion de ce plat contient environ 47g de protéines, 28g de graisses et un total de 523 calories. Cette recette sert 4. 9 personnes ont trouvé cette recette savoureuse et satisfaisante. Il est parfait pour la journée de valentin. Si vous avez du gorgonzola, de l''huile d''olive, de l''échalote et quelques autres ingrédients, vous pouvez le faire. De la préparation à l''assiette, cette recette prend environ 45 minutes. Il vous est apporté par Foodista. En tenant compte de tous les facteurs, cette recette gagne un score cuilleré de 95 %, ce qui est super. Si vous aimez cette recette, vous aimerez peut-être aussi des recettes telles que les épinards de Bruce Aidells et les steaks de flans farcis de Gorgonzola, les steaks de flans farcis d''épinards et les steaks de flans farcis de carottes.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Préchauffer le four à 37", "step_number": 1}, {"duration": null, "equipment": ["couteau"], "ingredients": ["steak"], "instruction": "Butterfly le steak en utilisant un long couteau tranchant le tenant parallèle à la surface de travail, couper à travers le long côté du steak, s''arrêtant environ de pouce du côté opposé. Si le steak est déjà mince, il suffit de le battre avec un maillet à pouce d''épaisseur.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 2}, "equipment": ["poêle à frire"], "ingredients": ["huile d''olive", "échalote"], "instruction": "Dans une grande poêle à feu moyen, ajouter 1 cuillère à soupe d''huile d''olive et saupoudrer les échalotes jusqu''à ce qu''elles soient tendres, 2 minutes.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 2}, "equipment": [], "ingredients": ["épinard"], "instruction": "Ajouter les épinards et cuire jusqu''à ce qu''ils flétrissent, environ 2 à 3 minutes.", "step_number": 4}, {"duration": null, "equipment": ["colander"], "ingredients": [], "instruction": "Transfert dans une calandre.", "step_number": 5}, {"duration": null, "equipment": ["bol"], "ingredients": ["sel et poivre", "chapelure", "épinard", "fromage"], "instruction": "Lorsque vous êtes assez frais pour manipuler, pressez toute l''humidité des épinards et transférez-les dans un bol moyen. Incorporer les miettes de pain et le fromage. Assaisonner de sel et de poivre.", "step_number": 6}, {"duration": null, "equipment": ["enveloppe plastique"], "ingredients": ["épinard", "steak", "enveloppe"], "instruction": "Placez le steak sur une feuille de plastique. Éplucher le mélange d''épinards uniformément sur le steak, laissant une bordure d''environ 1 pouce le long du bord latéral. En commençant par le côté près de vous et en utilisant l''enveloppe en plastique comme aide, rouler le steak, appuyez doucement sur le remplissage.", "step_number": 7}, {"duration": null, "equipment": ["ficelle de cuisine"], "ingredients": ["steak"], "instruction": "Attachez le steak roulé avec la ficelle à un intervalle de 2-3 pouces.", "step_number": 8}, {"duration": null, "equipment": [], "ingredients": ["sel et poivre"], "instruction": "Assaisonner l''extérieur de sel et de poivre.", "step_number": 9}, {"duration": {"unit": "minutes", "number": 2}, "equipment": ["poêle à frire"], "ingredients": ["huile d''olive"], "instruction": "Chauffer les 2 autres cuillères à soupe d''huile d''olive dans une grande poêle à feu moyen-élevé. Placer le rôti sur tous les côtés, environ 2 minutes de chaque côté.", "step_number": 10}, {"duration": {"unit": "minutes", "number": 20}, "equipment": ["four"], "ingredients": [], "instruction": "Mettre au four et rôtir de 20 à 25 minutes.", "step_number": 11}, {"duration": {"unit": "minutes", "number": 10}, "equipment": ["feuille d''aluminium", "planche à découper"], "ingredients": [], "instruction": "Transférer sur une planche à découper, tendre avec du papier aluminium et laisser reposer 10 minutes.", "step_number": 12}, {"duration": null, "equipment": ["ficelle de cuisine"], "ingredients": [], "instruction": "Pour servir, retirer la ficelle du rôti et couper en tranches de 1 pouce d''épaisseur.", "step_number": 13}]', 'https://img.spoonacular.com/recipes/661259-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.312839', '2026-01-19 18:23:17.312839', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": true}', 'spoonacular', '661259');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('c9d5a5cc-7f01-4ce5-979e-d7f799790ab0', 'Filet Mignan avec sauce au cognac', 'Fichier Mignan Avec Cognac La sauce est peut-être l''hor d''oeuvre que vous recherchez. Cette recette sans gluten, primal, et fodmap amical sert 2 et coûte 2,65 $ par portion. Une portion contient 215 calories, 7g de protéines et 13g de graisse. Si vous avez des steaks de filet de bœuf, des assaisonnements de steak montréal, des oninons et quelques autres ingrédients à la main, vous pouvez le faire. De la préparation à l''assiette, cette recette prend environ 45 minutes. Cette recette est appréciée par 1 foodies et cuisiniers. Il vous est apporté par Foodista. Dans l''ensemble, cette recette gagne une note pas si super cuilleraculaire de 14%. Try Filet Day: Filet Charred de boeuf avec sauce Chili-Corn, sauce canneberge avec Cognac, et Steak avec sauce Cognac et salade pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Chauffer le four à 35", "step_number": 1}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["assaisonnement de steak montreal", "huile de cuisson", "broyage sec"], "instruction": "Utilisez l''assaisonnement Steak de Montréal comme un frottage sec. Dans une poêle en acier, ajouter l''huile et chauffer à feu moyen-élevé.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["steak"], "instruction": "Ajouter les steaks et saisir le haut et le bas jusqu''à un", "step_number": 3}, {"duration": null, "equipment": ["feuille d''aluminium", "poêle à frire"], "ingredients": [], "instruction": "Retirer de la poêle et placer sur une plaque et couvrir d''aluminium.", "step_number": 4}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": [], "instruction": "Retourner la poêle au brûleur à feu moyen.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["oignons verts"], "instruction": "Ajoutez des oignons verts et laissez-les étourdir un moment.", "step_number": 6}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["bouillon de bœuf", "cognac", "sauce"], "instruction": "Verser le bouillon de bœuf et le cognac. En utilisant un wisk de fil, enlever tous les bits du bas de la poêle. Une fois à ébullition, réduire le feu pour réduire la sauce de 1/", "step_number": 7}, {"duration": null, "equipment": [], "ingredients": ["beurre", "steak"], "instruction": "Ajouter le beurre. Faire pivoter les steaks dans les jus avant de servir.", "step_number": 8}, {"duration": null, "equipment": [], "ingredients": ["sauce", "steak", "viande"], "instruction": "Transférer le steak dans l''assiette et la sauce à la cuillère sur la viande.", "step_number": 9}]', 'https://img.spoonacular.com/recipes/642825-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.316125', '2026-01-19 18:23:17.316125', '{"vegan": false, "dairyFree": false, "lowFodmap": true, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '642825');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('f9a1e1ca-1d52-4f25-a1b6-ab8d5f7e1f66', 'Pommes de terre douces farcies de boeuf rôties (choix 30 et PALEO)', 'Besoin d''un plat d''accompagnement sans gluten, sans lait, paléolithique et primal? Pommes de terre douces farcies de boeuf (Whole 30 & PALEO) pourrait être une excellente recette à essayer. Une portion de ce plat contient environ 135g de protéines, 242g de graisses et un total de 3376 calories. Pour 4,24 $ par portion, cette recette couvre 69% de vos besoins quotidiens en vitamines et minéraux. Cette recette sert 5. Allez au magasin et ramassez des patates douces, rôti, bouillon de boeuf, et quelques autres choses pour le faire aujourd''hui. De la préparation à l''assiette, cette recette prend environ 8 heures et 10 minutes. Cette recette de Pink When a 8 fans. Avec un score cuilleré de 62%, ce plat est assez bon. Si vous aimez cette recette, regardez ces recettes similaires : Pommes de terre douces farcies de boeuf (choix 30 et PALEO), Paléo s: Pommes de terre douces farcies de poulet, et Paléo Choisis lentement Boeuf rôti avec citrouille et salsa + Un tour d''horizon de la cuisson lente et GIVEAWAY.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 490, '[{"duration": {"unit": "minutes", "number": 480}, "equipment": ["cuisinière lente"], "ingredients": ["patate douce", "bouillon de bœuf"], "instruction": "Placer le rôti dans le pot à croquer, couvrir de bouillon de boeuf et cuire à feu doux pendant 8 heures. Cuire entièrement les patates douces quand elles sont prêtes. Lorsque le rôti est fini, déchiqueter et servir sur les patates douces.", "step_number": 1}]', 'https://img.spoonacular.com/recipes/1044252-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.319523', '2026-01-19 18:23:17.319523', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": true}', 'spoonacular', '1044252');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('ee94acdb-22ca-4b43-8c5a-cd1845416874', 'Comment faire cuire les patates douces sur le gril', 'Comment faire cuire les patates douces sur le Grill est un plat latéral qui sert 6. Surveiller votre silhouette? Cette recette sans gluten, lacto ovo végétarienne et primal a 175 calories, 2g de protéines et 8g de graisse par portion. Pour 62 cents par portion, cette recette couvre 11 % de vos besoins quotidiens en vitamines et minéraux. Cette recette est appréciée par 2 gourmets et cuisiniers. De la préparation à l''assiette, cette recette prend environ 40 minutes. Si vous avez des patates douces, du beurre, de la cannelle et quelques autres ingrédients à la main, vous pouvez le faire. Elle vous est apportée par Pink When. Avec un score cuilleré de 42%, ce plat est bon. Si vous aimez cette recette, regardez ces recettes similaires : Comment faire cuire les patates douces sur le gril, les patates douces pour le gril et les patates douces cuites au four ou au gril.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 40, '[{"duration": null, "equipment": ["grille"], "ingredients": [], "instruction": "Chauffer la grille à 350 degrés.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["patate douce"], "instruction": "Couper les patates douces en rondelles de 1\".", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["patate douce", "cannelle", "beurre"], "instruction": "Vaporiser les deux côtés des patates douces avec du beurre et saupoudrer de cannelle.", "step_number": 3}, {"duration": null, "equipment": ["feuille d''aluminium"], "ingredients": ["patate douce"], "instruction": "Placer le papier sur les grilles de grillage et placer les patates douces directement sur le papier.", "step_number": 4}, {"duration": null, "equipment": ["feuille d''aluminium"], "ingredients": ["patate douce", "pomme de terre", "beurre"], "instruction": "Vaporisez à nouveau les patates douces avec un peu de beurre. (Pour empêcher les pommes de terre de coller à la feuille)", "step_number": 5}, {"duration": {"unit": "minutes", "number": 40}, "equipment": ["grille"], "ingredients": ["patate douce", "beurre"], "instruction": "Fermez le couvercle et faites cuire environ 30 minutes. Assurez-vous de tourner et de retourner les patates douces toutes les 10 minutes et ajouter des sprays supplémentaires de beurre pour éviter de coller.", "step_number": 6}]', 'https://img.spoonacular.com/recipes/1077392-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.321298', '2026-01-19 18:23:17.321298', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '1077392');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('c464f9ed-7301-45d0-8372-d22004a6bb33', 'Kappa Maki', 'Si vous avez environ 45 minutes à passer dans la cuisine, Kappa Maki pourrait être une recette agréable sans gluten, sans lait, lacto ovo végétarien, et fodmap amical pour essayer. Cette recette fait 8 portions avec 352 calories, 7g de protéines et 1g de graisse chacune. Pour 73 cents par portion, cette recette couvre 8 % de vos besoins quotidiens en vitamines et minéraux. 1 personne a trouvé cette recette délicieuse et satisfaisante. Il fonctionne bien comme un plat latéral. Un mélange de concombre japonais, de nori, de riz sushi et une poignée d''autres ingrédients sont tout ce qu''il faut pour rendre cette recette si délicieuse. Il vous est apporté par Foodista. Dans l''ensemble, cette recette rapporte un score cuilleré solide de 69%. Si vous aimez cette recette, vous aimerez aussi des recettes telles que Kappa Maki (Cucumber Sushi Roll), Live Sigma Kappa – Texas Caviar, et Live Sigma Kappa – Elvis Cookies.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["nori"], "instruction": "Mettez un nori de demi-taille sur un tapis de bambou (makisu).", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["riz sushi", "étendue"], "instruction": "Étaler une demi-tasse de riz sushi sur le dessus.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["concombre", "riz"], "instruction": "Placez les bâtonnets de concombre sur le riz.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["rouleau"], "instruction": "Rouler le tapis de bambou, en appuyant vers l''avant pour former le sushi dans un cylindre. Appuyez fermement sur le tapis de bambou avec les mains. Déballez le tapis de bambou.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["rouleau"], "instruction": "Couper le rouleau de sushi en morceaux.", "step_number": 5}]', 'https://img.spoonacular.com/recipes/648742-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.322506', '2026-01-19 18:23:17.322506', '{"vegan": true, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '648742');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('d9143dc5-5575-46db-90c8-97db3e795574', 'Frises de pommes de terre sucrées au four', 'La recette Baked Sweet Potato Fries pourrait satisfaire votre envie américaine en environ 45 minutes. Cette recette sert 1. Ce plat d''appoint contient 496 calories, 7g de protéines et 12g de graisse par portion. Pour 1,67 $ par portion, cette recette couvre 23 % de vos besoins quotidiens en vitamines et minéraux. 1 personne a été impressionnée par cette recette. Si vous avez de la margarine, des petites patates douces, du sel assaisonné et quelques autres ingrédients, vous pouvez le faire. C''est une bonne option si vous suivez un régime sans gluten, sans lait et 30 régimes entiers. Il vous est apporté par Foodista. Avec un score cuilleré de 89%, ce plat est excellent. Si vous aimez cette recette, vous aimerez peut-être aussi des recettes comme les frites de patate douce cuite, frites de patate douce cuite et frites de patate douce cuite.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["boîte à cuisson"], "ingredients": ["pomme de terre"], "instruction": "Vaporiser une poêle de 15 x 10 x 1 pouce avec un revêtement antiadhésif. Frottez les pommes de terre; coupez en quartiers, puis coupez chaque quart en 2 coins. Disposer les pommes de terre dans une seule couche.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["margarine", "beurre", "muscade", "sel"], "instruction": "Mélanger la margarine ou le beurre, le sel et la muscade.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["pomme de terre"], "instruction": "Badigeonner les pommes de terre.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 20}, "equipment": ["four"], "ingredients": [], "instruction": "Cuire au four 450 20 minutes ou jusqu''à ce qu''il soit brun et tendre.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/633837-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.324139', '2026-01-19 18:23:17.324139', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '633837');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('ac1be587-5af0-4e8b-b9b8-99a18f198df1', 'Nasi Pudina (riz à la menthe)', 'La recette Nasi Pudina ( Riz à la menthe) peut être faite en environ 45 minutes. Une portion contient 457 calories, 8g de protéines et 13g de graisse. Pour 91 cents par portion, cette recette couvre 11 % de vos besoins quotidiens en vitamines et minéraux. Cette recette sert 4. 1 personne a trouvé cette recette délicieuse et satisfaisante. Il fonctionne bien comme un plat latéral. Allez au magasin et ramassez de l''eau, des feuilles de menthe, du lait de coco et quelques autres choses à faire aujourd''hui. Il vous est apporté par Foodista. C''est une bonne option si vous suivez un régime sans gluten, sans lait, lacto ovo végétarienne et fodmap amical. Tout compte fait, nous avons décidé que cette recette mérite un score cuilleré de 49%. Ce score est plutôt bon. Si vous aimez cette recette, regardez ces recettes similaires : Pudina Riz ou menthe Pulao, pudina dal ou menthe dal.Pudina lung dal, et jus de menthe ou sherbet pudina, comment faire du jus de menthe.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["lait de coco", "menthe"], "instruction": "Mélanger les feuilles de menthe au lait de coco jusqu''à ce qu''elles soient lisses.", "step_number": 1}, {"duration": null, "equipment": ["cuisinière de riz"], "ingredients": ["riz"], "instruction": "Verser dans une cuisinière à riz.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["eau", "riz", "sel"], "instruction": "Ajouter le riz, l''eau et le sel.", "step_number": 3}, {"duration": null, "equipment": ["baguettes"], "ingredients": ["riz"], "instruction": "Allumez et une fois le riz cuit. Flatter doucement avec une fourchette/choppicks.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["cacahuètes grillées"], "instruction": "Facultatif: Pour la croûte, saupoudrer d''arachides rôties avant de servir.", "step_number": 5}]', 'https://img.spoonacular.com/recipes/652965-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.32703', '2026-01-19 18:23:17.32703', '{"vegan": true, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '652965');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('deed7459-0429-43e1-a699-91d312769bb9', 'Poudre de riz noir infusée de cardamon avec lait de coco', 'Riz noir infusé de cardamon La pudding avec du lait de coco prend environ 45 minutes du début à la fin. Ce dessert contient 247 calories, 1g de protéines et 7g de graisse par portion. Cette recette sert 4. Pour 87 cents par portion, cette recette couvre 4 % de vos besoins quotidiens en vitamines et minéraux. Cette recette est appréciée par 1 foodies et cuisiniers. Un mélange de riz, de lait de coco, de sel et une poignée d''autres ingrédients sont tout ce qu''il faut pour rendre cette recette si somptueuse. Il vous est apporté par Foodista. C''est une bonne option si vous suivez un régime sans gluten, sans lait, lacto ovo végétarienne et fodmap amical. Compte tenu de tous les facteurs, cette recette gagne une note cuilleraculaire de 19%, ce qui n''est pas si spectaculaire. La pudding de riz au lait de coco, la pudding de riz de lait de coco et le risotto de lait de coco (pouding de riz Arborio) sont très semblables à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Chauffer le four à 300F.", "step_number": 1}, {"duration": null, "equipment": ["processeur alimentaire"], "ingredients": ["grains", "riz"], "instruction": "Mettre le riz dans un robot culinaire et pousser quelques fois pour casser les grains un peu et gratter leurs coques; ne pas trop faire, ou vous allez les pulvériser. Cette étape est très importante.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 30}, "equipment": ["four à hollandaise", "four", "poêle à frire"], "ingredients": [], "instruction": "Mettez tous les ingrédients dans un four à 2 quarts ou un four hollandais. Mélanger quelques fois et mettre la poêle dans le four, couvert. Cuire 30 minutes, puis remuer.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 30}, "equipment": [], "ingredients": ["lait", "riz"], "instruction": "Cuire encore 30 minutes et remuer à nouveau. À ce stade, le lait aura un peu obscurci et devrait être bouillonnant, et le riz aura commencé à gonfler.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 30}, "equipment": [], "ingredients": ["lait", "riz"], "instruction": "Cuire encore 30 minutes. Le lait sera encore plus foncé, et le pudding commencera à ressembler plus au riz qu''au lait. C''est presque fini.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 10}, "equipment": ["four"], "ingredients": [], "instruction": "Retournez le mélange au four et vérifiez toutes les 10 minutes, en remuant doucement chaque fois que vous vérifiez.", "step_number": 6}]', 'https://img.spoonacular.com/recipes/637095-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.329806', '2026-01-19 18:23:17.329806', '{"vegan": true, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '637095');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('2999bbf5-672b-4504-b221-995e8249e213', 'ensemble de recette dosa', 'Vous ne pouvez jamais avoir trop de recettes de plat d''appoint, alors donnez un essai de set dosa. Cette recette sans gluten, sans lait, lacto ovo végétarien et végétalien sert 5 et coûte 82 cents par portion. Une portion de ce plat contient environ 10g de protéines, 15g de graisses et un total de 458 calories. Rendez-vous au magasin et ramassez les graines de fenugrec/ menthu/méthi, l''huile, l''urad dal / minapa pappu, et quelques autres choses pour le faire aujourd''hui. De la préparation à l''assiette, cette recette prend environ 25 minutes. Il vous est apporté par l''utilisateur cuilleraculaire swasthi. Les utilisateurs qui ont aimé cette recette ont aussi aimé Godhuma Dosa – Instant Wheat Dosa.Sabudana dosa.Sago dosa pour rapide, vrat et poha dosan ou atukula dosa, comment faire poha dosa.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 25, '[{"duration": null, "equipment": [], "ingredients": [], "instruction": "Vérifiez les instructions de la recette de l''ensemble dosa", "step_number": 1}]', 'https://img.spoonacular.com/recipes/624304-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.332589', '2026-01-19 18:23:17.332589', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '624304');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('85fb5b9d-0ded-4556-82a5-cdc2f6d54871', 'Sexe dans un verre', 'Vous ne pouvez jamais avoir trop de recettes de plat d''appoint, alors donnez Sex dans un verre un essai. Cette recette sert 6. Une portion de ce plat contient environ 3g de protéines, 29g de graisses et un total de 501 calories. Pour 1,1 $ par portion, cette recette couvre 4 % de vos besoins quotidiens en vitamines et minéraux. 79 personnes ont trouvé cette recette savoureuse et satisfaisante. Cette recette de Foodista nécessite de l''eau, du sucre, du dulce de leche et du sucre. De la préparation à l''assiette, cette recette prend environ 45 minutes. C''est une bonne option si vous suivez un régime végétarien sans gluten et lacto ovo. Dans l''ensemble, cette recette gagne un score cuilleré pas si excellent de 21%. Stained Glass Jello (également connu sous le nom de Broken Glass Jello), mieux que le gâteau sexuel, et mieux que le sexe Le gâteau est très similaire à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["glace", "expresso", "eau"], "instruction": "Pour faire l''espresso porter l''eau à ébullition et puis verser sur l''espresso. Réserver pour refroidir. Lorsque refroidi, ajouter la crème glacée fondue", "step_number": 1}]', 'https://img.spoonacular.com/recipes/659782-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.336093', '2026-01-19 18:23:17.336093', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '659782');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('ba8ebe0d-6106-4cd2-8037-fe71aef34390', 'Panna Cotta Italienne', 'Si vous voulez ajouter plus de recettes sans gluten à votre boîte de recettes, italien Panna Cotta pourrait être une recette que vous devriez essayer. Cette recette sert 4. Ce dessert contient 378 calories, 4g de protéines et 23g de graisses par portion. Pour 68 cents par portion, cette recette couvre 4 % de vos besoins quotidiens en vitamines et minéraux. De la préparation à l''assiette, cette recette prend environ 45 minutes. Cette recette de Foodista a 1 fans. Si vous avez de la sauce caramel, du sucre, du lait et quelques autres ingrédients à la main, vous pouvez le faire. C''est une recette très abordable pour les amateurs de cuisine méditerranéenne. Dans l''ensemble, cette recette rapporte un score assez mauvais de cuilleraculaire de 12%. Des recettes similaires sont la mangue panna cotta, comment faire la mangue végétarienne panna cotta, Ghostly Panna Cottas avec la sauce Ghastly (Panna Cotta avec la sauce canneberge-orange), et Panna Cotta.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 15}, "equipment": ["bol"], "ingredients": ["feuille gélatine", "eau"], "instruction": "Prenez les feuilles de gélatine et adoucissez-les dans un bol d''eau froide pendant environ 15 min.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 15}, "equipment": [], "ingredients": ["crème lourde", "sucre", "lait"], "instruction": "Pendant ce temps chauffer le lait, le sucre et la crème lourde pendant environ 15 min sans l''avoir bouilli!", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Éteignez la chaleur", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["gélatine", "eau"], "instruction": "Prenez la gélatine et pressez l''eau, ajoutez-la au mélange. Bien mélanger jusqu''à ce qu''il se dissolve.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Verser le mélange dans 4 petites formes de panna cotta", "step_number": 5}, {"duration": {"unit": "minutes", "number": 300}, "equipment": [], "ingredients": [], "instruction": "Réfrigérer pendant 4-5 heures.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": ["sauce caramel"], "instruction": "Avant de servir, sortir et ajouter la sauce caramel.", "step_number": 7}]', 'https://img.spoonacular.com/recipes/648183-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.339289', '2026-01-19 18:23:17.339289', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '648183');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('9de1aa92-552c-499a-86a0-7037b96eeb1e', 'Cookie d''éponge de sucre brun avec caramels recouverts de chocolat', 'Si vous avez environ 45 minutes à passer dans la cuisine, Brown Sugar Sponge Cookie avec Caramels Chocolat couvert pourrait être une recette végétarienne super lacto ovo à essayer. Ce dessert contient 50 calories, 1g de protéines et 2g de graisse par portion. Cette recette sert 24. Pour 11 cents par portion, cette recette couvre 1 % de vos besoins quotidiens en vitamines et minéraux. 15 personnes ont essayé et aimé cette recette. Cette recette de Foodista nécessite un extrait de vanille, des rolos, du sucre brun et des œufs. Avec un score cuilleraculaire de 11%, ce plat est plutôt mauvais. Des recettes similaires comprennent le tart de sucre de confiture de fraise recouverte de chocolat, les caramels de sucre brun et les caramels recouverts de chocolat.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["papier à pâtisserie", "plaque de cuisson", "mélangeur de support", "bol", "four"], "ingredients": ["pulvérisateur de cuisson", "blancs d''œufs"], "instruction": "Préchauffer le four à 375 degrés. Étaler les plaques de cuisson avec du papier parchemin et pulvériser avec du pulvérisateur antiadhésif. Dans le bol d''un mélangeur à vitesse moyenne, battre les blancs d''oeufs jusqu''à mousser.", "step_number": 1}, {"duration": null, "equipment": ["plaque de cuisson", "bol"], "ingredients": ["poudre à pâte", "zeste de citron", "blancs d''œufs", "jaune d''œuf", "vanille", "cookies", "farine de tous usages", "sucre", "rolo", "sel", "œuf"], "instruction": "Ajouter la poudre à pâte, le sel et le sucre et continuer à battre à vitesse moyenne jusqu''à ce que des pics raides se forment. Dans un autre bol, mélanger les jaunes d''œufs, la vanille et le zeste de citron, battre avec la fourchette jusqu''à bien mélanger. Pliez les jaunes dans le mélange blanc d''oeufs jusqu''à ce qu''ils soient combinés. Sirotez la farine sur le mélange d''oeufs et repliez-la jusqu''à ce que la pâte soit lisse et légère. Déposer environ 2 cuillères à café de pâte pour chaque biscuit à environ 2 pouces de distance sur des feuilles de cuisson. Remontez chacun avec un Rolo au centre et appuyez légèrement.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 17}, "equipment": ["four"], "ingredients": [], "instruction": "Cuire 12 minutes ou jusqu''à ce qu''il soit doré. Laisser refroidir sur les feuilles pendant 5 minutes, puis passer aux racks pour refroidir complètement.", "step_number": 3}]', 'https://img.spoonacular.com/recipes/636315-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.341687', '2026-01-19 18:23:17.341687', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '636315');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('5e5c4767-761f-4127-ad2c-d27960d7b5e1', 'Banana Split Parfait', 'La recette Banana Split Parfait peut être faite en environ 45 minutes. Cette recette sans gluten sert 3 $ et coûte 26,82 $ par portion. Ce dessert contient 824 calories, 21g de protéines et 55g de graisses par portion. Peu de gens ont fait cette recette, et je dirais qu''elle a atteint l''endroit. Il vous est apporté par Foodista. Un mélange d''arachides, de sirop de caramel, de yaourt et une poignée d''autres ingrédients sont tout ce qu''il faut pour rendre cette recette si délicieuse. Dans l''ensemble, cette recette gagne un score cuilleré solide de 47 %. Essayez Healthy Banana Split Banana Pain, Banana Parfait et Banana Chocolate Parfait pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["bol"], "ingredients": ["extrait de banane", "banane", "yaourt"], "instruction": "Ajouter l''extrait de banane au yogourt; goût pour la saveur de banane souhaitée. Mettez 1/3 tasse de yogourt sur le fond du bol de parfait; ajoutez suffisamment de produits tropicaux Banana Split pour couvrir le yogourt. Répétez la quantité de yogourt sur le dessus et ajoutez plus de Banana Split.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["croustilles de chocolat", "sauce caramel", "cacahuètes", "banane", "yaourt"], "instruction": "Ajoutez des chips de chocolat sur le dessus de Banana Split, puis ajoutez des cacahuètes hachées. Répéter les étapes de yaourt et Banana Split; arroser le sirop de caramel sur le dessus.", "step_number": 2}]', 'https://img.spoonacular.com/recipes/634188-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.344756', '2026-01-19 18:23:17.344756', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '634188');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('65e45baf-a119-4cd5-b292-205783c845f8', 'Browses de pécan caramel facile', 'Easy Caramel Pecan Brownies est un dessert qui sert 12. Une portion de ce plat contient environ 4g de protéines, 19g de graisses et un total de 335 calories. Pour 60 cents par portion, cette recette couvre 6 % de vos besoins quotidiens en vitamines et minéraux. Seulement quelques personnes ont vraiment aimé ce plat américain. 1 personne a fait cette recette et la ferait à nouveau. De la préparation à l''assiette, cette recette prend environ 45 minutes. Si vous avez du beurre, des pécans, un mélange de gâteau au chocolat allemand et quelques autres ingrédients à la main, vous pouvez le faire. Il vous est apporté par Foodista. Avec un score cuilleré de 13%, ce plat n''est pas si spectaculaire. Si vous aimez cette recette, regardez ces recettes similaires : Brownies de caramel, Brownies de caramel et Brownies de caramel.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["bonbons au caramel", "lait"], "instruction": "Faire fondre les caramels avec 1/3 tasse de lait.", "step_number": 1}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["mélange de gâteaux", "beurre", "lait"], "instruction": "Mélanger le mélange de gâteau avec 1/3 tasse de lait et beurre fondu. Presser la moitié du mélange dans une poêle au beurre 9x13.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 8}, "equipment": ["four"], "ingredients": [], "instruction": "Cuire à 350 pendant 5-8 minutes.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["bonbons au caramel", "étendue"], "instruction": "Étendre les caramels fondus sur le dessus.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["croustilles de chocolat", "noix"], "instruction": "Saupoudrer de croustilles et de noix de chocolat.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["étendue"], "instruction": "Étendre le reste du mélange de gâteaux sur le dessus.", "step_number": 6}, {"duration": {"unit": "minutes", "number": 15}, "equipment": ["four"], "ingredients": [], "instruction": "Cuire à 350 pendant 15 minutes.", "step_number": 7}]', 'https://img.spoonacular.com/recipes/641878-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.347681', '2026-01-19 18:23:17.347681', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '641878');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('055f716e-6fa5-4877-b8cd-003814843600', 'Mug de mug d''amande caramel', 'Caramel Almond Mug Cake est une recette végétarienne sans gluten et lacto ovo avec 1 portions. Ce dessert contient 514 calories, 16g de protéines et 24g de graisse par portion. Pour 1,65 $ par portion, cette recette couvre 19 % de vos besoins quotidiens en vitamines et minéraux. 1 personne était heureuse qu''ils aient essayé cette recette. De la préparation à l''assiette, cette recette prend environ 3 minutes. Allez au magasin et ramassez les amandes, la cannelle, le sel, et quelques autres choses pour le faire aujourd''hui. Il vous est apporté par Foodista. Compte tenu de tous les facteurs, cette recette gagne un score cuilleré de 60%, ce qui est assez bon. Banane Mug caramel Cake, Mug caramel chocolat et Mug caramel-fleur de Sel Le gâteau est très similaire à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 3, '[{"duration": null, "equipment": [], "ingredients": ["farine de coco", "cannelle", "sel"], "instruction": "Dans une tasse de 6-8 oz, mélanger la farine de coco, la cannelle et le sel, mélanger avec une fourchette", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["caramel", "œuf"], "instruction": "Ajouter le caramel 2 c. à soupe et l''oeuf, remuer jusqu''à mélanger et sans grumeaux", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["poudre à pâte", "amandes"], "instruction": "Ajouter et mélanger la poudre à pâte et les amandes 1/8 c", "step_number": 3}, {"duration": null, "equipment": ["micro-ondes"], "ingredients": [], "instruction": "Déposer au micro-ondes et cuire à feu moyen-élevé pendant 2 minutes", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["amandes tranchées", "caramel"], "instruction": "Ajouter le reste 2 cbsp caramel et 1/8 c. amandes tranchées", "step_number": 5}]', 'https://img.spoonacular.com/recipes/636971-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.350291', '2026-01-19 18:23:17.350291', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '636971');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('78f0556e-a819-45b9-a19b-efe53e42d0fc', 'Journée Nationale des Hotdog Official Hotdog Cupcakes', 'Oubliez de sortir manger ou commander à emporter chaque fois que vous avez envie de nourriture américaine. Essayez de faire des cupcakes officiels Hotdog à la maison. Une portion contient 206 calories, 1g de protéines et 9g de graisse. Cette recette sert 12 $ et coûte 37 cents par portion. 1 personne était heureuse qu''ils aient essayé cette recette. Elle vous est apportée par Pink When. De la préparation à l''assiette, cette recette prend environ 15 minutes. Si vous avez du fondant brun, de l''extrait de vanille, du sucre de confiserie et quelques autres ingrédients à la main, vous pouvez le faire. Il fonctionne bien comme un dessert. C''est une bonne option si vous suivez un régime végétarien sans gluten et lacto ovo. En tenant compte de tous les facteurs, cette recette gagne un score cuilleré de 9%, ce qui est improvable. Si vous aimez cette recette, vous aimerez peut-être aussi des recettes comme Hotdog Bean Soupe, Grilled Hotdog Skewers With Creamy Avocat Dip, et le français en Flash (Super Bowl): Hotdog Vol-au-Vent.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 15, '[{"duration": null, "equipment": ["plaque de cuisson", "mélangeur de support", "papier cire", "four"], "ingredients": ["bonbons au caramel", "chien chaud", "cupcakes", "glaçage", "hot-dogs", "glaçage du fondant", "ketchup", "moutarde", "vanille", "beurre", "sucre", "lait", "rouleau", "enveloppe", "glace"], "instruction": "Cuire vos cupcakes selon les instructions de l''emballage ou de la recette et leur permettre de refroidir complètement. Dans un mélangeur de stand, battre le sucre, le beurre, le lait et la vanille à vitesse moyenne et augmenter progressivement à haut. Battre jusqu''à ce qu''une consistance semi-droite se forme. Ice chacun de vos cupcakes avec un sac givrant. Étaler une plaque de cuisson avec du papier de cire et commencer à rouler le fondant dans de petites sphères de 1/4 pouce. Puis roulez-les en cylindres avec des extrémités arrondies - ce seront vos \"chauds\". Commencer à pétrir chaque bonbon de caramel et aplatir chacun pour avoir 1 pouce de diamètre - il agira comme votre \"chaud de chien\". Puis, placez votre « hot dog » au centre de vos bonbons au caramel aplatis et enveloppez-le pour ressembler à un hot dog. Décorer le dessus avec du gel rouge et jaune pour ressembler à du ketchup et de la moutarde et placer sur chaque cupcake.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servir à une fête d''été amusante et profiter!", "step_number": 2}]', 'https://img.spoonacular.com/recipes/1017375-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.352691', '2026-01-19 18:23:17.352691', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '1017375');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('28f1b14f-2fd7-4537-a81f-b63915fc50bf', 'Tomates fraîches Mozzarella Salade latérale', 'Tomates fraîches Mozzarella Salade latérale est un plat principal sans gluten, lacto ovo végétarien, primal et cétogène. Pour 1,34 $ par portion, cette recette couvre 9% de vos besoins quotidiens en vitamines et minéraux. Cette recette sert 8. Une portion de ce plat contient environ 13g de protéines, 15g de graisses et un total de 212 calories. 2 personnes ont fait cette recette et la feraient à nouveau. Un mélange de sel casher, de feuilles de basilic, de 6 tomates roma, et une poignée d''autres ingrédients sont tout ce qu''il faut pour rendre cette recette si délicieuse. De la préparation à l''assiette, cette recette prend environ 15 minutes. Il vous est apporté par Foodista. En tenant compte de tous les facteurs, cette recette gagne un score cuilleré de 40%, ce qui n''est pas si génial. Essayez la tomate fraîche Mozzarella Salade latérale, salade de tomates fraîches Mozzarella et tomates fraîches et mozzarella Salade pour recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 15, '[{"duration": null, "equipment": [], "ingredients": ["mozzarella", "tomate"], "instruction": "Couper la mozzarella en tranches de 1/2 pouce. Couper les tomates en tranches. Disposer les tranches alternant la mozzarella et les tomates dans une rangée.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["vinaigre balsamique", "huile d''olive"], "instruction": "Arroser d''huile d''olive puis de vinaigre balsamique", "step_number": 2}, {"duration": null, "equipment": ["couteau"], "ingredients": ["basilic frais", "sel casher", "rouleau"], "instruction": "Saupoudrer d''une pincée de sel Kosher. Piquer 4 feuilles de basilic ensemble à la fois et rouler comme un rondeau. Faire des tranches le long des feuilles roulées en diagonale avec un couteau. Enlevez les feuilles et vous devriez voir des bandes de feuilles de basilic.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["mozzarella", "tomate", "basilic"], "instruction": "Saupoudrer les ficelles de basilic sur les tranches de mozzarella et de tomates.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servir réfrigéré.", "step_number": 5}]', 'https://img.spoonacular.com/recipes/643633-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.355033', '2026-01-19 18:23:17.355033', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '643633');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('aec74389-bfe5-499d-bdd9-9e2fa010ed9d', 'Caprese Sticks', 'Besoin d''un hor d''oeuvre végétarien sans gluten et lacto ovo? Caprese Sticks pourrait être une recette spectaculaire à essayer. Cette recette fait 12 portions de 147 calories, 2g de protéines et 16g de graisse chacune. Pour 40 cents par portion, cette recette couvre 2 % de vos besoins quotidiens en vitamines et minéraux. C''est une recette à prix très raisonnable pour les amateurs de nourriture méditerranéenne. Cette recette est appréciée par 1 foodies et cuisiniers. Si vous avez des pics de cocktail, des tomates cerises, des boules de mozzarella et quelques autres ingrédients à la main, vous pouvez le faire. Il vous est apporté par Foodista. De la préparation à l''assiette, cette recette prend environ 45 minutes. En tenant compte de tous les facteurs, cette recette gagne un score cuilleré de 16%, ce qui est plutôt mauvais. L''insalata caprese all=americana (Salade de Caprese de style américain), les crânes sur bâtonnets et les bâtonnets à biscuits sont très semblables à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["bocconcini", "tomate", "basilic"], "instruction": "Disposer les boules de mozzarella, le basilic et les tomates sur les cocktails, en alternant les trois ingrédients.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["huile d''olive", "sel"], "instruction": "Avant de servir, saler et arroser d''huile d''olive.", "step_number": 2}]', 'https://img.spoonacular.com/recipes/636958-556x370.png', 'PUBLISHED', '2026-01-19 18:23:17.357786', '2026-01-19 18:23:17.357786', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '636958');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('7f11bea1-70b3-40d4-a579-a99b1dfdf279', 'Tomates grillées lentes avec filet d''anchois', 'Savory Slow Roasted Tomatoes avec Filet d''Anchovy pourrait être juste le plat d''appoint que vous recherchez. Cette recette sans gluten, sans lait, paléolithique et primal sert 4 et coûte 83 cents par portion. Une portion de ce plat contient environ 3g de protéines, 15g de graisses et un total de 156 calories. Quelques personnes ont fait cette recette, et 10 diraient qu''elle a atteint l''endroit. Il vous est apporté par Foodista. Si vous avez des tomates rondes, de l''huile d''olive extra vierge, du sel et du poivre, et quelques autres ingrédients à la main, vous pouvez le faire. De la préparation à l''assiette, cette recette prend environ 45 minutes. Avec un score cuilleré de 74%, ce plat est solide. Si vous aimez cette recette, vous aimerez peut-être aussi des recettes comme Savory Slow Roasted Tomatoes avec un filet d''anchois, un filet de boeuf et de parmesan mayonnaise de basilic, et Salade César avec l''ail enrobé d''anchois et Savory Lemon Sabayon.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Préchauffer le four à 150 C ou 280 F", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["tomate"], "instruction": "Couper la 3e partie du dessus des tomates et jeter le dessus.", "step_number": 2}, {"duration": null, "equipment": ["papier à pâtisserie", "boîte à cuisson"], "ingredients": ["tomate"], "instruction": "Placer les tomates sur un plateau de cuisson, doublé de papier parchemin.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["poivre", "herbes", "sel"], "instruction": "Saupoudrer généreusement de sel, poivre et herbes.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["huile d''olive"], "instruction": "Arrosez avec une généreuse quantité d''huile d''olive.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 360}, "equipment": ["four", "poêle à frire"], "ingredients": ["huile d''olive", "tomate"], "instruction": "Déposer au four pendant 4-6 heures selon la taille de vos tomates. De temps en temps, lorsque vous passez la cuisine, déposez les tomates dans les jus et l''huile d''olive dans la poêle.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": ["tomate"], "instruction": "Une fois que les tomates se raclent un peu et commencent à regarder séchées au soleil, elles sont prêtes. Ils devraient toujours tenir leur forme et ne pas devenir musqués.", "step_number": 7}, {"duration": null, "equipment": ["four"], "ingredients": ["anchois", "tomate"], "instruction": "Retirer du four chaque tomate avec un filet entier d''anchois.", "step_number": 8}, {"duration": null, "equipment": ["boîte à cuisson"], "ingredients": ["huile d''olive"], "instruction": "Servir à température chaude ou ambiante avec de l''huile d''olive de la casserole de cuisson arnaquée sur le dessus.", "step_number": 9}]', 'https://img.spoonacular.com/recipes/631757-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.359812', '2026-01-19 18:23:17.359812', '{"vegan": false, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '631757');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('d6fdc5bf-ae56-49eb-94c9-7691ae9da035', 'Grenade à tomates Jambon', 'Vous ne pouvez jamais avoir trop de recettes de condiment, alors donnez une chance à Tomato-Romegranate Jam. Une portion contient 770 calories, 15g de protéines et 3g de graisse. Cette recette sert 2. Pour 2,83 $ par portion, cette recette couvre 44% de vos besoins quotidiens en vitamines et minéraux. De la préparation à l''assiette, cette recette prend environ 45 minutes. Cette recette de Foodista a 2 fans. Si vous avez en conserve des tomates, du poivre, du sel et quelques autres ingrédients à la main, vous pouvez le faire. C''est une bonne option si vous suivez un régime sans gluten, sans lait, lacto ovo végétarienne et fodmap amical. Dans l''ensemble, cette recette gagne un score cuilleré exceptionnel de 85 %. Essayez la confiture de tomates, de grenade et de poire, et la salade de feta de myrtilles de poulet avec la vinaigrette de confiture de grenade pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 60}, "equipment": ["casserole"], "ingredients": [], "instruction": "Mélanger tous les ingrédients dans une grande casserole. Porter à ébullition, puis baisser le feu à feu moyen et laisser mijoter et buller, en remuant souvent, jusqu''à ce qu''il soit épais et embrouillé (environ 1 heure).", "step_number": 1}, {"duration": null, "equipment": ["louche"], "ingredients": ["confiture"], "instruction": "Laisser refroidir et déposer dans un pot de 1 litre. La confiture se conservera 2 semaines au réfrigérateur.", "step_number": 2}]', 'https://img.spoonacular.com/recipes/663652-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.363889', '2026-01-19 18:23:17.363889', '{"vegan": true, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '663652');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('6c66dcdc-17f5-41ff-8523-ad39eca79d03', 'Salade de tomates vertes', 'Si vous voulez ajouter plus de recettes végétariennes sans gluten, sans lait, paléolithique et lacto ovo à votre boîte de recettes, Salade de tomate verte peut être une recette que vous devriez essayer. Cette recette sert 1 $ et coûte 1,85 $ par portion. Ce plat d''appoint contient 180 calories, 3g de protéines et 15g de graisse par portion. Allez au magasin et ramassez les feuilles de sauge et de menthe, l''huile d''olive, la poudre de sumac, et quelques autres choses pour le faire aujourd''hui. 1 personne a essayé et aimé cette recette. De la préparation à l''assiette, cette recette prend environ 45 minutes. Il vous est apporté par Foodista. En tenant compte de tous les facteurs, cette recette gagne un score cuilleraculaire de 79%, qui est solide. Essayez la salade de haricots et de tomates verts avec la vinaigrette torréfié-tomato, la salade de tomates vertes en conserve et la salade de tomates vertes de haricots pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["tomate"], "instruction": "Couper la tomate en petits disques ronds.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["sauge", "menthe", "rouleau"], "instruction": "Rouler la menthe et la sauge laisse dans une balle serrée et la hacher finement.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["huile d''olive", "sumac"], "instruction": "Ajouter à l''huile d''olive et au sumac pour faire une vinaigrette.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["tranches de tomates"], "instruction": "Arroser les tranches de tomates", "step_number": 4}]', 'https://img.spoonacular.com/recipes/645555-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.366037', '2026-01-19 18:23:17.366037', '{"vegan": true, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": true, "veryHealthy": true}', 'spoonacular', '645555');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('c28765d0-0e1f-4482-a5f6-f538f14d1c04', 'Figurines grillées avec Brie et Prosciutto', 'La recette Grilled Figs With Brie et Prosciutto peut être faite en environ 45 minutes. Cette recette fait 1 portion avec 111 calories, 2g de protéines et 4g de graisse chacune. Pour 1,61 $ par portion, cette recette couvre 4% de vos besoins quotidiens en vitamines et minéraux. Il vous est apporté par Foodista. 1 personne était heureuse qu''ils aient essayé cette recette. Il peut être apprécié à tout moment, mais il est particulièrement bon pour le Quatrième de Juillet. Peu de gens ont vraiment aimé ce plat. C''est une bonne option si vous suivez un régime sans gluten et primal. Allez au magasin et ramassez des figues, du fromage brie, du prosciutto, et quelques autres choses à faire aujourd''hui. En tenant compte de tous les facteurs, cette recette gagne un score cuilleré de 16%, ce qui n''est pas si spectaculaire. Des recettes similaires sont grillées Brie avec Figs & Thyme Honey, GRILLED FIGS, PROSCUITTO et BURRATA, et grillées Figs avec fromage de chèvre et Prosciutto.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["brochettes en bois"], "ingredients": [], "instruction": "Si vous utilisez des brochettes en bois, trempez-les pendant au moins une heure.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["brie", "figues"], "instruction": "Couper chaque figues en deux, puis placer un carré de brie sur le dessus.", "step_number": 2}, {"duration": null, "equipment": ["brochettes"], "ingredients": ["prosciutto", "fromage", "enveloppe", "figues"], "instruction": "Enveloppez une tranche de prosciutto autour du fromage, de la figues et de la brochette.", "step_number": 3}, {"duration": null, "equipment": ["grille"], "ingredients": ["poisson"], "instruction": "Si vous utilisez un grill extérieur, un grill de poisson est recommandé (un avec de petits trous).", "step_number": 4}, {"duration": null, "equipment": ["grille"], "ingredients": [], "instruction": "Un grill intérieur fonctionne bien aussi.", "step_number": 5}]', 'https://img.spoonacular.com/recipes/645708-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.36768', '2026-01-19 18:23:17.36768', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '645708');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('5e0628a2-1f42-4db0-9be8-b01ea58409df', 'Salade de céleri, d''orange et de maquereau fumé', 'Besoin d''un plat sans gluten, sans lait, entier 30 et pescatarien principal? Salade de céleri, d''orange et de maquereau fumé pourrait être une excellente recette à essayer. Une portion contient 460 calories, 36g de protéines et 28g de graisse. Pour 2,75 $ par portion, cette recette couvre 34% de vos besoins quotidiens en vitamines et minéraux. 1 personne a fait cette recette et la ferait à nouveau. Il vous est apporté par Foodista. De la préparation à l''assiette, cette recette prend environ 45 minutes. Un mélange d''orange, d''huile de colza, de céleri et une poignée d''autres ingrédients sont tout ce qu''il faut pour rendre cette recette si délicieuse. Dans l''ensemble, cette recette gagne une bonne note cuilleraculaire de 82%. Les utilisateurs qui ont aimé cette recette ont aussi aimé Salade de céleri, d''orange et de maquereau fumé, de maquereau fumé, de salade d''orange et de couscous, et de nouvelle pomme de terre chaude et salade de maquereau fumé.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["bol"], "ingredients": ["tranches d''orange", "orange", "jus"], "instruction": "Couper le dessus et le bas de l''orange, puis couper soigneusement l''épluchage, couper de haut en bas, essayer de ne pas couper trop de chair, recueillir n''importe quel jus dans un bol, puis couper les segments d''orange couper de chaque côté de la membrane, presser la membrane restante sur le bol et recueillir n''importe quel jus.", "step_number": 1}, {"duration": null, "equipment": ["fouet"], "ingredients": ["tranches d''orange", "sel et poivre", "maquereau", "céleri", "jus", "huile de cuisson"], "instruction": "Ajouter l''huile au jus et fouetter ensemble, ajouter les segments orange, le céleri, le maquereau et le sel et le poivre, combiner avec une fourchette, manger immédiatement.", "step_number": 2}]', 'https://img.spoonacular.com/recipes/637357-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.369403', '2026-01-19 18:23:17.369403', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '637357');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('8ef9951a-dcb2-45e9-81ff-058dae7b3642', 'Céleri & Ginger Jus', 'Céleri & Ginger Le jus pourrait être juste sans gluten, sans lait, lacto ovo végétarien, et la recette végétalienne que vous avez cherché. Pour 31 cents par portion, cette recette couvre 2 % de vos besoins quotidiens en vitamines et minéraux. Cette boisson contient 154 calories, 0g de protéines et 0g de graisse par portion. Cette recette sert 2. Peu de gens ont fait cette recette, et je dirais qu''elle a atteint l''endroit. Cette recette de Foodista nécessite du céleri, de l''eau, du gingembre et environ 2 jus de lime. De la préparation à l''assiette, cette recette prend environ 45 minutes. Compte tenu de tous les facteurs, cette recette gagne un score cuilleré de 12%, ce qui est plutôt mauvais. Jus de Celery Ginger, Jus de Celery-Apple-Kiwi avec Ginger et Jus de Celery-Apple-Kiwi avec Ginger sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["mélangeur", "jus de fruits"], "ingredients": ["céleri", "gingembre", "jus", "eau"], "instruction": "Mélanger le céleri et le gingembre avec de l''eau dans un mélangeur ou un jus de fruits. Retirez le jus.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["jus de chaux", "citron vert"], "instruction": "Ajouter le jus de chaux (j''ai utilisé deux chaux clés)", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["miel", "sucre"], "instruction": "Mélanger le miel ou le sucre.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Bien mélanger.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/637344-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.371736', '2026-01-19 18:23:17.371736', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '637344');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('8336f96f-746e-42ff-9268-42004ac62afd', 'Stir Fried Cabbage et tomates', 'Stir Fried Cabbage and Tomatoes est une recette sans gluten, sans lait, lacto ovo végétarien, et végétalien avec 2 portions. Une portion de ce plat contient environ 4g de protéines, 0g de graisse et un total de 96 calories. Pour 81 cents par portion, cette recette couvre 18 % de vos besoins quotidiens en vitamines et minéraux. Ça marche bien comme un hor d''oeuvre. 6 personnes ont essayé et aimé cette recette. Allez au magasin et ramassez du sel, des tomates, des gants d''ail, et quelques autres choses pour le faire aujourd''hui. Il vous est apporté par Foodista. De la préparation à l''assiette, cette recette prend environ 45 minutes. Tout compte fait, nous avons décidé que cette recette mérite un score cuilleré de 90%. Ce score est exceptionnel. Chabage Thoran (Kerala Style Stir-Fried Cabbage), Pan-Fried Striped Bass avec Stir-Fried Tomatoes et Dill, et Stir-Fried Cabbage sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["choux"], "instruction": "Déchiqueter grossièrement le chou et bien rincer.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Égoutter et réserver.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["tomate"], "instruction": "Rincer les tomates et les dés, réserver.", "step_number": 3}, {"duration": null, "equipment": ["wok"], "ingredients": ["choux", "ail", "eau", "huile de cuisson"], "instruction": "Chauffer le wok avec un peu d''huile pour faire revenir l''ail. Mettre le chou et cuire jusqu''à tendreté, ajouter un peu d''eau si nécessaire.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["assaisonnement", "tomate", "eau"], "instruction": "Ajouter les tomates en dés et assaisonner avec 2-3 cuillères à soupe d''eau. Mélanger et servir immédiatement.", "step_number": 5}]', 'https://img.spoonacular.com/recipes/661653-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.373904', '2026-01-19 18:23:17.373904', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '661653');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('c301cc47-7554-424f-b867-ef2f88c36d9e', 'Farine d''avoine de nuit', 'Si vous voulez ajouter plus de recettes végétariennes sans gluten et lacto ovo à votre boîte de recettes, Overnight Oatmeal pourrait être une recette que vous devriez essayer. Cette recette sert 4 $ et coûte 1,42 $ par portion. Une portion de ce plat contient environ 9g de protéines, 7g de graisses et un total de 380 calories. Il vous est apporté par Foodista. Seulement quelques personnes ont vraiment aimé ce petit déjeuner. De la préparation à l''assiette, cette recette prend environ 45 minutes. Allez au magasin et ramassez des canneberges, de l''eau, la moitié, et quelques autres choses pour le faire aujourd''hui. 3 personnes ont été impressionnées par cette recette. En tenant compte de tous les facteurs, cette recette gagne un score cuilleraculaire de 32%, ce qui est plutôt mauvais. Les utilisateurs qui ont aimé cette recette ont également aimé Clean Eating Cookie Overnight Oatmeal, Clean Eating Cookie Overnight Oatmeal et Clean Eating Cookie Overnight Oatmeal.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 540}, "equipment": ["bol", "pot"], "ingredients": ["farine d''avoine"], "instruction": "Dans une cruche, mélanger tous les ingrédients et mettre à feu. Couvrir et laisser cuire pendant 8 à 9 heures. Incorporer et retirer dans les bols. Cette méthode fonctionne mieux si elle a commencé avant d''aller au lit. Ainsi, votre farine d''avoine sera finie demain matin. Cette recette produit 4 portions.", "step_number": 1}]', 'https://img.spoonacular.com/recipes/654271-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.376646', '2026-01-19 18:23:17.376646', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '654271');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('88095d54-582e-4122-a8c4-1ecef880cee5', 'Pamplemousses roses Griffe', 'Pamplemousses roses Slaw est un plat végétarien sans gluten, sans lait et lacto ovo. Cette recette fait 4 portions avec 90 calories, 2g de protéines et 3g de graisse chacune. Pour 51 cents par portion, cette recette couvre 9% de vos besoins quotidiens en vitamines et minéraux. Cette recette de Foodista nécessite du sel ou, de l''oignon, du chou et de la mayonnaise. Le Quatrième De Juillet sera encore plus spécial avec cette recette. Seulement quelques personnes ont fait cette recette, et 3 disent qu''elle a atteint l''endroit. De la préparation à l''assiette, cette recette prend environ 45 minutes. Tout compte fait, nous avons décidé que cette recette mérite un score cuilleré de 61%. Ce score est solide. Les utilisateurs qui ont aimé cette recette ont également aimé les cupcakes de pamplemousse rose avec le fromage à la crème de pamplemousse rose, Margaritas de pamplemousse rose et le sorbet de pamplemousse rose.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["tasse de mesure", "fouet", "bol"], "ingredients": ["jus de pamplemousse", "zeste de pamplemousse", "pamplemousses", "mayonnaise", "choux", "poivre", "oignon", "sucre", "sel"], "instruction": "Dans un petit bol ou une tasse à mesurer, mélanger la mayonnaise, 3 cuillères à soupe de jus de pamplemousse frais (à partir d''un seul segment ou deux), le sucre, 1 c. à soupe de zeste de pamplemousse, le sel et le poivre; fouetter pour mélanger. Dans un grand bol, mélanger les morceaux de chou, de pamplemousse de ce qui reste du pamplemousse et de l''oignon; habiller et mélanger pour enrober.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["persil"], "instruction": "Garnir de persil, si désiré, et servir immédiatement.", "step_number": 2}]', 'https://img.spoonacular.com/recipes/656227-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.378821', '2026-01-19 18:23:17.378821', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '656227');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('b1b8d3fa-42cd-4211-a318-9ea9aa6390c2', 'Barres de protéines simples et entièrement naturelles', 'Protéines simples et naturelles Bars est une recette végétarienne sans gluten, sans lait, paléolithique et lacto ovo avec 6 portions. Pour 99 cents par portion, cette recette couvre 10 % de vos besoins quotidiens en vitamines et minéraux. Une portion contient 241 calories, 8g de protéines et 13g de graisse. Si vous avez des amandes, des dattes, de la poudre de protéines de chanvre et quelques autres ingrédients à la main, vous pouvez le faire. Il fonctionne bien comme un plat latéral. De la préparation à l''assiette, cette recette prend environ 15 minutes. Il vous est apporté par cuilleraculaire user de haricots café. Des recettes similaires sont des aliments naturels pour bébés : des bâtonnets de chou-fleur, des barres de Brownie aux protéines puissantes et des barres d''avoine aux protéines de banane de citrouille.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 15, '[{"duration": null, "equipment": [], "ingredients": [], "instruction": "Processus simple", "step_number": 1}, {"duration": null, "equipment": ["processeur alimentaire", "mélangeur"], "ingredients": ["amandes", "noix"], "instruction": "Traiter les amandes (ou autres noix) dans un robot culinaire ou un mélangeur à grande vitesse. Vous n''avez pas besoin d''une poudre fine, mais si les morceaux d''amande sont", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "trop grande, il peut être difficile d''empêcher les barres de s''effondrer.", "step_number": 3}, {"duration": null, "equipment": ["mélangeur"], "ingredients": ["fruits secs", "dates", "figues"], "instruction": "Ajouter les figues, les dattes ou un autre fruit séché humide et les mélanger uniformément. Vous pourriez avoir besoin de gratter les côtés de votre mélangeur quelques fois.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["noix de coco déchiquetées", "croustilles de chocolat", "poudre de protéines"], "instruction": "Ajouter tous les mélanges que vous désirez (noix de coco, croustilles de chocolat, poudre de protéines, etc.) Veillez à ne pas faire le mélange mouillé ou trop sec. Si", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["eau"], "instruction": "nécessaire, vous pouvez ajouter un peu d''eau pour aider à se fondre. Déposer le mélange sur une surface plane et former vos barres. A conserver au réfrigérateur ou au congélateur. Bon appétit ! C''est tout", "step_number": 6}]', 'https://img.spoonacular.com/recipes/149199-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.381724', '2026-01-19 18:23:17.381724', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '149199');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('abfae642-2fbf-45d2-94bc-0b06c57fe5dd', 'Suisse Bircher Muesli', 'Swiss Bircher Muesli pourrait être une bonne recette pour élargir votre boîte de recettes petit déjeuner. Cette recette végétarienne lacto ovo sert 1 et coûte 1,31 $ par portion. Une portion contient 363 calories, 12g de protéines et 7g de graisse. 1 personne a fait cette recette et la ferait à nouveau. De la préparation à l''assiette, cette recette prend environ 45 minutes. Cette recette de Foodista nécessite des yaourts de pommes, de lait, de muesli et de vanille. Dans l''ensemble, cette recette gagne un excellent score cuilleré de 84%. Si vous aimez cette recette, vous aimerez aussi des recettes comme Bircher Muesli, Bircher Muesli et Bircher Muesli.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["bol"], "ingredients": ["muesli"], "instruction": "Mettre Muesli dans un bol", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["yaourt", "muesli", "lait"], "instruction": "Verser le lait pour couvrir le muesli et mélanger au yaourt", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Couvrir et réfigerer pendant quelques heures ou pendant la nuit", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["muesli", "pomme", "lait"], "instruction": "Quand prêt à manger, si le mélange est trop épais, desserrer avec le lait. Gratter la pomme et mélanger le muesli", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Mangez", "step_number": 5}]', 'https://img.spoonacular.com/recipes/662665-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.383144', '2026-01-19 18:23:17.383144', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '662665');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('df52d678-5ba0-4ab7-96e8-2c98f9327e34', 'Petit déjeuner rouge sur un croissant', 'Vous ne pouvez jamais avoir trop de recettes de petit déjeuner, alors donnez Redneck Breakfast sur un croissant un essai. Pour 1,56 $ par portion, cette recette couvre 12 % de vos besoins quotidiens en vitamines et minéraux. Une portion de ce plat contient environ 14g de protéines, 22g de graisses et un total de 368 calories. Cette recette de Foodista nécessite sel et poivre casher, haschisch de bœuf corné, oeuf et beurre. 1 personne a été impressionnée par cette recette. De la préparation à l''assiette, cette recette prend environ 45 minutes. En tenant compte de tous les facteurs, cette recette gagne un score cuilleré de 31%, ce qui est plutôt mauvais. Des recettes similaires incluent Redneck Breakfast on a croissant, Holiday Breakfast: Ham-and-Cheese Croissant Breakfast Casserole, et croissant Breakfast Casserole.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["croissant", "pain sandwich"], "instruction": "Séparer le croissant en deux et porter un toast.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 6}, "equipment": ["spatule", "poêle à frire"], "ingredients": ["boeuf corné", "puces", "marronneries"], "instruction": "Chauffer une poêle sans bâton à feu moyen-élevé, ajouter le haschisch corné. Cuire l''a jusqu''à ce qu''il soit brun et croustillant d''un côté (3 à 5 minutes), puis retourner avec un tourneur et cuire l''autre côté jusqu''à ce qu''il soit croustillant et brun, un autre 3 à 5 minutes. Remarque: Alors que la cuisson a poussé ensemble et l''aplatir ainsi il rend un peu patty, il est beaucoup plus facile de retourner et servir ainsi.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["boeuf corné", "croissant", "marronneries"], "instruction": "Placez le haschty corné sur la moitié inférieure du croissant grillé.", "step_number": 3}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["beurre", "œuf"], "instruction": "Dans la même casserole, faire fondre le beurre et ajouter l''œuf, faire frire selon le goût.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["sel et poivre", "boeuf corné", "croissant", "fromage", "marronneries", "œuf"], "instruction": "Saupoudrer l''œuf d''un peu de sel et de poivre et placer sur le haschty corné. Sur le côté supérieur du croissant, pressez une couche de fromage en conserve dessus.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Placer la couche supérieure sur la moitié inférieure.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servir immédiatement.", "step_number": 7}]', 'https://img.spoonacular.com/recipes/658134-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.385128', '2026-01-19 18:23:17.385128', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '658134');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('0cd2a758-c9a5-43f0-a1bc-e4306a13661f', 'Des croissants français aux fraises', 'French Toast croissants avec fraises est un petit-déjeuner américain. Pour 2,63 $ par portion, cette recette couvre 17 % de vos besoins quotidiens en vitamines et minéraux. Une portion contient 657 calories, 9g de protéines et 49g de graisses. Cette recette sert 4. 11 personnes ont fait cette recette et la ferait à nouveau. Un mélange d''écorce d''orange, de sucre en poudre, de lait et une poignée d''autres ingrédients sont tout ce qu''il faut pour rendre cette recette si savoureuse. Il vous est apporté par Foodista. De la préparation à l''assiette, cette recette prend environ 20 minutes. Dans l''ensemble, cette recette gagne une bonne note cuilleraculaire de 48 %. Parmi les recettes similaires, mentionnons le toast français aux fraises et crèmes, les fraises et crèmes au toast français, et le pain au citron aux fraises fraîches.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 20, '[{"duration": {"unit": "minutes", "number": 1}, "equipment": ["poêle à frire", "forme de tarte", "mélangeur", "bol"], "ingredients": ["zeste d''orange", "croissant", "beurre", "orange", "œuf", "lait", "trempette"], "instruction": "Dans un petit bol mélangeur, battre tous les ingrédients du beurre d''orange à vitesse moyenne, racler souvent le bol jusqu''à ce qu''il soit léger et moelleux (1 à 2 minutes); réserver. Dans la poêle à tarte, mélanger le lait, les œufs et 1 cuillère à café d''orange. Dans une poêle de 10 pouces ou une grille, faire fondre 2 cuillères à soupe de beurre à feu moyen. Tremper 4 croissants de moitié en mélange d''oeufs, en tournant pour enrober les deux côtés.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 3}, "equipment": ["poêle à frire"], "ingredients": ["croissant"], "instruction": "Placer les moitiés de croissant, couper le côté vers le bas, dans la poêle. Cuire, tourner une fois, jusqu''à ce qu''il soit doré (3 à 4 minutes de chaque côté).", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["sucre en poudre", "croissant", "beurre", "orange"], "instruction": "Retirer pour servir le plateau; garder au chaud. Répéter avec 2 cuillères à soupe de beurre et 4 moitiés de croissant. Dust croissant moitiés avec du sucre en poudre; servir avec du beurre orange.", "step_number": 3}]', 'https://img.spoonacular.com/recipes/643405-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.387469', '2026-01-19 18:23:17.387469', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '643405');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('f11f0a4f-49e9-4c9a-8a8a-c5a8a046387a', 'Porridge de quinoa avec sauce aux pommes, Skyr et Muesli grillé au miel', 'Quinoa Porridge avec pommeau, Skyr et miel Toasted Muesli est un petit déjeuner végétarien lacto ovo. Cette recette sert 2 $ et coûte 5,36 $ par portion. Une portion de ce plat contient environ 19g de protéines, 12g de graisses et un total de 702 calories. 1 personne a fait cette recette et la ferait à nouveau. Cette recette de Foodista nécessite des pommes, de l''eau, des graines de gousses de vanille et des céréales de muesli. De la préparation à l''assiette, cette recette prend environ 45 minutes. Avec un score cuilleré de 84%, ce plat est super. Les recettes similaires comprennent le Muesli d''érable grillé, le Muesli de noix de coco grillé et le Muesli de noix de coco grillé.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["casserole", "poêle à frire"], "ingredients": ["vanille", "pomme", "quinoa", "miel", "graines", "pain sandwich", "eau"], "instruction": "Peler les pommes et les couper en petits morceaux. Cuire les pommes dans une casserole avec un peu d''eau et de graines de vanille jusqu''à ce que vous ayez une purée grossière. Réserver pour refroidir. Servir le msli dans une poêle sèche avec du miel jusqu''à ce qu''il soit doré. Réserver pour refroidir. Rincez bien le quinoa.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 15}, "equipment": ["casserole", "bol"], "ingredients": ["poudre de vanille", "crème fraîche", "muesli", "quinoa", "pomme", "lait"], "instruction": "Ajouter le quinoa dans une casserole avec le lait et la poudre de vanille et laisser mijoter environ. 15 minutes jusqu''à ce que le quinoa soit cuit et que le lait soit absorbé. Disposer la guinoa dans un bol et garnir de pommes, de crème sure et de muesli. Bon appétit !", "step_number": 2}]', 'https://img.spoonacular.com/recipes/657674-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.390604', '2026-01-19 18:23:17.390604', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '657674');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('5517856d-2f9b-4134-9fbd-8a8bb8070b57', 'Gingembre de gingembre avec garniture de pêche à la cannelle', 'La recette Gingerbread Gaufres Avec Cinnamon Peach Topping peut être faite en environ 45 minutes. Pour 1,21 $ par portion, cette recette couvre 9% de vos besoins quotidiens en vitamines et minéraux. Une portion contient 281 calories, 5g de protéines et 16g de graisse. Cette recette sert 8. Noël sera encore plus spécial avec cette recette. Cette recette est appréciée par 1 foodies et cuisiniers. Si vous avez des pêches, du sucre, des gaufres de pain d''épice et quelques autres ingrédients à la main, vous pouvez le faire. Il fonctionne bien comme un petit déjeuner économique amical. Il vous est apporté par Foodista. En tenant compte de tous les facteurs, cette recette gagne un score cuilleré de 35%, ce qui est plutôt mauvais. Gingembre de gingembre avec garniture de pêche à la cannelle, gingembre de gingembre avec garniture de pomme à la cannelle et gâteau à l''amande de pêche à la cannelle La garniture est très similaire à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["cannelle", "pêche", "sirop"], "instruction": "Pêches à la cannelle avec sirop", "step_number": 1}, {"duration": null, "equipment": ["enveloppe plastique", "micro-ondes", "bol"], "ingredients": ["sirop d''érable", "cannelle", "pêche", "sucre", "enveloppe", "pop"], "instruction": "Mélanger les pêches congelées, la cannelle et le sucre dans un bol. Couvrir le bol dans un emballage en plastique et laisser reposer au réfrigérateur pendant la nuit. Les pêches congelées fonctionnent le mieux avec cela en raison de leur texture plus douce qu''elles atteignent pendant le processus de congélation. Si vous n''avez pas le temps de laisser cette macérer pendant la nuit, faites-la sauter au micro-ondes et zappez-la pendant 20 secondes, remuez jusqu''à obtenir la texture désirée. Macering ces nuit créera le liquide brun le plus délicieux qui dépassera tout sirop d''érable que vous aurez jamais. Gingembre à pain", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Ça fait 8 gaufres.", "step_number": 3}, {"duration": null, "equipment": ["fer à gaufres"], "ingredients": [], "instruction": "Chauffer votre gaufrier belge.", "step_number": 4}, {"duration": null, "equipment": ["bol"], "ingredients": ["poudre à pâte", "margarine", "épices", "farine de tous usages", "sucre"], "instruction": "Mélanger la farine, le sucre, la poudre à pâte, les épices dans un bol. Verser la cuillère à soupe de margarine par cuillère à soupe dans le mélange de farine.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["crème fraîche", "mélasse", "œuf", "lait"], "instruction": "Ajouter les œufs, la mélasse, le lait et la crème aigre.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Mélanger soigneusement jusqu''à ce que toutes les bosses soient parties mais ne pas trop mélanger.", "step_number": 7}, {"duration": null, "equipment": ["fer à gaufres"], "ingredients": [], "instruction": "Ajoutez une partie du mélange à votre fabricant de gaufres. Environ 1/2 tasse. Cuire jusqu''à ce que ce soit le croustillant désiré.", "step_number": 8}, {"duration": null, "equipment": ["serviettes en papier"], "ingredients": [], "instruction": "Coucher les gaufres entre les serviettes en papier pour les empêcher de se faire ensanglanter.", "step_number": 9}, {"duration": null, "equipment": [], "ingredients": ["girofle du sol", "muscade", "margarine", "cannelle", "mélasse", "beurre", "pêche", "sirop"], "instruction": "Servir avec une partie de la pêche à la cannelle et la garniture de sirop. Bon appétit ! Si vous voulez ces épicés, ajoutez plus de muscade et de gousses de terre. Si vous voulez qu''il soit plus sombre, ajoutez plus de mélasses. Si vous le voulez plus croustillant, remplacez la margarine douce par du beurre fondu.", "step_number": 10}]', 'https://img.spoonacular.com/recipes/644699-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.39389', '2026-01-19 18:23:17.39389', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '644699');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('77d5e8ce-d155-45f1-b6c6-e3d7f2dbeea4', 'Toast français croissant aux bleuets farcis avec bacon', 'Blueberry Stuffed Croisant French Toast with Bacon est un petit déjeuner américain. Cette recette sert 4. Pour 3,0 $ par portion, cette recette couvre 16 % de vos besoins quotidiens en vitamines et minéraux. Une portion contient 783 calories, 14g de protéines et 55g de graisses. 1 personne a essayé et aimé cette recette. Un mélange d''oeufs, de miel, de crème lourde et une poignée d''autres ingrédients sont tout ce qu''il faut pour rendre cette recette si somptueuse. Elle vous est apportée par Pink When. De la préparation à l''assiette, cette recette prend environ 45 minutes. Dans l''ensemble, cette recette rapporte une note assez mauvaise de 34%. Des recettes similaires incluent le pain de Toast français croissant à la myrtille, le Toast français croissant farci avec des pêches grillées et le Casserole au chocolat.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 2}, "equipment": ["poêle à frire", "fouet", "bol"], "ingredients": ["extrait de vanille", "muscade", "fromage à la crème", "crème lourde", "croissant", "cannelle", "beurre", "bacon", "miel", "œuf", "lait", "trempette"], "instruction": "Dans un bol moyen, mélanger le fromage à la crème et le miel. Plier doucement dans le bacon et réserver. Dans un grand bol peu profond, fouetter ensemble la crème lourde, le lait, les œufs, l''extrait de vanille, la cannelle et la muscade moulue. Mettez de côté. Faire fondre le beurre dans une grande poêle antiadhésive à feu moyen. Prendre chaque moitié de croissant, tremper complètement dans le mélange d''oeufs, en veillant à enrober chaque côté. Ajoutez-le soigneusement à la poêle chaude. Répétez 2-3 fois selon la taille de votre poêle. Essayez de ne pas surpeupler la poêle. Cuire 2 minutes de chaque côté ou jusqu''à ce qu''il soit doré à votre goût. Répétez le reste de vos moitiés de croissant.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["fromage à la crème", "myrtilles", "croissant", "étendue", "bacon"], "instruction": "Étendre le mélange de fromage au bacon-crème sur 4 moitiés de croissant et placer une poignée de bleuets sur le dessus.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["croissant"], "instruction": "Placer les 4 moitiés restantes sur le dessus.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["myrtilles", "sirop d''érable", "beurre"], "instruction": "Garnir de bleuets supplémentaires et servir avec du beurre et/ou du sirop d''érable 100% si désiré. Profitez-en immédiatement !", "step_number": 4}]', 'https://img.spoonacular.com/recipes/673440-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.39987', '2026-01-19 18:23:17.39987', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '673440');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('62179ea0-8093-4792-b1d4-0f84ca2b7c8f', 'Jambes de canard grillées lentement', 'Les jambes de canard grillées lentement pourraient être juste le plat principal que vous recherchez. Tu regardes ta figure ? Cette recette sans gluten, sans lait, paléolithique et primal contient 381 calories, 46g de protéines et 20g de graisse par portion. Cette recette sert 2. Pour 1,85 $ par portion, cette recette couvre 10 % de vos besoins quotidiens en vitamines et minéraux. 1 personne a fait cette recette et la ferait à nouveau. Cette recette de Foodista nécessite du thym, de l''échalote, du poivre et de l''ail. De la préparation à l''assiette, cette recette prend environ 45 minutes. Avec un score cuilleré de 53%, ce plat est solide. Essayez les cuisses de canard cuites lentement à Port avec du gratin de céleri, les cuisses de canard grillées à la sauce cerise noire et les cuisses de canard braisées et le sein de canard sauté pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["poivre noir moulu", "cuisse de canard", "sel de mer"], "instruction": "Nettoyer et taper les jambes de canard sec. Assaisonner de sel de mer et de poivre noir fraîchement moulu.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["ail haché", "échalote", "thym", "broyage sec"], "instruction": "Frotter un mélange sec d''ail haché, d''échalotes et de thym et laisser au réfrigérateur une nuit ou au moins deux heures.", "step_number": 2}, {"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Le lendemain, préchauffez le four à 200 degrés C/400 degrés F.", "step_number": 3}, {"duration": null, "equipment": ["torréfaction"], "ingredients": ["cuisse de canard"], "instruction": "Retirer le mélange sec et placer les pattes de canard dans une poêle.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["pomme de terre nouvelle", "légumes", "carotte", "oignon", "pomme de terre"], "instruction": "Ajouter les légumes préférés comme les carottes ou les oignons. J''avais des pommes de terre pour me débarrasser, alors je les ai plonnées dans l''espoir de pouvoir les appeler confit de pomme de terre, ce qui semble d''ailleurs être un favori dans les magazines gastronomiques.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 45}, "equipment": ["feuille d''aluminium", "four"], "ingredients": ["pop"], "instruction": "Couvrir d''une feuille d''aluminium et la mettre au four pendant 45 minutes.", "step_number": 6}, {"duration": {"unit": "minutes", "number": 45}, "equipment": ["feuille d''aluminium", "four"], "ingredients": [], "instruction": "Retirez ensuite la feuille, baissez la température à 170 degrés Celsius et faites rôtir la peau au four pendant encore 45 minutes.", "step_number": 7}, {"duration": null, "equipment": [], "ingredients": ["cuisse de canard", "viande"], "instruction": "Vous obtenez bien brunis jambes de canard avec de la viande déchiquetable par une fourchette.", "step_number": 8}]', 'https://img.spoonacular.com/recipes/660312-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.403803', '2026-01-19 18:23:17.403803', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '660312');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('7176d063-65af-43ea-bf04-28e53ad8ca59', 'Noix de coco de pêche Crème glacée', 'Noix de coco de pêche Crème glacée prend environ 45 minutes du début à la fin. Pour 72 cents par portion, vous obtenez un dessert qui sert 14. Une portion de ce plat contient environ 2g de protéines, 14g de graisses et un total de 190 calories. Rendez-vous au magasin et ramassez du lait de coco plein de gras, moitié et moitié, sucre de canne, et quelques autres choses pour le faire aujourd''hui. C''est parfait pour l''été. 8 personnes ont fait cette recette et la referaient. Il vous est apporté par Foodista. C''est une bonne option si vous suivez un régime végétarien sans gluten et lacto ovo. En tenant compte de tous les facteurs, cette recette gagne un score cuilleré de 31%, ce qui est plutôt mauvais. Essayez Cobbler Coconut-Peach avec crème glacée Bourbon-Pecan, crème glacée Coconut Peach avec des amandes grillées Best Lick! 2008, et crème glacée au lait de coco de fraise rôtie (Vegan) + conseils pour rendre votre crème glacée maison douce pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["casserole", "cuisinière"], "ingredients": ["lait de coco", "moitié et moitié"], "instruction": "Chauffer le lait de coco et la moitié et la moitié sur le poêle à feu moyen-élevé dans une casserole jusqu''à ce que chaud et à peine bouillonnant (porter à ébullition faible).", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["sucre"], "instruction": "Ajouter le sucre; mélanger pour dissoudre.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Retirer du feu.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 10}, "equipment": ["mélangeur"], "ingredients": ["pêche"], "instruction": "Verser le mélange dans un mélangeur avec les pêches hachées. Laisser refroidir environ 10 minutes avant de verser le mélange dans un grand récipient; réfrigérer quelques heures jusqu''au froid.", "step_number": 4}, {"duration": null, "equipment": ["machine à crème glacée"], "ingredients": ["glace"], "instruction": "Si vous utilisez une crème glacée, suivez les instructions sur votre crème glacée en conséquence.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 600}, "equipment": ["machine à crème glacée"], "ingredients": ["glace"], "instruction": "Vous pouvez également essayer cela sans une glacière en mettant le mélange de crème glacée dans un contenant sans danger pour le congélateur, en le plaçant dans le congélateur et en remuant avec une cuillère toutes les heures pendant environ 8 10 heures. Si vous essayez cela sans un fabricant de crème glacée, la consistance ne sera pas aussi crémeuse que vous l''obtiendrez quand vous utilisez un fabricant de crème glacée, mais la crème glacée sera toujours super!", "step_number": 6}, {"duration": {"unit": "minutes", "number": 10}, "equipment": [], "ingredients": ["glace"], "instruction": "Si vous avez des restes dans le congélateur, décongelez la glace au moins 10 minutes avant d''essayer de creuser car elle sera beaucoup plus rigide que la glace achetée au magasin.", "step_number": 7}]', 'https://img.spoonacular.com/recipes/655098-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.406309', '2026-01-19 18:23:17.406309', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '655098');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('bd9ebe2b-9b11-4b99-ad52-ba772506c61a', 'Boeuf coupé chaud', 'Besoin d''un plat principal sans gluten et sans lait ? Hot Sliced Beef pourrait être une super recette à essayer. Une portion de ce plat contient environ 533g de protéines, 127g de graisses et un total de 3591 calories. Pour 29,52 $ par portion, cette recette couvre 69% de vos besoins quotidiens en vitamines et minéraux. 1 personne a trouvé cette recette délicieuse et satisfaisante. Cette recette de Foodista nécessite de la crème de soupe aux champignons, de l''oignon, du croupion rôti de boeuf, du sel et du poivre. De la préparation à l''assiette, cette recette prend environ 45 minutes. Dans l''ensemble, cette recette gagne un score spectaculaire de 86%. Des recettes similaires incluent les restes de Thanksgiving: Sichuan-Style Hot and Numbing Sliced Turkey, Thai-Style Sliced-Beef Laitue Wraps et Thai-Style Sliced-Beef Laitue Wraps.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["torréfaction"], "ingredients": ["sel et poivre", "oignon", "eau"], "instruction": "Assaisonner le rôti avec du sel et du poivre, mettre dans le rôti avec de l''oignon et un peu d''eau.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 180}, "equipment": ["four"], "ingredients": [], "instruction": "Cuire à 325 degrés pendant 3 heures. Sors et calme-toi.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 60}, "equipment": ["poêle à frire"], "ingredients": ["bouquet de cuisine", "sauce", "bœuf", "potage"], "instruction": "Chauffer la soupe jusqu''à ce qu''elle soit crémeuse, ajouter toutes les gouttes de cuisson du rôti et ajouter un peu de Bouquet de cuisine ou de maître gras pour s''assombrir. Couper le boeuf et ajouter au mélange de sauce et laisser mijoter lentement, environ 1 heure.", "step_number": 3}]', 'https://img.spoonacular.com/recipes/647524-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.408239', '2026-01-19 18:23:17.408239', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": true}', 'spoonacular', '647524');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('f5e50a1b-b68e-4014-847c-7f443e46ad99', 'Poulet rôti simple', 'Simple Roast Chicken est une recette sans gluten avec 4 portions. Pour 2,76 $ par portion, cette recette couvre 37% de vos besoins quotidiens en vitamines et minéraux. Une portion de ce plat contient environ 47g de protéines, 64g de graisses et un total de 990 calories. Il fonctionne bien comme un plat principal plutôt bon marché. 2 personnes étaient heureuses d''avoir essayé cette recette. De la préparation à l''assiette, cette recette prend environ 45 minutes. Il vous est apporté par Foodista. Allez au magasin et ramassez le poulet, le beurre, le citron, et quelques autres choses pour le faire aujourd''hui. Dans l''ensemble, cette recette rapporte un score cuilleré solide de 69%. Essayez simple poulet rôti, le meilleur poulet rôti simple, et simple poulet rôti pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["sel et poivre", "poulet"], "instruction": "Lavez le poulet à l''intérieur et à l''extérieur et faites sécher. Assurez-vous que la peau est agréable et sèche pour que la peau soit croustillante. Assaisonner bien avec du sel et du poivre à l''intérieur, dehors et sous la peau.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["beurre aromatisé", "sel et poivre", "peau de citron", "beurre", "piment", "ail", "citron"], "instruction": "Mélanger le beurre avec l''ail, le piment et la croûte de citron. Assaisonner un peu de sel et de poivre. Placer le beurre aromatisé sous la peau sur la poitrine, les jambes et le dos. Emmenez la moitié du citron dans la cavité.", "step_number": 2}, {"duration": null, "equipment": ["boîte à cuisson", "four"], "ingredients": ["sel et poivre", "huile d''olive", "pommes de terre", "piment"], "instruction": "Préchauffer le four à 400F. Mélanger les deux sortes de pommes de terre dans le fond de la poêle avec le piment, sel et poivre au goût et une aide généreuse de l''huile d''olive.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["poitrine de poulet", "légumes"], "instruction": "Placez une grille sur les légumes. Placez le côté poitrine de poulet sur la grille.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 15}, "equipment": ["four"], "ingredients": [], "instruction": "Cuire les 15 premières minutes à 400F. Puis baissez la température et continuez à cuire pendant environ une heure à 300F.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["poulet"], "instruction": "À mi-cuisson, tourner le poulet sur sa poitrine. Passez-moi un peu de jus.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": ["poulet"], "instruction": "Plus tard, pour vérifier la cuisson, percer la partie la plus épaisse du poulet (la cuisse). Si les jus sont vides, le poulet est prêt, sinon continuer la cuisson.", "step_number": 7}, {"duration": null, "equipment": [], "ingredients": ["pommes de terre rôties", "poulet"], "instruction": "Servir le poulet sur un plateau sur le lit de pommes de terre grillées.", "step_number": 8}]', 'https://img.spoonacular.com/recipes/660133-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.434279', '2026-01-19 18:23:17.434279', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '660133');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('4c79b656-11dc-43b6-8c66-e1aeb8f84c96', 'Kale avec l''oignon rouge', 'Kale avec l''oignon rouge est un plat d''appoint qui sert 8. Une portion de ce plat contient environ 1g de protéines, 2g de graisses et un total de 25 calories. Pour 13 cents par portion, cette recette couvre 6% de vos besoins quotidiens en vitamines et minéraux. 1 personne a trouvé cette recette délicieuse et satisfaisante. Allez au magasin et prenez du chou, de l''oignon, de l''ail, et quelques autres choses pour le faire aujourd''hui. C''est une bonne option si vous suivez un régime végétarien sans gluten, sans lait, paléolithique et lacto ovo. De la préparation à l''assiette, cette recette prend environ 45 minutes. Il vous est apporté par Foodista. En tenant compte de tous les facteurs, cette recette gagne un score cuilleré de 90%, ce qui est excellent. Si vous aimez cette recette, regardez ces recettes similaires : Kale, Mushroom et Red Onion Pizza, Red Onion, Kale And Cheese Strata, et Parsnip, Red Onion, Kale et Gouda Frittata.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["poêle à frire"], "ingredients": ["légumes", "huile d''olive", "ail", "oignon"], "instruction": "Dans une casserole en fonte, à feu moyen doux, faire chauffer l''huile d''olive, l''ail et l''oignon jusqu''à ce que les légumes soient tendres", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["eau", "chou"], "instruction": "Ajouter le chou haché lavé (conserver l''eau sur les feuilles pour créer de la vapeur)", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Couvrir immédiatement et laisser la vapeur 3-5 minutes", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Retirer le couvercle, remuer et éteindre le feu", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["vinaigre balsamique"], "instruction": "Servir avec du vinaigre balsamique", "step_number": 5}]', 'https://img.spoonacular.com/recipes/648729-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.410028', '2026-01-19 18:23:17.410028', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '648729');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('77ae5c68-9386-43b7-ab11-ae2e8b107cd4', 'Oignons de perles émaillés', 'La recette d''oignons de perles émaillés peut être faite en environ 45 minutes. Cette recette sert 4. Une portion de ce plat contient environ 1g de protéines, 4g de gras et un total de 61 calories. Pour 1,16 $ par portion, cette recette couvre 2 % de vos besoins quotidiens en vitamines et minéraux. Seulement quelques personnes ont fait cette recette, et je dirais qu''elle a atteint l''endroit. Il vous est apporté par Foodista. Il fonctionne bien comme un plat latéral. Un mélange de miel, d''huile d''olive, de vinaigre de vin rouge et une poignée d''autres ingrédients sont tout ce qu''il faut pour rendre cette recette si délicieuse. C''est une bonne option si vous suivez un régime végétarien sans gluten, sans lait, paléolithique et lacto ovo. Tout compte fait, nous avons décidé que cette recette mérite un score cuilleré de 11 %. Ce score est plutôt mauvais. Les oignons glacés, les oignons glacés et les oignons glacés sont très semblables à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 1}, "equipment": ["couteau", "bol", "pot"], "ingredients": ["oignon perlé", "eau", "oignon"], "instruction": "C''est le moyen le plus facile de peler les oignons perlés. Portez un pot d''eau à ébullition rapide et ajoutez des oignons perlés non pelés. Faire bouillir pendant une minute, écraser et placer les oignons dans un bol d''eau glacée pour arrêter le processus de cuisson. À l''aide d''un couteau tranchant, couper la racine des oignons. Pressez du haut, et votre oignon devrait glisser.", "step_number": 1}, {"duration": null, "equipment": ["poêle à frire", "fouet"], "ingredients": ["vinaigre de vin rouge", "huile d''olive", "miel"], "instruction": "Fouetter ensemble le miel et le vinaigre de vin rouge. Mettez de côté. Dans une poêle, faire chauffer l''huile d''olive à feu moyen-élevé.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 4}, "equipment": [], "ingredients": ["oignon perlé"], "instruction": "Ajouter les oignons perlés pelés et saupoudrer pendant 3-4 minutes jusqu''à ce qu''ils commencent à brunir.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["vinaigre", "oignon", "miel", "sauce", "sirop"], "instruction": "Verser le miel et le vinaigre sur les oignons et mélanger pour les enrober uniformément. Porter le feu à feu moyen et continuer à saupoudrer les oignons jusqu''à ce que la sauce soit réduite à un sirop.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servir au chaud", "step_number": 5}]', 'https://img.spoonacular.com/recipes/644758-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.411259', '2026-01-19 18:23:17.411259', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '644758');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('f5cb0fb2-5021-4079-b90a-99ddd8e96c70', 'Oignons et haricots fumés doux Vidalia', 'Smoky Sweet Vidalian Oignons et haricots nécessitent environ 45 minutes du début à la fin. Cette recette sert 6. Une portion de ce plat contient environ 7g de protéines, 5g de graisses et un total de 186 calories. Pour 77 cents par portion, cette recette couvre 9 % de vos besoins quotidiens en vitamines et minéraux. Peu de gens ont fait cette recette, et je dirais qu''elle a atteint l''endroit. Il fonctionne bien comme un plat d''appoint très économique. Si vous avez de la fumée liquide, des oignons vidaliens, de l''huile d''olive et quelques autres ingrédients, vous pouvez le faire. Il vous est apporté par Foodista. C''est une bonne option si vous suivez un régime sans gluten, sans lait, lacto ovo végétarien et végétalien. Avec un score cuilleré de 60%, ce plat est solide. Les utilisateurs qui ont aimé cette recette ont également aimé les moules avec le jambon fumé et les oignons vidaliens, les haricots sucrés fumés et les haricots de cowboy sucrés et fumés.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["oignon", "grains"], "instruction": "Peler et trancher les oignons contre le grain, Cela coupera les cellules et permettra aux jus d''être libérés et créera des oignons très crémeux et doux lorsqu''ils seront dorés.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["huile d''olive", "oignon"], "instruction": "Brunir lentement les oignons dans l''huile d''olive, ce qui leur permet de réduire et de devenir très doux.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["haricots en conserve", "haricots cuits"], "instruction": "Ajouter les haricots en conserve avec du liquide et réduire en entier sur une faible mijoter jusqu''à la consistance des haricots cuits.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["fumée liquide", "sel"], "instruction": "Incorporer la fumée liquide et le sel au goût.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["l''oignon", "oignon doux", "haricots cuits", "sucre brun", "mélasse", "oignon", "bonbons", "porc"], "instruction": "Remarque:Les oignons Vidalia sont incroyablement doux par nature et ont très peu d''épices pour eux. Dans cette recette, j''ai créé une torsion sur les plats de fèves classiques qui utilisent le sucre brun, la mélasse, etc. pour créer de la douceur dans le plat. La version que j''ai faite était très riche et douce, mais tout cela venait des oignons. Ce plat se trouve également être végétalien, mais a un goût beaucoup comme vous avez utilisé le porc fumé. Si vous ne trouvez pas Vidalia Sweet Onions, qui ne viennent que de Géorgie, vous pouvez remplacer Walla Wall Sweet Onions, Maya Sweets, ou Maui Sweets.", "step_number": 5}]', 'https://img.spoonacular.com/recipes/660415-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.41271', '2026-01-19 18:23:17.41271', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '660415');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('27fbdf63-b784-4e04-8868-91a262fce05d', 'Cuisinière entière 30 lente', 'Total 30 Slow Cooker nécessite environ 45 minutes du début à la fin. Cette recette sert 65 $ et coûte 17,22 $ par portion. Tu regardes ta figure ? Cette recette sans gluten, sans lait et 30 entiers contient 3512 calories, 347g de protéines et 218g de graisses par portion. Quelques personnes ont vraiment aimé cet hor d''oeuvre. 24 personnes ont été impressionnées par cette recette. Un mélange de barbacoa d''agneau de faire à partir de la nourriture saine, la cuisson lente cuisses de poulet marocain de la vraie nourriture, poulet à une pan et légumes rôtis de kristine entre, et une poignée d''autres ingrédients sont tout ce qu''il faut pour rendre cette recette si délicieux. Elle vous est apportée par Pink When. Tout compte fait, nous avons décidé que cette recette mérite un score cuilleré de 94%. Ce score est spectaculaire. Cuisinier Slow Honey-Garlic Baby Back Ribs (et ‘Real Food Slow Cooker Cènes) Cookbook Giveaway), Cooker Slow Honey-Garlic Baby Back Ribs (et ‘Real Food Slow Cooker Cènes) et Paleo Shredded Slow Cooker Roast Beef avec citrouille et salsa + A Slow Cooker Roundup et GIVEAWAY sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[]', 'https://img.spoonacular.com/recipes/795512-556x370.png', 'PUBLISHED', '2026-01-19 18:23:17.414896', '2026-01-19 18:23:17.414896', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": true}', 'spoonacular', '795512');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('0cb349e0-9618-4aaa-bfe5-3538055fba45', 'Poivrons à cloches farcies à la poêle', 'Pan-Fried Poppers Bell Stuffed pourrait être une bonne recette pour élargir votre boîte de recettes de plat principal. Une portion contient 397 calories, 29g de protéines et 18g de graisses. Pour 4,35 $ par portion, cette recette couvre 37 % de vos besoins quotidiens en vitamines et minéraux. Cette recette sert 2. 1 personne ont été impressionnés par cette recette. Allez au magasin et ramassez la solution stachy, les haricots noirs, les crevettes, et quelques autres choses à faire aujourd''hui. C''est une bonne option si vous suivez un régime sans gluten et sans lait. De la préparation à l''assiette, cette recette prend environ 45 minutes. Il vous est apporté par Foodista. En tenant compte de tous les facteurs, cette recette rapporte un score cuilleraculaire de 76%, qui est solide. Des recettes semblables comprennent des poivrons à cloches farcies, des poivrons à cloches farcies et des poivrons à cloches farcies.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 10}, "equipment": [], "ingredients": ["crevettes", "eau"], "instruction": "Faire tremper les crevettes séchées dans l''eau pendant environ 10 minutes.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["boeuf haché", "crevettes"], "instruction": "Égoutter. Devinez et hachez finement les crevettes décortiquées. Mélanger ensuite les crevettes séchées et la viande hachée. Hacher jusqu''à ce que le mélange entier soit entièrement incorporé.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["poivre blanc", "poivron", "fécule de maïs", "poivre", "sucre", "sel"], "instruction": "Ajouter le sucre, le sel, le poivre blanc et la fécule de maïs et remuer vigoureusement jusqu''à ce que le mélange soit élastique. Poussez légèrement l''intérieur des coins de poivron avec de la fécule de maïs. Remplir chaque coin de poivre avec le mélange, bombant légèrement. Avec un peu d''amidon de maïs.", "step_number": 3}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["huile de cuisson"], "instruction": "Chauffer une poêle avec de l''huile.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 5}, "equipment": ["poêle à frire"], "ingredients": ["poivron", "haricots noirs", "ail", "gingembre", "poivre", "huile de cuisson"], "instruction": "Placer les quartiers de poivre farcis, les remplir à l''envers, dans la poêle et faire cuire pendant environ 3-5 minutes. Pousser doucement les poivrons sur les côtés. Laisser la moitié de la cuillère à soupe d''huile pour remuer le gingembre, l''ail et les haricots noirs jusqu''à parfumer.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 8}, "equipment": [], "ingredients": ["poivron", "poivrons", "sauce", "sucre", "eau", "sel"], "instruction": "Verser dans l''eau, assaisonner de sel et de sucre et laisser mijoter 5-8 minutes. Disposer les poivrons sur un plat et épaissir la sauce avec la solution féculente. Spoon sur les poivrons farcis et servir.", "step_number": 6}]', 'https://img.spoonacular.com/recipes/654462-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.428382', '2026-01-19 18:23:17.428382', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '654462');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('61128f14-e888-4366-9264-277b69c3968e', 'Udon frit avec crevettes séchées', 'Une portion contient 234 calories, 18g de protéines et 17g de graisse. Pour 62 cents par portion, cette recette couvre 8 % de vos besoins quotidiens en vitamines et minéraux. 1 personne était heureuse qu''ils aient essayé cette recette. De la préparation à l''assiette, cette recette prend environ 45 minutes. Cette recette de Foodista nécessite des nouilles udon, de l''ail, de la coriandre/parsil/chili pour garnir et conserver le radis. C''est une bonne option si vous suivez un régime sans lait. Dans l''ensemble, cette recette gagne un score cuilleraculaire pas si spectaculaire de 23%. Si vous aimez cette recette, regardez ces recettes similaires : Crevettes frites d''Udon, Udon Yaki (Easy Stir Fried Udon Noodles) et Simple Stir-fried Udon.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["crevettes séchées", "ail", "crevettes", "huile de cuisson"], "instruction": "Chauffer l''huile, saupoudrer l''ail haché et les crevettes séchées jusqu''à ce que parfumées et crevettes commencent à danser.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["poivre noir moulu", "boeuf haché", "radis"], "instruction": "Ajouter le radis haché, le poivre noir moulu et la viande hachée et remuer jusqu''à ce qu''il soit aromatique.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["assaisonnement"], "instruction": "Ajouter dans l''Udon, assaisonner et remuer jusqu''à bien mélanger. Sécher et servir.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["coriandre", "persil", "piment"], "instruction": "Garnir de coriandre/parsil/chili comme vous voulez.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/643823-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.437778', '2026-01-19 18:23:17.437778', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '643823');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('30cb878f-5adb-4fc1-b348-07da7aa49462', 'Roulettes d''oeufs philippins', 'Les rouleaux d''oeufs philippins peuvent être une bonne recette pour élargir votre boîte de recettes hors d''oeuvre. Cette recette sans lait sert 1 et coûte 20,15 $ par portion. Une portion de ce plat contient environ 227g de protéines, 226g de graisses et un total de 5264 calories. Prenez le poivre, l''ail, le sel et quelques autres choses pour le faire aujourd''hui. Quelques personnes ont vraiment aimé ce plat chinois. 14 personnes ont été impressionnées par cette recette. De la préparation à l''assiette, cette recette prend environ 45 minutes. Il vous est apporté par Foodista. En tenant compte de tous les facteurs, cette recette gagne un score cuilleré de 88%, ce qui est excellent. Les rouleaux d''oeufs philippins, les rouleaux d''oeufs philippins et les rouleaux de petit déjeuner de Pandesal (Filipino Breakfast Rolls) sont très semblables à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["poêle à frire"], "ingredients": ["huile d''olive", "ail"], "instruction": "Dans une poêle, faire revenir l''ail dans l''huile d''olive jusqu''à ce qu''il soit brun clair.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["oignon"], "instruction": "Ajoutez des oignons.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Saute jusqu''à presque translucide.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["porc haché", "sel"], "instruction": "Ajouter le porc haché et saupoudrer de c. à thé de sel et c. à thé de poivre noir. Faire frire jusqu''à ce que la couleur rose ne s''affiche plus.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["sauce huître", "sauce de poisson", "carotte"], "instruction": "Ajouter les carottes, la sauce aux huîtres et la sauce au poisson.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Bien mélanger.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": ["crevettes", "œuf"], "instruction": "Ajouter les crevettes et cuire jusqu''à ce qu''elles soient roses, puis ajouter les œufs.", "step_number": 7}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Bien mélanger et retirer de la chaleur. Laisser refroidir complètement.", "step_number": 8}, {"duration": null, "equipment": [], "ingredients": ["sauce"], "instruction": "Égoutter si nécessaire. Mettez de côté la sauce.", "step_number": 9}, {"duration": null, "equipment": [], "ingredients": ["sauce", "eau", "rouleau", "œuf"], "instruction": "Les emballages de lumpia sont très serrés, alors soyez prudent lors de les séparer. Spoon 1 Mélange à soupe sur le bord inférieur de l''emballage laissant 1 pouce de bord. Commencer à plier le rouleau d''oeuf comme une enveloppe : d''abord, plier sur le bord inférieur de 1 pouce au-dessus du landage, puis le bord gauche, puis le bord droit, puis rouler jusqu''au bord supérieur. Pour sceller l''emballage, il suffit d''hydrater le bord supérieur avec de l''eau. J''ai utilisé la sauce que j''ai obtenue en drainant le mélange cuit.", "step_number": 10}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["huile végétale"], "instruction": "Chauffer l''huile végétale dans une grande poêle profonde à feu moyen-élevé.", "step_number": 11}, {"duration": {"unit": "minutes", "number": 5}, "equipment": ["poêle à frire"], "ingredients": ["rouleau", "agiter", "œuf", "huile de cuisson"], "instruction": "Placez le rouleau d''oeuf un à la fois dans l''huile chaude, avec la couture vers le bas (ce qui l''empêchera de démêler) puis tournez rapidement le rouleau d''oeuf pour assurer la peau croustillante et ne colle pas aux autres rouleaux d''oeuf dans la poêle. Réglez la chaleur pour que l''huile bouillonne doucement et pas trop vigoureusement autour des rouleaux d''oeufs. Chaque rouleau d''oeufs prendra environ 5 minutes pour cuisiner. Agiter le rouleau d''oeuf sur la casserole pour aider à enlever l''excès d''huile.", "step_number": 12}, {"duration": null, "equipment": ["serviettes en papier"], "ingredients": ["rouleau", "œuf"], "instruction": "Placer le rouleau d''oeuf sur les couches de serviettes en papier pour égoutter.", "step_number": 13}, {"duration": null, "equipment": [], "ingredients": ["sauce douce et aigre", "vinaigre", "rouleau", "sauce", "œuf"], "instruction": "Servez les rouleaux d''oeufs lumpia ou philippins avec votre sauce sucrée et aigre préférée ou une sauce au vinaigre épicé.", "step_number": 14}]', 'https://img.spoonacular.com/recipes/642863-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.44175', '2026-01-19 18:23:17.44175', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": true}', 'spoonacular', '642863');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('6019c03d-33f2-436d-bbbe-850ebea36b76', 'Surf et Turf Kababs', 'Besoin d''un plat principal sans gluten et sans lait ? Surf et Turf Kababs pourraient être une super recette à essayer. Pour 7,96 $ par portion, cette recette couvre 39% de vos besoins quotidiens en vitamines et minéraux. Une portion contient 749 calories, 68 g de protéines et 33 g de graisse. Cette recette sert 4. 1 personne a fait cette recette et la ferait à nouveau. Un mélange de sauce de soja, & poivron, de sucre brun, et une poignée d''autres ingrédients sont tout ce qu''il faut pour rendre cette recette si savoureux. Il vous est apporté par Foodista. De la préparation à l''assiette, cette recette prend environ 45 minutes. Avec un score cuilleré de 82%, ce plat est exceptionnel. Surf et Turf pour deux, Surf & Turf, et Surf et Turf pour deux sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["légumes", "marinade", "viande", "rouleau"], "instruction": "Mettre la viande coupée & légumes dans le sac Ziploc et verser la moitié de la marinade sur eux. Sceller le sac serré et rouler dans les mains pour enrober soigneusement les ingrédients.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 360}, "equipment": ["brochettes", "grille"], "ingredients": ["marinade", "viande"], "instruction": "Placer le sac au réfrigérateur et laisser mariner au moins 4 à 6 heures ou toute la nuit. Lorsque vous êtes prêt à griller, verser l''excédent de marinade et la viande à cordes et les légumes alternativement sur les brochettes.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 11}, "equipment": ["grille"], "ingredients": ["marinade", "glaçure"], "instruction": "Chauffer le gril à feu moyen-élevé et faire griller les kabobs directement sur les charbons ou les flammes de gaz. Faire griller environ 6 à 8 minutes de chaque côté ou jusqu''à ce que la cuisson soit désirée. Au cours des 5 dernières minutes de cuisson, baste kabobs avec glaçure et fermer le grill et laisser caraméliser. Marinade & Glace", "step_number": 3}, {"duration": null, "equipment": ["casserole"], "ingredients": ["marinade"], "instruction": "Mélanger la marinade et verser la moitié dans une petite casserole.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["légumes", "glaçure"], "instruction": "Verser la moitié restante sur le meeting et les légumes dans le sac Ziploc. Pour glaçure : Faire cuire la glaçure à feu moyen, en remuant occasionnellement. Réduire le mélange de 1/3 à 1/2 ou jusqu''à ce que la glaçure recouvre le dos d''une cuillère.", "step_number": 5}]', 'https://img.spoonacular.com/recipes/662375-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.446018', '2026-01-19 18:23:17.446018', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '662375');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('e27738eb-dc95-4bcc-b69c-31a810770619', 'Tarte de poulet en pot de croûte', 'Si vous voulez ajouter plus de recettes sans lait à votre répertoire, Crock Pot Chicken Pot Pie pourrait être une recette que vous devriez essayer. Cette recette sert 20 $ et coûte 83 cents par portion. Cet hor d''oeuvre a 276 calories, 9g de protéines et 13g de graisse par portion. 15 personnes étaient heureuses d''avoir essayé cette recette. Cette recette de Foodista nécessite un blanc d''œuf, crème condensée de soupe de poulet, croûtes de tarte et légumes - nous préférons les pois et les carottes. De la préparation à l''assiette, cette recette prend environ 45 minutes. Tout compte fait, nous avons décidé que cette recette mérite un score cuilleré de 59%. Ce score est solide. Les utilisateurs qui ont aimé cette recette ont aussi aimé Healthy Chicken Pot Pie Soupe dans le pot à croquer (toute la 30, sans lait), Crock Pot Chicken Pot Pie et Crock Pot Chicken Pot Pie.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["cuisinière lente"], "ingredients": ["crème de soupe de poulet", "poitrine de poulet", "légumes", "pommes de terre"], "instruction": "Dans Crock Pot, mélanger poitrines de poulet, pommes de terre, légumes congelés, crème de soupe de poulet et bien mélanger.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["sel et poivre"], "instruction": "Ajouter du sel et du poivre si désiré.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 480}, "equipment": ["four"], "ingredients": ["poulet"], "instruction": "Cuire à basse température pendant 6-8 heures jusqu''à ce que le poulet soit entièrement cuit. Utilisez une cuillère robuste pour casser le poulet après la cuisson. Préchauffer le four à 40", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["croûte de tarte", "poulet"], "instruction": "Préparez des croûtes de tarte. Saupoudrer le poulet dans la croûte de tarte.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["croûte de tarte"], "instruction": "Garnir de croûte de tarte.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["croûte"], "instruction": "Couper les fentes dans la croûte supérieure pour évacuer la vapeur pendant la cuisson.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": ["croûte"], "instruction": "Couper l''excès de croûte des bords et pincer pour sceller.", "step_number": 7}, {"duration": {"unit": "minutes", "number": 30}, "equipment": ["four"], "ingredients": ["blancs d''œufs", "beurre", "croûte"], "instruction": "Badigeonner de blanc d''œuf ou de beurre fondu et cuire 20-30 minutes jusqu''à ce que la croûte soit entièrement cuite et dorée sur le dessus.", "step_number": 8}, {"duration": {"unit": "minutes", "number": 10}, "equipment": [], "ingredients": [], "instruction": "Laisser refroidir au moins 10 minutes avant de couper les tartes. Meilleur servi chaud.", "step_number": 9}]', 'https://img.spoonacular.com/recipes/640862-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.451058', '2026-01-19 18:23:17.451058', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '640862');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('29c3d7f3-d4d8-4a3c-bf7b-df1902ebe9ca', 'Riz frit thaï facile', 'Si vous voulez ajouter plus sans gluten, sans lait, lacto ovo végétarien, et fodmap recettes amicales à votre boîte de recettes, Easy Thai Fried Rice pourrait être une recette que vous devriez essayer. Cette recette sert 4. Ce plat principal contient 587 calories, 16g de protéines et 5g de gras par portion. Pour 97 cents par portion, cette recette couvre 18 % de vos besoins quotidiens en vitamines et minéraux. 1 personne a essayé et aimé cette recette. Cette recette est typique de la cuisine chinoise. De la préparation à l''assiette, cette recette prend environ 45 minutes. Allez au magasin et ramassez du riz, du sel et du poivre, des légumes, et quelques autres choses à faire aujourd''hui. Il vous est apporté par Foodista. Avec un score cuilleré de 53%, ce plat est assez bon. Des recettes similaires incluent le riz frit thaïlandais, le riz frit thaïlandais et le riz frit thaïlandais.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["sel et poivre", "œuf", "riz"], "instruction": "Casser les œufs dans le reste du riz. Assaisonner de sel et de poivre. Utilisez une fourchette et mélangez le riz et les oeufs jusqu''à bien mélanger.", "step_number": 1}, {"duration": null, "equipment": ["serviettes de cuisine", "poêle à frire"], "ingredients": ["étendue", "huile de cuisson"], "instruction": "Chauffer de l''huile dans une poêle. Au-dessus de la flamme basse, couper les feuilles de kaffir dans l''huile. Lorsque les feuilles semblent croustillantes, faites-les sortir de l''huile et étalez-les et reposez-vous sur une serviette de cuisine.", "step_number": 2}, {"duration": null, "equipment": ["spatule", "poêle à frire"], "ingredients": ["riz", "œuf"], "instruction": "Ajouter le mélange riz-œuf dans la même casserole à feu moyen. Utilisez une spatule et vérifiez si le côté (en faisant face à la poêle) ressemble à une texture omelette (brun doré).", "step_number": 3}, {"duration": null, "equipment": ["spatule"], "ingredients": ["grains", "riz"], "instruction": "Lorsque la texture de l''omelette est atteinte, retourner le mélange pour cuire l''autre côté. Comme il cuit, commencez à casser le mélange avec une spatule pour ressembler à des grains de riz lâches.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["légumes mélangés", "pâte de curry rouge"], "instruction": "Ajouter la pâte de curry rouge et mélanger les légumes et mélanger. Le frit est prêt lorsque le légume mélangé est chauffé.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["riz"], "instruction": "Saupoudrer les feuilles de kaffir croustillantes sur le riz frit avant de servir.", "step_number": 6}]', 'https://img.spoonacular.com/recipes/642125-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.454408', '2026-01-19 18:23:17.454408', '{"vegan": false, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '642125');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('675f4d42-3176-4048-b9b2-9321d9250bc8', 'Poulet grillé et aubergine Sandwichs', 'Poulet grillé et aubergine Sandwiches est un cours principal qui sert 4. Pour 3,69 $ par portion, cette recette couvre 37% de vos besoins quotidiens en vitamines et minéraux. Une portion de ce plat contient environ 55g de protéines, 44g de graisses et un total de 810 calories. Si vous avez du sel et du poivre, des tranches de poulet, du basilic et quelques autres ingrédients à la main, vous pouvez le faire. 2 personnes ont été impressionnées par cette recette. Le Quatrième De Juillet sera encore plus spécial avec cette recette. Il vous est apporté par Foodista. De la préparation à l''assiette, cette recette prend environ 45 minutes. Tout compte fait, nous avons décidé que cette recette mérite un score cuilleré de 77%. Ce score est solide. Si vous aimez cette recette, vous aimerez peut-être aussi des recettes comme les sandwiches grillés au poulet et à l''aubergine, les sandwichs grillés à l''aubergine et les sandwichs grillés à l''aubergine.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["huile d''ail"], "instruction": "Mélanger tous les ingrédients pour l''huile d''ail.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 10}, "equipment": ["cuillère en bois", "casserole"], "ingredients": ["huile d''ail", "tomates", "ail"], "instruction": "Chauffer 1 cuillère à soupe d''huile d''ail dans une casserole moyenne à feu moyen. Lorsque l''ail commence à cracher et à sentir parfumé, ajouter les tomates en dés et leur liquide. Porter à mijoter et laisser mijoter pendant environ 10 minutes, jusqu''à ce que les tomates s''épaississent légèrement, en brisant un peu les tomates avec une cuillère en bois.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 10}, "equipment": ["grille"], "ingredients": ["huile d''ail", "poulet", "olives", "poivre", "basilic", "sel"], "instruction": "Ajouter les olives et le basilic. Assaisonner de sel & poivre au goût, réserver. Préchauffez votre grill pendant au moins 10 minutes. Assaisonner le poulet avec du sel et du poivre et mélanger avec 2 cuillères à soupe d''huile d''ail.", "step_number": 3}, {"duration": null, "equipment": ["serviettes en papier", "grille"], "ingredients": ["huile d''ail", "aubergines", "rouleau", "huile de cuisson"], "instruction": "Badigeonner l''aubergine de 2 cuillères à soupe de l''huile d''ail. Coupez les rouleaux de hoagie et brossez avec les 2 autres cuillères à soupe d''huile d''ail. Grattez et huilez la grille du gril (en utilisant une bande de papier torchon trempé dans l''huile).", "step_number": 4}, {"duration": {"unit": "minutes", "number": 7}, "equipment": ["grille", "feuille d''aluminium"], "ingredients": ["aubergines", "poulet"], "instruction": "Ajouter l''aubergine et cuire jusqu''à tendre environ 5-7 minutes par côté, tourner une fois, retirer l''aubergine de la grille et couvrir de papier pendant le grillage du poulet.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 5}, "equipment": ["grille"], "ingredients": ["poulet", "fromage"], "instruction": "Ajouter le poulet et faire griller jusqu''à ce qu''il soit cuit, environ 4-5 minutes de chaque côté, en ajoutant le fromage pendant environ 30 secondes à une minute.", "step_number": 6}, {"duration": null, "equipment": ["grille"], "ingredients": ["poulet"], "instruction": "Retirer le poulet du grill.", "step_number": 7}, {"duration": null, "equipment": ["grille"], "ingredients": ["aubergines", "poulet", "rouleau", "sauce"], "instruction": "Ajouter les rouleaux de hoagie, couper le côté vers le bas et griller jusqu''à grillé. Pour assembler les sandwiches, déposer une partie de l''aubergine sur le rouleau grillé, garnie d''un peu de sauce, puis une partie du poulet et de la sauce supplémentaire.", "step_number": 8}]', 'https://img.spoonacular.com/recipes/645624-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.508763', '2026-01-19 18:23:17.508763', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '645624');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('3d7244da-62fa-4c97-8476-949a63b9096f', 'Kare Katsu', 'Kare Katsu n''est peut-être que le plat que vous recherchez. Une portion de ce plat contient environ 5g de protéines, 3g de graisses et un total de 74 calories. Cette recette sert 12 $ et coûte 24 cents par portion. Peu de gens ont fait cette recette, et je dirais qu''elle a atteint l''endroit. Si vous avez des oignons, des pommes de terre, du riz et quelques autres ingrédients, vous pouvez le faire. C''est une bonne option si vous suivez un régime sans gluten et sans lait. Il vous est apporté par Foodista. De la préparation à l''assiette, cette recette prend environ 45 minutes. Avec un score cuilleré de 29%, ce plat n''est pas si excellent. Les utilisateurs qui ont aimé cette recette ont également aimé Kare Kare (ox Tail And Peanut Stew) Recipe, Crevettes Seared avec Kare-Kare Butter et Kare Kare (oxtail Stew).', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["poêle à frire"], "ingredients": ["porc", "huile de cuisson"], "instruction": "Faire cuire le porc dans une casserole à l''huile; réserver", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["oignon", "eau", "porc"], "instruction": "Faire revenir les oignons jusqu''à ce qu''ils se ramollissent; ajouter le porc et 1/2 tasse d''eau et laisser mijoter.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["pommes de terre", "carotte"], "instruction": "Ajouter les pommes de terre, les carottes et le curry. Mélanger pour dissoudre le curry, réduire le feu et porter à ébullition; cuire jusqu''à ce que les pommes de terre et les carottes soient tendres.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["riz"], "instruction": "Servir sur le riz.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/648749-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.456652', '2026-01-19 18:23:17.456652', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '648749');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('ada26865-9bc5-4901-9c54-cf07f2cfda33', 'Soupe de chou et de racine de céleri Savoy avec confit Leek', 'Savoy Cabbage et Céleri Soupe Racine avec Leek Confit pourrait être juste l''hor d''oeuvre que vous recherchez. Cette recette sert 7. Regarder votre silhouette? Cette recette sans gluten contient 183 calories, 5g de protéines et 6g de gras par portion. Pour 1,51 $ par portion, cette recette couvre 10 % de vos besoins quotidiens en vitamines et minéraux. Un mélange de bouillon de légumes, gousses d''ail, racine de céleri, et une poignée d''autres ingrédients sont tout ce qu''il faut pour rendre cette recette si savoureux. Ce sera un succès à votre événement d''automne. 2 personnes ont trouvé cette recette délicieuse et satisfaisante. Il vous est apporté par Foodista. De la préparation à l''assiette, cette recette prend environ 45 minutes. Avec un score cuilleré de 50%, ce plat est bon. Parmi les recettes similaires, mentionnons le savoyage et la soupe aux racines Celery, la soupe aux racines Leek Confit, Leek et Celery et la soupe aux racines Silky Leek & Celery.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["pot"], "ingredients": ["huile d''olive"], "instruction": "Chauffer l''huile d''olive dans un pot lourd, comme un Creuset, à feu moyen-vif.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 15}, "equipment": [], "ingredients": ["céleriac", "oignons verts", "ail", "oignon", "poireaux"], "instruction": "Ajouter l''oignon, la racine de céleri, l''ail, les dessus de pétoncle et le confit de poireau. Sauter jusqu''à ce que l''oignon ramollisse, environ 15 minutes.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["romarin", "moutarde", "pomme"], "instruction": "Ajouter la pomme, la moutarde et le romarin et cuire encore quelques minutes. Le mélange sera très aromatique.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 40}, "equipment": [], "ingredients": ["assaisonnement"], "instruction": "Ajouter le reste des ingrédients et laisser mijoter. Couvrir et laisser mijoter pendant 40 minutes. Régler l''assaisonnement si nécessaire.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/659513-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.459237', '2026-01-19 18:23:17.459237', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '659513');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('969b462e-c584-4e06-bafb-7d0d806c8b2c', 'Curry crevé', 'Si vous voulez ajouter plus de recettes sans gluten et pescataires à votre boîte de recettes, Prawn Curry pourrait être une recette que vous devriez essayer. Pour 3,14 $ par portion, cette recette couvre 15 % de vos besoins quotidiens en vitamines et minéraux. Ce plat principal a 446 calories, 28g de protéines et 16g de graisse par portion. Cette recette sert 8. 1 personne a essayé et aimé cette recette. Pas beaucoup de gens ont vraiment aimé ce plat indien. Si vous avez du cumin, des gousses de cardamome, du curcuma moulu et quelques autres ingrédients à la main, vous pouvez le faire. De la préparation à l''assiette, cette recette prend environ 45 minutes. Il vous est apporté par Foodista. En tenant compte de tous les facteurs, cette recette gagne un score cuilleré de 53%, qui est solide. Si vous aimez cette recette, regardez ces recettes similaires : Curry de noix de coco (Thengai Konju Curry), Curry de noix de coco et curry de noix de coco.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 30}, "equipment": [], "ingredients": ["curcuma", "pommes de terre", "crevettes", "eau", "sel", "huile de cuisson", "broyage sec"], "instruction": "Coquille, deveine et laver les crevettes avec de l''eau salée. Frottez les crevettes avec 2 cuillères à café de curcuma moulu et 1 cuillère à café de sel. Réserver 30 minutes. Peau et quart de grandes pommes de terre. Coupez les petits. Frotter avec 1/2 cuillère à café de sel et 1 cuillère à café de curcuma moulu. Faire frire dans 2 onces d''huile à feu moyen jusqu''à ce qu''il soit doré.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 6}, "equipment": [], "ingredients": ["cardamome", "cannelle", "oignon", "cumin", "huile de cuisson"], "instruction": "Retirer dans un plat. Dans la même huile chaude, faire revenir le cumin, la cannelle et la cardamome pendant 1 minute, puis ajouter les oignons tranchés et faire revenir 5 minutes de plus.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["coriandre terrestre", "jus de gingembre", "poudre de chili", "oignon", "crevettes", "yaourt", "sucre", "sel"], "instruction": "Ajouter les crevettes, le chili moulu, la coriandre moulue, les oignons moulus, le jus de gingembre, le yaourt, le sucre et le sel au goût. Incorporer pour bien mélanger.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["pommes de terre", "tomates", "sauce", "eau"], "instruction": "Ajouter 3/4 pinte d''eau bouillante et les pommes de terre et cuire jusqu''à ce que les pommes de terre soient tendres et que la sauce soit très épaisse. Ajouter les tomates coupées et retirer du feu.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["riz"], "instruction": "Servir avec du riz.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Sers 8.", "step_number": 6}]', 'https://img.spoonacular.com/recipes/657095-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.465306', '2026-01-19 18:23:17.465306', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '657095');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('2df57704-9950-4144-89ea-1840fde40100', 'Bateta Poha', 'La recette Bateta Poha peut être faite en environ 45 minutes. Cette recette sert 4 $ et coûte 2,02 $ par portion. Tu regardes ta figure ? Cette recette sans gluten, sans lait, lacto ovo végétarien et végétalien a 1032 calories, 19g de protéines et 41g de graisse par portion. 1 personne a trouvé cette recette délicieuse et satisfaisante. Cette recette de Foodista nécessite du sucre, du jus de citron, de la coriandre et des feuilles de curry. Il fonctionne bien comme un cours principal plutôt bon marché. Tout compte fait, nous avons décidé que cette recette mérite un score cuilleré de 93%. Ce score est super. Batata Poha. Comment faire Aloo Poha. Bataka Pauaa, Kanda Batata Poha , Comment faire Aloo Poha sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["colander"], "ingredients": ["huile de tournesol", "pommes de terre", "eau"], "instruction": "Placer le poha dans une petite calandre et verser sur l''eau à moitié bouillie. Mettez de côté. Laver et sécher les pommes de terre en cubes, puis faire frire l''huile de tournesol jusqu''à ce qu''elle soit dorée.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Égoutter sur du papier de cuisine et réserver.", "step_number": 2}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["piment", "gingembre", "oignon", "noix", "huile de cuisson"], "instruction": "Chauffer 2 c. à soupe d''huile dans une grande casserole et ajouter les oignons hachés, le gingembre, les noix et le piment. Cuire jusqu''à ce que les arômes et les noix soient dorés. Ne la laissez pas devenir trop brune.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["feuilles de curry", "graines de cumin", "asafoetida", "curcuma"], "instruction": "Ajouter les graines de cumin, le curcuma, l''asafoetida et les feuilles de curry. Sauter 30 secondes.", "step_number": 4}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["fenouil moulu", "pommes de terre", "grains", "poivre", "citron", "sucre", "sel"], "instruction": "Ajouter la poudre de fenouil et les pommes de terre et bien mélanger. Séparer doucement les grains de poha refroidis avec une fourchette et les ajouter à la poêle. Assaisonner de sel, de sucre, de citron et de poivre. Ajouter délicatement dans la poêle et retirer de la chaleur.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["coriandre"], "instruction": "Garnir de coriandre hachée.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servir aux amis et à la famille affamés seulement si vous avez réussi à vous abstenir de se moquer de tout le lot après la cuisine.", "step_number": 7}]', 'https://img.spoonacular.com/recipes/634452-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.470061', '2026-01-19 18:23:17.470061', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": true}', 'spoonacular', '634452');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('a1f9d6ab-d2dc-4330-a624-6f3cb7b548c5', 'Minétrone', 'Vous ne pouvez jamais avoir trop de recettes méditerranéennes, alors essayez Minestrone. Tu regardes ta figure ? Cette recette sans gluten contient 403 calories, 15g de protéines et 12g de graisse par portion. Cette recette sert 9 $ et coûte 1,35 $ par portion. De la préparation à l''assiette, cette recette prend environ 45 minutes. Cette recette de Foodista nécessite du sel, du poivre, des pommes de terre et des tomates en conserve. 2 personnes ont essayé et aimé cette recette. Il fonctionne bien comme un cours principal abordable. Tout compte fait, nous avons décidé que cette recette mérite un score cuilleré de 78%. Ce score est bon. Si vous aimez cette recette, vous aimerez aussi des recettes comme The Vegetable Broth et the Minestrone — Le bouillon de légumes et la minestrone, Minestrone et Minestrone.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 20}, "equipment": [], "ingredients": ["choux", "carotte", "beurre", "céleri", "ail", "oignon", "soupe"], "instruction": "Faire fondre le beurre dans une grande bouilloire à soupe; faire revenir les carottes, le céleri, les oignons, l''ail et le chou, environ 20 minutes; remuer souvent.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 30}, "equipment": [], "ingredients": ["cube de bouillon", "assaisonnement", "pommes de terre", "tomates", "courgettes", "eau", "riz"], "instruction": "Ajouter les tomates, l''eau, le riz, les assaisonnements, les pommes de terre, les cubes de bouillon et les courgettes. Porter à ébullition. Réduire le feu et laisser mijoter au moins 30 minutes.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["épinards", "haricots", "eau"], "instruction": "Ajouter les haricots et les épinards; revenir à ébullition et cuire à feu moyen jusqu''à ce que les épinards soient cuits; ajouter plus d''eau si nécessaire.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["parmesan"], "instruction": "Garnir de Parmesan.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Pour 9", "step_number": 5}]', 'https://img.spoonacular.com/recipes/651922-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.47611', '2026-01-19 18:23:17.47611', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '651922');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('1bce5f72-23cc-4131-b44c-2ae9fefb4a49', 'Barres de café amande', 'Amandes Bars est un dessert qui sert 1. Une portion contient 4340 calories, 64g de protéines et 235g de graisses. Pour 7,23 $ par portion, cette recette couvre 63% de vos besoins quotidiens en vitamines et minéraux. Pas beaucoup de gens ont vraiment aimé ce plat du Sud. 4 personnes ont été impressionnées par cette recette. De la préparation à l''assiette, cette recette prend environ 45 minutes. Cette recette de Foodista nécessite un extrait d''amande, sucre de confiserie, chocolat au lait recouvert d''une tasse d''amande et de margarine. Dans l''ensemble, cette recette gagne un score cuilleré exceptionnel de 82 %. Les barres de café amande, les barres de café amande croquante et les barres de café amande sont très semblables à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Préchauffer le four à 350 degrés (325 si vous utilisez un plat en verre)", "step_number": 1}, {"duration": null, "equipment": ["boîte à cuisson", "bol"], "ingredients": ["sucre en poudre", "margarine", "farine de tous usages"], "instruction": "Dans un bol moyen, mélanger la farine et le sucre glaçant, coupés en margarine jusqu''à miettes. Appuyez fermement sur le fond de 13X9 dans la poêle.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 15}, "equipment": ["four"], "ingredients": [], "instruction": "Faire cuire 15 minutes.", "step_number": 3}, {"duration": null, "equipment": ["bol"], "ingredients": ["extrait d''amande", "lait condensé sucré", "œuf"], "instruction": "Pendant ce temps, dans un grand bol, mélanger le lait condensé, l''oeuf et l''extrait d''amande", "step_number": 4}]', 'https://img.spoonacular.com/recipes/632197-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.480922', '2026-01-19 18:23:17.480922', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '632197');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('516e98c4-6504-4be6-bb8f-1acdd9be00f2', 'Biscuit viennois', 'Viennoise Biscuit pourrait être une bonne recette pour élargir votre boîte de recettes dessert. Cette recette sert 26. Pour 11 cents par portion, cette recette couvre 1 % de vos besoins quotidiens en vitamines et minéraux. Une portion contient 87 calories, 1g de protéines et 7g de graisse. 1 personne était heureuse qu''ils aient essayé cette recette. De la préparation à l''assiette, cette recette prend environ 45 minutes. Si vous avez une double crème, des gouttes de chocolat au lait, 2 grammes 40 sucre glace, et quelques autres ingrédients à la main, vous pouvez le faire. Il vous est apporté par Foodista. Tout compte fait, nous avons décidé que cette recette mérite un score cuilleré de 8%. Ce score est très mauvais (mais toujours fixable). Les utilisateurs qui ont aimé cette recette ont également aimé Viennese Fudge, les cookies viennois et le café viennois.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Préchauffer le four à 170C ventilateur/190C/375F/gaz marque", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["beurre"], "instruction": "Graisse (avec beurre) deux plateaux de cuisson", "step_number": 2}, {"duration": null, "equipment": ["bol"], "ingredients": ["extrait de vanille", "sucre en poudre", "fécule de maïs", "beurre", "farine de tous usages"], "instruction": "Dans un bol, déposer le beurre (175g). Siroter le sucre glace (40g) sur le beurre. Battre le mélange jusqu''à ce qu''il soit agréable et crémeux. Incorporer 1tsp d''extrait de vanille. Siroter la farine (175g) et la farine de maïs (40g) sur le mélange. Incorporez-les jusqu''à ce qu''ils soient doux. Prenez 1 cuillère à soupe du mélange et formez-le en une petite boule. Faites autant de petites boules que vous pouvez et placez-les sur un plateau laissant des espaces entre eux. Aplatissez chaque boule de mélange légèrement avec le dos d''une cuillère.", "step_number": 3}]', 'https://img.spoonacular.com/recipes/664825-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.483931', '2026-01-19 18:23:17.483931', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '664825');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('9c7f0b9c-b481-43d1-bc07-66bf5b810ba9', 'Cupcakes Brownie', 'Brownie Cupcakes est une recette américaine qui sert 24. Ce dessert contient 123 calories, 2g de protéines et 7g de graisse par portion. Pour 21 cents par portion, cette recette couvre 3 % de vos besoins quotidiens en vitamines et minéraux. C''est une bonne option si vous suivez un régime lacto ovo végétarien. Un mélange de farine, d''extrait de vanille, d''oeufs et d''une poignée d''autres ingrédients est tout ce qu''il faut pour rendre cette recette si savoureuse. 2 personnes ont fait cette recette et la feraient à nouveau. Il vous est apporté par Foodista. De la préparation à l''assiette, cette recette prend environ 45 minutes. Tout compte fait, nous avons décidé que cette recette mérite un score cuilleré de 13 %. Ce score est plutôt mauvais. Des recettes similaires sont Brownie Cupcakes, Brownie Cupcakes et Brownie Cupcakes.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["poulet", "four"], "ingredients": [], "instruction": "Préchauffer le four à 325 degrés F (170 degrés Celsius). Turbo grilleur 150 degrés", "step_number": 1}, {"duration": null, "equipment": ["casserole", "bol"], "ingredients": ["chocolat", "beurre", "eau"], "instruction": "Faire fondre le chocolat haché et le beurre dans un bol en acier inoxydable placé sur une casserole d''eau mijotée. Une fois le chocolat fondu et lisse, retirer du feu et laisser refroidir quelques minutes", "step_number": 2}, {"duration": null, "equipment": ["mélangeur à main"], "ingredients": ["sucre"], "instruction": "Puis remuer (peut également utiliser un mélangeur à main) dans le sucre.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["vanille", "œuf"], "instruction": "Ajouter la vanille et ajouter les œufs, un à la fois, bien mélanger après chaque ajout.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["farine de tous usages", "sel"], "instruction": "Mélanger la farine et le sel jusqu''à bien mélanger.", "step_number": 5}, {"duration": null, "equipment": ["liners à muffins"], "ingredients": [], "instruction": "Divisez uniformément la pâte entre les tasses de muffin.", "step_number": 6}, {"duration": {"unit": "minutes", "number": 40}, "equipment": ["four", "poulet"], "ingredients": [], "instruction": "Mettre au four préchauffé et cuire pendant environ 20 à 25 minutes. Pour grilleur turbo 150 Degrees pendant 13-15 minutes.", "step_number": 7}, {"duration": null, "equipment": ["porte-fils", "four"], "ingredients": ["cupcakes", "givrage"], "instruction": "Retirer du four et laisser refroidir sur une grille. Une fois que les cupcakes ont complètement refroidi, geler avec glaçage.", "step_number": 8}]', 'https://img.spoonacular.com/recipes/636331-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.487323', '2026-01-19 18:23:17.487323', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '636331');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('54b1f5f9-923c-4891-844e-7407f1df1d8c', 'Chocolat Orange Madeleines', 'Chocolat Orange Madeleines pourrait être une bonne recette pour élargir votre boîte de recettes dessert. Une portion de ce plat contient environ 6g de protéines, 12g de graisses et un total de 257 calories. Cette recette sert 8. Pour 98 cents par portion, cette recette couvre 9 % de vos besoins quotidiens en vitamines et minéraux. Allez au magasin et ramassez du jus d''orange, du zeste d''orange, du chocolat et quelques autres choses pour le faire aujourd''hui. Cette recette est appréciée par 3 gourmets et cuisiniers. De la préparation à l''assiette, cette recette prend environ 45 minutes. Il vous est apporté par Foodista. C''est une bonne option si vous suivez un régime sans lait et lacto ovo végétarien. Tout compte fait, nous avons décidé que cette recette mérite un score cuilleré de 32%. Ce score est plutôt mauvais. Si vous aimez cette recette, regardez ces recettes similaires : Les madeleines orange et chocolat noir, les Madeleines oranges et les Madeleines oranges.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["bol", "four"], "ingredients": ["madeleine", "poudre à pâte", "farine de tous usages", "sel"], "instruction": "Préchauffer le four à 374F. Graisser généreusement et fariner généreusement une boîte à biscuits madeleine. Dans un petit bol, mélanger la farine, la poudre à pâte et le sel.", "step_number": 1}, {"duration": null, "equipment": ["fouet", "bol"], "ingredients": ["jus d''orange", "zeste d''orange", "beurre", "farine de tous usages", "sucre", "œuf"], "instruction": "Fouetter ensemble et réserver. Dans un bol moyen, battre le sucre et les œufs à vitesse moyenne/élevée jusqu''à ce que le volume triple en taille. Cela peut prendre plusieurs minutes et vous devriez avoir un beau \"ribbon\" épais de pâte lorsque vous soulevez les batteurs hors du bol. Incorporer le jus d''orange et le zeste d''orange. En commençant par le mélange de farine, ajouter le beurre fondu à la pâte d''oeufs/sucre.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 45}, "equipment": [], "ingredients": ["madeleine", "cookies", "étendue", "pâte"], "instruction": "Mélanger seulement jusqu''à ce qu''il se combine. Réfrigérer pendant environ 45 minutes à une heure. Déposer par cuillère à café arrondie pleines dans le centre des moules madeleine. Laissez la pâte bombée, ne la répandez pas. J''ai trouvé que je devais ajouter plus qu''une cuillère à café, donc ajuster en conséquence pour la taille de votre moule. Ne vous inquiétez pas si la pâte ne remplit pas tout le moule. Les cookies prendront le joli modèle indépendamment de leur taille.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 12}, "equipment": ["four"], "ingredients": ["cookies"], "instruction": "Cuire 10 à 12 minutes ou jusqu''à ce que les bords commencent à tourner l''or et que le centre des biscuits ressorte lorsqu''ils sont légèrement touchés.", "step_number": 4}, {"duration": null, "equipment": ["papier à pâtisserie", "casserole", "four"], "ingredients": ["chocolat", "cookies", "trempette"], "instruction": "Retirer du four et tapoter immédiatement l''étain sur le comptoir pour desserrer les cookies. Enlevez soigneusement les cookies et laissez-les refroidir complètement. Préparer le chocolat : Faire fondre le chocolat dans une casserole et verser dans un plat profond ou une tasse avec une grande bouche. Déposer la moitié ou le quart de chaque cookie dans le chocolat et placer sur un morceau de papier parchemin jusqu''à ce que le chocolat soit prêt.", "step_number": 5}]', 'https://img.spoonacular.com/recipes/639125-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.48956', '2026-01-19 18:23:17.48956', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '639125');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('ecdaaed6-dc14-44d9-be08-06b4f1f82967', 'Brownies de baies de Boysen', 'Si vous voulez ajouter plus de recettes américaines à votre boîte de recettes, Boysenberry Brownies pourrait être une recette que vous devriez essayer. Cette recette sert 16 cents par portion. Une portion de ce plat contient environ 3g de protéines, 10g de graisses et un total de 164 calories. Il fonctionne mieux comme un dessert, et est fait en environ 45 minutes. Cette recette de Foodista nécessite du chocolat carré, des œufs, des noix et du sucre granulé. Cette recette est appréciée par 1 foodies et cuisiniers. En tenant compte de tous les facteurs, cette recette gagne un score cuilleré de 15%, ce qui est plutôt mauvais. Si vous aimez cette recette, vous aimerez aussi des recettes comme Boysenberry Cobbler, Boysenberry Pancakes et Boysenberry Cobbler.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["chocolat", "beurre", "crème", "sucre", "confiture"], "instruction": "C''est une de mes recettes préférées. C''est incroyablement facile à faire, et c''est délicieux. Une mise en garde: si vous devez utiliser une confiture achetée au magasin au lieu de maison, vous serez frappé par l''éclaircissement. Faire fondre le chocolat. Crèmer le beurre et le sucre.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["chocolat", "œuf"], "instruction": "Ajouter les œufs battus et bien mélanger, puis remuer progressivement dans le chocolat refroidi.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["noix", "farine de tous usages"], "instruction": "Ajouter la farine et mélanger. Incorporer les noix.", "step_number": 3}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["confiture"], "instruction": "Mettre la pâte dans une casserole de 9\" beurrée. Déposer des cuillères à café de la confiture au hasard sur la pâte. Puis tourner la confiture avec une fourchette pour l''incorporer dans la pâte.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 25}, "equipment": ["cure-dents", "four"], "ingredients": ["cookies"], "instruction": "Cuire à 350 pendant 25 minutes ou jusqu''à ce que le cure-dent soit presque propre; ne pas surcuire./COOKIES", "step_number": 5}]', 'https://img.spoonacular.com/recipes/635754-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.492131', '2026-01-19 18:23:17.492131', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '635754');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('da950e9b-a259-4e5c-95ff-73a258f1a9ad', 'Autres', 'Brownies prend environ 45 minutes du début à la fin. Pour 3,89 $ par portion, vous obtenez un dessert qui sert 1. Surveiller votre silhouette ? Cette recette végétarienne lacto ovo a 2149 calories, 29g de protéines et 120g de graisse par portion. Allez au magasin et ramassez la farine, la vanille, les noix, et quelques autres choses à faire aujourd''hui. 1 personne a trouvé cette recette délicieuse et satisfaisante. Il vous est apporté par Foodista. Seulement quelques personnes ont vraiment aimé ce plat américain. Avec un score cuilleré de 66%, ce plat est solide. Si vous aimez cette recette, regardez ces recettes similaires : Douce et salée Marronneries: Chocolat noir Brownies de Fudge avec Dulce De Leche, Mississippi Mud Brownies {AKA Brownies de marshmallow grosted}, et Mississippi Mud Brownies {AKA Brownies de marshmallow grosted}.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": [], "instruction": "Mélanger les ingrédients dans l''ordre indiqué.", "step_number": 1}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": [], "instruction": "Lignez une poêle carrée de sept pouces avec du papier paraffine.", "step_number": 2}, {"duration": null, "equipment": ["four", "couteau", "poêle à frire"], "ingredients": ["étendue"], "instruction": "Répartir uniformément le mélange dans la poêle et cuire dans un four lent. Dès qu''il est pris du four, tourner de la poêle, retirer le papier et couper le gâteau en lanières, à l''aide d''un couteau tranchant.", "step_number": 3}]', 'https://img.spoonacular.com/recipes/636342-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.494749', '2026-01-19 18:23:17.494749', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '636342');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('3ac15553-c034-4392-9d0e-7ae96200d6d2', 'Pâte à framboises', 'Vous ne pouvez jamais avoir trop de recettes de dessert, alors donnez un coup de gâteau à la truffe framboise. Une portion contient 471 calories, 5g de protéines et 28g de graisse. Cette recette sert 10 $ et coûte 1,66 $ par portion. Cette recette est appréciée par 1 foodies et cuisiniers. Si vous avez des œufs, de la confiture de framboise, du sucre et quelques autres ingrédients à la main, vous pouvez le faire. De la préparation à l''assiette, cette recette prend environ 45 minutes. Il vous est apporté par Foodista. Dans l''ensemble, cette recette rapporte un score assez mauvais de cuilleraculaire de 24 %. Des recettes similaires sont les framboises Cake Pops, Blackberry-Raspberry Truffle Cake et Raspberry Truffle Tart.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["casserole"], "ingredients": ["chocolat", "beurre"], "instruction": "Dans une grande casserole, mélanger le chocolat et le beurre.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["chocolat"], "instruction": "Chauffer jusqu''à ce que le chocolat fond.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["jaune d''œuf", "liqueur", "farine de tous usages", "sucre"], "instruction": "Retirer du feu et ajouter le sucre, la farine et la liqueur. À l''aide d''une cuillère, battre les jaunes d''oeufs un à la fois jusqu''à ce qu''ils soient combinés. Mettez de côté.", "step_number": 3}, {"duration": null, "equipment": ["bol mélangeur"], "ingredients": ["blancs d''œufs", "chocolat"], "instruction": "Dans un bol à mélanger, battre les blancs d''œufs jusqu''à ce qu''ils soient raides. Pliez dans le mélange de chocolat.", "step_number": 4}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": [], "instruction": "Verser dans une poêle graissée à ressort de 8 pouces.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 60}, "equipment": ["four"], "ingredients": [], "instruction": "Cuire au four à 350 degrés pendant 25-30 minutes jusqu''à ce qu''il soit gonflé. Laisser refroidir sur un support pendant 30 minutes.", "step_number": 6}, {"duration": {"unit": "minutes", "number": 1440}, "equipment": [], "ingredients": [], "instruction": "Retirer le côté des casseroles et laisser refroidir complètement. Du froid, couvert, pendant 4-24 heures.", "step_number": 7}, {"duration": null, "equipment": ["casserole"], "ingredients": ["confiture"], "instruction": "Faire chauffer la confiture dans une petite casserole jusqu''à ce qu''elle fond. Pour servir, arroser la confiture sur chaque assiette, garnir de tranches de gâteau.", "step_number": 8}, {"duration": null, "equipment": [], "ingredients": ["crème fouettée", "framboises"], "instruction": "Garnir de crème fouettée et de framboises fraîches.", "step_number": 9}]', 'https://img.spoonacular.com/recipes/657912-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.497044', '2026-01-19 18:23:17.497044', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '657912');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('4f601644-d7db-4766-bec7-fc163a4c1318', 'Pains plats à tapénade d''olive', 'Si vous voulez ajouter plus de recettes végétariennes lacto ovo à votre boîte de recettes, Olive Tapenade Flatbread pourrait être une recette que vous devriez essayer. Cette recette sert 4. Pour 1,8 $ par portion, cette recette couvre 6% de vos besoins quotidiens en vitamines et minéraux. Une portion de ce plat contient environ 13g de protéines, 25g de graisses et un total de 404 calories. Seulement quelques personnes ont fait cette recette, et 4 disent qu''elle a atteint l''endroit. Un mélange d''olives kalamatan, huile d''olive extra vierge, huile d''olive extra vierge, et une poignée d''autres ingrédients sont tout ce qu''il faut pour rendre cette recette si délicieuse. De la préparation à l''assiette, cette recette prend environ 20 minutes. Il vous est apporté par Foodista. Globalement, cette recette gagne un score cuilleraculaire pas si étonnant de 26%. Les utilisateurs qui ont aimé cette recette ont aussi aimé Olive Tapenade Flatbread, Olive Tapenade Flatbread et Olive Tapenade Flatbread.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 20, '[{"duration": {"unit": "minutes", "number": 3}, "equipment": ["grille"], "ingredients": ["huile d''olive", "naan"], "instruction": "Préchauffer le barbecue grill à moyennement haut. Utilisez la cuillère à soupe d''huile d''olive pour brosser les deux côtés du naan. Griller pendant 3 minutes de chaque côté", "step_number": 1}, {"duration": null, "equipment": ["processeur alimentaire"], "ingredients": ["olives", "saumure", "jus"], "instruction": "Placer les olives et 6 à 8 cuillères à café de jus d''olive/saumure (vous pouvez mélanger les deux sortes) dans un robot culinaire et le pouls jusqu''à ce qu''il ait une texture plus fine mais pas lisse (vous voudrez encore voir des morceaux d''olives).", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["tapenade d''olive", "étendue", "naan"], "instruction": "Étendre cette tapenade d''olive sur un côté de chaque naan.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["mozzarella"], "instruction": "Ajouter les morceaux du fromage mozzarella.", "step_number": 4}, {"duration": null, "equipment": ["grille"], "ingredients": ["vinaigre balsamique", "pain plat", "rouille", "fromage", "naan"], "instruction": "Replacez le naan sur le grill et faites cuire jusqu''à ce que le fond soit brun et croustillant et que le fromage fond. Mélanger la roquette avec le vinaigre balsamique et ajouter la roquette au pain plat cuit.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["huile d''olive"], "instruction": "Arrosez les pains plats avec plus d''huile d''olive.", "step_number": 6}]', 'https://img.spoonacular.com/recipes/1098351-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.499983', '2026-01-19 18:23:17.499983', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '1098351');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('80b8be70-ae47-41b3-a680-1a12415bcb6b', 'Fromage grillé au poulet Buffalo', 'Buffalo Chicken Grilled Cheese est une recette végétarienne lacto ovo avec 1 portions. Pour 1,11 $ par portion, cette recette couvre 15 % de vos besoins quotidiens en vitamines et minéraux. Une portion contient 418 calories, 19g de protéines et 25g de graisse. Cette recette de cuilleraculaire érableroad nécessite la trempette de poulet, pain, beurre et fromage cheddar d''Erich. Il est parfait pour le 4 juillet. Il fonctionne mieux comme un cours principal, et se fait en environ 45 minutes. Fromage grillé de poulet de Buffalo et comment prendre une photo de fromage grillé épique, fromage grillé de poulet de Buffalo et comment prendre une photo de fromage grillé épique, et Sandwich au fromage grillé de Mary avec poulet de Buffalo épicé, Popper Jack et bleu Le fromage est très similaire à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["beurre", "pain"], "instruction": "Beurrer l''extérieur de deux tranches de pain.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["Fromage bleu", "étendue", "pain"], "instruction": "Ensuite, retournez le pain et saupoudrez un peu de fromage bleu émietté ou étalez une fine couche sur une tranche de pain.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["fromage cheddar"], "instruction": "Ensuite, saupoudrer sur autant de fromage cheddar que vous voulez.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["plongée de poulet de bison", "pain"], "instruction": "Enfin, à l''aide d''une cuillère, couchez sur une partie de cette trempette de poulet de Buffalo et placez le deuxième morceau de pain sur le dessus.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 2}, "equipment": ["poêle à frire"], "ingredients": ["fromage"], "instruction": "Réchauffez votre poêle à feu moyen et faites cuire le sandwich environ 2 minutes par côté, ou jusqu''à ce qu''il soit légèrement grillé brun et le fromage est sur les côtés.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["frites", "boisson"], "instruction": "Prenez un verre froid, des chips, et profitez!", "step_number": 6}]', 'https://img.spoonacular.com/recipes/1697591-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.503207', '2026-01-19 18:23:17.503207', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '1697591');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('657c96f9-d63e-4c85-ad76-3d72ac1a5567', 'Tomate grillée Crostini avec tapenade d''olive', 'Vous ne pouvez jamais avoir trop de recettes méditerranéennes, alors essayez la tomate rôtie Crostini avec Olive Tapenade. Pour 1,47 $ par portion, vous obtenez un hors-d''oeuvre qui sert 10. Une portion contient 352 calories, 14g de protéines et 27g de graisse. Peu de gens ont fait cette recette, et je dirais qu''elle a atteint l''endroit. De la préparation à l''assiette, cette recette prend environ 45 minutes. Il vous est apporté par Foodista. Un mélange de tomates à la prune, girofles d''ail, poivre de plat, et une poignée d''autres ingrédients sont tout ce qu''il faut pour faire cette recette si délicieux. Compte tenu de tous les facteurs, cette recette gagne un score cuilleré de 37%, ce qui est plutôt mauvais. Si vous aimez cette recette, regardez ces recettes similaires : Cod rôti avec tapenade chaude à la tomate-olive-caper, cod rôti avec tapenade chaude à la tomate-olive-caper, et cod rôti avec tapenade chaude à la tomate-olive-caper.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Chauffer le four à 40", "step_number": 1}, {"duration": null, "equipment": ["bol mélangeur"], "ingredients": ["poivre noir moulu", "huile d''olive", "sel de mer", "tomates"], "instruction": "Dans un grand bol à mélanger, mélanger les tomates à moitié avec une bruine saine d''huile d''olive, arroser de sel de mer et verser le poivre noir jusqu''à ce que toutes les tomates soient belles et lisses.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 60}, "equipment": ["plaque de cuisson", "four"], "ingredients": ["tomates"], "instruction": "Déposer la peau des tomates sur une plaque à cuisson plate et mettre au four environ 30 minutes. **Notez que certains temps peuvent varier pour cuire un peu plus longtemps en fonction de l''épaisseur de la tomate, marque du four. À 30 minutes ce que vous recherchez est le début d''un char plus foncé sur les tomates et une caramélisation satinée.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 180}, "equipment": ["four"], "ingredients": [], "instruction": "Retirez le plateau du four après avoir assisté au changement. Vous laisserez cela assis pendant au moins 2-3 heures jusqu''à la température ambiante.", "step_number": 4}, {"duration": null, "equipment": ["processeur alimentaire"], "ingredients": ["huile d''olive", "ail", "olives"], "instruction": "Dans un robot culinaire, mélanger les olives, l''ail écrasé, un autre bruissement d''huile d''olive si votre robot a besoin d''aide pour couper les olives et l''ail. Vous voulez que la texture soit un mélange légèrement chunky mais extensible, pas une pâte mince, une certaine texture est bonne.", "step_number": 5}, {"duration": null, "equipment": ["bol"], "ingredients": ["basilic frais", "parmigiano reggiano"], "instruction": "Retirer dans le bol et mélanger dans une saupoudrée de parmigiano, déchirer dans 5 feuilles de basilic.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": ["baguette"], "instruction": "Couper la baguette en tranches minces sur un biais de sorte que vous avez au moins 10 tranches.", "step_number": 7}, {"duration": null, "equipment": ["poulet", "four"], "ingredients": ["huile d''olive", "baguette", "pain sandwich"], "instruction": "Badigeonner légèrement les deux côtés d''huile d''olive et les griller délicatement sous le gril. Vous devez surveiller la couleur dès qu''elle devient un brun doré clair (ce qui se produit rapidement sous un grilleur). Flipez les tranches de baguette et retournez au four pour croquer l''autre côté.", "step_number": 8}, {"duration": null, "equipment": ["four"], "ingredients": ["bandes magnétiques", "étendue", "tomates"], "instruction": "À mesure que les tranches sont retirées du four et refroidies, étaler la tapenade sur chaque tranche et garnir d''une moitié tomate, côté peau vers le haut.", "step_number": 9}, {"duration": null, "equipment": [], "ingredients": ["basilic frais"], "instruction": "Chiffonade restant 5 feuilles de basilic et saupoudrer sur le dessus.", "step_number": 10}]', 'https://img.spoonacular.com/recipes/658682-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.505631', '2026-01-19 18:23:17.505631', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '658682');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('8fd5e01d-62ec-479a-bee8-fc2c4e678470', 'Graisse grillée', 'La graisse grillée pourrait être juste la recette middl est que vous recherchez. Une portion de ce plat contient environ 9g de protéines, 18g de graisses et un total de 295 calories. Pour 2,17 $ par portion, vous obtenez un plat d''appoint qui sert 6. Le Quatrième De Juillet sera encore plus spécial avec cette recette. Un mélange de concombre, d''huile d''olive, de citron et une poignée d''autres ingrédients sont tout ce qu''il faut pour rendre cette recette si savoureux. C''est une bonne option si vous suivez un régime lacto ovo végétarien. De la préparation à l''assiette, cette recette prend environ 45 minutes. 2 personnes ont essayé et aimé cette recette. Il vous est apporté par Foodista. En tenant compte de tous les facteurs, cette recette gagne un score cuilleré de 81%, ce qui est génial. Si vous aimez cette recette, regardez ces recettes similaires : Le gras gras grillé, le gras gras grillé et l''espadon grillé sur le gras.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["grille"], "ingredients": ["courgettes", "poivrons", "pita", "graines"], "instruction": "Préchauffer le gril à haute température. Couper les courgettes dans le sens de la longueur et couper les poivrons en gros morceaux et retirer les graines. Séparer les couches des pitas pour faire 6 cercles de pita.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["sel et poivre", "huile d''olive", "courgettes", "poivrons", "pita"], "instruction": "Arrosez l''huile d''olive sur les courgettes, les poivrons et les pitas, salez-les et poivrez-les.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 4}, "equipment": ["grille", "bol"], "ingredients": ["herbes", "pita", "fromage feta", "rouleau", "huile de cuisson"], "instruction": "Faites-les rouler pour qu''ils aient une bonne couche d''huile. Faire griller les légumes pendant environ 2-3 minutes de chaque côté, jusqu''à ce que de belles marques de grill se forment et que les légumes soient légèrement tendres. Puis faire griller les pitas, pendant 1 minute de chaque côté, jusqu''à ce qu''ils soient grillés. Dans un grand bol, ajouter tous les autres légumes et herbes. Une fois les légumes grillés refroidis, les hacher dans des cubes de pouce et les ajouter dans le bol de service. Découpez les pitas en morceaux et ajoutez au mélange. Mélanger la salade et saupoudrer le feta sur le dessus.", "step_number": 3}, {"duration": null, "equipment": ["fouet", "bol"], "ingredients": ["sel et poivre", "huile d''olive", "cumin", "jus", "citron"], "instruction": "Mélanger la tasse d''huile d''olive et le jus d''un citron dans un petit bol. Assaisonner de cumin, sel, poivre et fouet.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Arroser la salade quand elle est prête à servir!", "step_number": 5}]', 'https://img.spoonacular.com/recipes/645704-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.513454', '2026-01-19 18:23:17.513454', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '645704');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('22481567-2e51-445a-a929-9352d0cc6b31', 'Chorizo et Crostini au fromage', 'Chorizo et Fromage Crostini est une recette méditerranéenne qui sert 1. Pour 9,43 $ par portion, cette recette couvre 44% de vos besoins quotidiens en vitamines et minéraux. Une portion de ce plat contient environ 114g de protéines, 143g de graisses et un total de 2092 calories. Allez au magasin et ramassez la baguette, 1⁄2 mélange de muenster et de fromage maisy, chorizo, et quelques autres choses à faire aujourd''hui. Il fonctionne mieux comme un hor d''oeuvre, et se fait en environ 45 minutes. 1 personne a été impressionnée par cette recette. Il vous est apporté par Foodista. En tenant compte de tous les facteurs, cette recette gagne un score cuilleré de 86%, ce qui est énorme. Des recettes similaires sont le fromage de chèvre et Chorizo Crostini, le fromage de chèvre et Chorizo Crostini, et Yuca Chorriada con Chorizo (Cassava avec Chorizo et sauce au fromage).', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Préchauffer le four à 400 degrés.", "step_number": 1}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": [], "instruction": "Chauffer une poêle en fonte de 12 pouces.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 8}, "equipment": ["cuillère en bois"], "ingredients": ["chorizo"], "instruction": "Ajouter le chorizo, le casser en morceaux avec une cuillère en bois et cuire à feu modéré, en tournant, jusqu''à ce que cuit et légèrement doré, environ 8 minutes.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Retirer du feu pour laisser refroidir. (Cette étape peut être faite et avance et réfrigérée toute la nuit.)", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["choux"], "instruction": "Grattez les fromages et le chou.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["baguette"], "instruction": "Couper la baguette en tranches 1/4 sur un léger angle diagonal.", "step_number": 6}, {"duration": null, "equipment": ["feuille d''aluminium"], "ingredients": [], "instruction": "Placer sur une plaque de cuisson. (Considérez la doublure avec du papier pour faciliter le nettoyage puisque vous allez cuillerer le mélange sur chaque tranche.)", "step_number": 7}, {"duration": null, "equipment": [], "ingredients": ["baguette", "choux", "chorizo", "fromage"], "instruction": "Mélanger le fromage et le chou avec le chorizo cuit. À l''aide d''une cuillère, garnir chaque tranche de baguette d''une ou deux cuillères.", "step_number": 8}, {"duration": {"unit": "minutes", "number": 10}, "equipment": ["four"], "ingredients": ["fromage", "pain"], "instruction": "Chauffer au four pendant 10 minutes pour laisser le fromage fondre et le pain pour obtenir croustillant.", "step_number": 9}]', 'https://img.spoonacular.com/recipes/639318-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.517097', '2026-01-19 18:23:17.517097', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '639318');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('e786b3e1-b848-4f2d-92e1-63f51750f971', 'Salade de saumon grillée avec de la vinaigrette orange de sang', 'Si vous avez environ 45 minutes à passer dans la cuisine, Salade de saumon grillée avec du sang Orange Cilantro Vinaigrette pourrait être une excellente recette sans gluten, sans lait, paléolithique et primal à essayer. Une portion contient 252 calories, 34g de protéines et 11g de graisses. Pour 4,45 $ par service, vous obtenez un plat principal qui sert 4. Cette recette de Foodista a 1 fans. Il peut être apprécié à tout moment, mais il est particulièrement bon pour le Quatrième de Juillet. Allez au magasin et ramassez des légumes verts, du concombre, des steaks de saumon, et quelques autres choses à faire aujourd''hui. Avec un score cuilleré de 32%, ce plat est plutôt mauvais. Essayez la salade de saumon grillé et de pamplemousse avec de la vinaigrette orange sang, la salade orange sang + gingembre et la vinaigrette orange sang Cayenne, et la salade de persimmon avec de la vinaigrette orange sang pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["feuille d''aluminium", "grille"], "ingredients": ["steak de saumon"], "instruction": "Placez les steaks de saumon sur une feuille d''aluminium sur une grille chauffée.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 9}, "equipment": ["grille"], "ingredients": ["sel et poivre", "tomates de raisins", "sang orange", "Verts mixtes", "vinaigrette", "coriandre", "concombre", "avocat", "verts", "jicama", "saumon", "salsa", "maïs"], "instruction": "Badigeonner de vinaigrette Blood Orange Cilantro et saupoudrer de sel et de poivre. Faire griller 6-9 minutes de chaque côté. Laver les verts mélangés et placer environ une poignée sur chaque assiette. Laver et demi tomates de raisin et saupoudrer de légumes verts. Couper le concombre et déposer sur les verts. Peler et jicama julienne et placer sur les verts. Disposer chaque tranche de saumon sur les verts et trancher. Portez la salsa de maïs avocat sur le saumon, et bruissez la vinaigrette d''orange de sang sur la salade. La salsa de maïs avocat et la vinaigrette de cilantro orange de sang sont listées comme recettes séparées dans mon fichier de recettes.", "step_number": 2}]', 'https://img.spoonacular.com/recipes/645849-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.519016', '2026-01-19 18:23:17.519016', '{"vegan": false, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": false, "veryHealthy": true}', 'spoonacular', '645849');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('9c1258c9-869f-405b-873d-517ea3c214a2', 'Salade de poulet turque avec sauce cacik yogourt maison', 'Vous ne pouvez jamais avoir trop de recettes de plat principal, alors donnez à la salade de poulet turque avec la sauce cacik yogourt faite maison un essai. Cette recette sert 4 $ et coûte 4,48 $ par portion. Tu regardes ta figure ? Cette recette sans gluten contient 643 calories, 67g de protéines et 30g de gras par portion. 9 personnes ont trouvé cette recette savoureuse et satisfaisante. Rendez-vous au magasin et ramassez du concombre lebanais, du poulet rôti, de l''ail et quelques autres choses pour le faire aujourd''hui. De la préparation à l''assiette, cette recette prend environ 45 minutes. Il vous est apporté par Foodista. Tout compte fait, nous avons décidé que cette recette mérite un score cuilleré de 95 %. Ce score est exceptionnel. Des recettes similaires incluent des Kabobs d''Agneau Spicy avec du Cacik turc, des Cuisses de poulet en jerk avec de la sauce chaude Mango-Habanero maison, et du Yogurt et du Cucumber Dip Cacik.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 30}, "equipment": ["bol"], "ingredients": ["concombre", "yaourt", "sel"], "instruction": "Préparez d''abord le Cacik: Pour le Cacik : Coupez le concombre en petits morceaux, aussi petits que possible, et placez-le dans un bol. Couvrir le concombre de sel et réserver 30 minutes. Les concombres commenceront à exsuder leurs jus qui parfumeront bien le yogourt.", "step_number": 1}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["huile d''olive", "poivrons"], "instruction": "Mettre un poêlon à feu moyen-élevé, couvrir les poivrons d''huile d''olive et commencer à carboniser.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["oignon rouge", "concombre", "persil", "tomates"], "instruction": "Couper la tomate et le concombre en morceaux moyens. Coupez l''oignon rouge aussi fin que possible. Coupez le persil bien.", "step_number": 3}, {"duration": null, "equipment": ["bol"], "ingredients": ["sel et poivre", "jus", "citron"], "instruction": "Mettre tous les ingrédients dans un bol et couvrir d''un jus de 1 citron. Assaisonner de sel et de poivre.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 90}, "equipment": [], "ingredients": ["jus"], "instruction": "Laisser reposer au réfrigérateur pendant 30 minutes 1 heure, en remuant quelques fois, donc il commence à exsuder le jus.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["laitue"], "instruction": "Attachez la laitue dans des pices à la bouche.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": ["chou rouge", "carotte"], "instruction": "Couper le chou rouge en tranches fines. Râper la carotte.", "step_number": 7}, {"duration": null, "equipment": ["bol"], "ingredients": [], "instruction": "Mélanger dans un bol.", "step_number": 8}, {"duration": null, "equipment": [], "ingredients": ["poulet"], "instruction": "Ajouter le poulet en gros morceaux et ajouter à la salade.", "step_number": 9}, {"duration": null, "equipment": [], "ingredients": ["tomates", "salsa"], "instruction": "Retirer la salsa tomate du réfrigérateur.", "step_number": 10}, {"duration": null, "equipment": [], "ingredients": ["concombre", "poulet", "persil", "tomates", "jus", "oignon"], "instruction": "Égoutter le jus et garder pour plus tard. Ajoutez maintenant la tomate, le concombre, le mélange d''oignon de persil à la salade de poulet, ainsi que le gherkin tranché.", "step_number": 11}, {"duration": null, "equipment": ["planche à découper"], "ingredients": [], "instruction": "Étendre la salade sur une grande assiette ou une planche à découper.", "step_number": 12}, {"duration": null, "equipment": [], "ingredients": ["vinaigrette", "poivrons", "piment", "salsa", "sauce"], "instruction": "Servir avec les poivrons carbonisés, cacik, salsa vinaigrette et un peu de sauce pimentée.", "step_number": 13}]', 'https://img.spoonacular.com/recipes/664090-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.521932', '2026-01-19 18:23:17.521932', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": true}', 'spoonacular', '664090');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('291dfb3c-406b-4b07-8cb8-5c5cab7fd076', 'Salade latérale de betterave d''été', 'Si vous avez environ 45 minutes à passer dans la cuisine, Summer Beet Side Salad pourrait être une excellente recette végétarienne sans gluten, sans lait, paléolithique et lacto ovo. Cette recette fait 3 portions avec 205 calories, 3g de protéines et 14g de graisse chacune. Pour 1,33 $ par portion, cette recette couvre 11 % de vos besoins quotidiens en vitamines et minéraux. Un mélange de betteraves, de concombre, de tomates et une poignée d''autres ingrédients sont tout ce qu''il faut pour rendre cette recette si savoureuse. Le Quatrième De Juillet sera encore plus spécial avec cette recette. Pas beaucoup de gens ont vraiment aimé cet hor d''oeuvre. Cette recette est appréciée par 1 foodies et cuisiniers. Il vous est apporté par Foodista. En tenant compte de tous les facteurs, cette recette gagne un score cuilleraculaire de 72%, qui est solide. Si vous aimez cette recette, vous aimerez peut-être aussi des recettes telles que Salade de betteraves à l''orge : côté végétalien brillant, Salade de betteraves rôties d''été, et Salade de betteraves grillées et de bleuets pour embrasser la fin de l''été.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["feuille d''aluminium", "serviettes en papier", "couteau"], "ingredients": ["sel de table", "huile d''olive", "betterave", "eau", "enveloppe"], "instruction": "Pour rôtir les betteraves : tranchez les tiges, lavez-les soigneusement, et enveloppez-les dans une poche en aluminium avec un filet d''huile d''olive et un peu de sel de table (essentiellement les placer sur un morceau de papier d''aluminium, et plier sur les bords pour faire une petite enveloppe serrée). Les betteraves prendront environ une heure pour rôtir à 350 degrés. Refroidir avant de manipuler. Ensuite, éplucher les peaux à l''aide d''une serviette en papier, le dos d''un couteau et/ou un peu d''eau fraîche. Laisser refroidir les betteraves (c''est une salade froide). Une fois cool, quart. Assemblez les ingrédients; arrosez l''huile d''olive sur le dessus de la salade et saupoudrez une touche de sel de table. De petites portions.", "step_number": 1}]', 'https://img.spoonacular.com/recipes/651467-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.526342', '2026-01-19 18:23:17.526342', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '651467');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('c6710b5c-48ff-41ee-b7a3-da4eed7dfe01', 'Pudding au pain de mûre', 'Si vous avez environ 45 minutes à passer dans la cuisine, Blackberry Pain Pudding pourrait être une recette végétarienne lacto ovo incroyable à essayer. Cette recette fait 12 portions avec 230 calories, 10g de protéines et 10g de graisse chacune. Pour 1,09 $ par portion, cette recette couvre 12 % de vos besoins quotidiens en vitamines et minéraux. 1 personne était heureuse qu''ils aient essayé cette recette. Allez au magasin et ramassez des haricots vanillés, du beurre, du lait, et quelques autres choses pour le faire aujourd''hui. Il vous est apporté par Foodista. Tout compte fait, nous avons décidé que cette recette mérite un score cuilleré de 34%. Ce score n''est pas si spectaculaire. Des recettes similaires comprennent la pudding au pain de Blackberry, la pudding au pain de blé entier avec des noix et de la sauce Blackberry, et la pudding au pain de pêche de Blackberry avec des pois grillés.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["casserole"], "ingredients": ["vanille", "beurre", "pain", "sauce", "lait"], "instruction": "Beurrer chaque tranche de pain des deux côtés. Mettre le lait dans une casserole lourde. Couper la vanille dans le sens de la longueur et ajouter au lait.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["lait"], "instruction": "Chauffer le lait à feu moyen jusqu''à ce qu''il soit presque bouillant.", "step_number": 2}, {"duration": null, "equipment": ["boîte à cuisson", "bol mélangeur", "fouet"], "ingredients": ["haricots vanille", "crème", "vanille", "pain", "graines", "sucre", "œuf", "lait"], "instruction": "Retirer les haricots vanillés et racler les graines dans le lait. Pendant que le lait chauffe, mettre les œufs, le sucre et la framboise dans un bol de mélange et fouetter jusqu''à ce que lisse. Après avoir gratté les graines de vanille dans le lait, fouetter lentement le lait chaud dans le mélange d''oeufs, créant une crème douce. Mettre quatre tranches de pain dans le fond d''un plat de cuisson non graissé de 3 po de profondeur avec couverture.", "step_number": 3}, {"duration": null, "equipment": ["four"], "ingredients": ["mûres", "crème", "eau"], "instruction": "Placer 1/2 des mûres sur 3Préchauffer le four à 350 degrés F. Couvrir le plat de crème et le placer au four, dans un autre plat plus grand, et ajouter de l''eau chaude au plat extérieur jusqu''à ce qu''il atteigne la moitié des côtés du plat intérieur.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 45}, "equipment": ["four"], "ingredients": ["crème", "eau"], "instruction": "Cuire 45 minutes. Préchauffer le four à 350 degrés F. Couvrir le plat de crème et le mettre au four, dans un autre plat plus grand, et ajouter l''eau chaude dans le plat extérieur jusqu''à ce qu''il atteigne la moitié des côtés du plat intérieur.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 45}, "equipment": ["four"], "ingredients": [], "instruction": "Cuire 45 minutes.", "step_number": 6}, {"duration": {"unit": "minutes", "number": 30}, "equipment": ["four"], "ingredients": ["eau"], "instruction": "Retirer le plat intérieur de l''eau et le retourner au four pendant encore 30 minutes. [NOTE: C''est là qu''il tend à m''énerver -)].", "step_number": 7}, {"duration": {"unit": "minutes", "number": 15}, "equipment": ["four"], "ingredients": [], "instruction": "Retirer la couverture [si elle n''a pas déjà été repoussée -)] et cuire pendant 15 minutes. Laisser refroidir (température ambiante, ou un peu chaud), couper et servir!", "step_number": 8}]', 'https://img.spoonacular.com/recipes/635186-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.544748', '2026-01-19 18:23:17.544748', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '635186');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('bf6b9687-0a79-4a63-9501-fc7fe081156d', 'Salade grecque', 'La salade grecque est un hor d''oeuvre qui sert 4. Surveiller votre silhouette? Cette recette sans gluten, lacto ovo végétarienne et primal a 277 calories, 7g de protéines et 23g de graisse par portion. Pour 1,9 $ par portion, cette recette couvre 15 % de vos besoins quotidiens en vitamines et minéraux. Seulement quelques personnes ont fait cette recette, et 3 disent qu''elle a atteint l''endroit. Il vous est apporté par Foodista. Un mélange de concombre, d''huile d''olive extra vierge, de tomates et une poignée d''autres ingrédients sont tout ce qu''il faut pour rendre cette recette si savoureux. De la préparation à l''assiette, cette recette prend environ 15 minutes. Cette recette est typique de la cuisine méditerranéenne. Tout compte fait, nous avons décidé que cette recette mérite un score cuilleré de 74%. Ce score est bon. Des recettes similaires incluent Fashoulakia (Greek Green Bean Side Dish), Fashoulakia (Greek Green Bean Side Dish) et Salade grecque d''Horiatiki (Salade grecque d''agriculteur traditionnel).', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 15, '[{"duration": null, "equipment": [], "ingredients": ["légumes"], "instruction": "Couper les légumes en morceaux", "step_number": 1}, {"duration": null, "equipment": ["bol"], "ingredients": ["huile d''olive"], "instruction": "Ajouter dans un bol à l''huile d''olive", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["fromage feta"], "instruction": "Placer le feta sur la salade ou casser en miettes", "step_number": 3}]', 'https://img.spoonacular.com/recipes/645348-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.527614', '2026-01-19 18:23:17.527614', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '645348');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('9ffbedf6-af99-43ff-bee0-f4523f84f194', 'Salade de pâtes rotini tricolores', 'Si vous avez environ 45 minutes à passer dans la cuisine, Tricolor Rotini pâtes Salade pourrait être une recette gratuite de lait incroyable à essayer. Une portion de ce plat contient environ 6g de protéines, 5g de graisses et un total de 146 calories. Pour 2,57 $ par portion, cette recette couvre 23 % de vos besoins quotidiens en vitamines et minéraux. Seulement quelques personnes ont fait cette recette, et je dirais qu''elle a atteint l''endroit. Il fonctionne bien comme un hor d''oeuvre plutôt bon marché. Cette recette de Foodista nécessite 2 c. à soupe de mayonnaise, des feuilles de laitue, des olives 10 nos et des n°s de tomate prune. Dans l''ensemble, cette recette gagne un bon score cuilleraculaire de 69%. Si vous aimez cette recette, regardez ces recettes similaires : Salade de pâtes de Tricolore, Salade de pâtes de Rotini arc-en-ciel et Salade de pâtes de Tri-Color.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["poêle à frire"], "ingredients": ["pâtes", "eau"], "instruction": "Faire bouillir l''eau dans une grande casserole. Une fois que l''eau arrive à la température bouillante immerger les pâtes. Tourner la chaleur", "step_number": 1}, {"duration": {"unit": "minutes", "number": 10}, "equipment": [], "ingredients": ["pâtes"], "instruction": "à baisser et cuire encore 10 minutes. Garde ça de côté jusqu''à ce qu''il se refroidisse. Ou cuire les pâtes selon", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "l''instruction donnée dans le colis.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["concombre", "laitue", "olives"], "instruction": "Hacher le concombre, les olives et la laitue.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["tomates prunes"], "instruction": "Couper les tomates en deux. Depuis Je n''avais pas de tomates aux prunes", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["tomates"], "instruction": "stocké, j''ai utilisé des tomates normales", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": ["mayonnaise", "poivre", "sel"], "instruction": "Mélanger la poudre de poivre et saler avec la mayonnaise.", "step_number": 7}, {"duration": null, "equipment": [], "ingredients": ["mayonnaise", "légumes", "pâtes"], "instruction": "Mélanger tous les légumes et la mayonnaise avec les pâtes et mélanger doucement.", "step_number": 8}]', 'https://img.spoonacular.com/recipes/663813-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.529122', '2026-01-19 18:23:17.529122', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '663813');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('df1987a7-2147-4aa8-82b2-21d4e138bd7f', 'Salade d''orzo avec légumes et herbes', 'Vous ne pouvez jamais avoir trop de recettes hor d''oeuvre, alors essayez la salade Orzo avec des légumes et des herbes. Tu regardes ta figure ? Cette recette sans lait contient 358 calories, 9g de protéines et 15g de gras par portion. Cette recette sert 8 cents par portion. Seulement quelques personnes ont fait cette recette, et je dirais qu''elle a atteint l''endroit. Allez au magasin et ramassez l''huile d''olive, la laitue de boston - en option, oignons verts dont 2 pouces de tige verte, et quelques autres choses à faire aujourd''hui. De la préparation à l''assiette, cette recette prend environ 45 minutes. Il vous est apporté par Foodista. Tout compte fait, nous avons décidé que cette recette mérite un score cuilleré de 92%. Ce score est énorme. Essayez la salade Orzo avec du poulet et des légumes, la salade Orzo avec du poulet et des légumes rôtis, et la poêle Orzo avec du poisson et des herbes pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["pot"], "ingredients": ["eau"], "instruction": "Pour faire la salade : Portez une grande casserole d''eau salée à ébullition.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 1}, "equipment": ["cuillère à fente", "tamis"], "ingredients": ["pois secs de sucre", "eau", "pois"], "instruction": "Ajouter les pois secs de sucre; cuire 1 minute, puis transférer les pois dans une passoire avec une cuillère à fentes. Rincer avec de l''eau froide et égoutter.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 8}, "equipment": ["pot"], "ingredients": ["orzo"], "instruction": "Ajouter l''orzo dans la même casserole. Faire bouillir jusqu''à tendreté mais encore ferme à mordre; environ 8 minutes.", "step_number": 3}]', 'https://img.spoonacular.com/recipes/654119-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.53273', '2026-01-19 18:23:17.53273', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '654119');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('dd7d4e03-17b3-452f-ad04-ac9b6b6ed26d', 'Sandwich aux oeufs à face ouverte avec bacon, asperges et pesto', 'Sandwich aux oeufs à visage ouvert avec bacon, asperges et pesto est un plat principal qui sert 4. Une portion de ce plat contient environ 27g de protéines, 42g de graisses et un total de 654 calories. Pour 4,2 $ par portion, cette recette couvre 43% de vos besoins quotidiens en vitamines et minéraux. 1 personne a été impressionnée par cette recette. Si vous avez du parmesan, des noix de pin, du basilic et quelques autres ingrédients à la main, vous pouvez le faire. Il vous est apporté par Foodista. De la préparation à l''assiette, cette recette prend environ 45 minutes. En tenant compte de tous les facteurs, cette recette gagne un score cuilleré de 80%, ce qui est excellent. Des recettes semblables comprennent des sandwichs aux oeufs à visage ouvert, des sandwichs au jambon et aux œufs à visage ouvert et des sandwichs au poulet à visage ouvert avec du pesto à l''artichaut.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"step": 1, "instruction": "Pour faire le pesto : Placer les feuilles d''épinards, les feuilles de basilic, l''ail haché, les noix de pin, le fromage parmesan et l''huile d''olive dans le bol d''un robot culinaire.</li><li> Pulse jusqu''à ce qu''une pâte se forme.</li><li> Réserver.</li><li> Pour rôtir les asperges et les pétoncles: Chauffer le four à 400 degrés.</li><li> Placer les asperges et les pétoncles dans une casserole 9x13 et arroser avec l''huile d''olive et le vinaigre balsamique.</li><li> Saupoudrer de sel et de poivre.</li><li> Faire cuire pendant environ 20 minutes ou jusqu''à ce qu''ils soient dorés.</li><li> Pour faire la salade de tomates et de concombres: Dans un bol moyen, mélanger la tomate hachée, le concombre haché et le basilic haché.</li><li> Arroser le jus de citron frais.</li><li> Saupoudrer de sel et de poivre au goût.</li><li> Pour faire le bacon et le toast bronzé : Faire frire les tranches de bacon sur une grille à feu moyen.</li><li> Une fois que les deux côtés ont croqué, retirer de la grille et placer sur une serviette en papier.</li><li> Ne pas égoutter la graisse de bacon, utilisez cette poêle pour griller les tranches de pain. Placez les tranches de pain aurifère sur la grille et le bronze de chaque côté.</li><li> Retirer le feu une fois que les deux côtés ont bruni</li><li> Pour l''œuf frit: faire fondre le beurre dans la poêle à feu moyen.</li><li> Pour obtenir l''oeuf en forme de cœur, nous avons fissuré les œufs dans Norpro Nonstick Heart et Pancake Egg Rings, puis continué à faire frire juste jusqu''à ce que le blanc d''oeuf soit cuit, ou côté ensoleillé vers le haut, environ 1 minute.</li><li> Vous pouvez aussi faire frire l''œuf normalement et couper l''œuf en forme de cœur.</li><li> Pour assembler des sandwichs : Placer 2 tranches de bacon sur une tranche de pain grillé au sourd.</li><li> Placer quelques lances d''asperges grillées et de pétoncle sur le dessus du bacon.</li><li> Étendre une épaisse couche de pesto de basilic d''épinards.</li><li> Enfin, garnir de l''œuf frit en forme de cœur.</li><li> Servir la salade sur le côté.</li></ol>"}]', 'https://img.spoonacular.com/recipes/653775-556x370.', 'PUBLISHED', '2026-01-19 18:23:17.536725', '2026-01-19 18:23:17.536725', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '653775');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('1251a73e-5f9b-4a8b-bc8b-e4008554ec8c', 'Toast français farci de Nutella', 'La recette Nutella Stuffed French Toast pourrait satisfaire votre envie américaine en environ 45 minutes. Tu regardes ta figure ? Cette recette végétarienne lacto ovo a 378 calories, 9g de protéines et 20g de gras par portion. Cette recette sert 2. Pour 80 cents par portion, cette recette couvre 10 % de vos besoins quotidiens en vitamines et minéraux. 15 personnes ont trouvé cette recette délicieuse et satisfaisante. Cette recette de Foodista nécessite de la nutella, du pain, du sucre et du sucre en poudre. Quelques personnes ont vraiment aimé ce petit déjeuner. Dans l''ensemble, cette recette gagne un score cuilleraculaire pas si étonnant de 32%. Des recettes similaires sont le toast français farci de Nutella, le toast français farci de nutella et le toast français farci de Nutella avec des fraises.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["couteau", "bol"], "ingredients": ["cannelle", "à tartiner de noisettes au chocolat", "sucre", "pain sandwich", "œuf", "lait"], "instruction": "n un grand bol profond, mélanger les œufs, le lait, le sucre et la cannelle. Mélangez-le à l''aide d''une fourchette et gardez de côté. Maintenant, enrobez la noixella d''un côté de 2 toasts et fermez les deux toasts ensemble en sandwichant les côtés de la noixella entre les deux. Faire tremper la noixella farcie dans le mélange d''oeufs et la pousser à l''aide d''un couteau pour qu''elle soit bien enduite.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 10}, "equipment": ["poêle à frire"], "ingredients": ["beurre"], "instruction": "Laissez-le s''asseoir pendant 3-5 minutes, puis retournez et laissez l''autre côté se couche trop bien. Faites tremper les côtés aussi. Une fois prêt, cuire sur une poêle préchauffée avec du beurre pendant environ 5 minutes de chaque côté jusqu''à ce que bien doré mais non brûlé.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["sucre en poudre", "café"], "instruction": "Saupoudrer de sucre en poudre et servir avec du café noir. Répétez pour le suivant de la même façon.", "step_number": 3}]', 'https://img.spoonacular.com/recipes/653371-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.542154', '2026-01-19 18:23:17.542154', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '653371');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('7e24ff63-1d75-40ca-a7f3-6ecd544ca213', 'Petit déjeuner Strata', 'Le petit déjeuner Strata nécessite environ 45 minutes du début à la fin. Cette recette sert 6. Ce petit déjeuner contient 1529 calories, 69g de protéines et 44g de graisse par portion. Pour 4,67 $ par portion, cette recette couvre 51 % de vos besoins quotidiens en vitamines et minéraux. Cette recette de Foodista nécessite des œufs, du pain, des saucisses et de la moutarde. 1 personne était heureuse qu''ils aient essayé cette recette. Tout compte fait, nous avons décidé que cette recette mérite un score cuilleré de 78%. Ce score est solide. Si vous aimez cette recette, vous aimerez aussi des recettes telles que Breakfast Strata, Breakfast Strata et Breakfast Strata.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["saucisse"], "instruction": "Faire cuire et écraser la saucisse.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 720}, "equipment": ["four"], "ingredients": [], "instruction": "Mélanger tous les ingrédients et verser dans un plat de four de 13x9 pouces. Réfrigérer 12 heures.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 45}, "equipment": ["four"], "ingredients": [], "instruction": "Cuire à 350 pendant 45 minutes ou jusqu''à ce que le dessus soit ferme et doré.", "step_number": 3}]', 'https://img.spoonacular.com/recipes/636078-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.547398', '2026-01-19 18:23:17.547398', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '636078');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('650bb7e0-2332-47cf-9681-45a8c060156c', 'Toast français facile Berry', 'Facile Berry Français Toast est une recette végétarienne lacto ovo avec 4 portions. Une portion de ce plat contient environ 19g de protéines, 23g de graisses et un total de 544 calories. Pour 2,79 $ par portion, cette recette couvre 23 % de vos besoins quotidiens en vitamines et minéraux. Il fonctionne bien comme un petit déjeuner abordable. Un mélange d''oeufs, de pain, de baies et une poignée d''autres ingrédients sont tout ce qu''il faut pour rendre cette recette si délicieuse. De la préparation à l''assiette, cette recette prend environ 45 minutes. Il vous est apporté par cuilleraculaire user de haricots café. Si vous aimez cette recette, vous aimerez peut-être aussi des recettes comme les Muffins de Toast français de Berry, le Toast français de Summertime et le Toast français de Berry Casserole.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["œuf"], "instruction": "Battre des œufs.", "step_number": 1}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["sucre vanille", "beurre", "pain", "lait", "trempette", "œuf"], "instruction": "Ajouter le lait et le sucre vanille. Laisser tremper le pain dans le mélange d''oeufs une tranche à la fois, en pressant légèrement les tranches dans le mélange d''oeufs. Tourner pour enrober les deux côtés uniformément. Faire fondre 1 c. à soupe de beurre dans une grande poêle à feu moyen.", "step_number": 2}, {"duration": null, "equipment": ["casserole", "poêle à frire", "four"], "ingredients": ["baies", "beurre", "pain", "pain sandwich"], "instruction": "Ajouter 2-3 tranches à la poêle (selon la taille de votre pain et votre poêle). Faire frire le pain jusqu''à ce qu''il soit doré des deux côtés. Gardez au chaud au four pendant que vous terminez les autres tranches, en ajoutant du beurre à la poêle au besoin. Garnir de baies congelées fraîches ou chauffées (je chauffe les baies congelées doucement dans une casserole pendant que je fais le toast français).", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["sirop d''érable"], "instruction": "Servir avec du sirop d''érable.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/1444543-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.550115', '2026-01-19 18:23:17.550115', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '1444543');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('944fd486-fdd6-4ccd-b236-1562541f6edf', 'Cinnamon bâtons de pain français', 'Cinnamon French Toast Sticks pourrait être une bonne recette pour élargir votre boîte de recettes petit déjeuner. Cette recette fait 1 portion de 695 calories, 23g de protéines et 26g de gras chacun. Pour 2,91 $ par portion, cette recette couvre 28 % de vos besoins quotidiens en vitamines et minéraux. Un mélange de sucre glace, de lait, de fruits et une poignée d''autres ingrédients sont tout ce qu''il faut pour rendre cette recette si délicieuse. Cette recette d''Afrolems a 4 fans. C''est une bonne option si vous suivez un régime lacto ovo végétarien. De la préparation à l''assiette, cette recette prend environ 45 minutes. Pas beaucoup de gens ont vraiment aimé ce plat américain. Tout compte fait, nous avons décidé que cette recette mérite un score cuilleré de 62%. Ce score est solide. Si vous aimez cette recette, regardez ces recettes similaires : Cinnamon French Toast Sticks, Cinnamon French Toast Sticks et Cinnamon Sugar French Toast Sticks.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["pain"], "instruction": "Coupez votre pain en petits bâtonnets rectangulaires", "step_number": 1}, {"duration": null, "equipment": ["fouet", "bol"], "ingredients": ["cannelle au sol", "pain", "chérie", "lait", "trempette", "œuf"], "instruction": "Dans un bol, fouetter votre œuf, lait, 1 cuillère à soupe de miel, 1 cuillère à soupe de cannelle en poudre. Plongez votre pain dans le mélange, tournez des deux côtés et réservez", "step_number": 2}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["beurre", "pain"], "instruction": "Dans une poêle à feu doux, chauffer votre beurre et faire frire vos bâtonnets de pain.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["cannelle au sol", "sucre en poudre", "fruits", "crème", "chérie", "pain sandwich", "glace"], "instruction": "Servez vos bâtonnets de pain français avec les fruits hachés, arrosez le reste du miel, saupoudrez le reste de la cannelle en poudre et le sucre glaçant. P:S – Si vous le prenez comme dessert, vous pouvez y ajouter une boule de glace.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/764752-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.552851', '2026-01-19 18:23:17.552851', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '764752');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('30f90ae8-bf22-4192-856c-95f0738f9108', 'Brioche Pain pudding', 'Pain de brioche La pudding nécessite environ 45 minutes du début à la fin. Pour 1,65 $ par portion, cette recette couvre 15 % de vos besoins quotidiens en vitamines et minéraux. Une portion de ce plat contient environ 15g de protéines, 32g de graisses et un total de 503 calories. Cette recette sert 8. Elle fonctionne bien comme un dessert. Cette recette est appréciée par 3 gourmets et cuisiniers. Un mélange de lait, d''extrait de vanille, d''oeufs et d''une poignée d''autres ingrédients sont tout ce qu''il faut pour rendre cette recette si savoureuse. Il vous est apporté par Foodista. En tenant compte de tous les facteurs, cette recette gagne un score cuilleré de 40%, ce qui est plutôt mauvais. Si vous aimez cette recette, regardez ces recettes similaires : Poudre de pain de brioche de bleu, pudding de pain de citrouille de brioche et pudding de pain de brioche de baie.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["boîte à cuisson"], "ingredients": ["cubes de pain"], "instruction": "Placer les cubes de pain dans une casserole de 13- par 9- par 2-pouces.", "step_number": 1}, {"duration": null, "equipment": ["fouet", "bol"], "ingredients": ["extrait de vanille", "extrait d''amande", "crème fouettée", "frangelico", "sucre", "œuf", "lait"], "instruction": "Whisk oeufs, crème fouettée, lait, sucre, frangelico, extrait de vanille et d''amande dans un grand bol à mélanger.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["cubes de pain"], "instruction": "Verser sur les cubes de pain.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 160}, "equipment": ["plaque de cuisson", "four"], "ingredients": ["crème", "pain"], "instruction": "Laisser reposer 30 minutes, presser occasionnellement le pain dans le mélange de crème. (Peut être préparé 2 heures à l''avance. Couvrir et réfrigérer.) Préchauffer le four à 350 degrés. Disposer les croûtes de pain réservées sur la plaque de cuisson et cuire jusqu''à sec, environ 10 minutes. Génial. Maintenir la température du four.", "step_number": 4}, {"duration": null, "equipment": ["processeur alimentaire"], "ingredients": [], "instruction": "Transférer les croûtes au robot culinaire et les broyer jusqu''à ce que les miettes fines se forment.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["croûte"], "instruction": "Saupoudrer 1 tasse de croûte de miettes sur le dessus du pudding.", "step_number": 6}, {"duration": {"unit": "minutes", "number": 40}, "equipment": ["four"], "ingredients": [], "instruction": "Cuire jusqu''à ce que le pudding soit au centre, environ 40 minutes. Refroidir légèrement.", "step_number": 7}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servir au chaud. Cette recette donne 8 à 10 portions.", "step_number": 8}]', 'https://img.spoonacular.com/recipes/636131-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.555635', '2026-01-19 18:23:17.555635', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '636131');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('4d058390-e5fa-4526-a74b-ca815d5713df', 'Pâtes de pain au chocolat avec des poires Surprise', 'Pudding au pain de chocolat avec des poires Surprise pourrait être juste le dessert que vous recherchez. Une portion contient 3117 calories, 59g de protéines et 131g de graisse. Pour 5,69 $ par portion, cette recette couvre 62% de vos besoins quotidiens en vitamines et minéraux. Cette recette de Foodista nécessite des chips de chocolat, des poires et ou, du sucre, et des œufs. 1 personne a fait cette recette et la ferait à nouveau. De la préparation à l''assiette, cette recette prend environ 45 minutes. Avec un score cuilleré de 83%, ce plat est spectaculaire. Si vous aimez cette recette, vous aimerez aussi des recettes comme Surprise Ingredients Chocolate Pudding, Surprise Ingredients Chocolate Pudding et Pain pudding with Pears, Currants and Cannamon.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Préchauffer le four à 325 degrés F.", "step_number": 1}, {"duration": null, "equipment": ["bol"], "ingredients": ["extrait de vanille", "beurre", "sucre", "œuf", "lait"], "instruction": "Dans un grand bol, remuer le lait chaud et le beurre fondu avec le sucre, les œufs et l''extrait de vanille.", "step_number": 2}, {"duration": null, "equipment": ["fouet"], "ingredients": [], "instruction": "Fouetter jusqu''à incorporation et lisse.", "step_number": 3}, {"duration": null, "equipment": ["boîte à cuisson"], "ingredients": ["cubes de pain", "poire"], "instruction": "Étaler un plat de taille moyenne avec des tranches de poire et les deux tiers des cubes de pain.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["croustilles de chocolat", "cubes de pain", "poire"], "instruction": "Saupoudrer de la moitié des croustilles de chocolat et des poires restantes coupées en petits morceaux. Garnir du reste des cubes de pain et des chips de chocolat.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 5}, "equipment": [], "ingredients": ["pain", "lait"], "instruction": "Verser lentement le mélange de lait sur le dessus de tout et laisser reposer jusqu''à ce que le pain ait absorbé presque tout le liquide (5 à 10 minutes).", "step_number": 6}, {"duration": {"unit": "minutes", "number": 50}, "equipment": ["feuille d''aluminium", "boîte à cuisson", "four"], "ingredients": ["enveloppe"], "instruction": "Enveloppez fermement le plat de cuisson avec du papier d''aluminium et faites cuire pendant 50 minutes.", "step_number": 7}, {"duration": {"unit": "minutes", "number": 10}, "equipment": ["feuille d''aluminium"], "ingredients": [], "instruction": "Retirer la feuille d''aluminium et cuire pendant 10 à 15 minutes, ou jusqu''à ce qu''elle soit au milieu et légèrement dorée sur le dessus.", "step_number": 8}, {"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Retirer du four et laisser refroidir avant de servir.", "step_number": 9}]', 'https://img.spoonacular.com/recipes/638850-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.559148', '2026-01-19 18:23:17.559148', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '638850');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('76162910-bf14-48c2-bf85-5c79f928ea64', 'Bisque alouette de tomates séchées et basilic', 'Si vous souhaitez ajouter plus de recettes sans gluten et sans produits laitiers à votre boîte de recettes, la bisque Alouette Sundried Tomato and Basil pourrait être une recette à essayer. Une portion de ce plat contient environ 2 g de protéines, 2 g de matières grasses et un total de 96 calories. Cette recette en sert 8 et coûte 45 cents la portion. De la préparation à l’assiette, cette recette prend environ 45 minutes. 83 personnes ont été impressionnées par cette recette. Quelques personnes ont vraiment aimé cette hors-d’œuvre. Si vous avez du bacon, de la soupe à la tomate entièrement naturelle, de l’alouette au fromage à tartiner tout naturel à la tomate séchée au soleil et au basilic, ainsi que quelques autres ingrédients, vous pouvez le préparer. Il est présenté par Foodista. Tout bien considéré, nous avons décidé que cette recette méritait un score cuillère de 27 %. Ce score n’est pas si impressionnant. Essayez les pâtes tomate séchée, basilic et fromage de chèvre, tartinée à la tomate séchée et basilic, et bisque tomate-basilic pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["pot"], "ingredients": ["bacon", "sauce"], "instruction": "Faites sauter le bacon dans une casserole à sauce épaisse jusqu’à ce qu’il soit croustillant", "step_number": 1}, {"duration": null, "equipment": ["pot"], "ingredients": ["sauce"], "instruction": "Égoutter la graisse de la casserole", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["stock de légumes", "soupe à la tomate"], "instruction": "Ajoutez la soupe aux tomates et le bouillon de légumes et portez à ébullition", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["Fromage à pâte", "tomate", "basilic"], "instruction": "Ajoutez du fromage à tomate séchée alouette et du basilic", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Remettez à ébullition et servez", "step_number": 5}]', 'https://img.spoonacular.com/recipes/632250-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.622458', '2026-01-19 18:23:17.622458', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '632250');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('f836236d-78ce-47d5-ad82-680503b633de', 'Tarragon poulet avec pois', 'Tarragon Chicken With Peas pourrait être juste la recette sans gluten et primal que vous avez cherché. Cette recette sert 4 $ et coûte 3,01 $ par portion. Une portion de ce plat contient environ 54g de protéines, 39g de graisses et un total de 614 calories. Si vous avez des petits pois, du sel et du poivre, du bouillon de poulet et quelques autres ingrédients à la main, vous pouvez le faire. 1 personne a fait cette recette et la ferait à nouveau. Il fonctionne bien comme un cours principal assez cher. De la préparation à l''assiette, cette recette prend environ 30 minutes. Il vous est apporté par Foodista. Dans l''ensemble, cette recette rapporte un score cuilleré solide de 68%. Les utilisateurs qui ont aimé cette recette ont aussi aimé Tarragon Chicken With Peas, Tarragon Chicken With Peas et Orzo avec Tarragon and Peas.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 30, '[{"duration": {"unit": "minutes", "number": 5}, "equipment": ["poêle à frire"], "ingredients": ["sel et poivre", "huile d''olive", "poulet"], "instruction": "Chauffer une grande poêle à feu moyen-élevé et ajouter l''huile d''olive. Assaisonner généreusement le poulet de sel et de poivre, puis le saisir jusqu''à ce qu''il soit doré, environ 5 minutes de chaque côté.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 11}, "equipment": ["poêle à frire"], "ingredients": ["sel et poivre", "de poulet", "estragon", "poulet", "crème", "sauce", "pois", "riz"], "instruction": "Mélanger le bouillon de poulet et la crème et ajouter au poulet, grattant les morceaux brunis du fond de la poêle. Porter à ébullition, puis réduire à mijoter et cuire jusqu''à ce que le poulet soit cuit et la sauce épaissie, environ 5-10 minutes. Mélanger délicatement l''estragon et les pois, couvrir et cuire 1 minute pour chauffer les pois. Assaisonner de sel et de poivre et servir le poulet tranché sur le riz pour une entrée facile et élégante.", "step_number": 2}]', 'https://img.spoonacular.com/recipes/662880-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.561454', '2026-01-19 18:23:17.561454', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '662880');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('f42a45ec-0ab8-480c-99fd-c2a007639ffe', 'Soupe de tomate crémeuse maison', 'Besoin d''un hor d''oeuvre végétarien sans gluten et lacto ovo? Soupe de tomate crémeuse maison pourrait être une recette formidable à essayer. Cette recette sert 6 et coûte 74 cents par portion. Une portion contient 221 calories, 4g de protéines et 17g de graisse. De la préparation à l''assiette, cette recette prend environ 45 minutes. Cette recette de Foodista nécessite du stock de légumes, de l''oignon, de la crème lourde et des tomates. 1 personne a trouvé cette recette délicieuse et satisfaisante. Il est parfait pour l''automne. En tenant compte de tous les facteurs, cette recette gagne un score cuilleré de 27%, ce qui n''est pas si génial. Pesto de basilic maison et fromage grillé Cheddar avec soupe à la tomate crémeuse, pâtes avec sauce à la tomate crémeuse maison (Vegan), et tomate maison Les soupes sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["bol"], "ingredients": ["tomates", "graines", "eau"], "instruction": "Commencez par écorcher et ensemencer vos tomates. Pour ce faire, il faut porter l''eau à ébullition et marquer vos tomates en coupant légèrement une croix aux deux extrémités. Submerger les tomates dans l''eau bouillante pendant 30 secondes et les transférer dans un bol d''eau froide. Peler la peau, couper puis terminer, puis couper en deux et retirer les graines.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 3}, "equipment": ["pot"], "ingredients": ["oignon", "huile de cuisson"], "instruction": "Chauffer l''huile dans une grande casserole et cuire les oignons pendant 3 minutes.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 15}, "equipment": [], "ingredients": ["ail", "tomates", "stock"], "instruction": "Ajouter l''ail et cuire encore une minute. Ajouter ensuite la tomate et cuire jusqu''à ce qu''elle soit tendre, ou environ 5 minutes. Incorporer le bouillon, porter à ébullition, puis laisser mijoter 10 minutes.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Retirer du feu et refroidir légèrement.", "step_number": 4}, {"duration": null, "equipment": ["mélangeur d''immersion", "processeur alimentaire"], "ingredients": [], "instruction": "Transférer dans un robot culinaire en petits lots ou utiliser un mélangeur d''immersion pour mélanger jusqu''à ce qu''il soit lisse.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["sel et poivre", "pâte de tomate", "crème", "sucre"], "instruction": "Ajouter le sucre et la pâte de tomate et porter à ébullition. Réduire la chaleur. En remuant continuellement, ajouter lentement de la crème. Laisser mélanger et chauffer mais pas bouillir. Assaisonner au goût avec du sel et du poivre.", "step_number": 6}]', 'https://img.spoonacular.com/recipes/646976-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.563788', '2026-01-19 18:23:17.563788', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '646976');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('eca49c5d-0d3d-4584-a82c-27681179602b', 'Scallop marin avec crème d''asperges', 'Scallops marins Avec Aspergus Cream pourrait être une bonne recette pour élargir votre boîte de recettes de plat principal. Cette recette sert 1. Une portion contient 374 calories, 13g de protéines et 24g de graisse. Pour 3,3 $ par portion, cette recette couvre 16 % de vos besoins quotidiens en vitamines et minéraux. Il vous est apporté par Foodista. C''est une bonne option si vous suivez un régime sans gluten et pescatarien. 1 personne était heureuse qu''ils aient essayé cette recette. Un mélange de sel, de vin blanc, de bouillon de poulet et une poignée d''autres ingrédients sont tout ce qu''il faut pour rendre cette recette si somptueuse. De la préparation à l''assiette, cette recette prend environ 45 minutes. Toutes choses considérées, nous avons décidé que cette recette mérite un score cuilleré de 43%. Ce score est solide. Le scallop marin Gemelli aux asperges, aux pois snap, au pecorino, à la salade de scallop marin et aux tacos de scallop marin de Cumin sont très semblables à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 60}, "equipment": ["mélangeur"], "ingredients": ["sauce à la crème", "asperges", "sauce"], "instruction": "Mélanger les asperges, les ingrédients de la sauce à la crème et porter à ébullition pendant 1 heure jusqu''à ce que la sauce soit réduite. Procéder dans un mélangeur et une souche.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["pétoncles", "huile de cuisson"], "instruction": "Chauffer l''huile et les pétoncles des deux côtés jusqu''à ce qu''ils soient dorés.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["sauce à la crème", "asperges", "pétoncles", "tomates"], "instruction": "Verser une partie de la sauce aux asperges sur une assiette. Disposer les pétoncles sur le dessus et saupoudrer de tomates coupées en dés.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["nori"], "instruction": "Garnir de nori.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/659677-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.566244', '2026-01-19 18:23:17.566244', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '659677');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('b70324a0-048c-45f9-a2ff-82851dc778ce', 'Soupe de citrouille de poivre chaud', 'Soupe de citrouille de poivre chaud est un hor d''oeuvre qui sert 4. Une portion de ce plat contient environ 4g de protéines, 14g de graisse et un total de 246 calories. Pour 2,85 $ par portion, cette recette couvre 16 % de vos besoins quotidiens en vitamines et minéraux. 10 personnes ont été impressionnées par cette recette. L''automne sera encore plus spécial avec cette recette. Cette recette de Foodista nécessite l''origan, l''ail, l''oignon et le beurre. C''est une bonne option si vous suivez un régime sans gluten, lacto ovo végétarien et primal. De la préparation à l''assiette, cette recette prend environ 45 minutes. En tenant compte de tous les facteurs, cette recette gagne un score cuilleraculaire de 48%, qui est solide. Les recettes similaires sont Soupe de citrouille chaude et chaude, Soupe crémeuse de poivre rouge citrouille, et Soupe de citrouille et de poivre jaune avec paprika fumé.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 60}, "equipment": ["processeur alimentaire", "mélangeur", "poêle à frire"], "ingredients": ["origan séché", "crème lourde", "maïs poivré", "coriandre", "citrouille", "beurre", "ail", "oignon", "stock", "sel", "soupe"], "instruction": "Dans une poêle profonde, chauffer le bouillon, le sel, la citrouille, l''oignon, l''ail, les feuilles de coriandre et les grains de poivre. Porter à ébullition, réduire le feu à feu doux et laisser mijoter 30 minutes à découvert. Puis purifier la soupe en petits lots (1 tasse à la fois) en utilisant un robot culinaire ou un mélangeur. Dans une même casserole, ajouter le beurre et l''origan séché. Quand le beurre fondu. Puis ajouter la purée et porter à ébullition à nouveau. Réduire le feu à faible intensité et laisser mijoter encore 30 minutes à découvert. Incorporer la crème lourde.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servir chaud.", "step_number": 2}]', 'https://img.spoonacular.com/recipes/647501-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.56945', '2026-01-19 18:23:17.56945', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '647501');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('a2b0511c-9e7b-492b-bd0b-785ac1f9eb76', 'Linguini dans une sauce crémeuse aux pois et crevettes sautées', 'Linguini dans une sauce aux pois crémeux et crevettes sautées pourrait être juste le plat principal que vous recherchez. Cette recette sert 4 $ et coûte 3,72 $ par portion. Une portion contient 839 calories, 45g de protéines et 26g de graisses. 1 personne a trouvé cette recette délicieuse et satisfaisante. Un mélange de bouillon de légumes, gousses d''ail, petits pois et une poignée d''autres ingrédients sont tout ce qu''il faut pour rendre cette recette si savoureux. De la préparation à l''assiette, cette recette prend environ 45 minutes. Il vous est apporté par Foodista. C''est une bonne option si vous suivez un régime pescatarien. En tenant compte de tous les facteurs, cette recette gagne un score cuilleré de 72%, ce qui est assez bon. Linguini avec crevettes, Linguine avec sauce à l''oignon et crevettes sautées, et Crevettes rapides & Linguini sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["poêle à frire"], "ingredients": ["huile d''olive", "échalote", "ail"], "instruction": "Dans une grande casserole, à feu moyen, ajouter quelques bruines d''huile d''olive, les échalotes et l''ail. Sauter jusqu''à ramollir.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["pois"], "instruction": "Ajouter 2 tasses de pois congelés et cuire quelques minutes.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 5}, "equipment": [], "ingredients": ["bouillon"], "instruction": "Ajouter le bouillon et laisser mijoter à feu doux pendant 5 minutes pour permettre aux saveurs de se fondre.", "step_number": 3}, {"duration": null, "equipment": ["processeur alimentaire", "mélangeur"], "ingredients": [], "instruction": "À l''aide d''un mélangeur (vent ouvert pour laisser sortir la vapeur) ou d''un robot culinaire, purifier le mélange jusqu''à ce qu''il soit lisse.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 10}, "equipment": [], "ingredients": ["crème", "pois"], "instruction": "Ajouter la crème et une tasse supplémentaire de pois et laisser mijoter à feu doux pendant environ 8-10 minutes.", "step_number": 5}, {"duration": null, "equipment": ["serviettes en papier"], "ingredients": ["poudre d''ail", "poivre", "crevettes", "sel"], "instruction": "Pendant que cela mijote, nous pouvons aller de l''avant et cuire les crevettes. Utiliser une serviette en papier pour sécher toute humidité supplémentaire de la crevette. Ajouter le sel, le poivre et un peu de poudre d''ail.", "step_number": 6}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["huile d''olive", "crevettes"], "instruction": "Dans une grande casserole, à feu moyen-élevé, ajouter quelques bruines d''huile d''olive et cuire les crevettes quelques minutes de chaque côté. Ils sont cuits à travers une fois qu''ils ont tourné rose et recourbé dans un peu, les centres devraient être translucides. Cuire en lots pour que la casserole ne soit pas trop bondée.", "step_number": 7}, {"duration": null, "equipment": [], "ingredients": ["sel et poivre", "linguine", "sauce"], "instruction": "Une fois que la sauce a fini de mijoter, mélanger dans les linguini cuits. Goûtez au sel et au poivre.", "step_number": 8}, {"duration": null, "equipment": [], "ingredients": ["linguine", "crevettes"], "instruction": "Servir les linguini avec plusieurs crevettes sur le dessus.", "step_number": 9}]', 'https://img.spoonacular.com/recipes/650147-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.572281', '2026-01-19 18:23:17.572281', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '650147');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('0b949005-b47f-48c7-8724-1b43b00e646c', 'Soupe de poireau crémeuse Omega-3', 'Omega-3 Soupe de poireau crémeuse pourrait être une bonne recette pour élargir votre boîte de recette de plat principal. Cette recette sert 2. Surveiller votre silhouette ? Cette recette sans gluten, primal, pescatarien et cétogène contient 766 calories, 48g de protéines et 54g de graisse par portion. Pour 5,95 $ par portion, cette recette couvre 38% de vos besoins quotidiens en vitamines et minéraux. Cette recette de cuilleraculaire utilise du saumon, du bouillon de légumes, du jus de citron, du sel et du poivre. De la préparation à l''assiette, cette recette prend environ 45 minutes. C''est parfait pour l''hiver. Si vous aimez cette recette, vous aimerez aussi des recettes comme la soupe crémeuse de pommes de terre et de poireaux, la soupe crémeuse de poireaux de pommes de terre et la soupe de chou-fleur, de poireaux et de cheddar.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["poêle à frire"], "ingredients": ["huile d''olive", "poireaux"], "instruction": "Couper la partie blanche du poireau en rondelles fines et faire frire les rondelles dans l''huile d''olive dans une grande casserole jusqu''à ce qu''elles soient adoucies.", "step_number": 1}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["bouillon de légumes", "jus de citron", "pois", "vin"], "instruction": "Ajouter le jus de citron, le vin, le bouillon de légumes et les pois congelés dans la poêle.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Laissez tout mijoter quelques minutes.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["crème", "lait"], "instruction": "Mélanger la crème et le lait.", "step_number": 4}, {"duration": null, "equipment": ["mélangeur d''immersion"], "ingredients": ["soupe"], "instruction": "Purifier la soupe avec un mélangeur à main.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["saumon", "crevettes"], "instruction": "Ajouter le saumon et la crevette jusqu''à cuisson.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": ["sel et poivre", "L''aneth frais"], "instruction": "Assaisonner de sel et de poivre et servir avec beaucoup d''aneth fraîche.", "step_number": 7}]', 'https://img.spoonacular.com/recipes/157081-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.575185', '2026-01-19 18:23:17.575185', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '157081');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('80269994-21f5-48af-b7f1-4f2884879ff7', 'Broth aromatique d''asperges avec caviar', 'Broth Aromatique des Asperges Avec Caviar pourrait être juste l''hor d''oeuvre que vous recherchez. Une portion de ce plat contient environ 7g de protéines, 4g de graisses et un total de 225 calories. Cette recette sans gluten, primal et pescatarien sert 14 $ et coûte 3,23 $ par portion. Si vous avez du persil, de la crème lourde, du bouillon de poulet et quelques autres ingrédients à la main, vous pouvez le faire. Il vous est apporté par Foodista. 1 personne a essayé et aimé cette recette. De la préparation à l''assiette, cette recette prend environ 45 minutes. Avec un score cuilleraculaire de 39%, ce plat est plutôt mauvais. Si vous aimez cette recette, vous aimerez peut-être aussi des recettes telles que le bouillon de boeuf vietnamien aromatique, le bouillon de boeuf vietnamien aromatique, et le bouillon asiatique Kale et asperges avec épeautre.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["huile d''olive", "beurre", "oignon", "poireaux"], "instruction": "Pour commencer, couper quelques oignons et poireaux et les faire revenir légèrement dans le beurre et l''huile d''olive. Faire cela pendant quelques minutes jusqu''à ce que les oignons commencent à translucide.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["vin"], "instruction": "Ajouter un trait de vin pour faire un tourneau et laisser brûler le vin pendant une minute ou", "step_number": 2}, {"duration": {"unit": "minutes", "number": 5}, "equipment": [], "ingredients": ["asperges"], "instruction": "Faire bouillir quelques asperges (j''utilise normalement les plus minces, les plus petites) pendant environ 5 minutes jusqu''à ce qu''elles deviennent vert vif.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["de poulet", "asperges", "oignon", "poireaux"], "instruction": "Ajouter suffisamment de bouillon de poulet dans le mélange d''oignon et de poireau et porter à ébullition. Une fois qu''il fait bouillir, faire mijoter lentement le feu et ajouter les asperges.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 20}, "equipment": ["mélangeur"], "ingredients": ["persil à feuilles plates", "sel et poivre", "crème lourde", "asperges", "assaisonnement", "caviar", "bouillon", "crème", "soupe"], "instruction": "Laisser cuire et laisser mijoter pendant au moins 20 minutes, ce qui fera ressortir les arômes d''asperges dans le mélange de bouillon. Ensuite, ajouter une crème lourde pour épaissir le bouillon, mais attention à ne pas ajouter beaucoup pour en faire une soupe à base de crème. Apportez tout le mélange à un mélangeur et blitz. Ne pas utiliser toutes les asperges dans le mélangeur, et ajouter seulement si la couleur n''est pas assez verte. C''est pour lui donner une texture de bouillon plus légère. Goûter pour s''assurer qu''il y a suffisamment d''assaisonnement, sinon, ajouter suffisamment d''assaisonnement (sel et poivre) pour améliorer les saveurs. Verser le bouillon dans une assiette de soupe et déposer dans un peu de caviar au milieu et le garnir d''un persil italien pour lui donner un léger parfum de menthe et d''herbe. Fait !", "step_number": 5}]', 'https://img.spoonacular.com/recipes/632721-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.577838', '2026-01-19 18:23:17.577838', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '632721');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('cab762f4-2b8b-40ac-bbe8-093b5e390fea', 'Agnolotti (ou raviolis) grillés"', 'Les Agnolotti (ou Raviolis) grillés nécessitent environ 45 minutes du début à la fin. Cette recette en fait 2 et coûte 1,95 $ la portion. Ce plat principal contient 965 calories, 41 g de protéines et 28 g de matières grasses par portion. Cette recette est appréciée par 7 gourmets et cuisiniers. C’est une bonne option si vous suivez un régime sans produits laitiers. C’est une recette économique pour les amateurs de cuisine méditerranéenne. Si vous avez des agnolotti/raviolis prêts à l’emploi, des œufs, de la chapelure et quelques autres ingrédients à portée de main, vous pouvez le faire. Il est présenté par Foodista. Dans l’ensemble, cette recette obtient un score cuillère assez bon de 61 %. Les utilisateurs qui ont aimé cette recette ont également apprécié les raviolis à la courge musquée : Agnolotti di Zucca, Raviolis grillés et Raviolis grillés.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Préchauffez le four à 180 degrés Celsius (350 F) pour un four à ventilateur ou à 200 degrés Celsius (392 F) pour un four à convection.", "step_number": 1}, {"duration": null, "equipment": ["papier à pâtisserie", "boîte à cuisson"], "ingredients": [], "instruction": "Tapisser une plaque de papier pâtisseur.", "step_number": 2}, {"duration": null, "equipment": ["papier à pâtisserie"], "ingredients": ["huile d''olive", "huile de cuisson"], "instruction": "Vaporisez une fine couche d’huile d’olive (n’importe quelle huile de votre choix fera l’affaire) sur le papier cuit. Mets de côté.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["chapelure", "œuf"], "instruction": "Casser et battre un œuf dans une assiette. Sur une assiette séparée, ajoutez la chapelure.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["Agnolotti", "trempette", "œuf"], "instruction": "Trempez d’abord les agnolotti dans l’œuf battu.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["chapelure", "Agnolotti", "œuf"], "instruction": "Ensuite, enrobez-le de chapelure.  Répétez les étapes 5 et 6 avec les agnolotti restants jusqu’à ce que l’œuf et la chapelure soient terminés.", "step_number": 6}, {"duration": null, "equipment": ["boîte à cuisson"], "ingredients": ["Agnolotti", "huile de cuisson"], "instruction": "Placez les agnolotti émietés sur une plaque de cuisson. Une fois les étapes 5 et 6 terminées, vaporisez une autre fine couche d’huile sur les aganolotti émiettés.", "step_number": 7}, {"duration": {"unit": "minutes", "number": 25}, "equipment": ["four"], "ingredients": ["Agnolotti"], "instruction": "Faites cuire les agnolotti miettes pendant 25 minutes ou jusqu’à ce qu’ils soient dorés.", "step_number": 8}, {"duration": null, "equipment": [], "ingredients": ["Sauce pour pâtes", "ketchup"], "instruction": "Servez immédiatement avec une sauce pour pâtes ou du ketchup.", "step_number": 9}]', 'https://img.spoonacular.com/recipes/631807-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.579943', '2026-01-19 18:23:17.579943', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '631807');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('7b040e82-6b75-48d3-b545-df473153c20c', 'Pâtes simples à l’ail', 'Si vous souhaitez ajouter plus de recettes sans produits laitiers, lacto-ovo-végétariennes et véganes à votre coffret de recettes, Simple Garlic Pasta pourrait être une recette à essayer. Ce plat principal contient 759 calories, 14g de protéines et 44g de matières grasses par portion. Cette recette sert 1. Pour 95 cents la portion, cette recette couvre 16 % de vos besoins quotidiens en vitamines et minéraux. Une personne a trouvé cette recette savoureuse et satisfaisante. Si vous avez du sel de mer, de l’ail, des spaghettini et quelques autres ingrédients sous la main, vous pouvez en préparer. Il est présenté par Foodista. De la préparation à l’assiette, cette recette prend environ 45 minutes. Tout bien considéré, nous avons décidé que cette recette mérite un score cuillère de 70 %. Cette partition est plutôt bonne. Simple Garlic Pasta, Simple Garlic Pasta et Simple Crewn And Garlic Pasta Supper sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": [], "instruction": "Important : le timing est primordial", "step_number": 1}, {"duration": null, "equipment": ["pot"], "ingredients": ["eau"], "instruction": "Commencez par faire bouillir de l’eau dans une grande casserole.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["Spaghettini", "sel de mer", "pâtes", "eau", "sel"], "instruction": "Ajoutez une bonne quantité de sel de mer à l’eau bouillante pour que vous puissiez vraiment goûter un peu de sel dans l’eau. (vous faites des pâtes aromatisées avec de l’eau salée)Mettez des spaghettini dans l’eau et faites bouillir pendant 7 minutes", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["Spaghettini", "ail", "viande hachée"], "instruction": "Pendant que vous faites bouillir les spaghettinis, hachez l’ail", "step_number": 4}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["piment", "huile d''olive", "pâtes"], "instruction": "Faites chauffer une poêle (feu moyen-bas) avec de l’huile d’olive et du piment après 4 minutes de pâtes bouillantes.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 10}, "equipment": ["poêle à frire"], "ingredients": ["ail", "eau"], "instruction": "Mettez l’ail dans la poêle. C’est presque comme si tu faisais frire l’ail au lieu de le faire frire à la poêle. Vous avez 2 à 3 minutes pour faire dorer l’ail à l’ail. Après 7 minutes de fin d’ébullition, mettez la poêle à feu fort, puis versez 2 cuillères à soupe d’eau bouillante salée et versez-les dans la poêle (encore chaude) – vous verrez un peu de vapeur sortir... Cela aide le passé à rester au chaud", "step_number": 6}, {"duration": null, "equipment": ["poêle à frire", "pot"], "ingredients": ["pâtes"], "instruction": "Sortez rapidement les pâtes de la casserole, égouttez-les, puis versez-les dans la poêle et mélangez-les rapidement... Et c’est fini !", "step_number": 7}]', 'https://img.spoonacular.com/recipes/660101-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.581604', '2026-01-19 18:23:17.581604', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '660101');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('d4c9835a-289b-4673-8204-755629d2cd9d', 'Comment préparer le poulet Instant Pot parfait', 'La recette Comment faire le poulet parfait à l’Instant Pot peut être préparée en environ 18 minutes. Pour 1,53 $ la portion, vous avez un plat principal pour 6 personnes. Tu fais attention à ta silhouette ? Cette recette sans gluten, sans produits laitiers, paléolithique et primordiale contient 157 calories, 25 g de protéines et 4 g de matières grasses par portion. Rendez-vous au magasin et achetez de l’huile d’avocat, des poitrines de poulet, du sel d’Himalaya et quelques autres choses pour le préparer aujourd’hui. Une personne a essayé et aimé cette recette. Il est présenté par Pink When. Avec un score cuillère de 70 %, ce plat est solide. Des recettes similaires sont les blancs de poulet Perfect Instant Pot, le cheesecake Perfect Instant Pot New York et les Carnitas Instant Pot – parfaits à chaque fois !', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 18, '[{"duration": null, "equipment": ["Instant Pot"], "ingredients": ["assaisonnement", "poulet", "huile de cuisson"], "instruction": "Chauffez le fond de l’Instant Pot en mode saut. Une fois qu’il a chauffé, ajoutez l’huile et les assaisonnements avant de placer le poulet dans l’huile en une seule couche.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 2}, "equipment": [], "ingredients": [], "instruction": "Dorez chaque côté pendant 1 à 2 minutes pour obtenir une saveur riche, puis annulez le mode sauté.", "step_number": 2}, {"duration": null, "equipment": ["poêle à frire", "pot"], "ingredients": ["poulet", "bouillon", "fond"], "instruction": "Versez le bouillon ou le bouillon et déglaçez le fond du moule. Faites glisser le poulet pour décoller les petits morceaux dorés sur la casserole, car c’est la saveur que vous voulez. Remettez le poulet en une seule couche.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 4}, "equipment": [], "ingredients": [], "instruction": "Tournez le couvercle de verrouillage et assurez-vous que la vanne de vapeur est en mode étanchéité. Ensuite, sélectionnez le réglage manuel pour cuire pendant 4 minutes. Veillez à ajuster votre temps de cuisson en fonction de la taille et de l’épaisseur de vos poitrines.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 10}, "equipment": [], "ingredients": ["poulet"], "instruction": "Lorsque le poulet a fini de cuire, laissez-le libérer naturellement la pression pendant 10 minutes. Lorsque le temps est écoulé, relâchez soigneusement toute pression restante et retirez le couvercle.", "step_number": 5}, {"duration": null, "equipment": ["Instant Pot", "mélangeur à main"], "ingredients": ["poulet"], "instruction": "Retirez votre poulet de l’Instant Pot et déchiquetez-le à l’aide de fourchettes ou d’un batteur à main. Le liquide restant de la cuisson peut être conservé pour de futures recettes s’il est utilisé dans les 3 à 4 jours. Bonne lecture !", "step_number": 6}]', 'https://img.spoonacular.com/recipes/1050444-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.583322', '2026-01-19 18:23:17.583322', '{"vegan": false, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '1050444');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('827181cc-0368-4108-8491-15533d75a978', 'Feuilles de curry frites', 'Les chips de feuilles de curry prennent environ 45 minutes du début à la fin. Cette recette en fait 3 et coûte 55 cents la portion. Une portion de ce plat contient environ 4g de protéines, 3g de matières grasses et un total de 177 calories. Quatre personnes étaient ravies d’avoir essayé cette recette. Si vous avez de l’huile, du piment en poudre, du sel et quelques autres ingrédients sous la main, vous pouvez le préparer. Il est présenté par Foodista. Peu de gens aimaient vraiment cet accompagnement. Cette recette est typique de la cuisine américaine. C’est une bonne option si vous suivez un régime sans gluten, sans produits laitiers, lacto-ovo-végétarien et compatible avec les FODMAP. Tout bien considéré, nous avons décidé que cette recette méritait un score cuillère de 92 %. Cette note est exceptionnelle. Les utilisateurs qui ont aimé cette recette ont également apprécié le sauté de poulet avec pommes de terre, noix de cajou et feuilles de curry, feuilles d’igname, feuilles de patate douce sautées, et chutney de feuilles de curry, comment faire un chutney de feuilles de curry.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["pomme de terre"], "instruction": "Essuyez/tapotez les pommes de terre sèches.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["poudre de chili", "sel"], "instruction": "Mélangez du chili en poudre et du sel.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["huile de cuisson"], "instruction": "Chauffez de l’huile et faites frire en quantités jusqu’à ce qu’elles soient croustillantes et croustillantes.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Retirez-les et gardez de côté.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["feuilles de curry", "huile de cuisson"], "instruction": "Dans la même huile, faites frire les feuilles de curry jusqu’à ce qu’elles soient croustillantes aussi.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["frites"], "instruction": "Retirez et ajoutez les chips par-dessus.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": ["frites"], "instruction": "Écrasez et jetez les feuilles avec les chips.", "step_number": 7}]', 'https://img.spoonacular.com/recipes/641122-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.587142', '2026-01-19 18:23:17.587142', '{"vegan": true, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '641122');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('a18e87ad-ec71-4cc3-a4a4-9490d9a23f48', 'Légumes rôtis faciles', 'Easy Roasted Vegetables est une recette sans gluten, sans produits laitiers, lacto-ovo végétarienne et complète de 30 avec 4 portions. Une portion de ce plat contient environ 9 g de protéines, 4 g de matières grasses et un total de 358 calories. Pour 1,28 $ la portion, cette recette couvre 30 % de vos besoins quotidiens en vitamines et minéraux. Trois personnes ont essayé et aimé cette recette. Cette recette de Foodista utilise de la courge musquée, du paprika, du sel et du poivre, et de l’huile d’olive. Ça marche bien comme accompagnement. De la préparation à l’assiette, cette recette prend environ 45 minutes. Tout bien considéré, nous avons décidé que cette recette mérite un score cuillère de 94 %. Cette partition est spectaculaire. Des recettes similaires incluent les légumes rôtis faciles, les légumes rôtis faciles et les légumes d’été rôtis faciles.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Préchauffez le four à 200 degrés Celsius (ventilateur : 180 degrés Celsius)", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["légumes", "pomme de terre"], "instruction": "Épluchez et coupez les légumes en morceaux de la taille d’une bouchée (les pommes de terre n’ont pas forcément besoin d’être pelées).", "step_number": 2}, {"duration": null, "equipment": ["bol"], "ingredients": ["sel et poivre", "Basilic séché", "légumes", "huile d''olive", "paprika"], "instruction": "Mélangez l’huile d’olive, le paprika, le basilic séché, le sel et le poivre dans un grand bol avant d’ajouter les légumes.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Mélangez bien tout.", "step_number": 4}, {"duration": null, "equipment": ["boîte à cuisson"], "ingredients": ["légumes", "étendue"], "instruction": "Placez les légumes sur une grande plaque de cuisson ou un plat de cuisson. Assurez-vous qu’elles soient bien réparties. Vise une simple couche.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 30}, "equipment": ["four"], "ingredients": ["légumes"], "instruction": "Faites cuire les légumes au four pendant environ 30 minutes. Ils doivent être tendres mais garder un léger mordant.", "step_number": 6}]', 'https://img.spoonacular.com/recipes/642085-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.588793', '2026-01-19 18:23:17.588793', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": true}', 'spoonacular', '642085');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('e596b799-00ec-4fa9-94f8-5f65a7b4b578', 'Purée de pommes de terre au parmesan', 'La recette de purée de pommes de terre parmesan peut être préparée en environ 45 minutes. Cette recette contient 4 portions avec 690 calories, 15g de protéines et 51g de matières grasses chacune. Pour 1,39 $ la portion, cette recette couvre 17 % de vos besoins quotidiens en vitamines et minéraux. Thanksgiving sera encore plus spécial avec cette recette. 9 personnes ont fait cette recette et la referaient. Il est présenté par Foodista. Rendez-vous au magasin et achetez du beurre, de la crème, des pommes de terre rouilles, et quelques autres choses pour le préparer aujourd’hui. Il fonctionne bien comme accompagnement à prix raisonnable. C’est une bonne option si vous suivez un régime sans gluten. Tout bien considéré, nous avons décidé que cette recette méritait un score cuillère de 48 %. Cette partition est solide. Essayez la purée de pommes de terre au parmesan, la purée de pommes de terre à l’ail et le parmesan pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["pot"], "ingredients": ["pomme de terre", "eau"], "instruction": "Placez les pommes de terre dans une casserole moyenne et couvrez d’eau froide. Faites bouillir, chauffez à mijoté.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 20}, "equipment": [], "ingredients": ["pomme de terre", "sel"], "instruction": "Ajoutez une bonne pincée de sel et continuez à mijoter jusqu’à ce que les pommes de terre soient tendres comme une fourchette, environ 20 minutes.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 6}, "equipment": ["Effré de pommes de terre", "casserole", "pot"], "ingredients": ["sel et poivre", "pomme de terre", "beurre", "crème"], "instruction": "Faites chauffer de la crème, du sel, du poivre et du beurre dans une casserole moyenne à feu moyen, jusqu’à ce qu’elles soient bien chaudes, environ 6 minutes. Quand les pommes de terre sont prêtes, égouttez et remettez les pommes de terre dans le pot pour qu’elles sèchent un peu. Optionnel : Faites passer les pommes de terre dans un moulin alimentaire ou un poudrichonnet à pommes de terre dans la casserole.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["parmesan", "assaisonnement", "pomme de terre", "beurre", "crème"], "instruction": "Ajoutez des pommes de terre au mélange de crème et de beurre. Incorporez le parmesan, goûtez pour l’assaisonnement.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/654679-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.591049', '2026-01-19 18:23:17.591049', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '654679');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('d5fe315b-64d9-4cb3-8126-566cacf54f63', 'Dulce De Leche Crème Brûlée', 'Si vous souhaitez ajouter plus de recettes végétariennes sans gluten et lacto ovo à votre répertoire, la Dulce de Leche Crème Brûlée pourrait être une recette à essayer. Cette recette en fait 1 et coûte 4,36 $ la portion. Une portion contient 2277 calories, 27 g de protéines et 195 g de matières grasses. Cette recette de Foodista compte 42 fans. De la préparation à l’assiette, cette recette prend environ 45 minutes. Un mélange de crème, de dulce de leche, de sucre et d’autres ingrédients suffit pour rendre cette recette aussi délicieuse. Quelques personnes ont vraiment aimé ce plat principal. Dans l’ensemble, cette recette obtient un excellent score cuillère de 83 %. Les utilisateurs qui ont aimé cette recette ont également apprécié les Alfajores (biscuits à la crème au sandwich au dulce de leche), le gâteau gaufré russe au dulce de leche et le dulce de leche instantané, ainsi que le milkshake au dulce de leche (malteada de arequipe o dulce de leche).', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Four : 325°F", "step_number": 1}, {"duration": null, "equipment": ["Ramequin"], "ingredients": ["eau"], "instruction": "Placez six ramequins dans un bain-marie.", "step_number": 2}, {"duration": null, "equipment": ["fouet"], "ingredients": ["crème", "sucre", "jaune d''œuf", "œuf"], "instruction": "Fouetter les œufs et le sucre jusqu’à ce qu’ils soient pâles, puis versez lentement la crème chaude dans les jaunes en fouettant soigneusement.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 215}, "equipment": ["four", "Ramequin"], "ingredients": [], "instruction": "Versez les crèmes dans les ramequins et faites cuire ~35 minutes jusqu’à ce que ce soit prêt. Laissez au frais au moins 3 heures avant de servir.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["crème", "croûte", "sucre"], "instruction": "Pour servir, saupoudrez environ ~2 cuillères à café de sucre uniformément sur chaque crème et chauffez avec un chalumeau de cuisine jusqu’à ce qu’une croûte brûlée se forme sur chaque crème.", "step_number": 5}]', 'https://img.spoonacular.com/recipes/641727-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.592591', '2026-01-19 18:23:17.592591', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '641727');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('9880e67d-c2b5-4b60-8461-fe8e438e1ff6', 'Œufs brouillés au fromage faciles', 'Easy Cheesy Scrambled Eggs est un petit-déjeuner lacto-ovo végétarien, primal et cétogène sans gluten. Une portion contient 246 calories, 16 g de protéines et 19 g de matières grasses. Cette recette en sert 4 et coûte 78 cents la portion. Trois personnes étaient ravies d’avoir essayé cette recette. Rendez-vous au magasin et achetez du jack cheese, du lait, du sel et du poivre, ainsi que quelques autres choses pour le préparer aujourd’hui. De la préparation à l’assiette, cette recette prend environ 45 minutes. Il est présenté par Foodista. Avec un score cuillère de 42 %, ce plat est solide. Des recettes similaires sont les œufs brouillés faciles au fromage, les œufs brouillés faciles au fromage et les œufs brouillés faciles au fromage.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["sel et poivre", "crème", "œuf", "lait"], "instruction": "Faites brouiller les œufs avec du lait ou de la crème, un peu de sel et de poivre.", "step_number": 1}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["œuf"], "instruction": "Faites cuire dans une poêle antiadhésive à feu moyen, en remuant pour soulever les œufs cuits du fond de la poêle pendant la cuisson.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 2}, "equipment": [], "ingredients": ["Fromage Monterey Jack", "fromage", "œuf"], "instruction": "Quand les œufs sont presque cuits, ajoutez du fromage jack et faites cuire encore 1 à 2 minutes pour faire fondre le fromage.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["tortilla", "pain sandwich"], "instruction": "Servez-le tel quel, sur des toasts ou dans une tortilla.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/641890-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.594342', '2026-01-19 18:23:17.594342', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '641890');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('81b1aa70-8562-4b6b-89dc-9ee5fa399e12', 'Glace facile à 3 ingrédients pour congélateur', 'Easy 3 Ingredient Freezer Ice Cream pourrait être exactement la recette végétarienne sans gluten et lacto ovo que vous cherchiez. Cette recette en fait 8. Pour 47 cents la portion, cette recette couvre 5 % de vos besoins quotidiens en vitamines et minéraux. Une portion contient 262 calories, 5 g de protéines et 15 g de matières grasses. Il est présenté par Foodista. L’été sera encore plus spécial avec cette recette. Une personne a été impressionnée par cette recette. Rendez-vous au magasin et achetez de la crème fouettée épaisse, de l’extrait de vanillan, du lait concentré et quelques autres choses pour le préparer aujourd’hui. De la préparation à l’assiette, cette recette prend environ 24 heures et 20 minutes. Tout bien considéré, nous avons décidé que cette recette mérite un score cuillère de 20 %. Cette partition n’est pas si excellente. La sauce au chocolat facile à 3 ingrédients pour la glace, la glace à deux ingrédients (la glace Reese’s mini beurre de cacahuète au beurre de glace) et la glace à deux ingrédients (la glace Reese’s mini beurre de cacahuète glace) sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 1460, '[{"duration": {"unit": "minutes", "number": 3}, "equipment": ["mélangeur de support", "mélangeur à main", "bol"], "ingredients": ["lait condensé sucré", "extrait de vanille", "crème fouettée"], "instruction": "Dans un bol de batteur sur pied (ou dans un grand bol de cuisine, si vous prévoyez d’utiliser un batteur à main), versez la crème fouettée réfrigérée et l’extrait de vanille. Fouetter jusqu’à ce que des pics mous se forment, environ 2-3 minutes. Ajoutez lentement le lait condensé sucré en fouettez, puis fouettez jusqu’à ce que des pics fermes se forment.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 1440}, "equipment": ["enveloppe plastique", "Moule à pain", "bol"], "ingredients": ["enveloppe"], "instruction": "Versez dans un moule ou un bol. Couvrez-le de film plastique, mettez-le au congélateur et laissez-y jusqu’à ce que ce soit ferme et solide. Cela peut prendre 24 heures.", "step_number": 2}]', 'https://img.spoonacular.com/recipes/1096297-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.595853', '2026-01-19 18:23:17.595853', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '1096297');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('d149eeee-dcfa-4af3-aef8-79096f103b0a', 'Glace au chocolat doux-amer', 'La glace au chocolat amère-douce est une recette lacto-ovo-végétarienne sans gluten, et primale en 2 portions. Une portion de ce plat contient environ 11 g de protéines, 71 g de matières grasses et un total de 734 calories. Pour 1,6 $ la portion, cette recette couvre 12 % de vos besoins quotidiens en vitamines et minéraux. 68 personnes ont goûté et aimé cette recette. Un mélange de moitié-moitié, de crème fouettée épaisse, d’extrait de vanillan et d’une poignée d’autres ingrédients suffisent pour rendre cette recette aussi savoureuse. De la préparation à l’assiette, cette recette prend environ 45 minutes. Ce sera un succès lors de votre événement d’été. Il est présenté par Foodista. Avec un score cuillère de 52 %, ce plat est bon. Si vous aimez cette recette, vous pourriez aussi aimer des recettes comme la glace au chocolat doux-amer, le gâteau au chocolat avec glace à la fraise et la sauce au chocolat doux-amer, et les gâteaux au chocolat fondu doux-amer avec glace au café.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["machine à crème glacée", "casserole", "fouet", "bol"], "ingredients": ["moitié et moitié", "jaune d''œuf", "glace", "sauce"], "instruction": "Préparez votre machine à glaces selon les instructions du fabricant. Dans une casserole moyenne, chauffez la moitié et la moitié jusqu’à ce qu’elles soient chaudes – pas chaudes. Dans un bol, fouetter les jaunes jusqu’à ce qu’ils soient mixés.", "step_number": 1}, {"duration": null, "equipment": ["casserole"], "ingredients": ["moitié et moitié", "sucre"], "instruction": "Ajoutez le sucre et environ la moitié de la moitié tiède de la moitié et moitié. Remuez pour bien mélanger et réajoutez le mélange dans la casserole.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 12}, "equipment": ["spatule de cuisson", "fouet"], "ingredients": [], "instruction": "Fouetter rapidement tout en mélangeant. Faites cuire à feu moyen jusqu’à ce que le mélange enrobe le dos d’une spatule en silicone (environ 10-12 minutes).", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["chocolat", "café"], "instruction": "Retirez du feu et ajoutez le chocolat et le café, remuez pour faire fondre et mélangez bien.", "step_number": 4}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["crème", "glace"], "instruction": "Placez la poêle avec la crème dans un bain de glace pour qu’elle refroidisse, en remuant de temps en temps, jusqu’à atteindre la température ambiante.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["crème fouettée", "vanille"], "instruction": "Ajoutez la crème chantilly et la vanille", "step_number": 6}, {"duration": null, "equipment": ["machine à crème glacée"], "ingredients": ["glace"], "instruction": "Versez dans un autre récipient et refroidissez jusqu’à ce que vous refroidissez - plusieurs heures - ou soyez prêt à verser dans la machine à glaces. Congelez dans la machine à glaces selon les instructions du fabricant. Ça fait environ un litre.", "step_number": 7}]', 'https://img.spoonacular.com/recipes/635040-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.64099', '2026-01-19 18:23:17.64099', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '635040');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('7f762f48-de15-4669-b287-726263be1396', 'Accompagnement rapide et frais « pickle »', 'Le plat d’accompagnement rapide « pickle » frais est un accompagnement végétarien sans gluten, sans produits laitiers, paléolithique et lacto ovo. Une portion contient 15 calories, 1g de protéines et 0g de matières grasses. Cette recette en fait 6. Pour 31 centimes la portion, cette recette couvre 2 % de vos besoins quotidiens en vitamines et minéraux. Cette recette est appréciée par un gourmet et des cuisiniers. Rendez-vous au magasin et achetez du vinaigre de vin blanc, de l’aneth, des glaçons et quelques autres choses pour le préparer aujourd’hui. De la préparation à l’assiette, cette recette prend environ 1 heure et 15 minutes. Il est présenté par Foodista. Avec un score cuillère de 51 %, ce plat est plutôt excellent. Le plat d’accompagnement rapide au brocoli, le plat d’accompagnement rapide au brocoli et le plat d’accompagnement rapide au brocoli sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 75, '[{"duration": null, "equipment": ["bol"], "ingredients": ["concombre"], "instruction": "Placez les lances de concombre dans un bol ou un plat où elles peuvent s’aplatir. Les herbes Nestlé arrivent avec des lances.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["Glaçons", "vinaigre"], "instruction": "Saupoudrez du vinaigre sur les lances. Garnissez de glaçons et placez-les au réfrigérateur pendant une heure avant de servir.", "step_number": 2}]', 'https://img.spoonacular.com/recipes/643422-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.596862', '2026-01-19 18:23:17.596862', '{"vegan": true, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '643422');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('2b96b08c-d0f8-4968-832c-739591b56a47', 'Kyuri Tsukemono', 'La recette Kyuri Tsukemono est prête en environ 45 minutes et est définitivement une excellente option sans gluten, sans produits laitiers, lacto-ovo végétarienne et adaptée aux FODMAP pour les amateurs de cuisine asiatique. Cette recette contient 4 portions avec 45 calories, 2g de protéines et 1g de matières grasses chacune. Pour 65 cents la portion, cette recette couvre 5 % de vos besoins quotidiens en vitamines et minéraux. 5 personnes ont fait cette recette et la referaient. Rendez-vous au magasin et achetez jusqu’à 4 concombres japonais, piments, vinaigre de riz et quelques autres choses pour le préparer aujourd’hui. Ça marche bien comme accompagnement. Il est présenté par Foodista. Dans l’ensemble, cette recette obtient un bon score cuillère de 46 %. Si vous aimez cette recette, jetez un œil à ces recettes similaires : .', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["concombre"], "instruction": "Hacher grossièrement les concombres.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["Vinaigre de riz", "Huile de sésame", "sauce de soja"], "instruction": "Dans un contenant moyen et bien scellable, mélangez la sauce soja, le vinaigre de riz et l’huile de sésame.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["concombre", "marinade", "agiter"], "instruction": "Ajoutez les concombres à la marinade, refermez le contenant et secouez.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 120}, "equipment": [], "ingredients": ["concombre", "marinade", "agiter"], "instruction": "Mettez au réfrigérateur pendant 1 à 2 heures. Secouez les concombres de temps en temps, ou laissez-les mariner toute la nuit. Notez que plus les concombres restent longtemps dans la marinade, plus ils deviennent salés. Je les ai laissés dans la marinade jusqu’à 3 jours et les concombres étaient bons.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servez et profitez !", "step_number": 5}]', 'https://img.spoonacular.com/recipes/649137-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.598896', '2026-01-19 18:23:17.598896', '{"vegan": true, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '649137');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('3383dfde-d112-4688-9665-ea370d802ce4', 'Hot Charlotte Cocktail', 'On ne mange jamais trop de recettes de boissons, alors essayez Hot Charlotte Cocktail. Cette recette sans gluten, sans produits laitiers et adaptée aux FODMAP en fait un seul et coûte 3,72 $ la portion. Une portion de ce plat contient environ 0 g de protéines, 0 g de matières grasses et un total de 256 calories. Cette recette est appréciée par 4 gourmets et cuisiniers. Si vous avez du gin Hendrick’s, du St. Germain, du concombre et quelques autres ingrédients à disposition, vous pouvez le préparer. Il est présenté par Foodista. De la préparation à l’assiette, cette recette prend environ 45 minutes. Dans l’ensemble, cette recette obtient un score amélioré de 7 %. Le cocktail au rhum au beurre chaud, le cardigan chaud, un cocktail chaud et les boulettes de viande au cocktail chaud et sauté sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["cocktail", "concombre"], "instruction": "Dans un verre cocktail, écrasez le concombre avec du tobasco", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["alcool", "agiter"], "instruction": "Ajoutez les spiritueux et bien secouez", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["concombre", "glace"], "instruction": "Filtrez sur la glace et garnissez avec une roue à concombre", "step_number": 3}]', 'https://img.spoonacular.com/recipes/647412-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.601538', '2026-01-19 18:23:17.601538', '{"vegan": false, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '647412');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('8b0a3d55-1a21-4c42-8df4-6ac80bc5cb46', '4 juillet FRAMBOISES, BLANCS ET MYRTILLES Cocktail de la ferme à la table De Harvest Spirits', 'Vous avez besoin d’une boisson végétarienne sans produits laitiers, lacto ovo et végane ? 4 juillet FRAMBOISE, BLANC ET MYRTILLE : LE Cocktail From Harvest Spirits pourrait être une excellente recette à essayer. Cette recette sert 1. Une portion contient 559 calories, 2g de protéines et 1g de matières grasses. Pour 4,63 $ la portion, cette recette couvre 10 % de vos besoins quotidiens en vitamines et minéraux. Seules quelques personnes ont fait cette recette, et une dis-le a fait juste. C’est une recette assez coûteuse pour les amateurs de cuisine méditerranéenne. Rendez-vous au magasin et achetez un peu de jus de canneberge, d’eau tonique, de garnitures et quelques autres choses pour le préparer aujourd’hui. Il est présenté par Foodista. De la préparation à l’assiette, cette recette prend environ 45 minutes. Avec un score cuillère de 27 %, ce plat est plutôt mauvais. Les glaces glacées au cocktail du 4 juillet, le gâteau aux poké aux fraises aux myrtilles du 4 juillet, et le dessert du 4 juillet : fudge au chocolat blanc sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["jus de canneberge", "Eau tonique", "framboises", "alcool", "Vodka"], "instruction": "Mélangez 3oz de vodka framboise noire Harvest Spirits, 1oz d’eau tonique et ajoutez un peu de jus de canneberge.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["myrtilles", "pomme"], "instruction": "Garnissez d’une tranche de pomme cultivée localement, fendus pour fixer sur le verre et fixez les myrtilles avec un cure-dent.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["cocktail"], "instruction": "Servir dans un verre à cocktail bien frais", "step_number": 3}]', 'https://img.spoonacular.com/recipes/631870-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.603751', '2026-01-19 18:23:17.603751', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '631870');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('e34443ab-924f-4163-ac0a-9b9a64a925ac', 'Spaghettis au saumon fumé et crevettes', 'Les spaghettis avec saumon fumé et crevettes prennent environ 45 minutes du début à la fin. Ce plat d’œuvre contient 62 calories, 3 g de protéines et 3 g de matières grasses par portion. Pour 17 cents la portion, cette recette couvre 1 % de vos besoins quotidiens en vitamines et minéraux. Cette recette en sert 24. Rendez-vous au magasin et achetez du saumon, de l’ail – ou des crevettes – et des produits propres, ainsi que quelques autres choses pour les préparer aujourd’hui. Une personne a fait cette recette et la referait. C’est une bonne option si vous suivez un régime sans produits laitiers et pescétarien. Il est présenté par Foodista. Dans l’ensemble, cette recette obtient un score cuillère pas très bon de 31 %. Si vous aimez cette recette, vous pourriez aussi apprécier des recettes comme les spaghettis au saumon fumé, les spaghettis au saumon fumé rapidement, et les spaghettis au saumon fumé chaud et à l’aneth.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["bol"], "ingredients": ["saumon fumé", "spaghetti"], "instruction": "Faites cuire les spaghettis selon les instructions du paquet. Préparez la vaisselle et mettez-la dans un grand bol. Utilisez une fourchette pour desserrer le saumon fumé et mettez de côté.", "step_number": 1}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["Spaghettis cuits", "saumon fumé", "huile d''olive", "ail", "poivre", "crevettes"], "instruction": "Chauffez la poêle à feu moyen, ajoutez de l’huile d’olive, ajoutez de l’ail et faites sauter un moment. Ensuite, ajoutez les crevettes et faites frire jusqu’à cuire, baissez le feu et versez le saumon fumé et les aneths frais ~ bien sauté et coupez le feu. Enfin, versez tous les ingrédients sur les spaghettis cuits, mélangez bien avec un peu de poivre, puis servez dans une assiette individuelle. Bonne lecture !", "step_number": 2}]', 'https://img.spoonacular.com/recipes/660837-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.606729', '2026-01-19 18:23:17.606729', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '660837');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('aebb40af-bea8-4e4a-904e-62e1444d3cb4', 'Macaronis au fromage', 'Les macaronis au fromage sont un plat principal qui sert deux personnes. Pour 1,28 $ la portion, cette recette couvre 21 % de vos besoins quotidiens en vitamines et minéraux. Une portion contient 637 calories, 32g de protéines et 32g de matières grasses. Une personne était contente d’avoir essayé cette recette. Rendez-vous au magasin et achetez des pâtes, du lait, du fromage et quelques autres choses pour les préparer aujourd’hui. Il vous est présenté par thecuisine.blogspot.com. Peu de gens aimaient vraiment ce plat américain. De la préparation à l’assiette, cette recette prend environ 20 minutes. Avec un score cuillère de 0 %, ce plat est très mauvais (mais toujours réparable). Des recettes similaires incluent des macaronis au gruyère et emmentaler au jambon et au levain en cubes de ''Melt : L’art des macaronis au fromage, courge musquée, macaronis au fromage bacon et fromage bleu, et deux macaronis au fromage au courge musquée et cuisine en garderie.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 20, '[{"duration": null, "equipment": [], "ingredients": ["eau", "sel"], "instruction": "Faites bouillir de l’eau dans un grand récipient avec du sel.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["pâtes"], "instruction": "Ajoutez les pâtes et faites bouillir jusqu’à ce qu’elles soient cuites.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["pâtes"], "instruction": "Ne cuit pas trop les pâtes. Il doit être ferme à mordre, mais cuit à travers.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["eau"], "instruction": "Évacuez l’eau et rincez à l’eau froide.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Égouttez et gardez de côté.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["farine de tous usages", "lait"], "instruction": "Diluez la farine dans 1/4 de tasse de lait et gardez-la de côté.", "step_number": 6}, {"duration": null, "equipment": ["casserole"], "ingredients": ["lait"], "instruction": "Faites chauffer 1/2 tasse de lait dans la casserole à feu moyen.", "step_number": 7}, {"duration": null, "equipment": [], "ingredients": ["farine de tous usages", "lait"], "instruction": "Ajoutez la farine et le lait au lait tiède et continuez à remuer jusqu’à ce que le lait épaississe légèrement.", "step_number": 8}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Mets le feu à bas.", "step_number": 9}, {"duration": null, "equipment": [], "ingredients": ["fromage", "sel"], "instruction": "Ajoutez le fromage râpé et le sel, puis remuez bien jusqu’à ce que le fromage ait fondu.", "step_number": 10}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["sauce"], "instruction": "Lorsque la sauce est lisse et crémeuse, retirez la poêle du feu.", "step_number": 11}, {"duration": null, "equipment": [], "ingredients": ["Sauce au fromage", "pâtes cuites"], "instruction": "Ajoutez les pâtes cuites à la sauce au fromage.", "step_number": 12}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Mélangez jusqu’à ce que ce soit bien enrobé.", "step_number": 13}, {"duration": null, "equipment": [], "ingredients": ["poivre"], "instruction": "Saupoudrez un peu de poudre de poivre et servez immédiatement tout en étant encore chaud.", "step_number": 14}, {"duration": null, "equipment": [], "ingredients": ["sauce", "lait"], "instruction": "Si la sauce est sèche après le roucoulement, ajoutez un peu de lait et réchauffez-la pour la rendre crémeuse à nouveau.", "step_number": 15}]', 'https://img.spoonacular.com/recipes/1681413-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.609473', '2026-01-19 18:23:17.609473', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '1681413');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('da1fb312-39d0-4466-af21-70f0915a281b', 'Choux de Bruxelles avec œufs salés', 'Les choux de Bruxelles avec œufs salés nécessitent environ 45 minutes du début à la fin. Pour 1,34 $ la portion, vous avez un plat principal qui sert 1. Une portion de ce plat contient environ 20 g de protéines, 42 g de matières grasses et un total de 524 calories. Seules quelques personnes ont fait cette recette, et une dis-le a fait juste. Un mélange de flocons piquants, d’œufs, d’huile de pépins de raisin et d’une poignée d’autres ingrédients suffit pour rendre cette recette aussi savoureuse. C’est une bonne option si vous suivez un régime végétarien sans gluten et lacto ovo. Il est présenté par Foodista. Dans l’ensemble, cette recette obtient un solide score cuillère de 51 %. Des recettes similaires sont choux de Bruxelles au bacon rôti avec miel salé, choux de Bruxelles et œufs, et choux de Bruxelles et œufs.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["blancs d''œufs", "jaune d''œuf"], "instruction": "Écrasez ensemble 2 jaunes d’œuf salés + un blanc d’œuf. (Utiliser les deux blancs d’œufs rendrait les blancs trop salés)", "step_number": 1}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["Huile de pépins de raisin", "beurre", "ail"], "instruction": "Chauffez du beurre et de l’huile de pépins de raisin dans une poêle et incorporez de l’ail haché. Remuez rapidement sans trop brunir.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["Choux de Bruxelles", "œuf"], "instruction": "Ajoutez des œufs salés écrasés. Faites sauter un peu puis ajoutez les choux de Bruxelles.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["pousses", "eau", "lait"], "instruction": "Remuer pour mélanger. Si elle a l’air un peu sèche, ajoutez un peu d’eau ou de lait et faites cuire jusqu’à ce que les pousses prennent une légère couleur translucide... Ou si vous les aimez croquants, faites cuire plus court.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["sucre"], "instruction": "Ajoutez un peu de sucre au goût et mélangez des flocons pimentés.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["Riz blanc"], "instruction": "Servez chaud avec du riz blanc moelleux.", "step_number": 6}]', 'https://img.spoonacular.com/recipes/636366-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.611826', '2026-01-19 18:23:17.611826', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '636366');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('c69d48c5-9fdd-4b47-b050-0670b4ff4336', 'Galetes d’avoine de pois de cime', 'Si vous avez environ 45 minutes à passer en cuisine, les Garbanzo Oat Patties pourraient être une excellente recette sans gluten, sans produits laitiers, lacto-ovo végétarienne et vegan à essayer. Ce plat principal contient 1954 calories, 67 g de protéines et 105 g de matières grasses par portion. Cette recette sert 1. Pour 4,27 $ la portion, cette recette couvre 49 % de vos besoins quotidiens en vitamines et minéraux. Un mélange de levure chimique sans alun, de noix, de sel de mer et de quelques autres ingrédients suffit pour rendre cette recette aussi délicieuse. Une personne a fait cette recette et la referait. Il est présenté par Foodista. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 87 %, ce qui est excellent. Des recettes similaires incluent les galettes de pois chiches salées, la tarte au yaourt avec croûte d’avoine et garniture croquante d’avoine, et le gazpacho de garbanzo.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["bol"], "ingredients": ["Farine de pois chiches", "eau"], "instruction": "Mélangez de la farine de pois chiches et de l’eau froide dans un grand bol.", "step_number": 1}, {"duration": null, "equipment": ["bol"], "ingredients": ["flocons d''avoine", "eau"], "instruction": "Versez de l’eau bouillante sur des flocons d’avoine dans un autre bol. Couvrez et laissez reposer quelques minutes.", "step_number": 2}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": [], "instruction": "Mélangez tous les ingrédients ensemble. Remuez bien. Formez des galettes sur une plaque huilée.", "step_number": 3}, {"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Faites cuire jusqu’à ce que ce soit doré d’un côté. Tournez-vous et brunez de l’autre côté.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/644177-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.614908', '2026-01-19 18:23:17.614908', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '644177');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('204d12b2-7d88-44e7-97cb-e4fc7ed5ac39', 'Pâtes All’arrabbiata', 'Vous avez besoin d’un plat principal sans produits laitiers ? Le pastan All’arrabbiata pourrait être une excellente recette à essayer. Une portion contient 2750 calories, 84 g de protéines et 70 g de matières grasses. Cette recette en fait 1 et coûte 6,97 $ la portion. Cette recette de Foodista nécessite du persil, des pâtes, du sel — et de l’huile d’olive. Une personne était contente d’avoir essayé cette recette. De la préparation à l’assiette, cette recette prend environ 45 minutes. Avec un score cuillère de 92 %, ce plat est génial. Les utilisateurs qui ont aimé cette recette ont également apprécié la sauce pâtes arrabbiata, le gratin de pâtes arrabbiata tunan, et la sauce arrabbiata : pâtes saucisses épicées.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["Flocons de piment rouge", "Sauce tomate", "prosciutto", "huile d''olive", "Pancetta", "tomate"], "instruction": "Pour info : la sauce tomate avec seulement de l’huile d’olive et beaucoup de flocons de piment rouge est sous plusieurs noms, l’un des plus célèbres est celui-ci qui, traduit, signifie « en colère ». Souvent, ces sauces contiennent de la pancetta ou du prosciutto. Si des tomates fraîches sont utilisées, coupez-les en morceaux.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 25}, "equipment": ["cuillère en bois", "casserole", "pot"], "ingredients": ["Flocons de piment rouge", "tomates en conserve", "sel et poivre", "sel grossier", "tomate", "pâtes", "eau", "huile de cuisson"], "instruction": "Placez les tomates fraîches ou en conserve avec l’huile dans une casserole moyenne sur le feu du meduim et faites cuire pendant 25 minutes, en remuant de temps en temps avec une cuillère en bois. Assaisonner au goût avec du sel et du poivre. Faites passer le mélange dans un moulin à aliments, en utilisant l’idsc avec les plus petits trous, dans une deuxième casserole. Remettez les tomates à feu moyen, ajoutez les flocons de piment rouge, puis laissez mijoter encore 15 minutes. Portez à ébullition une grande casserole d’eau froide, ajoutez du gros sel à votre goût, puis ajoutez les pâtes et faites cuire jusqu’à l’eau au dente. Hachez grossièrement le parsin sur une planche.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["basilic frais", "persil", "pâtes"], "instruction": "Égouttez les pâtes, transférez sur un plateau chaud, étalez le suace, et servez immédiatement. Pour une variante, vous pouvez utiliser 15 grandes feuilles de basilic fraîches, déchirées en trois, au lieu du persil.", "step_number": 3}]', 'https://img.spoonacular.com/recipes/654796-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.618077', '2026-01-19 18:23:17.618077', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": true}', 'spoonacular', '654796');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('52cff43d-1de0-4dba-ad32-a51a92242204', 'Glace au bacon', 'La recette de la glace au bacon peut être préparée en environ 45 minutes. Cette recette sans gluten, adaptée aux FODMAP et en 30 entiers sert 2 personnes et coûte 5,45 $ la portion. Une portion de ce plat contient environ 30 g de protéines, 100 g de matières grasses et un total de 1040 calories. Il est présenté par Foodista. 9 personnes ont été impressionnées par cette recette. L’été sera encore plus spécial avec cette recette. Un mélange de bacon, de glace dulce de leche, de pacanes et de quelques autres ingrédients suffit pour rendre cette recette aussi délicieuse. Tout bien considéré, nous avons décidé que cette recette méritait un score cuillère de 66 %. Cette partition est bonne. Si vous aimez cette recette, jetez un œil à ces recettes similaires : Glace au bacon et à l’érable {Pas besoin de machine à glace !}, Glace Chocolat-Amande - Glace Bacon et Œufs, et Glace au Bacon.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["bol"], "ingredients": ["bacon", "noix"], "instruction": "Mélangez le bacon et les noix dans un bol. Mettez de côté une cuillère à café de bacon et de noix pour la garnisse.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["glace", "bacon", "noix"], "instruction": "Mélangez du bacon haché et des noix dans une glace, puis remettez au congélateur. Après avoir congelé la glace au bacon, servez-le dans une tasse et garnissez avec des morceaux de bacon et de noix. Bonne lecture !", "step_number": 2}]', 'https://img.spoonacular.com/recipes/633314-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.62412', '2026-01-19 18:23:17.62412', '{"vegan": false, "dairyFree": false, "lowFodmap": true, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '633314');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('63d57c82-813e-416d-a990-6c15641964c2', 'Comment réaliser une poitrine de poulet farcie au bacon incroyable', 'Comment faire une poitrine de poulet farcie emballée au bacon incroyable pourrait être exactement la recette sans gluten, sans produits laitiers, adaptée aux FODMAP, et complète des 30 recettes que vous cherchais. Cette recette en sert 4 et coûte 2,43 $ la portion. Cet accompagnement contient 594 calories, 38 g de protéines et 47 g de matières grasses par portion. Deux personnes ont trouvé cette recette délicieuse et satisfaisante. De la préparation à l’assiette, cette recette prend environ 1 heure et 15 minutes. Rendez-vous au magasin et achetez du bacon en noyer hickory marque Wright, des poitrines de poulet, de la sauce complète et quelques autres choses pour le préparer aujourd’hui. Il est présenté par Pink When. Avec un score cuillère de 47 %, ce plat est bon. Si vous aimez cette recette, jetez un œil à ces recettes similaires : Comment préparer une poitrine de poulet farcie au bacon enrobée de bacon, poitrine de poulet farcie douce et collante au bacon, et poitrine de poulet fourrée à l’avocat et au cheddar.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 75, '[{"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Chauffez le four à 375", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["poitrine de poulet", "poulet"], "instruction": "Blanc de poulet propre et sec. (Sécher le poulet facilite la découpe.)", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["poitrine de poulet"], "instruction": "Tranchez la poitrine de poulet dans le sens de la longueur.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["poitrine de poulet"], "instruction": "Ajoutez la vinaigrette à la poitrine de poulet. Ferme du mieux que tu peux.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["poulet farci", "bacon", "enveloppe"], "instruction": "Enroulez le bacon autour du blanc farci, en superposant les bords du bacon au fur et à mesure que vous l’enroulez.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 60}, "equipment": ["four"], "ingredients": [], "instruction": "Faites cuire au four pendant 1 heure, ou jusqu’à ce que la température interne atteigne 165°F.", "step_number": 6}, {"duration": {"unit": "minutes", "number": 5}, "equipment": ["four"], "ingredients": [], "instruction": "Sortez-le du four, laissez refroidir pendant 5 minutes.", "step_number": 7}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servez avec vos accompagnements préférés.", "step_number": 8}]', 'https://img.spoonacular.com/recipes/1056442-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.625116', '2026-01-19 18:23:17.625116', '{"vegan": false, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '1056442');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('4cfb1b4d-e65d-4b8d-8be3-137a24e03a3c', 'Gâteau S’mores', 'Le gâteau S’mores pourrait être exactement la recette sans produits laitiers que vous cherchiez. Une portion contient 222 calories, 3g de protéines et 10g de matières grasses. Cette recette en sert 10. Pour 77 cents la portion, cette recette couvre 5 % de vos besoins quotidiens en vitamines et minéraux. Seules quelques personnes ont fait cette recette, et une dis-le a fait juste. Rendez-vous au magasin et achetez des barres de chocolat Hershey’s de taille normale, des biscuits Graham, des guimauves et quelques autres choses pour le préparer aujourd’hui. Il est présenté par Pink When. De la préparation à l’assiette, cette recette prend environ 1 heure et 5 minutes. Dans l’ensemble, cette recette obtient un score pas si impressionnant de 22 % en cuillères. Des recettes similaires sont le gâteau S’mores, le gâteau S’mores et le gâteau S’mores.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 65, '[{"duration": null, "equipment": ["four"], "ingredients": ["Mélange à gâteau jaune"], "instruction": "Prenez le mélange à gâteau jaune et les ingrédients nécessaires et faites cuire deux gâteaux ronds de 8\". Laissez refroidir et placez-le sur des grilles de refroidissement.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["Glaçage au chocolat"], "instruction": "Ajoutez une couche de glaçage au chocolat Hershey’s par-dessus le bas du rond.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["Biscuits Graham", "glaçage"], "instruction": "Saupoudrez une couche de biscuits Graham sur le glaçage. Prenez le deuxième gâteau et saupoudrez le dessus de biscuits Graham.", "step_number": 3}, {"duration": null, "equipment": ["porte-fils", "poulet", "four", "poêle à frire"], "ingredients": ["guimauves"], "instruction": "Placez les guimauves sur le gâteau, puis mettez-les au four avec le gril pour faire fondre les guimauves. Surveillez cela de près pour ne pas brûler les guimauves ! Laissez le gâteau et les guimauves refroidir à nouveau. Ensuite, retirez soigneusement le gâteau du moule sur une grille de refroidissement.", "step_number": 4}, {"duration": null, "equipment": ["micro-ondes"], "ingredients": ["Glaçage au chocolat", "Barre-chocolat", "Biscuits Graham", "guimauves", "glaçage"], "instruction": "Placez le gâteau avec les guimauves sur le gâteau, avec le glaçage et la couche de biscuits graham. Prenez le glaçage au chocolat Hershey’s et couvrez les côtés arrondis. Ensuite, prenez les barres chocolatées Hershey’s et placez-les tout autour du gâteau sur les côtés. Si vous cassez les barres en deux, elles s’ajusteront parfaitement autour du gâteau. Quand vous êtes prêt à servir, il suffit de trancher et si vous voulez que ce soit chaud comme le traditionnel S’more, réchauffez-le au micro-ondes pendant environ 8 secondes. Ça devrait tout ramollir - ET - honnêtement, c’est tellement délicieux quand on est réchauffé !", "step_number": 5}]', 'https://img.spoonacular.com/recipes/673444-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.626617', '2026-01-19 18:23:17.626617', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '673444');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('7ce8b604-fb86-4514-b450-9064c24ef95a', 'Tourte au poulet à 4 ingrédients', 'La tarte au poulet 4 ingrédients pourrait être une bonne recette pour enrichir votre boîte de recettes principale. Cette recette en sert 6 et coûte 4,41 $ la portion. Une portion contient 802 calories, 79 g de protéines et 30 g de matières grasses. Rendez-vous au magasin et achetez une pâte à tarte, de la sauce au poulet Campbell’s, des conserves de blanc de poulet Swanson Premium dans de l’eau, et quelques autres choses pour la préparer aujourd’hui. C’est une bonne option si vous suivez un régime sans produits laitiers. 24 personnes ont goûté et aimé cette recette. De la préparation à l’assiette, cette recette prend environ 45 minutes. Il est présenté par Foodista. Tout bien considéré, nous avons décidé que cette recette mérite un score cuillère de 90 %. Cette partition est excellente. Essayez les tacos au poulet à 5 ingrédients Instant Pot, le poulet effiloché mexicain à la mijoteuse à 5 ingrédients, et les mini tourtes au poulet à 4 ingrédients | Des repas simples pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 15}, "equipment": [], "ingredients": ["croûte de tarte"], "instruction": "Laissez reposer les pâtes à température ambiante pendant 15 minutes ou jusqu’à ce qu’elles soient faciles à manipuler.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["croûte de tarte"], "instruction": "Placez une pâte à tarte dans une assiette de 20 cm.", "step_number": 2}, {"duration": null, "equipment": ["bol"], "ingredients": ["légumes", "poulet", "sauce"], "instruction": "Remuez la sauce, les légumes et le poulet dans un bol moyen. Mettez le mélange de poulet dans l’assiette à tarte.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["croûte de tarte"], "instruction": "Placez la pâte restante sur la garniture. Appuyez sur les bords pour sceller.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["croûte"], "instruction": "Découpez plusieurs fentes dans la croûte supérieure.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 45}, "equipment": ["four"], "ingredients": ["croûte"], "instruction": "Faites cuire à 400°F pendant 45 minutes ou jusqu’à ce que la croûte soit dorée.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": ["pomme de terre", "carotte", "petits pois"], "instruction": "Utilisez une combinaison de carottes tranchées, pois et pommes de terre en cubes.", "step_number": 7}]', 'https://img.spoonacular.com/recipes/631868-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.628627', '2026-01-19 18:23:17.628627', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '631868');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('e00ffe4d-7bcc-470f-b678-edc5e07267a3', 'Entrée au jalapeño farcie au fromage de chèvre', 'La recette, Entrée au jalapeño farci au fromage de chèvre et au bacon, peut être préparée en environ 45 minutes. Pour 1,05 $ la portion, cette recette couvre 5 % de vos besoins quotidiens en vitamines et minéraux. Cette recette fait 6 portions avec 192 calories, 7g de protéines et 17g de matières grasses chacune. Une personne a trouvé cette recette savoureuse et satisfaisante. Rendez-vous au magasin et achetez du bacon, du fromage de chèvre, des jalapeños et quelques autres choses pour le préparer aujourd’hui. C’est une bonne option si vous suivez un régime sans gluten et primitif. Ça marche bien comme accompagnement. Il est présenté par Foodista. Tout bien considéré, nous avons décidé que cette recette mérite un score cuillère de 19 %. Cette note est plutôt mauvaise. Si vous aimez cette recette, vous aimerez peut-être aussi des recettes comme Griller : crevettes enroulées au bacon, jalapeño et fromage, caille enrobée de bacon farcie au fromage de chèvre, et dattes enroulées au bacon farcies au fromage de chèvre.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 20}, "equipment": ["four", "grille"], "ingredients": ["chèvre", "piment jalapeño", "poivrons", "fromage", "poivre", "bacon", "graines", "enveloppe"], "instruction": "Coupez le dessus des jalapeños et jetez-le. Grattez et rincez autant de graines que possible des jalapeños. Répartissez uniformément le fromage de chèvre entre les 6 piments et garnissez chaque jalapeño avec le fromage. Enroulez une tranche de bacon autour de chaque poivron et réservez-la. Une fois tous les poivrons remplis et enveloppés, placez les piments sur un grill moyen-vif et faites cuire jusqu’à ce que le bacon soit complètement cuit. Ou posez les piments sur une plaque et faites cuire à 350 °F pendant 20 minutes.", "step_number": 1}]', 'https://img.spoonacular.com/recipes/644958-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.631014', '2026-01-19 18:23:17.631014', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '644958');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('6701e0b8-f8a9-49fb-a25b-5d1d3a0a4d5a', 'Truffes au chocolat alcoolisées', 'Si vous avez environ 45 minutes à passer en cuisine, Boozy Chocolate Truffles pourrait être une excellente recette sans gluten à essayer. Cette recette contient 1 portion contenant 1887 calories, 22g de protéines et 158g de matières grasses chacune. Pour 6,69 $ la portion, cette recette couvre 39 % de vos besoins quotidiens en vitamines et minéraux. Ça fonctionne bien comme plat principal coûteux. Si vous avez une barre de chocolat, des vermicelles au chocolat, de l’ameretto optionnel, et quelques autres ingrédients à disposition, vous pouvez la faire. Cette recette de Foodista a 1 fan. Tout bien considéré, nous avons décidé que cette recette méritait un score cuillère de 67 %. Cette partition est bonne. Des recettes similaires sont les Truffes au chocolat alcoolisées, le Chocolat alcoolisé, les Truffes noisette et orange, et les Truffes alcoolisées.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["bol", "poêle à frire"], "ingredients": ["chocolat", "eau"], "instruction": "Sécurisez le chocolat en petits morceaux et placez-les dans un bol, sur une casserole d’eau mijotée pour qu’il fasse fondre lentement. Ne laissez pas le fond du bol toucher l’eau.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["chocolat"], "instruction": "Soyez patient, ne montez pas le feu et ne précipitez pas le processus, sinon le chocolat va se fendre et devenir granuleux.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["alcool", "crème"], "instruction": "Une fois fondu, retirez le feu et incorporez la crème et l’alcool de votre choix (si vous en consommez).", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Bien mélanger.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["chocolat"], "instruction": "Laissez refroidir le mélange de chocolat.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 60}, "equipment": [], "ingredients": [], "instruction": "Une fois refroidi, mettez-le au congélateur pendant environ 1 heure pour qu’il devienne bien ferme.", "step_number": 6}, {"duration": null, "equipment": ["bol"], "ingredients": ["Poudre de cacao", "chocolat"], "instruction": "En attendant, placez un peu de cacao en poudre et de vermicelles au chocolat dans des bols individuels pour le revêtement.", "step_number": 7}, {"duration": null, "equipment": ["Melon Baller"], "ingredients": ["chocolat", "melon", "rouleau"], "instruction": "Avec un cueil à melon, retirez le chocolat. Mets-la sur ta main et roule pour t’assurer que c’est une balle bien définie.", "step_number": 8}, {"duration": null, "equipment": [], "ingredients": ["Poudre de cacao", "chocolat", "Truffes", "rouleau"], "instruction": "Laissez tomber des truffes individuelles dans la poudre de cacao ou les vermicelles au chocolat et roulez pour assurer un bon enrobage.", "step_number": 9}]', 'https://img.spoonacular.com/recipes/635676-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.642985', '2026-01-19 18:23:17.642985', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '635676');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('96402696-61fc-481d-9371-7d39345e1113', 'Pina colada congelée à trois ingrédients', 'La pina colada congelée à trois ingrédients prend environ 5 minutes du début à la fin. Pour 2,15 $ la portion, cette recette couvre 12 % de vos besoins quotidiens en vitamines et minéraux. Tu fais attention à ta silhouette ? Cette recette sans gluten, sans produits laitiers, lacto-ovo végétarien et vegan contient 320 calories, 2g de protéines et 8g de matières grasses par portion. Cette recette en fait 3. Cette recette de Foodista nécessite de l’ananas, du jus d’ananas, du lait de coco et du rhum à la noix de coco. Ça fonctionne bien comme boisson. 6 personnes étaient ravies d’avoir essayé cette recette. Cette recette est typique de la cuisine mexicaine. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 45 %, ce qui est positif. Essayez la pina colada congelée à trois ingrédients, la pina colada congelée à trois ingrédients et la pina colada congelée à trois ingrédients pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 5, '[{"duration": null, "equipment": ["mélangeur"], "ingredients": ["jus d''ananas", "lait de coco", "glace", "Rhum"], "instruction": "Ajoutez de la glace, du jus d’ananas, du lait de coco et du rhum au blender. Mélangez jusqu’à ce que ce soit lisse et crémeux.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["ananas", "cerises"], "instruction": "Servez avec des quartiers d’ananas frais et une garniture de cerise.", "step_number": 2}]', 'https://img.spoonacular.com/recipes/1098357-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.632594', '2026-01-19 18:23:17.632594', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '1098357');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('19bc82e6-3c9f-405e-86eb-d1bacda085e1', 'Glace Fraise Grillée au Lait de Noix de Coco', 'La glace au lait de coco et fraise grillée nécessite environ 45 minutes du début à la fin. Pour 1,44 $ la portion, vous obtenez un dessert pour 8 personnes. Une portion de ce plat contient environ 2g de protéines, 21g de matières grasses et un total de 213 calories. Cette recette est appréciée par deux passionnés de gastronomie et des cuisiniers. Rendez-vous au magasin et achetez du sucre de canne, des fraises, une gousse de vanille et quelques autres choses pour le préparer aujourd’hui. On peut en profiter à tout moment, mais c’est particulièrement bon pour la fête des mères. C’est une bonne option si vous suivez un régime sans gluten, sans produits laitiers, lacto-ovo-végétarien et compatible avec les FODMAP. Il est présenté par Foodista. Avec un score cuillère de 34 %, ce plat n’est pas si bon. Si vous aimez cette recette, jetez un œil à ces recettes similaires : Glace au lait de coco et fraise rôtie (Vegan) + Conseils pour rendre votre glace maison tendre, Glace au lait de coco et fraise grillée, et Glace au lait de coco et fraise grillée.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["casserole", "couteau"], "ingredients": ["lait de coco", "haricots vanille", "sucre granulé", "cardamome", "sauce", "graines"], "instruction": "Ajoutez le lait de coco, 1/2 tasse de sucre de canne cru et la cardamome dans une casserole.  À l’aide d’un petit couteau, coupez la longueur de la gousse de vanille et grattez toutes les graines dans le mélange de lait de coco.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["haricots vanille"], "instruction": "Ajoutez aussi la gousse de vanille.", "step_number": 2}]', 'https://img.spoonacular.com/recipes/658665-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.634859', '2026-01-19 18:23:17.634859', '{"vegan": true, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '658665');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('330320cb-a397-45b3-b4cc-2845bec4259d', 'La glace ultime à la noix de coco glacée avec une sauce chocolatée à coquille dure', 'La « glace » à la noix de coco glacée Ultimate avec une sauce chocolatée à coquille dure est un dessert qui peut servir 3 personnes. Pour 1,18 $ la portion, cette recette couvre 12 % de vos besoins quotidiens en vitamines et minéraux. Une portion de ce plat contient environ 5 g de protéines, 43 g de matières grasses et un total de 512 calories. Seules quelques personnes ont fait cette recette, et deux dis-le que c’était juste. On peut en profiter à tout moment, mais c’est particulièrement bon pour l’été. Rendez-vous au magasin et achetez de la noix de coco, des pépites de chocolat, des bananes et quelques autres choses pour le préparer aujourd’hui. De la préparation à l’assiette, cette recette prend environ 45 minutes. Il est présenté par Foodista. C’est une bonne option si vous suivez un régime sans gluten, sans produits laitiers, paléolithique et compatible avec les FODMAP. Dans l’ensemble, cette recette obtient un bon score cuillère de 46 %. Des recettes similaires sont la glace Ultimate Frozen Coconut avec une sauce au chocolat à la croûte dure, la sauce à la crème glacée à coquille dure et la glace au beurre de cacahuète avec une coquille de chocolat dur.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["Bac à glaçons"], "ingredients": ["lait de coco", "Glaçons"], "instruction": "Versez du lait de coco dans un bac à glaçons et mettez-le au congélateur pendant quelques heures.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["banane", "noix de coco"], "instruction": "Sortez 6 cubes de noix de coco du congélateur et 2 bananes.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 15}, "equipment": [], "ingredients": [], "instruction": "Laissez décongeler pendant 15 minutes.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["noix de coco", "banane"], "instruction": "Ajoutez les ingrédients dans le Yonana, en alternant entre banane et cubes de noix de coco", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Une fois les ingrédients bien traités, vous devriez avoir un produit similaire au mien ci-dessous.", "step_number": 5}, {"duration": null, "equipment": ["Ramequin"], "ingredients": [], "instruction": "Mettez les portions 3 dans des ramequins et mettez au congélateur pendant que vous préparez la garniture.", "step_number": 6}, {"duration": null, "equipment": ["micro-ondes", "bol"], "ingredients": ["croustilles de chocolat", "Sauce au fudge chaud", "Huile de coco"], "instruction": "Pour la sauce au chocolat : dans un bol adapté au micro-ondes, mélangez de l’huile de coco et des pépites de chocolat.", "step_number": 7}, {"duration": {"unit": "minutes", "number": 1}, "equipment": ["micro-ondes"], "ingredients": [], "instruction": "Faites chauffer au micro-ondes pendant 1 minute (en remuant à mi-chemin).", "step_number": 8}, {"duration": null, "equipment": ["Ramequin"], "ingredients": ["Sauce au fudge chaud"], "instruction": "Sortez les ramequins du congélateur et versez immédiatement une sauce au chocolat dessus.", "step_number": 9}, {"duration": null, "equipment": [], "ingredients": ["noix de coco déchiquetées"], "instruction": "On ajoute immédiatement la noix de coco râpée.", "step_number": 10}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servez et profitez !", "step_number": 11}]', 'https://img.spoonacular.com/recipes/663348-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.637039', '2026-01-19 18:23:17.637039', '{"vegan": false, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '663348');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('c235e19d-7b2c-44e3-a0b0-d4e592fcb95d', 'Une glace très vanille sans œufs', 'Si vous avez environ 45 minutes à passer en cuisine, la glace Very Vanillan Egg-Free Cream pourrait être une excellente recette végétarienne sans gluten et lacto ovo à essayer. Ce dessert contient 276 calories, 3g de protéines et 22g de matières grasses par portion. Cette recette en fait 8 et coûte 56 cents la portion. Une personne a fait cette recette et la referait. C’est parfait pour l’été. Un mélange de crème fouettée, de lait, d’extrait de vanillan et de quelques autres ingrédients suffit pour rendre cette recette aussi savoureuse. Il est présenté par Foodista. Avec un score cuillère de 14 %, ce plat est plutôt mauvais. Si vous aimez cette recette, vous pourriez aussi aimer des recettes comme la glace vanillane sans noix de coco et laitier, la glace cerise vanille et pépites de chocolat {sans œufs et pauvre en glucides}, et la glace à la vanille sans sucre {faible en glucides, faible en calories et sans œuf}.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["bol"], "ingredients": [], "instruction": "Placez tous les ingrédients dans un bol.", "step_number": 1}, {"duration": null, "equipment": ["fouet"], "ingredients": ["sucre"], "instruction": "Fouetter jusqu’à ce qu’une couche de bulles se forme à la surface et que le sucre soit dissous.", "step_number": 2}, {"duration": null, "equipment": ["machine à crème glacée"], "ingredients": ["glace"], "instruction": "Versez le mélange dans la boîte de la machine à glaces et battez selon les instructions du fabricant.", "step_number": 3}]', 'https://img.spoonacular.com/recipes/1096274-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.639823', '2026-01-19 18:23:17.639823', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '1096274');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('841923cc-8993-4086-aa9a-329aea6a3de6', 'Bouchées carrées crémeuses de tarte au citron vert', 'Les Square-Creamy Lime Pie sont peut-être exactement le dessert que vous recherchez. Une portion contient 631 calories, 8 g de protéines et 33 g de matières grasses. Cette recette végétarienne lacto ovo en fait 2 personnes et coûte 92 cents la portion. Il est présenté par Pink When. 1669 personnes ont été impressionnées par cette recette. Un mélange de farine tout usage, de miettes de biscuits Graham, de zeste de citron vert et d’une poignée d’autres ingrédients suffit pour rendre cette recette aussi délicieuse. De la préparation à l’assiette, cette recette prend environ 45 minutes. Tout bien considéré, nous avons décidé que cette recette mérite un score cuillère de 42 %. Cette partition est bonne. Si vous aimez cette recette, vous pourriez aussi aimer des recettes comme les Gâteaux carrés crémeux à la tarte au citron vert, les bouchées crémeuses à la truffe au citron vert et coco, et les bouchées de tarte au citron vert.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Préchauffez le four à 35", "step_number": 1}, {"duration": null, "equipment": ["feuille d''aluminium"], "ingredients": [], "instruction": "Couvrez un plat carré de 88 verre avec du papier aluminium.", "step_number": 2}, {"duration": null, "equipment": ["fouet", "feuille d''aluminium"], "ingredients": ["croûte"], "instruction": "Fouetter tous les ingrédients de votre croûte jusqu’à obtenir une consistance granuleuse. Prenez une cuillère et pressez la croûte graham dans le papier aluminium en vous assurant que tous les bords et le fond sont complètement couverts.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 15}, "equipment": ["four"], "ingredients": [], "instruction": "Mettez-le au four et laissez cuire pendant 10 à 15 minutes jusqu’à ce que ce soit doré.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 33}, "equipment": ["bol", "four"], "ingredients": [], "instruction": "Sortez-le du four et laissez refroidir environ une heure. Pour la garniture, ajoutez tous vos ingrédients dans un bol moyen et mélangez bien pendant environ 30 minutes, puis 3 minutes à feu doux.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["Croûte à tarte aux biscuits Graham"], "instruction": "Placez-le dans la pâte du biscuit Graham, en veillant à ce que tous les bords soient bien remplis.", "step_number": 6}, {"duration": {"unit": "minutes", "number": 10}, "equipment": ["four"], "ingredients": [], "instruction": "Faites cuire au four environ 5 à 10 minutes, puis retirez.", "step_number": 7}, {"duration": {"unit": "minutes", "number": 60}, "equipment": ["porte-fils", "feuille d''aluminium"], "ingredients": ["mûres", "fraises", "Spritzer", "noix de coco", "limeade", "citron vert", "huile de cuisson"], "instruction": "Placez sur une grille de refroidissement pendant environ 15 minutes, puis laissez refroidir au réfrigérateur pendant les 45 minutes restantes pour que la prise prenne. Pour servir, retirez soigneusement le plat avec du papier aluminium et coupez-les en carrés de la taille d’une bouchée. Vous cherchez d’autres façons d’utiliser l’huile essentielle de citron vert ? Un super groupe de blogueurs et moi-même nous sommes réunis pour partager nos recettes préférées à utiliser avec Lime. Vous n’avez pas besoin d’utiliser des huiles essentielles pour préparer ce délicieux dessert, mais si vous avez sous la main, essayez-le ! Vous pouvez trouver toutes les autres excellentes recettes de citron vert ci-dessous. Laissez-moi un commentaire si vous faites ces bouchées carrées crémeuses de tarte au citron vert et dites-moi si vous les aimez autant que nous ! Si vous avez déjà voulu commencer à utiliser des huiles essentielles, vous pouvez lire POURQUOI j’aime utiliser les miennes ici. Vous souhaitez utiliser le citron vert dans plusieurs recettes différentes ? Découvrez ces recettes supplémentaires. Spritzer noix de coco et citron vert // Margaritas mûre et citron vert // Limeade à la fraise", "step_number": 8}, {"duration": null, "equipment": [], "ingredients": ["fraises", "Margarita", "cerises", "citron vert"], "instruction": "Barres énergétiques cerise et citron vert // Cheesecake à la fraise margarita // Bouchées crémeuses de tarte au citron vert", "step_number": 9}, {"duration": null, "equipment": ["bol"], "ingredients": ["pastèque", "Margarita", "cookies"], "instruction": "Gâteau à la crêpe Margarita //Bol comestible de pastèque // Cookies Margarita", "step_number": 10}, {"duration": null, "equipment": [], "ingredients": ["maïs", "citron vert"], "instruction": "Salade de haricots noirs et de maïs du Sud-Ouest // Shooters de cheesecake au citron vert", "step_number": 11}, {"duration": null, "equipment": [], "ingredients": ["huile de cuisson"], "instruction": "Toutes les huiles essentielles ne sont pas comestibles. En raison d’un manque de pureté, 98 % des huiles essentielles vendues NE DOIVENT PAS être ingérées. Une huile essentielle comestible sera considérée comme de qualité thérapeutique et aura une case Informations sur les compléments indiquant la valeur nutritionnelle ; n’utilisez PAS n’importe quelle marque d’huile essentielle pour cuisiner ou aromatiser les aliments. Veillez à utiliser des huiles pures provenant de sources fiables, pas des parfums ou arômes synthétiques. REJOIGNEZ 500 000 ABONNÉS ! Rejoignez plus de 500 000 autres personnes qui suivent Pink", "step_number": 12}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Sur les réseaux sociaux, le Pink", "step_number": 13}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Quand tu blogues et que tu m’e-mails. Inscrivez-vous pour recevoir des bonus exclusifs comme ce livre électronique GRATUIT sur les dîners Simple Fit. N’attendez pas ! Vous ne voudrez rien manquer. Succès ! Maintenant, vérifiez vos e-mails pour confirmer votre abonnement et téléchargez votre ebook GRATUIT. Il y a eu une erreur en soumettant votre abonnement. Veuillez réessayer. Prénom", "step_number": 14}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Messagerie électronique", "step_number": 15}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Adresse", "step_number": 16}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "S’inscrire", "step_number": 17}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Propulsé par Convert", "step_number": 18}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Équipement", "step_number": 19}]', 'https://img.spoonacular.com/recipes/715381-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.64572', '2026-01-19 18:23:17.64572', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '715381');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('4bdde3c0-3f24-423a-a118-80ef9b14765d', 'Macarons à la noix de coco avec un filet de chocolat', 'Les macarons à la noix de coco avec filet de chocolat durent environ 45 minutes du début à la fin. Pour 27 cents la portion, cette recette couvre 3 % de vos besoins quotidiens en vitamines et minéraux. Cette recette contient 24 portions avec 156 calories, 2g de protéines et 7g de matières grasses chacune. 10 personnes ont essayé et aimé cette recette. Un mélange de farine, de noix de coco, de sel et d’une poignée d’autres ingrédients suffit pour rendre cette recette aussi savoureuse. C’est une bonne option si vous suivez un régime lacto-ovo-végétarien. Il est présenté par Foodista. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 21 %, ce qui est plutôt mauvais. Essayez les macarons à la noix de coco avec un filet de chocolat, les macarons au gingembre à la noix de coco avec un filet au chocolat, et Not your Mother’s Mounds Bar – chocolat chaud avec rhum à la noix de coco, noix de coco grillée et filet de chocolat maison pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["bol"], "ingredients": ["noix de coco", "farine de tous usages", "sel"], "instruction": "Mélangez la farine, la noix de coco et le sel dans un grand bol.", "step_number": 1}, {"duration": null, "equipment": ["bol"], "ingredients": ["lait condensé sucré", "vanille"], "instruction": "Dans un bol plus petit, mélangez la vanille et la boîte de lait concentré sucré et mélangez bien.", "step_number": 2}, {"duration": null, "equipment": ["cuillère en bois", "mélangeur"], "ingredients": [], "instruction": "Ajoutez cette substance aux ingrédients secs et mélangez avec une cuillère en bois, ou vous pouvez utiliser vos mains (cela me semble assez salissant). Je n’utiliserais probablement pas de mixeur à moins qu’elle soit à très faible vitesse. Cette pâte va être ÉPAISSE.", "step_number": 3}, {"duration": null, "equipment": ["Cuillère de glace", "papier à pâtisserie", "plaque de cuisson"], "ingredients": ["glace", "pâte"], "instruction": "Tapissez les plaques de cuisson avec du papier sulfurisé et, à l’aide d’une grande cuillère ou d’une cuillère à glace, versez la pâte sur les plaques.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 20}, "equipment": ["four"], "ingredients": [], "instruction": "Dans un four préchauffé à 350 degrés, faites cuire les macarons pendant environ 20 minutes, ou jusqu’à ce qu’ils aient un aspect doré ou grillé.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["Chocolat mi-sucré", "Chocolat à pain non sucré", "chocolat"], "instruction": "Versez un peu de chocolat fondu mi-sucré sur le dessus ou utilisez un mélange chocolat/chocolat de boulanger et optez pour la variété trempée.", "step_number": 6}]', 'https://img.spoonacular.com/recipes/639779-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.647935', '2026-01-19 18:23:17.647935', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '639779');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('4e53339d-adc0-4009-8ed7-1209f5cc5600', 'Bâtonnets de fromage frits', 'Les bâtonnets de fromage frits prennent environ 45 minutes du début à la fin. Pour 3,09 $ la portion, vous obtenez un hor d’œuvre qui sert 1. Une portion contient 710 calories, 38 g de protéines et 32 g de matières grasses. Deux personnes ont fait cette recette et la referaient. C’est une bonne option si vous suivez un régime lacto-ovo-végétarien. Rendez-vous au magasin et achetez des bâtonnets de fromage en chaîne individuels, de l’huile végétale, de l’œuf +2 de l’eau, et quelques autres choses pour le préparer aujourd’hui. Il est présenté par Foodista. Dans l’ensemble, cette recette obtient un solide score cuillère de 46 %. Essayez les bâtonnets de fromage frits, les bâtonnets de fromage frit et les bâtonnets de fromage frits pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["Fromage en ficelle", "farine de tous usages", "agiter"], "instruction": "Draguez les bâtonnets de fromage individuels dans de la farine. Oublie l’excès.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["rouleau", "œuf"], "instruction": "Roulez des bâtonnets dans du lavage d’œufs,", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["chapelure"], "instruction": "Ensuite, enrobez de chapelure.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["huile de cuisson"], "instruction": "Faites frire dans de l’huile chaude pendant 20 secondes, puis retournez et faites frire encore 20 secondes.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["Sauce pizza"], "instruction": "À servir avec une sauce à pizza ou de la marinara !!", "step_number": 5}]', 'https://img.spoonacular.com/recipes/643809-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.649565', '2026-01-19 18:23:17.649565', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '643809');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('c636e102-178a-4620-aeef-4a7cc8b3deb9', 'Bruschetta végane au pois et à la menthe', 'Le Bruschettan végan au pesto de pois et de menthe est une recette sans produits laitiers avec 10 portions. Une portion de ce plat contient environ 2g de protéines, 12g de matières grasses et un total de 137 calories. Pour 43 cents la portion, cette recette couvre 3 % de vos besoins quotidiens en vitamines et minéraux. Il fonctionne mieux comme un amusement d’œuvre, et se termine en environ 45 minutes. Cette recette de Foodista nécessite sans doute que vous l’aimerez autant que moi, des vrilles de pois, des feuilles de menthe et du sel de mer. Cette recette est appréciée par un gourmet et des cuisiniers. Peu de gens ont vraiment aimé ce plat méditerranéen. Avec un score cuillère de 23 %, ce plat n’est pas si exceptionnel. Si vous aimez cette recette, jetez un œil à ces recettes similaires : Bruschetta de pois écrasés avec menthe, pesto de menthe et pois sur baguette grillée, et soupe de pois refroidis avec pesto à la menthe.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["plaque de cuisson", "four"], "ingredients": ["huile d''olive", "pain", "huile de cuisson"], "instruction": "Préchauffez le four à 375 Tranchez le pain et badigeonnez l’huile d’olive sur les tranches et faites la face à l’huile vers le haut sur une plaque de cuisson.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 7}, "equipment": ["processeur alimentaire", "four"], "ingredients": ["menthe", "huile d''olive", "radis", "étendue", "Pesto", "pain sandwich", "petits pois", "sel"], "instruction": "Faites cuire pendant 5 à 7 minutes ou jusqu’à ce qu’elles soient légèrement dorées. Mélangez les pois, les feuilles de menthe, l’huile d’olive et le sel dans un robot culinaire jusqu’à ce que ce soit lisse. Quand le toast est froid, étalez une couche de pesto sur chaque tranche de toast, puis déposez quelques morceaux de radis sur chacun. Ajoute les tentacules. Des pois délicatement sucrés et une menthe savoureuse font une bruschetta de saison qui annonce que l’été est là !", "step_number": 2}]', 'https://img.spoonacular.com/recipes/664470-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.651956', '2026-01-19 18:23:17.651956', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '664470');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('cfffc209-19d9-46bb-9312-f5ca6a31baac', 'Courge gland Érable & Curry', 'La recette Courge Gland à l’Érable & Curry peut être préparée en environ 45 minutes. Une portion de ce plat contient environ 1 g de protéines, 5 g de matières grasses et un total de 119 calories. Pour 58 cents la portion, cette recette couvre 7 % de vos besoins quotidiens en vitamines et minéraux. Cette recette en fait 3. Deux personnes étaient ravies d’avoir essayé cette recette. Peu de gens ont vraiment aimé cette œuvre. Cette recette de Foodista contient du gland, de la poudre de curry, du sirop d’érable et de l’huile d’olive. C’est une recette très abordable pour les amateurs de cuisine indienne. C’est une bonne option si vous suivez un régime végétarien sans gluten, sans produits laitiers, paléolithique et lacto ovo. Tout bien considéré, nous avons décidé que cette recette méritait un score cuillère de 72 %. Cette partition est plutôt bonne. Si vous aimez cette recette, vous pourriez aussi apprécier des recettes comme la courge gland à l’érable et au curry, la courge gland glacée à l’érable et la courge de gland rôtie à l’érable.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["papier à pâtisserie", "plaque de cuisson", "four"], "ingredients": ["Courge gland", "courge"], "instruction": "Préchauffez le four à 400 °F. Tapisser une plaque de cuisson avec du papier sulfurisé ou un tapis en silicone. Rincez l’extérieur de la courge gland puis coupez-la en deux. Semez la courge et coupez la tige. Ensuite, coupez-le en tranches d’un pouce. J’aime utiliser les rainures naturelles de la courge comme guide pour l’épaisseur.", "step_number": 1}, {"duration": null, "equipment": ["bol"], "ingredients": ["Courge gland"], "instruction": "Placez la courge gland tranchée dans un bol de taille moyenne.", "step_number": 2}, {"duration": null, "equipment": ["bol"], "ingredients": [], "instruction": "Ajoutez le reste des ingrédients dans le bol et remuez jusqu’à ce que tout soit bien intégré.", "step_number": 3}, {"duration": null, "equipment": ["plaque de cuisson"], "ingredients": ["Courge gland"], "instruction": "Posez la courge acorn en une seule couche sur la plaque de cuisson doublée, côté coupé vers le bas.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 15}, "equipment": ["four"], "ingredients": ["Courge gland"], "instruction": "Faites cuire environ 15 minutes. Retournez les tranches de courge gland de l’autre côté afin que les deux côtés soient dorés également.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 10}, "equipment": ["four"], "ingredients": ["courge"], "instruction": "Faites cuire la courge encore 10 à 15 minutes ou jusqu’à ce que les morceaux puissent être facilement percés à la fourchette.", "step_number": 6}]', 'https://img.spoonacular.com/recipes/650871-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.65574', '2026-01-19 18:23:17.65574', '{"vegan": true, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '650871');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('87cc66aa-fab6-492d-a1d3-450bfb9117cf', 'Châtaignes rôties sur un feu ouvert', 'Les châtaignes rôties sur un feu ouvert sont un accompagnement qui sert 1. Une portion contient 9 calories, 0g de protéines et 0g de matières grasses. Pour 7 centimes la portion, cette recette couvre 1 % de vos besoins quotidiens en vitamines et minéraux. C’est une bonne option si vous suivez un régime végétarien sans gluten, sans produits laitiers, paléolithique et lacto ovo. Si vous avez dans George Orwell en 1984, des châtaignes rôties étaient vendues dans les rues de Rome au XVIe siècle et sont encore vendues dans les rues des villes européennes en hiver, le châtaignier est le fruit le plus ancien du Japon. Le kuri a été cultivé avant même de cultiver le riz, et avec quelques autres ingrédients à disposition, tu peux le faire. De la préparation à l’assiette, cette recette prend environ 45 minutes. Il est proposé par l’utilisateur cuillère Maplewoodroad. Si vous aimez cette recette, vous pourriez aussi aimer des recettes comme Cuisiner sur un feu ouvert : bacon anglais, soupe aux poireaux et pommes de terre, poulet rôti en saumure, et poulet rôti à l’origan.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Préchauffez le four à 425°F", "step_number": 1}, {"duration": null, "equipment": ["plaque de cuisson"], "ingredients": ["châtaignes"], "instruction": "Disposez les châtaignes préparées uniformément sur une plaque de cuisson", "step_number": 2}, {"duration": {"unit": "minutes", "number": 15}, "equipment": [], "ingredients": ["châtaignes", "viande"], "instruction": "Rôtissez environ 15 à 20 minutes ou jusqu’à ce que la chair de la châtaigne soit tendre", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["beurre", "trempette"], "instruction": "Éplucher et manger (ou peler, tremper dans du beurre fondu, et manger)", "step_number": 4}]', 'https://img.spoonacular.com/recipes/1697797-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.657484', '2026-01-19 18:23:17.657484', '{"vegan": true, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '1697797');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('573e43c3-4f7c-481e-9af0-24c8ffb12832', 'Méthode de cuisson infaillible pour faire la poitrine de poulet la plus juteuse', 'On n’a jamais trop de recettes principales, alors essayez la méthode de cuisson infaillible pour préparer le blanc de poulet le plus juteux. Cette recette en fait 2. Une portion de ce plat contient environ 48g de protéines, 27g de matières grasses et un total de 448 calories. Pour 2,33 $ la portion, cette recette couvre 25 % de vos besoins quotidiens en vitamines et minéraux. Il est proposé par l’utilisateur cuillère Maplewoodroad. Si vous avez du blanc de poulet, de l’huile d’olive, du poivre fraîchement moulu et quelques autres ingrédients à disposition, vous pouvez le préparer. C’est une bonne option si vous suivez un régime sans gluten, sans produits laitiers, paléolithique et primal. De la préparation à l’assiette, cette recette prend environ 40 minutes. Si vous aimez cette recette, jetez un œil à ces recettes similaires : Le blanc de poulet grillé le plus juteux, Le blanc de poulet grillé le plus juteux, et Blanc de dinde infaillible.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 40, '[{"duration": null, "equipment": [], "ingredients": ["poitrine de poulet", "huile d''olive", "broyage sec"], "instruction": "Frottez le blanc de poulet avec environ 1 cuillère à soupe d’huile d’olive.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["poitrine de poulet"], "instruction": "Mélangez tous les autres ingrédients et enrobez uniformément la poitrine de poulet avec.", "step_number": 2}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["huile d''olive"], "instruction": "Dans une poêle, apportez 2 cuillères à soupe d’huile d’olive juste à feu moyen-élevé.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 2}, "equipment": [], "ingredients": ["poitrine de poulet"], "instruction": "Ajoutez les poitrines de poulet et saisissez 2 minutes de chaque côté.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 6}, "equipment": [], "ingredients": ["poitrine de poulet"], "instruction": "Baissez le feu à moyen-bas (vous voulez toujours entendre un grésillement) et faites cuire la poitrine de poulet 6 minutes supplémentaires de chaque côté, couvercle posé.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 10}, "equipment": ["poêle à frire"], "ingredients": ["poitrine de poulet"], "instruction": "Coupez le feu et laissez le blanc de poulet reposer dans la poêle chaude pendant 10 minutes – ne soulevez pas le couvercle et ne laissez pas l’humidité s’échapper", "step_number": 6}, {"duration": null, "equipment": ["planche à découper"], "ingredients": ["poitrine de poulet"], "instruction": "Tranchez sur une planche à découper et goûtez à la poitrine de poulet la plus juteuse que vous ayez jamais goûtée. Accompagnez votre accompagnement préféré et profitez-en !", "step_number": 7}]', 'https://img.spoonacular.com/recipes/1697639-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.660708', '2026-01-19 18:23:17.660708', '{"vegan": false, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '1697639');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('cc6858c3-6156-425c-b01e-7f54110617a5', 'Canard Rumaki', 'Duck Rumaki est une œuvre sans gluten, sans produits laitiers, paléolithique et primitive. Cette recette contient 24 portions avec 66 calories, 2g de protéines et 6g de matières grasses chacune. Pour 29 cents la portion, cette recette couvre 3 % de vos besoins quotidiens en vitamines et minéraux. Une personne a fait cette recette et la referait. Si vous avez du bacon, du blanc de canard, des jalapeños et quelques autres ingrédients sous la main, vous pouvez le préparer. De la préparation à l’assiette, cette recette prend environ 45 minutes. Il est présenté par Foodista. Avec un score cuillère de 17 %, ce plat n’est pas si génial. Rumaki, Rumaki et Turkey Rumaki sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["cure-dents", "four"], "ingredients": ["piment jalapeño", "poivre", "bacon", "canard", "enveloppe"], "instruction": "Au centre de chaque morceau de bacon, placez une tranche de jalapeño et un morceau de canard. Enroulez le bacon bien autour du canard et du poivre et sécurisez avec un cure-dent. On peut le refroidir toute la nuit jusqu’à ce qu’il soit prêt à cuire. Préchauffez le four à 400 degrés.", "step_number": 1}, {"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Placez le rumaki sur une plaque et placez-le sur la grille centrale du four préchauffé.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 30}, "equipment": ["four"], "ingredients": [], "instruction": "Faites cuire pendant 30 minutes, en les secouant de temps en temps.", "step_number": 3}]', 'https://img.spoonacular.com/recipes/641717-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.663088', '2026-01-19 18:23:17.663088', '{"vegan": false, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '641717');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('62f6b088-7b2c-4144-9932-a67b47d1c167', 'Canard aux canneberges séchées, mandarines et sauce mascarpone', 'Le canard avec canneberges séchées, mandarines et sauce mascarpone est un accompagnement sans gluten et primitif. Cette recette en a 2 et coûte 11 cents la portion. Une portion de ce plat contient environ 1g de protéines, 7g de matières grasses et un total de 70 calories. Deux personnes ont fait cette recette et la referaient. Il est présenté par Foodista. Rendez-vous au magasin et achetez du jus de 6 mandarines, du sel et du poivre, ainsi que quelques autres choses pour le préparer aujourd’hui. Noël sera encore plus spécial avec cette recette. De la préparation à l’assiette, cette recette prend environ 45 minutes. Avec un score cuillère de 8 %, ce plat est améliorable. Des recettes similaires incluent les blancs de canard avec canneberges et sauce au miel, les blancs de canard croustillants avec mandarines glacées au balsamique, et la sauce pomme-rhubarbe morceaux avec canneberges séchées.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Préchauffez le four à 35", "step_number": 1}, {"duration": {"unit": "minutes", "number": 18}, "equipment": ["poêle à frire", "four"], "ingredients": ["sel et poivre", "Poitrine de canard", "canard", "huile de cuisson"], "instruction": "Dans une poêle au four, chauffez une ombre d’huile à feu maximal. Salez généreusement et ajoutez du poivre des deux côtés du blanc de canard. Quand la poêle est chaude, ajoutez la peau du canard vers le bas. Faites cuire jusqu’à ce que la peau soit dorée, environ 5 minutes, tournez-vous de l’autre côté et faites cuire pendant 3 minutes. Retournez-vous, côté peau vers le haut, jetez toute la graisse de la poêle et mettez-la dans le four chaud. Faites cuire encore 10 à 15 minutes.", "step_number": 2}, {"duration": null, "equipment": ["feuille d''aluminium", "casserole", "mélangeur", "four"], "ingredients": ["canneberges séchées", "jus de mandarine", "canneberges", "mascarpone", "Tangerine", "jus", "sauce"], "instruction": "Sortez-le du four et couvrez-le avec du papier aluminium pour rester au chaud. Pendant ce temps, dans une petite casserole séparée, placez les canneberges séchées et le jus de mandarine. Faites cuire à feu moyen jusqu’à ce que les canneberges soient ramollis et que le jus soit réduit. Baissez le feu et ajoutez le mascarpone. Quand le mascarpone est fondu et que le jus commence à épaissir, retirez-le du feu. Avec un batteur plongeant à main, réduisez le mascarpone et la sauce mandarine-canneberges jusqu’à ce qu’il soit bien lisse.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["canard"], "instruction": "Ajoutez moins d’une cuillère à soupe du jus du canard.", "step_number": 4}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": [], "instruction": "Mélangez bien. Remettez la poêle au feu et réchauffez pendant une minute environ.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["étendue", "sauce", "canard"], "instruction": "Étalez la sauce au fond de l’assiette et servez le canard tranché dessus.", "step_number": 6}]', 'https://img.spoonacular.com/recipes/641720-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.664882', '2026-01-19 18:23:17.664882', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '641720');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('0afa466a-ae12-4d04-962b-9246a81fe5d4', 'Canard grillé', 'Si vous souhaitez ajouter davantage de recettes sans gluten, sans produits laitiers, paléolithiques et primaires à votre répertoire, le canard grillé pourrait être une recette à essayer. Cette recette contient 6 portions avec 170 calories, 4g de protéines et 15g de matières grasses chacune. Pour 61 cents la portion, cette recette couvre 3 % de vos besoins quotidiens en vitamines et minéraux. Le 4 juillet sera encore plus spécial avec cette recette. Cette recette de Foodista a 1 fan. De la préparation à l’assiette, cette recette prend environ 45 minutes. Ça marche bien comme accompagnement. Un mélange de poudre d’ail, de poivre, de filets de poitrine de canard et d’une poignée d’autres ingrédients suffit pour rendre cette recette aussi délicieuse. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 41 %, ce qui est plutôt bien. Des recettes similaires sont le blanc de canard grillé frotté aux épices avec salade de pêche et de fromage de chèvre grillés, le canard laqué avec des figues grillées, et les paillards de canard grillés à la poêle.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 20}, "equipment": ["cure-dents"], "ingredients": ["bacon", "eau", "sel", "enveloppe", "glace"], "instruction": "Dégelez les filets au réfrigérateur pendant la nuit. Faites tremper les filets dans de l’eau salée et de la glace pendant au moins 20 minutes – répétez cette étape au moins deux fois. Enroulez le bord des filets avec une tranche de bacon, utilisez des cure-dents pour les maintenir en position.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 1440}, "equipment": [], "ingredients": ["poudre d''ail", "poivre noir", "marinade"], "instruction": "Placez les filets dans un contenant avec suffisamment de vinaigrette pour les recouvrir complètement, ajoutez de la poudre d’ail et du poivre noir selon votre goût, puis laissez mariner pendant 24 heures. Faites cuire les filets au niveau désiré (le moyen est très bon).", "step_number": 2}, {"duration": null, "equipment": ["cure-dents"], "ingredients": [], "instruction": "Enlevez les cure-dents !", "step_number": 3}, {"duration": null, "equipment": ["grille", "cuisinière"], "ingredients": ["sauce douce et aigre", "sauce barbecue", "jus d''ananas", "pain à la pâte", "Sauce teriyaki", "marinade", "bourbon", "merlot", "pomme de terre", "sucre", "Coca Cola", "canard", "viande", "tir"], "instruction": "Servez avec de la salade, de la pomme de terre au four, du pain au levain et du bon Merlot. Commentaires : Il existe de nombreuses excellentes marinades pour le canard - sauce teriyaki avec jus d’ananas ; Dales avec un shot de bourbon, et une pincée de Coca classique (sucre, caféine, colorants - le vrai) ; sauce aigre-douce ; ou sauce Bar-b-Que. La clé d’un bon canard grillé est de cuire à feu doux et de badigeonner régulièrement la marinade pour garder la viande moelleuse. Cette recette est VRAIMENT une échappatoire, mais l’une des plus populaires auprès des gens avec qui je chasse. C’est parfait sur le barbecue, le feu de camp ou la cuisinière dans le store à canards.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/645694-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.666868', '2026-01-19 18:23:17.666868', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '645694');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('a0f6fefc-3d01-4688-8ea4-78f8de8bef2e', 'Kale Bruschetta', 'Le kale Bruschettan est une recette végétarienne sans produits laitiers, lacto ovo et vegan, avec 1 portion. Pour 26 cents la portion, cette recette couvre 2 % de vos besoins quotidiens en vitamines et minéraux. Une portion de ce plat contient environ 0 g de protéines, 14 g de matières grasses et un total de 132 calories. Cette recette de Foodista nécessite du pain, de l’huile d’olive extra vierge, de la gousse d’ail et du sel marin. Il fonctionne mieux comme un amusement d’œuvre, et se termine en environ 45 minutes. Cette recette est typique de la cuisine méditerranéenne. Seules quelques personnes ont fait cette recette, et une dis-le a fait juste. Dans l’ensemble, cette recette obtient un score cuillère pas si exceptionnel de 28 %. Essayez la Bruschetta de chou kale, la Bruschetta de chou kale et de haricots, et la bruschetta de chou kale et haricots pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["eau", "chou"], "instruction": "Nettoyez le chou kale, en enlevant les tiges dures. Lavez et faites bouillir dans de l’eau salée jusqu’à ce qu’elle soit tendre", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Puits de drainage", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "côtelette", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["huile d''olive", "ail"], "instruction": "Faites revenir dans de l’huile d’olive avec de l’ail tranché", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["toast"], "instruction": "Pain grillé", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["gousses d''ail entières", "broyage sec"], "instruction": "Frottez avec de la gousse d’ail crue", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": ["chou"], "instruction": "Sur le dessus avec du chou frisé piquant", "step_number": 7}, {"duration": null, "equipment": [], "ingredients": ["sel"], "instruction": "Saupoudrez de sel", "step_number": 8}, {"duration": null, "equipment": [], "ingredients": ["huile d''olive extra vierge"], "instruction": "Arrosez de l’huile d’olive extra vierge", "step_number": 9}]', 'https://img.spoonacular.com/recipes/648715-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.668646', '2026-01-19 18:23:17.668646', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '648715');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('6f694e6c-36bc-4331-9bac-4e3a84c8c794', 'Trempette aux haricots blancs et courges', 'Vous cherchez un horaire végétarien sans gluten, sans produits laitiers, lacto ovo végétarien et vegan ? La sauce haricots blancs et courge pourrait être une excellente recette à essayer. Cette recette sert 3 personnes et coûte 1,99 $ la portion. Une portion contient 542 calories, 18 g de protéines et 6 g de matières grasses. Il est présenté par Foodista. Un mélange de courge globe, de bulbe d’ail, de haricots cannellini et d’une poignée d’autres ingrédients suffisent pour rendre cette recette aussi savoureuse. Peu de gens ont fait cette recette, et l’un dis-le serait parfait. Le Super Bowl sera encore plus spécial avec cette recette. De la préparation à l’assiette, cette recette prend environ 45 minutes. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 93 %, ce qui est excellent. Les utilisateurs qui ont aimé cette recette ont également apprécié la dip de courge aux haricots blancs et délicats torréfiés, la dip aux haricots blancs et la sauce aux haricots blancs.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["papier à pâtisserie", "plaque de cuisson", "four"], "ingredients": [], "instruction": "Préchauffez le four à 400°F (~205°C). Tapisser une plaque de cuisson avec du papier sulfurisé.", "step_number": 1}, {"duration": null, "equipment": ["feuille d''aluminium"], "ingredients": ["clou de girofle", "ail"], "instruction": "Coupez le dessus du bulbe d’ail, en exposant les gousses. Déchirez une feuille de papier aluminium et placez le bulbe d’ail dessus.", "step_number": 2}, {"duration": null, "equipment": ["feuille d''aluminium"], "ingredients": ["huile d''olive", "clou de girofle", "ail", "enveloppe"], "instruction": "Versez une cuillère à café d’huile d’olive sur l’ail, en veillant à bien couvrir toutes les gousses exposées. Enveloppez l’ail lâchement dans du papier aluminium, mais assurez-vous qu’il est bien scellé. Vous voulez piéger la chaleur à l’intérieur de la pochette en aluminium.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 90}, "equipment": ["four"], "ingredients": ["clou de girofle", "ail"], "instruction": "Faites cuire l’ail pendant environ 35 à 45 minutes, ou jusqu’à ce que les gousses soient dorées. Le mien a pris environ 45 minutes.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 20}, "equipment": ["plaque de cuisson", "four", "bol"], "ingredients": ["courge", "sel", "huile de cuisson"], "instruction": "Coupez le haut et le bas de chaque courge globe, puis coupez-les en petits cubes. Si vous voulez créer un bol de courge comme je l’ai fait sur la photo, gardez une courge globe pour le bol. Il suffit de couper le dessus et, à l’aide d’une cuillère, de déterrer toute la chair. Mélangez la courge avec une cuillère à soupe d’huile et une petite pincée de sel, puis faites cuire sur la plaque pendant environ 20 minutes.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 15}, "equipment": ["processeur alimentaire", "feuille d''aluminium"], "ingredients": ["clou de girofle", "ail", "enveloppe"], "instruction": "Quand l’ail est prêt, ouvrez l’emballage en aluminium et laissez refroidir pendant 10 à 15 minutes. Quand l’ail est assez froid pour être manipulé, pressez les gousses dans un robot culinaire.", "step_number": 6}, {"duration": null, "equipment": ["processeur alimentaire"], "ingredients": ["haricots cannellini", "courge", "pâtes", "sel", "trempette"], "instruction": "Ajoutez les fèves cannellini, la courge grillée et le sel dans le robot culinaire et mélangez jusqu’à ce que ce soit lisse. À savourer en sauce ou à ajouter à un plat de pâtes !", "step_number": 7}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Réfrigérez les restes dans un récipient hermétique.", "step_number": 8}]', 'https://img.spoonacular.com/recipes/665138-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.669811', '2026-01-19 18:23:17.669811', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": true}', 'spoonacular', '665138');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('254e3130-e5e8-447c-89e3-71ce25dece7a', 'Pesto végétalien aux graines de tournesol', 'Le pesto végétalien de graines de tournesol est un condiment végétarien sans gluten, sans produits laitiers, paléolithique et lacto ovo. Cette recette en fait 8 et coûte 52 cents la portion. Une portion contient 86 calories, 2g de protéines et 8g de matières grasses. De la préparation à l’assiette, cette recette prend environ 15 minutes. Il est présenté par Foodista. Une personne a fait cette recette et la referait. Si vous avez de l’ail, de l’huile d’olive, du sel et quelques autres ingrédients à portée de main, vous pouvez le préparer. Tout bien considéré, nous avons décidé que cette recette méritait un score cuillère de 66 %. Cette partition est solide. Des recettes similaires sont les barres granola au beurre de graines de tournesol avec filet de chocolat (sans cuisson, végane, sans gluten), le chocolat blanc maison et le beurre de tournesol (sans gluten, avec option végane), et les roulés Daikon avec un pesto aux graines de coriandre et citrouille (cru, végan, paléo).', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 15, '[{"duration": null, "equipment": ["colander", "tamis"], "ingredients": ["basilic frais", "eau"], "instruction": "Enlève toutes les feuilles de basilic de ses tiges. Rincez les feuilles de basilic à l’eau froide et à l’aide d’une passoire ou d’un passoire", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["herbes"], "instruction": "Voici maintenant une astuce qui vous aidera à sécher les herbes beaucoup plus rapidement et efficacement, sans casser de feuilles délicates -", "step_number": 2}, {"duration": null, "equipment": ["Fileuse à salade"], "ingredients": ["basilic frais", "eau"], "instruction": "Placez les feuilles de basilic dans un essoreur à salade, comme vous le feriez avec une salade, puis filez jusqu’à ce qu’il ne reste presque plus d’eau. Il faut s’assurer qu’il y ait un minimum d’eau afin qu’il conserve plus longtemps", "step_number": 3}, {"duration": null, "equipment": ["mélangeur"], "ingredients": ["graines de tournesol", "gousses d''ail entières", "huile d''olive", "basilic", "sel"], "instruction": "Ajoutez le basilic, l’huile d’olive, les graines de tournesol, la gousse d’ail et le sel dans un blender. Mélangez jusqu’à ce que les graines de tournesol soient normales.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["huile d''olive"], "instruction": "Ajoutez plus d’huile d’olive selon les besoins", "step_number": 5}, {"duration": null, "equipment": ["Bocaux de mise en conserve", "spatule"], "ingredients": ["Pesto", "huile d''olive"], "instruction": "Utilisez une spatule pour verser la sauce pesto dans un pot Mason ou un autre récipient en verre. Enfin, versez une couche d’huile d’olive juste pour recouvrir le pesto. Cela aide à la préserver. À utiliser dans les deux semaines.", "step_number": 6}]', 'https://img.spoonacular.com/recipes/1095767-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.672121', '2026-01-19 18:23:17.672121', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '1095767');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('7aeb8937-44e5-4995-9f1d-a1154e8c498c', 'Lassi à la Menthe Salée', 'Le salted mint lassi est une recette lacto-ovo végétarienne et primitive sans gluten, avec 6 portions. Cette boisson contient 89 calories, 14g de protéines et 1g de matières grasses par portion. Pour 1,22 $ la portion, cette recette couvre 7 % de vos besoins quotidiens en vitamines et minéraux. De la préparation à l’assiette, cette recette prend environ 45 minutes. Cette recette est appréciée par un gourmet et des cuisiniers. Si vous avez de l’eau, des feuilles de menthe, du yaourt et quelques autres ingrédients à portée de main, vous pouvez le préparer. Il est présenté par Foodista. Seules quelques personnes ont vraiment aimé ce plat indien. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 34 %, ce qui n’est pas si bon. Des recettes similaires incluent le lassi à la menthe salée, le lassi salé (lhassi) avec cumin et menthe, et le lassi salé, comment faire du lassi salé | Lassi S.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 1}, "equipment": ["poêle à frire"], "ingredients": ["cumin", "pain sandwich"], "instruction": "Faites griller le cumin dans une petite poêle sèche et lourde à feu moyen, en secouant fréquemment la poêle jusqu’à ce qu’elle soit parfumée, 1 à 2 minutes.", "step_number": 1}, {"duration": null, "equipment": ["mélangeur"], "ingredients": ["sel casher", "yaourt", "eau", "menthe"], "instruction": "Transférez 1 cuillère à café et demie dans un blender avec de la menthe, du yaourt, du sel casher et de l’eau.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["cumin", "menthe"], "instruction": "Mélangez jusqu’à obtenir un vert pâle avec des éclats de menthe et de cumin.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["graines de cumin", "Lassi", "glace"], "instruction": "Servez le lassi sur de la glace et saupoudrez d’une demi-cuillère à café de graines de cumin restantes.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/659204-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.673461', '2026-01-19 18:23:17.673461', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '659204');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('a4a734ac-1c50-40da-98bf-c876bc25a23d', 'Linguine avec pois chiches et bacon', 'Les linguines avec pois chiches et bacon sont un plat principal qui sert deux personnes. Pour 1,31 $ la portion, cette recette couvre 19 % de vos besoins quotidiens en vitamines et minéraux. Une portion contient 759 calories, 23 g de protéines et 50 g de matières grasses. Il est présenté par Foodista. Un mélange de fromage asiago, d’huile d’olive, de pois chiches et d’une poignée d’autres ingrédients suffit pour rendre cette recette aussi délicieuse. Une personne a été impressionnée par cette recette. De la préparation à l’assiette, cette recette prend environ 45 minutes. Tout bien considéré, nous avons décidé que cette recette méritait un score cuillère de 52 %. Cette partition est bonne. Des recettes similaires sont les linguines au bacon, le fromage de chèvre et les pois mange-de-sucre, l’orzo aux pois chiches et le sundal aux pois chiches.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["pois chiches", "linguine", "eau"], "instruction": "Si ce n’est pas fait à l’avance, faites tremper et faire bouillir les pois chiches selon les instructions de l’emballage. Faites bouillir de l’eau pour les linguini et cuisinez selon les instructions de l’emballage.", "step_number": 1}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["linguine", "bacon"], "instruction": "Égoutte les linguini. Dans une petite poêle, du bacon brun.", "step_number": 2}, {"duration": null, "equipment": ["serviettes en papier", "poêle à frire"], "ingredients": ["Gouttes de bacon", "huile d''olive", "bacon"], "instruction": "Retirez le bacon sur un essuie-tout pour sécher et égouttez la graisse de bacon. Dans la poêle, ajoutez 1/3 de tasse d’huile d’olive.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["pois chiches", "piment rouge", "huile d''olive", "linguine", "parmesan", "bacon"], "instruction": "Chauffez jusqu’à ce que vous soyez chaud, ajoutez des pois chiches et réchauffez jusqu’à ce que vous soyez chaud. Émietter le bacon et le poivron rouge en option, ajouter à un mélange d’huile d’olive et de pois chiches, puis mélanger avec des linguinis cuites égouttées.  Garnis de parmesan sec ou de chese asaigo", "step_number": 4}]', 'https://img.spoonacular.com/recipes/650132-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.68409', '2026-01-19 18:23:17.68409', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '650132');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('66921b7d-aaea-41b6-83f8-439315f41e47', 'Salsa de maïs fraîche', 'La salsa de maïs frais prend environ 45 minutes du début à la fin. Cette recette sert 12 personnes et coûte 28 cents la portion. Tu fais attention à ta silhouette ? Cette recette sans gluten, sans produits laitiers, lacto-ovo végétarienne et vegan contient 24 calories, 1 g de protéines et 0 g de matières grasses par portion. Cela marche bien comme hor d’œuvre mexicain. Une personne était contente d’avoir essayé cette recette. Cette recette de Foodista nécessite du sel et du poivre, du jalapeño, de l’oignon et de la coriandre. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 16 %, ce qui est plutôt mauvais. Si vous aimez cette recette, vous pourriez aussi apprécier des recettes comme la Salsa de Maïs Frais, la Salsa de Maïs Frais et la Salsa de Maïs Frais.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["bol"], "ingredients": ["sel et poivre", "jus de chaux", "oignon rouge", "coriandre", "piment jalapeño", "maïs"], "instruction": "Dans un bol moyen, mélangez le maïs, le jalapeño, l’oignon rouge, la coriandre et le jus de citron vert.  Assaisonnez avec du sel et du poivre, selon votre goût.  Mettez au réfrigérateur jusqu’à ce que vous servez.", "step_number": 1}]', 'https://img.spoonacular.com/recipes/643462-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.67456', '2026-01-19 18:23:17.67456', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '643462');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('9c2e12ba-b465-4d2e-9634-324df4dd7ee3', 'Cilanandre Lime Jalapeño Corn', 'Le maïs coriandre et citron vert et jalapeño est un accompagnement végétarien lacto-ovo sans gluten. Cette recette en fait 4 et coûte 99 cents la portion. Une portion contient 157 calories, 3 g de protéines et 10 g de matières grasses. Une personne a fait cette recette et la referait. Il est présenté par Foodista. Si vous avez des épis de maïs, du beurre, de la coriandre et quelques autres ingrédients sous la main, vous pouvez le préparer. De la préparation à l’assiette, cette recette prend environ 25 minutes. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 20 %, ce qui est plutôt mauvais. Si vous aimez cette recette, vous pourriez aussi apprécier des recettes comme le maïs au cilantro et au citron vert et au jalapeño, courgettes et beignets de maïs rôti avec yaourt grec coriandre et citron vert, et des poppers au maïs et jalapeños au cheddar enroulés au bacon avec un Ranch de coriandre et citron vert.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 25, '[{"duration": null, "equipment": ["pot"], "ingredients": ["eau"], "instruction": "Apportez une grande casserole d’eau à bouillir.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 15}, "equipment": [], "ingredients": ["maïs"], "instruction": "Ajoutez le maïs et faites cuire environ 15 minutes.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["beurre"], "instruction": "Mélangez le beurre avec tous les autres ingrédients jusqu’à ce que la répartition soit uniforme. Réfrigérez jusqu’à ce qu’il soit prêt à utiliser.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["beurre", "étendue", "maïs"], "instruction": "Étalez la quantité désirée de beurre sur le maïs. PROFITEZ-EN !", "step_number": 4}]', 'https://img.spoonacular.com/recipes/639412-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.676575', '2026-01-19 18:23:17.676575', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '639412');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('f038790e-cb15-4a34-bede-08a5a0dde98f', 'Purée simple d’ignames', 'Si vous avez environ 45 minutes à passer en cuisine, Simple Mashed Yams pourrait être une recette végétarienne sans gluten, lacto ovo et primitive à essayer. Pour 1,18 $ la portion, cette recette couvre 16 % de vos besoins quotidiens en vitamines et minéraux. Une portion de ce plat contient environ 8g de protéines, 10g de matières grasses et un total de 371 calories. Cette recette en fait 4. Une personne a essayé et aimé cette recette. Un mélange d’ignames, d’ail, de sel et de poivre casher, ainsi qu’une poignée d’autres ingrédients, suffit pour rendre cette recette aussi délicieuse. Ça marche bien comme accompagnement. Il est présenté par Foodista. Dans l’ensemble, cette recette obtient un assez bon score cuillère de 62 %. Si vous aimez cette recette, jetez un œil à ces recettes similaires : Purée d’ignames mince, Tarte Cottage avec purée d’ignames et Purée d’ignames dans des tasses orange.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 65}, "equipment": ["feuille d''aluminium", "four"], "ingredients": ["Ail rôti", "ail", "Igname"], "instruction": "Préchauffez le four à 375. Avec une fourchette, percez les ignames avec quelques piqûres de fourchette. Je mettrais une petite feuille de papier aluminium en dessous car les jus vont cuire au four. Grillez les ignames pendant environ 45 minutes. Si vous aimez aussi l’ail rôti, vous pouvez le rôtir environ 20 minutes.", "step_number": 1}, {"duration": null, "equipment": ["Écraseur de pommes de terre", "four"], "ingredients": ["pomme de terre", "Igname"], "instruction": "Sortez-les du four et laissez-les refroidir un peu. Vous pouvez les mettre au réfrigérateur pour accélérer le processus. Quand ils sont assez froids pour être manipulés, coupez-les en deux et retirez les bonnes choses. Avec un écraseur de pommes de terre, écrasez les ignames.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["sel et poivre", "fromage à la crème", "ail"], "instruction": "Ajoutez l’ail, le sel casher et le poivre ainsi que le fromage frais.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["crème", "Igname"], "instruction": "Mélangez tout et servez. La texture crémeuse des ignames et la saveur rôtie sont divines.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/651238-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.67815', '2026-01-19 18:23:17.67815', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '651238');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('8cd54fd2-e4d7-4d01-b7cc-9199a77e9044', 'Frites de Karela / Alevins de la courge amère', 'La friture Karela / la courge amère dure environ 45 minutes du début à la fin. Cette recette contient 2 portions contenant 85 calories, 1 g de protéines et 7 g de matières grasses chacune. Pour 59 cents la portion, cette recette couvre 9 % de vos besoins quotidiens en vitamines et minéraux. Une personne a fait cette recette et la referait. Il fonctionne très bien comme accompagnement très abordable. Il est présenté par Foodista. Si vous avez du karela/courge amère, de l’huile d’olive et 1 cuillère à café, de la poudre de curcuma et quelques autres ingrédients sous la main, vous pouvez le préparer. C’est une bonne option si vous suivez un régime végétarien sans gluten, sans produits laitiers, paléolithique et lacto ovo. Tout bien considéré, nous avons décidé que cette recette mérite un score cuillère de 83 %. Cette partition est excellente. Si vous aimez cette recette, vous aimerez peut-être aussi des recettes comme le karela sthot fry ou le karela sabzi, comment faire le karela stir fry, le karelan ou la courge amère, et le meal fry, morceaux de soja frits.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["casserole"], "ingredients": ["curcuma", "piment", "Bitter Gourd", "sauce", "sel"], "instruction": "Prenez une large casserole, mettez le karela coupé et ajoutez du piment, de la poudre de curcuma, assez de sel.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["Bitter Gourd", "huile de cuisson"], "instruction": "Remuez bien, versez de l’huile sur le karela et mélangez bien.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 3}, "equipment": ["cuisinière", "poêle à frire"], "ingredients": [], "instruction": "Ensuite, allumez la cuisinière, fermez la poêle avec le couvercle et faites cuire à feu moyen pendant 2 à 3 minutes.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Ensuite, ouvre le couvercle, remue bien.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Mettez le feu à bas et laissez frire jusqu’à ce qu’il soit croustillant et cuit. (Ne pas couvrir avec un couvercle.)", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Continuez à remuer de temps en temps et laissez bien frire.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": ["Bitter Gourd"], "instruction": "Une fois terminé, Karela est prête à servir.", "step_number": 7}, {"duration": null, "equipment": [], "ingredients": ["riz"], "instruction": "Il convient aussi bien à toutes sortes de riz, riz au yogurt, sambar et rasam sadham.", "step_number": 8}]', 'https://img.spoonacular.com/recipes/648752-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.679432', '2026-01-19 18:23:17.679432', '{"vegan": true, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '648752');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('a3218752-dfb7-44f3-857a-1f70148d5d6c', 'Que préparer pour le dîner ce soir ?? Porc et pâtes à la bruschetta', 'Que préparer pour le dîner ce soir ?? Le Porc et pâtes à la Bruschetta prend environ 35 minutes du début à la fin. Cette recette en peut 5 et coûte 1,96 $ la portion. Ce plat principal contient 591 calories, 45 g de protéines et 13 g de matières grasses par portion. Si vous avez des pâtes papillon, du parmigiano reggiano, des recettes au poulet bruschetta et quelques autres ingrédients à disposition, vous pouvez en faire. 163 personnes ont fait cette recette et la referaient. Il est présenté par Pink When. Beaucoup de gens ont vraiment aimé ce plat méditerranéen. Avec un score cuillère de 90 %, ce plat est exceptionnel. Des recettes similaires sont Dîner ce soir : Porc grillé façon Romesco, Dîner ce soir : Bruschetta aux pois chiches, et Dîner ce soir : Bruschetta aux crevettes de ''da Zaccaria.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 35, '[{"duration": {"unit": "minutes", "number": 2}, "equipment": ["poêle à frire"], "ingredients": ["Farfalle", "côtelettes de porc", "parmesan", "ail", "basilic", "pâtes", "sauce", "eau", "porc"], "instruction": "Lavez et rincez les côtelettes de porc et placez-les dans la poêle. Découpez-les en morceaux de taille petite et ajoutez la moitié de la sauce mijoté basilic-ail. Faites bouillir votre eau et commencez à cuire vos pâtes papillon. Une fois que vous avez fini de faire bouillir et d’égoutter vos pâtes, ajoutez-les au porc avec le reste de la sauce à mijoter basilic-ail,  Mélange légèrement. Ensuite, vous garnirez la sauce finale Bruschetta en morceaux, couvrez de parmesan, puis couvrez. Cuissons à feu doux 2 à 3 minutes ou jusqu’à ce que ce soit bien chaud.", "step_number": 1}]', 'https://img.spoonacular.com/recipes/715538-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.681696', '2026-01-19 18:23:17.681696', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '715538');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('f15eff73-81d5-44f0-9433-fc694a06b877', 'Œufs mimosi carrés', 'Si vous avez environ 45 minutes à passer en cuisine, Square Deviled Eggs pourrait être une excellente recette sans gluten et primitive à essayer. Une portion contient 212 calories, 19 g de protéines et 15 g de matières grasses. Cette recette en fait 6. Pour 30 cents la portion, cette recette couvre 9 % de vos besoins quotidiens en vitamines et minéraux. 25 personnes ont trouvé cette recette délicieuse et satisfaisante. Il fonctionne bien comme un ouvrage à prix très raisonnable. Il est présenté par Foodista. Quelques personnes ont vraiment aimé ce plat américain. Si vous avez des œufs, du fromage à la crème, du jambon et quelques autres ingrédients sous la main, vous pouvez le préparer. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 22 %, ce qui n’est pas si impressionnant. Si vous aimez cette recette, vous pourriez aussi apprécier des recettes comme les œufs mimosa carrés, les pommes de terre mimosades (comme les œufs farse véganes !) et les œufs durs Instant Pot (et les œufs farse faciles !).', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["œuf dur", "œuf"], "instruction": "Pour faire des œufs durs carrés, il vous faudra un cubier d’œufs ou un presse-œufs carré. (Voir la note dans la section À propos sur l’endroit d’achat)", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["œuf"], "instruction": "Faites d’abord bouillir vos œufs, puis glissez l’œuf dans la presse et vissez le dessus pour que l’œuf pousse dans les coins.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["œuf"], "instruction": "Laissez refroidir l’œuf et retirez-le du moule. Pour de meilleurs résultats, utilisez des œufs de taille moyenne.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["œuf"], "instruction": "Si vous comptez préparer cela pour une fête, je vous suggère d’acheter plusieurs cubers, ainsi vous pourrez faire bouillir et refroidir plusieurs œufs à la fois, sinon cela vous prendra beaucoup de temps.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 15}, "equipment": ["casserole"], "ingredients": ["œuf dur", "eau", "œuf"], "instruction": "Pour préparer des œufs durs, placez-les dans une casserole, couvrez-les d’eau froide et portez-les à ébullition à feu moyen. Dès que l’eau a atteint une pleine ébullition, laissez les œufs bouillir pendant 5 minutes, puis retirez-les du feu et laissez reposer dans de l’eau chaude pendant 10 minutes.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["fromage à la crème", "jaune d''œuf", "jambon"], "instruction": "La garniture est faite avec du fromage à la crème, du jambon et du jaune d’œuf, elle a un goût très doux, c’est idéal pour les enfants.", "step_number": 6}]', 'https://img.spoonacular.com/recipes/661447-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.686319', '2026-01-19 18:23:17.686319', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '661447');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('f1760b39-b1a8-4e4c-b73d-2274a924069e', 'Haricots verts avec noix grillées et canneberges sucrées', 'Les haricots verts avec noix grillées et canneberges douces pourraient être exactement la recette sans gluten, sans produits laitiers, paléolithique et primordiale que vous cherchiez. Une portion contient 88 calories, 5 g de protéines et 4 g de matières grasses. Pour 54 cents la portion, cette recette couvre 7 % de vos besoins quotidiens en vitamines et minéraux. Cette recette en fait 8. Trois personnes ont essayé et aimé cette recette. Noël sera encore plus spécial avec cette recette. Rendez-vous au magasin et achetez du sel et du poivre casher, de l’huile d’olive rôtie, et quelques autres choses pour le préparer aujourd’hui. Seules quelques personnes ont vraiment aimé cet accompagnement. De la préparation à l’assiette, cette recette prend environ 45 minutes. Il est présenté par Foodista. Dans l’ensemble, cette recette obtient un excellent score cuillère de 88 %. Des recettes similaires sont les haricots verts grillés avec canneberges et noix, les haricots verts grillés avec canneberges et noix, et les haricots verts sautés avec canneberges et noix.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["pot"], "ingredients": ["eau"], "instruction": "Portez à ébullition une grande casserole d’eau.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["haricots verts", "sel"], "instruction": "Ajoutez 1 cuillère à soupe de sel et les haricots verts et", "step_number": 2}, {"duration": {"unit": "minutes", "number": 4}, "equipment": [], "ingredients": [], "instruction": "Faites cuire jusqu’à ce qu’elles soient tendres, 4 à 6 minutes.", "step_number": 3}, {"duration": null, "equipment": ["bol"], "ingredients": ["canneberges", "noix", "huile de cuisson"], "instruction": "Pendant ce temps, dans un grand bol, mélangez l’huile, les noix et les canneberges.", "step_number": 4}, {"duration": null, "equipment": ["bol"], "ingredients": ["haricots verts"], "instruction": "Égouttez les haricots verts et transférez-les dans le bol.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["poivre", "sel"], "instruction": "Ajoutez 1/2 cuillère à café de sel et 1/4 de cuillère à café de poivre, puis mélangez pour enrober.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servez chaud ou à température ambiante.", "step_number": 7}]', 'https://img.spoonacular.com/recipes/645419-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.687945', '2026-01-19 18:23:17.687945', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '645419');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('333f5a92-d2cd-4e21-8f43-fcfad169f3af', 'Haricots verts de style Sud plus sains', 'Les haricots verts de style sudiste sains prennent environ 45 minutes du début à la fin. Une portion contient 89 calories, 4g de protéines et 4g de matières grasses. Cette recette sans gluten et primal en sert 6 personnes et coûte 61 cents la portion. Si vous avez des haricots verts, de l’oignon, du bacon et quelques autres ingrédients à portée de main, vous pouvez le préparer. Une personne était contente d’avoir essayé cette recette. Ça marche bien comme accompagnement. Il est présenté par Foodista. C’est une recette très abordable pour les amateurs de cuisine du Sud. Dans l’ensemble, cette recette obtient un score cuillère pas si exceptionnel de 40 %. Les utilisateurs qui ont aimé cette recette ont également apprécié les haricots verts de style Sudiste, les haricots verts de style sudiste et les haricots verts de style Sudiste.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["poêle à frire"], "ingredients": ["beurre", "bacon"], "instruction": "Dans une grande poêle à feu moyen-vif, ajoutez le bacon et le beurre et fondez le bacon jusqu’à ce qu’il soit cuit, mais pas encore croustillant.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["oignon"], "instruction": "Ajoutez l’oignon et continuez à cuire jusqu’à ce qu’il soit tendre.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["haricots"], "instruction": "Ajoutez les haricots et sauterez jusqu’à ce qu’ils soient tendres et bien chauffés.", "step_number": 3}]', 'https://img.spoonacular.com/recipes/646424-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.690089', '2026-01-19 18:23:17.690089', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '646424');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('4de5327b-c1db-424a-9e3c-a93b5f0f1524', 'Haricots verts italiens avec anchois et chapelure', 'Les haricots verts italiens avec anchois et chapelure nécessitent environ 45 minutes du début à la fin. Cette recette en fait 2. Pour 2,19 $ la portion, cette recette couvre 29 % de vos besoins quotidiens en vitamines et minéraux. Ce plat principal contient 591 calories, 15 g de protéines et 31 g de matières grasses par portion. Une personne a été impressionnée par cette recette. Si vous avez de l’anchois, de la chapelure, des haricots verts et quelques autres ingrédients sous la main, vous pouvez le préparer. Peu de gens ont vraiment aimé ce plat méditerranéen. C’est une bonne option si vous suivez un régime sans produits laitiers et pescétarien. Il est présenté par Foodista. Tout bien considéré, nous avons décidé que cette recette méritait un score cuillère de 87 %. Cette partition est super. Les spaghettis aux anchois et chapelure, les spaghettis aux anchois et chapelure, et l’entrée aux anchois avec chapelure et oignons verts sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["processeur alimentaire", "four"], "ingredients": ["chapelure", "pain", "grains"], "instruction": "Préparez la chapelure : préchauffez le four à 300°F. Mettez du pain vieux d’un jour dans un robot culinaire. Encore mieux si c’est un grain entier ou d’une boulangerie locale.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 15}, "equipment": ["boîte à cuisson", "four"], "ingredients": ["Filets d’anchois", "huile d''olive", "origan", "poivre", "étendue", "haricots", "sel"], "instruction": "Étalez les miettes sur un plat de cuisson feuilleté, ajoutez sel, poivre, origan et huile d’olive. Mélangez avec vos mains pour enrober et faites cuire pendant environ 15 minutes, ou jusqu’à ce que ce soit doré. Commencez les haricots : écrasez quatre filets d’anchois avec une fourchette.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 5}, "equipment": ["cuillère en bois", "poêle à frire"], "ingredients": ["anchois", "huile d''olive", "oignon"], "instruction": "Chauffez une grande poêle en fonte, ajoutez environ 2 cuillères à soupe d’huile d’olive. Mettez le feu à faible intensité et ajoutez les anchois. Aplatir avec une cuillère en bois jusqu’à ce qu’ils se dissolvent. Ensuite, montez le feu à moyen et ajoutez les oignons. Remuez jusqu’à ce que ce soit tendre et translucide, environ cinq minutes.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 10}, "equipment": [], "ingredients": ["poivre noir", "haricots verts"], "instruction": "Ajoutez les haricots verts, quelques moulues de poivre noir frais, et faites cuire pendant 10 minutes.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 1}, "equipment": [], "ingredients": ["chapelure"], "instruction": "Ajoutez la chapelure et remuez pour enrober. Faites cuire encore une minute et éteignez le feu.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["Filets d’anchois"], "instruction": "Servez avec un filet d’anchois drapé", "step_number": 6}]', 'https://img.spoonacular.com/recipes/648259-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.691261', '2026-01-19 18:23:17.691261', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": true}', 'spoonacular', '648259');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('eb1087ec-6c77-4474-abfd-9084a9ffed3d', 'BEURRE DE CACAHUÈTE AU CHOCOLAT, TREMPETTES DE BANANE SURGELÉES', 'On n’a jamais trop de recettes d’hor d’œuvre, alors essayez les CHOCOLAT BEURRE DE CACAHUÈTE, DIPS DE BANANE SURGELÉS. Pour 32 cents la portion, cette recette couvre 4 % de vos besoins quotidiens en vitamines et minéraux. Cette recette en fait 6. Tu fais attention à ta silhouette ? Cette recette sans gluten, sans produits laitiers et compatible avec les FODMAP contient 194 calories, 3 g de protéines et 11 g de matières grasses par portion. Seules quelques personnes ont fait cette recette, et une dis-le a fait juste. Si vous avez des bananes, des pépites de chocolat, de l’huile de coco et quelques autres ingrédients sous la main, vous pouvez le préparer. Il est présenté par Foodista. De la préparation à l’assiette, cette recette prend environ 45 minutes. Tout bien considéré, nous avons décidé que cette recette méritait un score cuillère de 25 %. Cette note est plutôt mauvaise. Les bouchées de banane au chocolat au chocolat et au beurre de cacahuète congelées, aux bouchées de banane au chocolat et au beurre de cacahuète congelées, et les milkshakes surgelés à la banane, au beurre de cacahuète et aux pépites de chocolat sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["banane"], "instruction": "Épluchez les bananes et coupez-les en morceaux (2 à 3 morceaux par banane, selon la taille).", "step_number": 1}, {"duration": {"unit": "minutes", "number": 30}, "equipment": ["papier à pâtisserie", "plaque de cuisson"], "ingredients": ["banane"], "instruction": "Placez les morceaux de banane sur une plaque de cuisson avec du papier sulfurisé, puis au congélateur pendant 30 minutes.", "step_number": 2}, {"duration": null, "equipment": ["micro-ondes"], "ingredients": ["écorce d’amande", "croustilles de chocolat", "Huile de coco"], "instruction": "Pour préparer l’enrobage de chocolat, faites fondre les pépites de chocolat et l’huile de coco dans un plat adapté au micro-ondes.", "step_number": 3}, {"duration": null, "equipment": ["bâtonnets de glace"], "ingredients": ["banane"], "instruction": "Retirez les morceaux de banane du congélateur et insérez des bâtonnets de glace.", "step_number": 4}, {"duration": null, "equipment": ["Pinceau à pâtisserie"], "ingredients": ["chocolat", "banane", "trempette"], "instruction": "Trempez chaque banane dans le chocolat fondu. Ou, si vous êtes comme moi et que vous avez souvent du mal à obtenir une couche uniforme avec le chocolat fondu, utilisez un pinceau pâtissier en silicone et peignez généreusement les morceaux de banane. Veillez à bien sceller le fond de la glace avec le chocolat, pour que la banane ne glisse pas.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 10}, "equipment": [], "ingredients": ["banane"], "instruction": "Remettez le plateau avec les morceaux de banane enduits au congélateur pendant 10 minutes.", "step_number": 6}, {"duration": null, "equipment": ["micro-ondes", "bol"], "ingredients": ["beurre de cacahuète"], "instruction": "Pendant ce temps, mesurez le beurre de cacahuète et placez-le dans un bol ou une tasse adaptée au micro-ondes.", "step_number": 7}, {"duration": null, "equipment": ["micro-ondes"], "ingredients": [], "instruction": "Faites chauffer le micro-ondes à plein vif jusqu’à ce que ce soit complètement lisse et fondu.", "step_number": 8}, {"duration": null, "equipment": [], "ingredients": ["beurre de cacahuète"], "instruction": "Sortez la plaque du congélateur et arrosez chaque morceau du beurre de cacahuète fondu.", "step_number": 9}, {"duration": null, "equipment": [], "ingredients": ["beurre de cacahuète"], "instruction": "Remettez la plaque au congélateur, jusqu’à ce que le beurre de cacahuète durcisse légèrement.", "step_number": 10}]', 'https://img.spoonacular.com/recipes/639152-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.70932', '2026-01-19 18:23:17.70932', '{"vegan": false, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '639152');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('f00eb378-e346-42eb-9427-ecf03c70a520', 'Sauce au cassis.', 'La sauce au cassis, c’est environ 45 minutes du début à la fin. Une portion contient 199 calories, 0 g de protéines et 0 g de matières grasses. Cette recette en sert 4 et coûte 81 cents la portion. Il est présenté par Foodista. Deux personnes ont fait cette recette et la referaient. C’est une bonne option si vous suivez un régime sans gluten, sans produits laitiers et compatible avec les FODMAP. Seules quelques personnes ont vraiment aimé cette sauce. Si vous avez des cassis, de la gelée de cassis, du jus de citron et quelques autres ingrédients à portée de main, vous pouvez en préparer. Tout bien considéré, nous avons décidé que cette recette mérite un score cuillère de 8 %. Ce score est améliorable. Les utilisateurs qui ont aimé cette recette ont également apprécié la Mousse de Cassise et Noix de Cor avec Cassis, des tranches de noix de coco et la reine des puddings à la Cassis.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 2}, "equipment": ["mélangeur", "tamis"], "ingredients": ["Arrowroot", "fécule de maïs", "eau"], "instruction": "Faites ébullir tous les ingrédients et laissez mijoter 2 minutes. Réduisez en mixeur au blender jusqu’à ce qu’il soit lisse ou forcez à passer un tamis. Épaissir légèrement avec 1 cuillère à café d’arrow-root ou de farine de maïs dissous dans une petite quantité d’eau si nécessaire.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["glace", "baies"], "instruction": "Servez avec de la glace ou des desserts. D’autres baies peuvent être remplacées. Délicieux avec des pancakes ou des gaufres.", "step_number": 2}]', 'https://img.spoonacular.com/recipes/635260-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.692896', '2026-01-19 18:23:17.692896', '{"vegan": false, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '635260');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('46fc7a79-9ab5-4080-bc08-6f5913e5131c', 'Pudding aux baies d’été', 'Le Summer Berry Pudding pourrait être exactement le dessert que vous cherchez. Tu fais attention à ta silhouette ? Cette recette lacto-ovo-végétarienne et végane sans produits laitiers, contient 44 calories, 0 g de protéines et 0 g de matières grasses par portion. Cette recette en fait 8. Pour 30 cents la portion, cette recette couvre 1 % de vos besoins quotidiens en vitamines et minéraux. Un mélange de sucre de ricin, de poignettes, de framboises, de cerises et de quelques autres ingrédients suffisent pour rendre cette recette si délicieuse. Ce sera un succès lors de votre événement du 4 juillet. Cette recette est appréciée par un gourmet et des cuisiniers. De la préparation à l’assiette, cette recette prend environ 45 minutes. Il est présenté par Foodista. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 9 %, ce qui est très mauvais (mais toujours réparable). Des recettes similaires incluent le pudding d’été aux baies, le pudding aux baies d’été et le pudding aux baies d’été.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["baies"], "instruction": "Réservez quelques baies pour décorer le pudding fini.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["fraises"], "instruction": "Écasser et trancher les fraises.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["jus de grenade", "sucre en poudre", "cerises", "baies", "eau"], "instruction": "Placez dans une poêle avec les autres baies et cerises, saupoudrez de sucre de ricin et ajoutez l’eau ou le jus de grenade.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 3}, "equipment": [], "ingredients": [], "instruction": "Laissez mijoter environ trois minutes pour libérer les jus, en remuant doucement une ou deux fois.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 10}, "equipment": ["tamis", "bol"], "ingredients": ["fruits", "jus"], "instruction": "Placez un tamis sur un bol et versez les fruits dedans. Laissez égoutter pendant 10 minutes, en conservant le jus.", "step_number": 5}, {"duration": null, "equipment": ["enveloppe plastique", "bol"], "ingredients": ["enveloppe"], "instruction": "En attendant, tapissez une gamelle d’une capacité de 1,5 litre de film plastique.", "step_number": 6}, {"duration": null, "equipment": ["bol"], "ingredients": ["pain"], "instruction": "Découpez un cercle dans le pain pour qu’il s’adapte au fond du bol.", "step_number": 7}, {"duration": null, "equipment": ["bol"], "ingredients": [], "instruction": "Découpez des formes légèrement effilées pour aligner le bol et des triangles pour le dessus.", "step_number": 8}, {"duration": null, "equipment": ["bol"], "ingredients": ["pain", "jus", "trempette"], "instruction": "Trempez rapidement un côté du cercle du bas du pain dans le jus et placez-le, côté jus vers le bas, dans le bol.", "step_number": 9}, {"duration": null, "equipment": [], "ingredients": ["pain", "jus"], "instruction": "Faites de même avec le pain pour les accompagnements, trempés-les dans le jus puis en les superposant de quelques centimètres.", "step_number": 10}, {"duration": null, "equipment": [], "ingredients": ["fruits"], "instruction": "Mets les fruits à la cuillère.", "step_number": 11}, {"duration": null, "equipment": [], "ingredients": ["pain"], "instruction": "Disposez les triangles de pain dessus, en les superposant à nouveau sur les morceaux.", "step_number": 12}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Verser doucement sur les jus restants.", "step_number": 13}, {"duration": null, "equipment": ["enveloppe plastique", "bol"], "ingredients": ["enveloppe"], "instruction": "Couvrez le dessus de film plastique puis placez le bol dans un plat peu profond pour récupérer les jus.", "step_number": 14}, {"duration": null, "equipment": ["bol"], "ingredients": [], "instruction": "Choisissez une assiette plate qui s’adapte au dessus du bol.", "step_number": 15}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Placez-le dessus et alourdissez-le avec quelque chose de lourd. Laissez-le au réfrigérateur pendant quelques heures ou toute la nuit.", "step_number": 16}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Pour servir, récupère les jus.", "step_number": 17}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Retirez le plastique du dessus et retournez le pudding sur une assiette de service.", "step_number": 18}, {"duration": null, "equipment": [], "ingredients": ["jus"], "instruction": "Verse sur tout le jus restant.", "step_number": 19}, {"duration": null, "equipment": [], "ingredients": ["Crème fouettée sucrée", "fruits"], "instruction": "Décorez avec les fruits réservés et servez avec de la crème fouettée sucrée.", "step_number": 20}]', 'https://img.spoonacular.com/recipes/662208-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.695166', '2026-01-19 18:23:17.695166', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '662208');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('9e90a378-0215-4d2d-a03b-3bbdbc34969d', 'Pizzette aubergine', 'La pizzette d’aubergine prend environ 45 minutes du début à la fin. Une portion de ce plat contient environ 11g de protéines, 11g de matières grasses et un total de 178 calories. Pour 1,2 $ la portion, vous obtenez un accompagnement qui en fait 3 personnes. Cette recette est appréciée par 5 passionnés de gastronomie et cuisiniers. C’est une bonne option si vous suivez un régime sans gluten, lacto-ovo végétarien et primal. Rendez-vous au magasin et achetez des aubergines rondes, des tomates, du gruyère, et quelques autres choses pour la préparer aujourd’hui. Il est présenté par Foodista. Avec un score cuillère de 70 %, ce plat est bien. Des recettes similaires sont Margherita Pizzette, Nicoise Salad Pizzette et Pizzette au Gorgonzola, Tomate et basilic.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 10}, "equipment": ["four", "poêle à frire"], "ingredients": ["huile d''olive", "aubergine"], "instruction": "Placez les rondelles d’aubergine dans une poêle antiadhésive graissée à l’huile d’olive et faites cuire au four pendant 10 minutes à 230°C.", "step_number": 1}, {"duration": null, "equipment": ["four", "poêle à frire"], "ingredients": ["aubergine"], "instruction": "Retirez la poêle du four, mais laissez l’aubergine au four à l’intérieur.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["basilic frais", "aubergine", "tomate", "origan"], "instruction": "Couvrez chaque rond d’aubergine d’une cuillère de tomates hachées, saupoudrez d’origan et de feuilles de basilic.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 5}, "equipment": ["four"], "ingredients": ["fromage"], "instruction": "Garnissez de fromage râpé et laissez cuire 5 minutes supplémentaires au four à la même température, jusqu’à ce que le fromage soit fondu et doré d’un dorat.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servez une pizzette chaude ou refroidie en entrée ou en petit repas indépendant.", "step_number": 5}]', 'https://img.spoonacular.com/recipes/642303-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.697714', '2026-01-19 18:23:17.697714', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '642303');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('1f4ea26f-1049-4c53-a8a2-c39a66752176', 'Aubergines « Chips » faciles et addictives', 'Si vous avez environ 45 minutes à passer en cuisine, Easy and Addictive Eggplant « Chips » pourrait être une recette très sans gluten, sans produits laitiers, lacto-ovo végétarienne et vegan à essayer. Cette recette en fait 3. Une portion contient 222 calories, 3g de protéines et 19g de matières grasses. Pour 85 cents la portion, cette recette couvre 7 % de vos besoins quotidiens en vitamines et minéraux. Il est présenté par Foodista. Un mélange de bouillon de poulet, 1 aubergine, sauce soja et quelques autres ingrédients suffisent pour rendre cette recette aussi délicieuse. Deux personnes ont trouvé cette recette savoureuse et satisfaisante. Il fonctionne bien comme accompagnement américain. Dans l’ensemble, cette recette obtient un solide score cuillère de 40 %. Les utilisateurs qui ont aimé cette recette ont également apprécié les « chips d’aubergine faciles et addictives », les chips d’aubergine faciles et addictives, et les chips de chou kale totalement addictives.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Préchauffez le four à 400 °F.", "step_number": 1}, {"duration": null, "equipment": ["plaque de cuisson"], "ingredients": ["aubergine", "cookies"], "instruction": "Placez les ronds d’aubergine en une seule couche sur une grande plaque à biscuits.", "step_number": 2}, {"duration": null, "equipment": ["fouet", "four"], "ingredients": ["aubergine", "marinade"], "instruction": "Fouetter tous les autres aliments et verser sur l’aubergine. Retournez les tranches pour que la marinade puisse aussi s’infiltrer de l’autre côté de l’aubergine. *Laissez l’aubergine mariner brièvement pendant que le four préchauffe. Retournez les tranches à nouveau, en les gardant en une seule couche.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 25}, "equipment": ["four", "spatule"], "ingredients": ["aubergine"], "instruction": "Faites-les cuire environ 10 à 15 minutes, ou jusqu’à ce que le dessous soit bien doré. Retournez les tranches avec une spatule et laissez-les cuire encore 5 à 10 minutes, ou jusqu’à ce que l’aubergine soit très tendre et ait l’air caramélisée (gluante et bien dorée) des deux côtés.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 10}, "equipment": ["four", "poêle à frire"], "ingredients": ["aubergine", "sauce"], "instruction": "Servez immédiatement. Vous aurez une sauce qui ne s’absorbe pas vraiment dans l’aubergine. Elle cuit sur la plaque, mais si vous la laissez tremper pendant au moins 10 minutes, elle s’enlevera facilement.", "step_number": 5}]', 'https://img.spoonacular.com/recipes/641811-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.699832', '2026-01-19 18:23:17.699832', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '641811');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('efbc83af-6f19-492e-b4b8-6b67ba8311c2', 'Omelette au poulet et courgette', 'L’omelette au poulet et courgette est un plat principal qui sert deux personnes. Pour 72 cents la portion, cette recette couvre 11 % de vos besoins quotidiens en vitamines et minéraux. Une portion contient 210 calories, 13 g de protéines et 16 g de matières grasses. Il est présenté par Foodista. De la préparation à l’assiette, cette recette prend environ 45 minutes. Cette recette est appréciée par 6 passionnés de gastronomie et cuisiniers. Si vous avez du poulet milanais restant, de l’huile, de la courgette et quelques autres ingrédients sous la main, vous pouvez le préparer. C’est une bonne option si vous suivez un régime sans gluten, sans produits laitiers, compatible avec les FODMAP et complet 30. Tout bien considéré, nous avons décidé que cette recette méritait un score cuillère de 38 %. Cette partition n’est pas si impressionnante. Si cette recette vous plaît, jetez un œil à ces recettes similaires : Omelette au poulet courgette, Omelette au poulet aux courgettes et Omelette au poulet aux courgettes.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["bol"], "ingredients": ["eau", "œuf"], "instruction": "Bats les œufs et l’eau dans un bol.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["sel et poivre", "courgettes"], "instruction": "Mélangez des courgettes râpées et assaisonnez avec du sel et du poivre.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 1}, "equipment": ["poêle à frire"], "ingredients": ["poulet", "œuf", "huile de cuisson"], "instruction": "Chauffez l’huile dans une petite poêle antiadhésive. Une fois chaud, ajoutez la moitié du mélange d’œufs et faites cuire pendant 1 minute jusqu’à ce que l’œuf commence à prendre. Dispersez uniformément avec du poulet en demi-dés.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 2}, "equipment": [], "ingredients": ["œuf"], "instruction": "Faites cuire encore 1 à 2 minutes, jusqu’à ce que l’œuf soit doré en dessous, puis posez simplement dessus. Glissez-le sur une assiette de service, en la pliant au fur et à mesure. Répétez.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servez l’omelette avec votre salade préférée.", "step_number": 5}]', 'https://img.spoonacular.com/recipes/665734-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.710917', '2026-01-19 18:23:17.710917', '{"vegan": false, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '665734');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('6431beef-7bdc-42b5-a82a-80cc465d196c', 'Maïs en épi dans la coriandre et le beurre au citron vert', 'Le maïs en épi dans du beurre de coriandre et citron vert est une recette américaine qui sert 3 personnes. Une portion de ce plat contient environ 3 g de protéines, 32 g de matières grasses et un total de 348 calories. Pour 1,2 $ la portion, cette recette couvre 6 % de vos besoins quotidiens en vitamines et minéraux. Une personne était contente d’avoir essayé cette recette. Il est présenté par Foodista. Rendez-vous au magasin et achetez du citron vert, de la coriandre, du maïs en épi et quelques autres choses pour le préparer aujourd’hui. Peu de gens aimaient vraiment cet accompagnement. De la préparation à l’assiette, cette recette prend environ 30 minutes. C’est une bonne option si vous suivez un régime végétarien sans gluten et lacto ovo. Tout bien considéré, nous avons décidé que cette recette mérite un score cuillère de 20 %. Cette note est plutôt mauvaise. Si vous aimez cette recette, vous pourriez aussi apprécier des recettes comme Maïs en Épi avec Beurre de Coriandre et Lime, Maïs grillé en Épi avec Beurre de Coriandre et Citron vert, et Maïs en Épi avec Beurre Épicé de Coriandre.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 30, '[{"duration": null, "equipment": ["bol"], "ingredients": ["coriandre", "beurre", "citron vert"], "instruction": "Prenez le bol et mélangez bien la coriandre, le citron vert et le beurre", "step_number": 1}, {"duration": null, "equipment": ["feuille d''aluminium", "four", "poêle à frire"], "ingredients": [], "instruction": "Prenez un moule à four et mettez-le dessus de la feuille aluminium", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["maïs"], "instruction": "Ajoutez les moitiés de maïs", "step_number": 3}, {"duration": {"unit": "minutes", "number": 20}, "equipment": ["four"], "ingredients": ["coriandre", "beurre", "maïs"], "instruction": "Versez le mélange de beurre et de coriandre sur le maïs. Recouvre-la d’aluminium. Préchauffez le four à 400 degrés et laissez-le reposer environ 20 minutes. Bon appétit et servez-le en accompagnement à chaque repas !", "step_number": 4}]', 'https://img.spoonacular.com/recipes/640089-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.702078', '2026-01-19 18:23:17.702078', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '640089');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('9752506a-94b0-4715-a12a-ad794111013a', 'Skinny Green Monster Smoothie', 'La recette Skinny Green Monster Smoothie peut être préparée en environ 45 minutes. Cette recette en fait 1 et coûte 1,99 $ la portion. Ce petit-déjeuner contient 286 calories, 18 g de protéines et 11 g de matières grasses par portion. 7 personnes ont essayé et aimé cette recette. C’est une bonne option si vous suivez un régime sans gluten. Si vous avez du yaourt grec, des petits épinards, du beurre de cacahuète et quelques autres ingrédients sous la main, vous pouvez le préparer. Il est présenté par Foodista. C’est parfait pour Halloween. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 87 %, ce qui est excellent. Des recettes similaires incluent le smoothie Skinny Green Monster, le smoothie Skinny Green Monster et le smoothie Skinny Green Monster.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["mélangeur"], "ingredients": [], "instruction": "Placez tous les ingrédients dans un blender et mixez jusqu’à ce que ce soit lisse.", "step_number": 1}]', 'https://img.spoonacular.com/recipes/660227-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.703466', '2026-01-19 18:23:17.703466', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '660227');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('794a5806-927d-4254-8400-63ad161deaed', 'Smoothie à l’orange et à la cardamome délicieux', 'Le smoothie délicieux à l’orange et à la cardamome prend environ 45 minutes du début à la fin. Une portion contient 133 calories, 2g de protéines et 1g de matières grasses. Cette recette en fait 2 et coûte 29 cents la portion. Une personne a été impressionnée par cette recette. Rendez-vous au magasin et achetez des bananes, du jus d’orange, de la poudre de cardamome et quelques autres choses pour le préparer aujourd’hui. C’est un bon choix de petit-déjeuner très économique. Il est présenté par Foodista. C’est une bonne option si vous suivez un régime végétarien sans gluten, sans produits laitiers, paléolithique et lacto ovo. Dans l’ensemble, cette recette obtient un solide score cuillère de 62 %. Si vous aimez cette recette, vous pourriez aussi apprécier des recettes comme le smoothie Lite ''n Luzzous, le défi des boulangers audacieux : Panna cotta vanille et orange sanguine avec sauce caramel à l’orange et piment de la Jamaise et aux Florentines au chocolat noir à la cardamome orange et aux noix noires (sans gluten), et la panna cotta à l’orange et délicieuse.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["Beurre d’amande", "sirop d''érable", "édulcorant", "dates", "miel", "sucre"], "instruction": "Mélangez les trois ingrédients ensemble jusqu’à ce qu’ils soient lisses et mousseux. Si besoin d’édulcorant, ajoutez des dattes, du miel, du sirop d’érable, du beurre d’amande ou du sucre selon votre goût.", "step_number": 1}]', 'https://img.spoonacular.com/recipes/650485-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.706799', '2026-01-19 18:23:17.706799', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '650485');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('388021cb-babd-42f3-a665-86a3fada0315', 'Salsa saine au chocolat et beurre de cacahuète et banana Xocai', 'La sauce Xocai Healthy Chocolate et Beurre de Cacahuète et Banana est un plat d’œuvre qui sert 1. Une portion de ce plat contient environ 6g de protéines, 18g de matières grasses et un total de 343 calories. Pour 66 cents la portion, cette recette couvre 10 % de vos besoins quotidiens en vitamines et minéraux. Une personne a essayé et aimé cette recette. On peut en profiter à tout moment, mais c’est particulièrement bon pour le Super Bowl. Un mélange de bananes tige, de chocolat, de beurre de cacahuète et de quelques autres ingrédients suffit pour rendre cette recette aussi savoureuse. Il est présenté par Foodista. De la préparation à l’assiette, cette recette prend environ 45 minutes. C’est une bonne option si vous suivez un régime sans gluten. Dans l’ensemble, cette recette obtient un solide score cuillère de 49 %. Si vous aimez cette recette, jetez un œil à ces recettes similaires : Xocai Irish Cream avec Xocai Healthy Dark Dark Chocolate Nuggets, Sauce au yaourt Healthy Peanut butter et pépites de chocolat, et Muffins au chocolat Xocai Healthy.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["micro-ondes"], "ingredients": ["beurre de cacahuète", "crème", "banane", "trempette"], "instruction": "Placez la Nugget dans une cuvette à crème anglaise et laissez-la faire passer au micro-ondes par tranches de 10 secondes jusqu’à ce qu’elle soit fondue. Incorporez le beurre de cacahuète et mélangez soigneusement. Faites tourner la banane dans la sauce.", "step_number": 1}]', 'https://img.spoonacular.com/recipes/665469-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.707834', '2026-01-19 18:23:17.707834', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '665469');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('5bf57e48-a758-458e-875b-89cc19a79089', 'Œufs au four Portobello', 'Portobello Baked Eggs est un plat principal végétarien, primal et cétogène sans gluten, lacto ovo. Cette recette en fait 4 et coûte 2,31 $ la portion. Une portion contient 233 calories, 12 g de protéines et 19 g de matières grasses. Cette recette de l’utilisateur cuillère Kitchen Dreaming contient des œufs, du sel et du poivre, des épinards et des coiffures de champignon portobello. De la préparation à l’assiette, cette recette prend environ 20 minutes. Essayez des mini-burgers de portobello au barbecue, des champignons portobello farcis sans allergies, et une salade de portobello grillée avec du parmigiano-reggiano coupé pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 20, '[{"duration": null, "equipment": ["four"], "ingredients": ["champignons"], "instruction": "Mettez le four au grill. Nettoyez les chapeaux de champignon et, si désiré, grattez légèrement les branchies sous chaque casquette.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["sel et poivre", "champignons", "huile d''olive"], "instruction": "Badigeonnez les champignons des deux côtés avec de l’huile d’olive, et assaisonnez avec du sel et du poivre.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 5}, "equipment": ["poêle à frire"], "ingredients": [], "instruction": "Placez le côté branchique vers le bas sur une plaque et faites cuire environ 3 à 5 minutes.", "step_number": 3}, {"duration": null, "equipment": ["four"], "ingredients": ["champignons", "épinard", "œuf"], "instruction": "Sortez-le du four.  Baissez le four à 350°F.    Retournez le côté branchique des champignons et commencez à construire.  D’abord, placez les épinards dans le capuchon en construisant les côtés et en créant un puits au centre, si nécessaire, pour accueillir l’œuf.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 15}, "equipment": ["four"], "ingredients": ["chèvre", "champignons", "œuf"], "instruction": "Ajoutez un peu de fromage de chèvre et cassez soigneusement un œuf dans le puits de chaque capuchon de champignon. Remettez-les maintenant dans votre four à 350°F et laissez-les cuire pendant 15 à 17 minutes selon votre qualité de cuisson ou de vos œufs bien ensoleillés.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servir immédiatement.", "step_number": 6}]', 'https://img.spoonacular.com/recipes/157960-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.793694', '2026-01-19 18:23:17.793694', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '157960');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('82df4950-9696-4752-bdae-e605001d273c', 'Pois et estragon avec fromage de chèvre frais', 'Pois et estragon avec fromage de chèvre frais nécessitent environ 45 minutes du début à la fin. Une portion contient 38 calories, 3 g de protéines et 0 g de matières grasses. Pour 19 cents la portion, vous obtenez un accompagnement qui peut servir 10 personnes. Si vous avez des pois, du fromage de chèvre chavrie, de l’estragon et quelques autres ingrédients sous la main, vous pouvez en préparer. Une personne a trouvé cette recette délicieuse et satisfaisante. C’est une bonne option si vous suivez un régime sans gluten, lacto-ovo végétarien et primal. Il est présenté par Foodista. Tout bien considéré, nous avons décidé que cette recette méritait un score cuillère de 79 %. Cette partition est plutôt bonne. Des toasts simples au fromage de chèvre et aux œufs avec pois frais et aneth, crème de pois, gnocchetti au pain aux raisins, fromage de chèvre frais, et asperges, pois et radis avec estragon frais sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["pot"], "ingredients": ["chèvre", "estragon", "sauce"], "instruction": "Mélangez du fromage de chèvre et de l’estragon dans une casserole à sauce moyenne.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Faites mijoter doucement.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 5}, "equipment": [], "ingredients": ["petits pois"], "instruction": "Ajoutez les petits pois et laissez mijoter jusqu’à ce que la température soit bien chaude, environ 5 minutes.", "step_number": 3}, {"duration": null, "equipment": ["Plat à gratin"], "ingredients": [], "instruction": "Servez dans un plat à gratin.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/655477-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.712711', '2026-01-19 18:23:17.712711', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '655477');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('994c0397-02b8-4711-9588-c4d82ac67e5e', 'Poulet rôti lentement au citron et à l’ail', 'Le poulet rôti lentement au citron et à l’ail pourrait être une bonne recette pour enrichir votre boîte de recettes principale. Une portion de ce plat contient environ 24g de protéines, 26g de matières grasses et un total de 347 calories. Cette recette en fait 6. Pour 1,12 $ la portion, cette recette couvre 12 % de vos besoins quotidiens en vitamines et minéraux. Seules quelques personnes ont fait cette recette, et une dis-le a fait juste. Cette recette de Foodista nécessite de l’huile de tournesol, des bulbes d’ail, des citrons et de l’huile d’olive. De la préparation à l’assiette, cette recette prend environ 45 minutes. C’est une bonne option si vous suivez un régime sans gluten, sans produits laitiers, entier 30 et cétogène. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 40 %, ce qui n’est pas si super. Essayez un poulet grappa rôti lentement à l’ail et citron au poivre avec des frites de panais, un gigot d’agneau désossé rôti lentement avec ail, romarin et citron, ainsi que du gigot d’agneau désossé rôti lentement avec ail, romarin et citron pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["Sauté de légumes", "champignons"], "instruction": "Sachets de 300g de champignons ou de légumes à l’italienne sauté ou sauté de votre choix, finement râpés", "step_number": 1}, {"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Équipement Aga : petit moule à rôtir sur un troisième ensemble de chemins au four à rôtir, puis un deuxième jeu de patins au four à mijotage", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["Graisse de poulet", "poulet", "clou de girofle", "ail"], "instruction": "Coupez les pointes des jambes et des ailes du poulet et retirez tout excès de graisse du cou de l’oiseau (gardez la graisse si vous comptez faire un confit dans les prochains jours). Assaisonnez le poulet à l’intérieur comme à l’extérieur. Séparez l’ail en gousses mais ne prenez pas la peine de les éplucher.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 640}, "equipment": ["enveloppe plastique"], "ingredients": ["huile d''olive", "poulet", "clou de girofle", "citron", "jus", "enveloppe", "broyage sec"], "instruction": "Placez environ les deux tiers des clous de girofle à l’intérieur du poulet et le reste au fond du moule à rôtir, en posant le poulet dessus. Retirez le zeste des citrons et couvrez-le de film plastique pour un usage ultérieur en garniture. Frottez le jus dans le poulet à l’intérieur et à l’extérieur, puis frottez l’huile d’olive sur la poitrine. Rôtissez rapidement le poulet pendant 30 minutes puis transférez-le au four mijotant et cuisez-le pendant au moins 4 heures. Laissez reposer 10 à 15 minutes avant de découper, ou, si vous avez laissé le poulet six heures ou plus, en écartant les joints pour le servir.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 5}, "equipment": ["poêle à frire", "wok"], "ingredients": ["poulet"], "instruction": "Chauffez un wok ou une grande poêle pendant 5 minutes sur le sol du four à rôtir pendant que le poulet est debout.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 3}, "equipment": ["wok"], "ingredients": ["huile de tournesol", "légumes", "estragon", "poulet", "ail", "citron", "os", "viande", "huile de cuisson"], "instruction": "Transférez le wok sur l’assiette bouillante et ajoutez l’huile de tournesol. Faites sauter les légumes dans l’huile pendant 3 à 4 minutes, puis servez le poulet sur les légumes ou mélangez-les avec si la viande s’est détachée de l’os. Je cuisine souvent du poulet avec du citron et de l’estragon, mais la saveur de cette herbe âcre se perd si la cuisson est trop longue. Donc, pour la cuisson lente de l’aga, j’utilise un mélange de citron et d’ail.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Au service de 6 personnes", "step_number": 7}]', 'https://img.spoonacular.com/recipes/649495-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.713866', '2026-01-19 18:23:17.713866', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '649495');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('7e445418-46cb-4b70-b44e-681cb1c0bae4', 'Glace aux fruits frais', 'La recette Glace aux Fruits Frais peut être préparée en environ 45 minutes. Cette recette contient 12 portions avec 198 calories, 5g de protéines et 10g de matières grasses chacune. Pour 60 centimes la portion, cette recette couvre 4 % de vos besoins quotidiens en vitamines et minéraux. Il est présenté par Foodista. Ce sera un succès lors de votre événement d’été. 5 personnes ont trouvé cette recette délicieuse et satisfaisante. C’est une bonne option si vous suivez un régime végétarien sans gluten et lacto ovo. Rendez-vous au magasin et achetez des fruits, de l’extrait de vanillan, du lait concentré et quelques autres choses pour les préparer aujourd’hui. Avec un score cuillère de 29 %, ce plat est plutôt mauvais. {Maigre} Gâteau Arc-en-ciel aux Fruits Frais, Glaces Dimanches : Glace à la Menthe Fraîche Pépites de Chocolat, et Glace Dimanches : Glace à la Menthe Fraîche Pépites de Chocolat sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["machine à crème glacée", "bol"], "ingredients": ["lait condensé sucré", "Glace à la vanille", "Tope fouettée", "crème fouettée", "Colorant alimentaire", "moitié et moitié", "glace", "vanille", "fruits"], "instruction": "Dans un récipient de glace, mélangez tous les ingrédients ; Mélange bien. Gelez selon les instructions du fabricant. Congelez les restes. Ice Cream Maker Vanilla Ice Cream : Omettez les fruits et les colorants alimentaires. Augmentez la dose moitié-moitié à 4 tasses. Procédez comme ci-dessus. Méthode du réfrigérateur au congélateur : Omettez la moitié et la moitié. Dans un grand bol, mélangez du lait condensé sucré et de la vanille ; Incorporez 1 tasse de fruits en purée ou de colorant alimentaire, si vous le souhaitez. Pliez 2 tasses (1 pinte) de crème fouettée Borden, fouettées (n’utilisez pas de garniture fouettée non laitière).", "step_number": 1}, {"duration": {"unit": "minutes", "number": 360}, "equipment": ["Moule à pain"], "ingredients": [], "instruction": "Versez dans un moule à pain de 9x5 pouces ou dans un autre contenant de 2 litres ; couvrir. Fixez 6 heures ou jusqu’à ce que vous soyez ferme. Congelez les restes.", "step_number": 2}]', 'https://img.spoonacular.com/recipes/643487-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.716228', '2026-01-19 18:23:17.716228', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '643487');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('c0a78e9a-dfd4-4407-b5d4-9d82aa9e817f', 'Prunes au chocolat', 'Chocolate Plums est une recette végétarienne sans gluten, sans produits laitiers, paléolithique et lacto ovo, avec 24 portions. Une portion contient 86 calories, 1 g de protéines et 5 g de matières grasses. Pour 38 cents la portion, cette recette couvre 3 % de vos besoins quotidiens en vitamines et minéraux. Peu de gens ont fait cette recette, et l’un dis-le serait parfait. Rendez-vous au magasin et achetez des prunes, des amandes entières, du chocolat et quelques autres choses pour le préparer aujourd’hui. Il est présenté par Foodista. Il fonctionne mieux comme un coup d’œuvre, et se termine en environ 45 minutes. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 22 %, ce qui n’est pas si impressionnant. Si cette recette vous plaît, vous pourriez aussi aimer des recettes comme le clafoutis aux prunes au chocolat et cardamome, le clafouti aux prunes aux prunes au brandi.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["papier à pâtisserie", "plaque de cuisson"], "ingredients": [], "instruction": "Préparez une plaque de cuisson en la tapissant de papier sulfurisé et laissez-la de côté pour l’instant.", "step_number": 1}, {"duration": null, "equipment": ["casserole"], "ingredients": ["chocolat", "pruneaux", "sauce"], "instruction": "Hachez le chocolat en petits morceaux et placez-le dans une casserole. Faites cuire à basse température, en remuant continuellement, jusqu’à ce que le chocolat soit fondu. Remuez jusqu’à ce que le chocolat soit lisse, puis laissez-le reposer et refroidir légèrement pendant que vous préparez les pruneaux.", "step_number": 2}, {"duration": null, "equipment": ["couteau"], "ingredients": ["amandes", "pruneaux"], "instruction": "Insérez les amandes au centre des pruneaux, un noix par pruneau. Je trouve qu’il est plus facile d’utiliser l’extrémité effilée de l’écrou pour la pousser au centre de la prune. Si vous avez des difficultés, pouvez utiliser un couteau d’office pour créer un petit trou afin d’insérer l’écrou.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["chocolat", "pruneaux", "trempette"], "instruction": "Utilisez une fourchette ou des outils à tremper pour tremper une des pruneaux dans le chocolat, en le submergeant complètement.", "step_number": 4}, {"duration": null, "equipment": ["bol"], "ingredients": ["chocolat"], "instruction": "Retirez-le du chocolat et faites glisser le fond le long du rebord du bol pour enlever l’excès de chocolat.", "step_number": 5}, {"duration": null, "equipment": ["plaque de cuisson"], "ingredients": ["chocolat", "noix"], "instruction": "Placez-le sur la plaque de cuisson préparée et, si désirez, saupoudrez le dessus de noix écrasées pendant que le chocolat est encore humide.", "step_number": 6}, {"duration": null, "equipment": ["plaque de cuisson"], "ingredients": ["chocolat", "pruneaux", "prune"], "instruction": "Répétez le trempage avec les pruneaux restants et le chocolat. Une fois toutes les pruneaux sur la plaque, laissez le chocolat prendre ainsi (ne les mettez pas au réfrigérateur car les prunes au chocolat auront l’air nœud). Conservez les prunes au chocolat dans un récipient hermétique au réfrigérateur pendant jusqu’à une semaine.", "step_number": 7}]', 'https://img.spoonacular.com/recipes/639167-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.717376', '2026-01-19 18:23:17.717376', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '639167');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('7f3a2e95-01ab-4908-908f-80e4f15bb182', 'Glace à la noix de coco et grenade - crue et végane', 'On n’a jamais trop de recettes de desserts, alors essayez la glace à la noix de coco et de grenade - crue et vegan. Une portion contient 557 calories, 3g de protéines et 28g de matières grasses. Pour 3,77 $ la portion, cette recette couvre 12 % de vos besoins quotidiens en vitamines et minéraux. Cette recette en fait 3. De la préparation à l’assiette, cette recette prend environ 45 minutes. Une personne a essayé et aimé cette recette. Ce sera un succès lors de votre événement d’été. Rendez-vous au magasin et achetez de la crème de coco, du sirop d’érable, de la grenade et quelques autres choses pour le préparer aujourd’hui. C’est une bonne option si vous suivez un régime végétarien sans gluten, sans produits laitiers, paléolithique et lacto ovo. Il est présenté par Foodista. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 41 %, ce qui est plutôt bien. Des recettes similaires incluent les cupcakes de glace au chocolat véganes crus, la glace aux fraises rôties au lait de coco (végane) + conseils pour tendre votre glace maison, et la base de glace végane crue super crémeuse d’Andy.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": [], "instruction": "Épluchez la grenade pour obtenir environ 1,5 à 2 tasses de grenade.", "step_number": 1}, {"duration": null, "equipment": ["jus de fruits"], "ingredients": ["jus", "graines", "citron vert"], "instruction": "Dans un extracteur de presses, pressez la grenade avec le jus d’une demi-lime. C’est à vous de décider si vous voulez inclure les graines de grenade ou les jeter. Je les ai inclus car ils sont très sains.", "step_number": 2}, {"duration": null, "equipment": ["bol"], "ingredients": ["sirop d''érable", "jus de chaux"], "instruction": "Transférez le jus de pomo et citron vert dans un bol. Incorporez le sirop d’érable.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["Crème de coco"], "instruction": "Ajoutez petit à petit la crème de coco dans le mélange, en remuant tout en continuant.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 10}, "equipment": ["mélangeur"], "ingredients": [], "instruction": "Vous pouvez aussi remettre ce mélange dans un blender et simplement faire passer un peu d’air en mélangeant pendant 5 à 10 minutes.", "step_number": 5}, {"duration": null, "equipment": ["bol"], "ingredients": [], "instruction": "Mettez le mélange dans un bol en boîte et mettez-le au congélateur avec un couvercle.", "step_number": 6}, {"duration": {"unit": "minutes", "number": 240}, "equipment": [], "ingredients": [], "instruction": "Après environ une heure à mettre le mélange au congélateur, enlève-le, casse les morceaux et remue un moment, puis remets-le au congélateur pour réinitialiser. Répétez ce processus encore quelques fois après environ une heure. Ensuite, laissez-le au congélateur pendant 4 heures pour qu’il soit posé une dernière fois.", "step_number": 7}]', 'https://img.spoonacular.com/recipes/639708-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.718834', '2026-01-19 18:23:17.718834', '{"vegan": true, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '639708');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('1aa0d2bb-c2c3-4cbc-8ca9-f66c5ebb8d11', 'Glaçage au citron pour gâteaux', 'Le Lemon Glaze For Cakes est un accompagnement sans gluten, sans produits laitiers, lacto-ovo végétarien et compatible avec les FODMAP. Cette recette sert 1. Une portion contient 837 calories, 0 g de protéines et 1 g de matières grasses. Pour 75 cents la portion, cette recette couvre 3 % de vos besoins quotidiens en vitamines et minéraux. Une personne a trouvé cette recette délicieuse et satisfaisante. Rendez-vous au magasin et achetez du jus, du citron, du sucre glace et quelques autres choses pour le préparer aujourd’hui. Il est présenté par Foodista. De la préparation à l’assiette, cette recette prend environ 45 minutes. Dans l’ensemble, cette recette obtient un score cuillère assez mauvais de 11 %. Des recettes similaires sont les gâteaux au citron Meyer avec glaçage à la grenade, les mini gâteaux à l’huile d’olive avec glaçage au citron, et le glaçage au chocolat pour gâteaux (qui durcit).', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["bol"], "ingredients": [], "instruction": "Dans un petit bol, avec des batteurs électriques, mélangez tous les ingrédients et battez jusqu’à ce qu’ils soient lisses.", "step_number": 1}]', 'https://img.spoonacular.com/recipes/649643-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.720669', '2026-01-19 18:23:17.720669', '{"vegan": true, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '649643');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('a7d0a25a-e820-4c08-ab83-b0c10e37ccd6', 'Pina Colada', 'La pina Coladan est une boisson sans gluten, sans produits laitiers, lacto-ovo végétarienne et adaptée aux FODMAP. Cette recette contient 1 portion contenant 1560 calories, 15 g de protéines et 4 g de matières grasses chacune. Pour 11,11 $ la portion, cette recette couvre 50 % de vos besoins quotidiens en vitamines et minéraux. De la préparation à l’assiette, cette recette prend environ 45 minutes. Un mélange de rhum, de lait de coco, de cuillère à soupe d’ananas et d’une poignée d’autres ingrédients suffit pour rendre cette recette aussi savoureuse. Il est présenté par l’utilisateur spoonacular drinkhero. Des recettes similaires sont la piña colada congelée à trois ingrédients.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["mélangeur"], "ingredients": ["Glaçons concassés"], "instruction": "Mélangez avec de la glace concassée au blender jusqu’à ce que ce soit lisse.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Versez dans un verre bien frais, garnissez et servez.", "step_number": 2}]', 'https://img.spoonacular.com/recipes/1956748-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.722621', '2026-01-19 18:23:17.722621', '{"vegan": true, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": true, "veryHealthy": true}', 'spoonacular', '1956748');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('d133341b-c38f-41b8-bec2-9658a249b0c0', 'Glace basilic-noix de coco', 'La glace basilic-coco est un dessert qui sert 8 personnes. Une portion de ce plat contient environ 3 g de protéines, 23 g de matières grasses et un total de 283 calories. Pour 1,08 $ la portion, cette recette couvre 7 % de vos besoins quotidiens en vitamines et minéraux. Cette recette de Foodista nécessite des feuilles de basilic, du sel, du miel, et moitié-moitié. Ce sera un succès lors de votre événement d’été. Cinq personnes ont été impressionnées par cette recette. C’est une bonne option si vous suivez un régime sans gluten, lacto-ovo végétarien et primal. De la préparation à l’assiette, cette recette prend environ 45 minutes. Tout bien considéré, nous avons décidé que cette recette méritait un score cuillère de 28 %. Cette partition n’est pas si impressionnante. Si vous aimez cette recette, vous pourriez aussi aimer des recettes comme la meilleure façon de lécher la glace à la noix de coco et au basilic thaï ! 2008 Glace C, Janine’s Blueberry Basilic Ice Cream Meilleur Lick ! Glace 2008 et glace au lait de coco fraise grillée (Vegan) + conseils pour rendre votre glace maison plus tendre.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["casserole", "cuisinière"], "ingredients": ["lait de coco", "crème"], "instruction": "Faites chauffer le lait de coco et la crème sur la cuisinière à feu moyen-vif dans une casserole jusqu’à ce qu’ils soient chauds et à peine bouillants (portez à ébullition douce).", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["miel", "sel"], "instruction": "Ajoutez du miel et du sel ; Mélange pour dissoudre.", "step_number": 2}, {"duration": null, "equipment": ["casserole"], "ingredients": ["basilic frais"], "instruction": "Ajoutez les feuilles de basilic, remuez et laissez-les flétrir dans le mélange ; Retirez la casserole du feu.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 20}, "equipment": ["colander", "tamis", "mélangeur"], "ingredients": ["basilic"], "instruction": "Versez le mélange dans un blender et émulsifiez jusqu’à ce qu’il soit complètement crémeux et qu’aucun morceau de basilic ne soit visible (si ce n’est pas possible dans votre blender, vous pouvez filtrer les morceaux de basilic avec une passoire fine en fil métallique si vous le souhaitez, ou vous pouvez laisser les morceaux de basilic dans le mélange).  Laissez le mélange refroidir 20 minutes ; Cela permet aux saveurs de s’infuser.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Versez le mélange dans un grand récipient et laissez-le réfrigérer quelques heures jusqu’à ce que cela refroidisse.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 25}, "equipment": ["machine à crème glacée", "Minuteur de cuisine", "bol"], "ingredients": ["glace"], "instruction": "Si vous utilisez une machine à glaces, suivez les instructions de votre machine à glaces en conséquence (celle que j’ai utilisée est posée sur le plan de travail). Il suffit de le brancher, de le mettre en mode chill, de laisser refroidir le bol intégré, puis de verser le mélange de glace. Vous activez ensuite le réglage de churn et activez le minuteur pendant 25 minutes.  Ça fait sa magie et tu as une délicieuse glace au moment où le dîner est dégusté).", "step_number": 6}, {"duration": {"unit": "minutes", "number": 600}, "equipment": ["machine à crème glacée"], "ingredients": ["glace", "glace"], "instruction": "Vous pouvez aussi essayer sans machine à glace en mettant le mélange dans un contenant sans congèlation et en remuant avec une cuillère toutes les heures pendant environ 8 à 10 heures.  Si vous essayez sans machine à glace, de petits cristaux de glace se formeront et la consistance ne sera pas aussi onctueuse que celle que vous obtiendriez avec une machine à glace, mais ce sera quand même sacrément délicieux !", "step_number": 7}, {"duration": {"unit": "minutes", "number": 10}, "equipment": [], "ingredients": ["glace"], "instruction": "Petite parenthèse : nous avions des restes quand j’ai fait ça et nous les avons congelés dans un contenant Tupperware. La glace est bien congelée, donc quand vous allez manger les restes, assurez-vous de la décongeler au moins 10 minutes avant de commencer à manger.", "step_number": 8}]', 'https://img.spoonacular.com/recipes/634425-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.724625', '2026-01-19 18:23:17.724625', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '634425');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('03509bd3-cdb7-48e4-aab6-7e10d7640220', 'Simple Vinaigrette', 'La Vinaigrette simple est un accompagnement qui peut servir 4 personnes. Une portion contient 14 calories, 0g de protéines et 0g de matières grasses. Pour 31 cents la portion, cette recette couvre 0 % de vos besoins quotidiens en vitamines et minéraux. Une personne a trouvé cette recette délicieuse et satisfaisante. Rendez-vous au magasin et achetez de la moutarde de Dijon, de l’ail, du vinaigre de riz assaisonné et quelques autres choses pour le préparer aujourd’hui. De la préparation à l’assiette, cette recette prend environ 45 minutes. C’est une bonne option si vous suivez un régime végétarien sans gluten, sans produits laitiers, paléolithique et lacto ovo. Il est présenté par Foodista. Dans l’ensemble, cette recette obtient un score cuillère assez mauvais de 15 %. Des recettes similaires incluent la Vinaigrette simple, la Vinaigrette simple et la Vinaigrette Simple réelle.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["Vinaigre de riz assaisonné", "Vinaigrette", "moutarde", "ail"], "instruction": "Ça fait une demi-tasse. Le vinaigre de riz assaisonné fait une sauce délicieuse à lui seul ou avec de la moutarde et de l’ail.", "step_number": 1}, {"duration": null, "equipment": ["fouet"], "ingredients": ["Vinaigre de riz assaisonné", "Vinaigre de riz", "légumes", "édulcorant", "sel"], "instruction": "Fouetter tous les ingrédients ensemble. À utiliser comme vinaigrette pour les salades et les légumes vapeur. NOTES : Ceci vient des nouveaux livres du Dr Barnard, avec des recettes de Jennifer Raymond. C’est une garniture très délicieuse, aussi bien froide que chaude. Selon votre vinaigre de riz assaisonné, il peut être très sucré. J’aime donc utiliser 1/2 vinaigre de riz assaisonné et 1/2 vinaigre de riz classique. Sinon, vous pouvez utiliser du vinaigre de riz classique et ajouter du sel et de l’édulcorant selon votre goût. Cela fait une demi-tasse, ce qui signifie qu’elle peut servir de 4 à 8 personnes, selon que vous voulez 2 ou 4 cuillères à soupe par personne.", "step_number": 2}]', 'https://img.spoonacular.com/recipes/660158-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.726223', '2026-01-19 18:23:17.726223', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '660158');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('63da26bf-9f37-4638-959a-4957a3c4903b', 'Chou frisé à l’ail', 'Le chou kale à l’ail nécessite environ 45 minutes du début à la fin. Cet accompagnement contient 170 calories, 2g de protéines et 15g de matières grasses par portion. Cette recette en fait 2. Pour 69 cents la portion, cette recette couvre 17 % de vos besoins quotidiens en vitamines et minéraux. 19 personnes ont fait cette recette et la referaient. Cette recette de Foodista nécessite du vinaigre balsamique, de l’ail, du chou frisé et de l’huile d’olive. C’est une bonne option si vous suivez un régime végétarien sans gluten, sans produits laitiers, paléolithique et lacto ovo. Avec un score cuillère de 99 %, ce plat est exceptionnel. Essayez le chou kale à l’ail, le chou kale à l’ail et le chou kale à l’ail pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["pot"], "ingredients": ["huile d''olive"], "instruction": "Chauffez l’huile d’olive dans une grande marmite à feu moyen.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["chou"], "instruction": "Ajoutez le chou kale et couvrez. Remuez de temps en temps jusqu’à ce que le volume du chou kale soit réduit de moitié. Découvrez.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["vinaigre", "ail"], "instruction": "Ajoutez de l’ail et de la base basalique. Laissez cuire environ 30 secondes, en mélangeant bien pour bien répartir l’ail et le vinaigre.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servir chaud.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/644387-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.727497', '2026-01-19 18:23:17.727497', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": true}', 'spoonacular', '644387');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('c808ebab-d447-4d95-b268-f782f569ebe9', 'Choux de Bruxelles rôti au miel de Dijon', 'Le choux de Bruxelles rôti au miel et à la Dijon est un accompagnement qui en sert 4. Pour 54 cents la portion, cette recette couvre 8 % de vos besoins quotidiens en vitamines et minéraux. Une portion de ce plat contient environ 2g de protéines, 7g de matières grasses et un total de 115 calories. 13 personnes ont été impressionnées par cette recette. Rendez-vous au magasin et achetez des choux de Bruxelles, de la moutarde de Dijon, de l’huile d’olive et quelques autres choses pour les préparer aujourd’hui. De la préparation à l’assiette, cette recette prend environ 45 minutes. C’est une bonne option si vous suivez un régime végétarien sans gluten, sans produits laitiers, paléolithique et lacto ovo. Il est présenté par Foodista. Dans l’ensemble, cette recette obtient un solide score cuillère de 68 %. Les utilisateurs qui ont aimé cette recette ont également apprécié la salade de choux de Bruxelles râpée avec raisins secs et érable à la vinaigrette de Dijon, le choux de Bruxelles à la moutarde et au miel, et la salade de chou de Bruxelles au miel et moutarde.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["bol", "four"], "ingredients": ["Choux de Bruxelles", "moutarde au miel", "huile d''olive", "moutarde", "miel"], "instruction": "Préchauffez le four à 400 km, fouettez ensemble l’huile d’olive, la moutarde et le miel jusqu’à ce que ce soit bien combiné. Dans un grand bol, mélangez les choux de Bruxelles dans un mélange miel et moutarde.", "step_number": 1}, {"duration": null, "equipment": ["torréfaction"], "ingredients": ["Choux de Bruxelles", "sel et poivre", "étendue"], "instruction": "Étalez les choux de Bruxelles uniformément sur une poêle en fonte ou un plat à rôtir. Sel et poivre selon votre goût.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 20}, "equipment": ["four"], "ingredients": [], "instruction": "Faites cuire sur la grille supérieure pendant 20 minutes.", "step_number": 3}, {"duration": null, "equipment": ["four"], "ingredients": ["Choux de Bruxelles"], "instruction": "Sortez-le du four et mélangez pour que les choux de Bruxelles cuissent uniformément.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 10}, "equipment": ["four"], "ingredients": [], "instruction": "Remettez au four et rôtissez encore 10 minutes. Les feuilles extérieures doivent être légèrement carbonisées et l’intérieur tendre.", "step_number": 5}]', 'https://img.spoonacular.com/recipes/647210-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.72875', '2026-01-19 18:23:17.72875', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '647210');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('f554e5fb-005e-40db-92f7-383133ed42be', 'Penne avec fromage de chèvre et basilic', 'Si vous souhaitez ajouter plus de recettes lacto-ovo végétariennes à votre coffret de recettes, le Penne au fromage de chèvre et au basilic pourrait être une recette à essayer. Cette recette en sert 12. Une portion de ce plat contient environ 6 g de protéines, 5 g de matières grasses et un total de 151 calories. Pour 48 cents la portion, cette recette couvre 5 % de vos besoins quotidiens en vitamines et minéraux. Trois personnes ont fait cette recette et la referaient. Cette recette de Foodista contient des pâtes penne, des feuilles de basilic, du fromage de chèvre et de l’huile d’olive. Ça fonctionne bien comme hor d’œuvre. De la préparation à l’assiette, cette recette prend environ 45 minutes. Tout bien considéré, nous avons décidé que cette recette mérite un score cuillère de 47 %. Cette partition est solide. Des recettes similaires sont le Penne avec Trévise et fromage de chèvre, le Penne à la tomate rôtie avec fromage de chèvre, et le Penne à l’ail doux et au fromage de chèvre.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["pâtes"], "instruction": "Faites cuire les pâtes selon les instructions de l’emballage", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["basilic frais", "rouleau"], "instruction": "Rangez les feuilles de basilic en pile, roulez comme un cigare et continuez à couper en travers.  Cette technique s’appelle chiffonade.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["chèvre", "huile d''olive", "pâtes"], "instruction": "Mélangez les pâtes avec de l’huile d’olive et du fromage de chèvre et laissez refroidir quelques minutes.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["poivre", "basilic", "sel"], "instruction": "Ajoutez du basilic, du sel et du poivre, puis servez", "step_number": 4}]', 'https://img.spoonacular.com/recipes/655589-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.730239', '2026-01-19 18:23:17.730239', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '655589');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('e94d3f6e-46e9-4510-8fdc-b3fc312ab227', 'Salade César à la truffe noire', 'La salade César à la truffe noire pourrait être une bonne recette pour enrichir votre boîte de recettes hor d’œuvre. Cette recette contient 4 portions avec 153 calories, 12g de protéines et 10g de matières grasses chacune. Pour 1,26 $ la portion, cette recette couvre 7 % de vos besoins quotidiens en vitamines et minéraux. C’est une bonne option si vous suivez un régime sans gluten, sans produits laitiers, paléolithique et primal. Rendez-vous au magasin et achetez du jus de citron, de l’huile d’olive extra vierge, de la laitue romaine, et quelques autres choses pour le préparer aujourd’hui. Une personne a fait cette recette et la referait. De la préparation à l’assiette, cette recette prend environ 45 minutes. Il est présenté par Foodista. Peu de gens aimaient vraiment ce plat américain. Tout bien considéré, nous avons décidé que cette recette méritait un score cuillère de 40 %. Cette partition est plutôt bonne. Si vous aimez cette recette, jetez un œil à ces recettes similaires : Salade César sans œuf avec poulet fumé au poivre noir, César au saumon fumé au cèdre avec vinaigrette Meyer au citron et truffe et anchois, et Salade César grillée avec sauce César légère.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["processeur alimentaire", "mélangeur"], "ingredients": ["jus de citron", "huile d''olive", "sel"], "instruction": "Ajoutez du jus de citron, de l’huile d’olive et du sel dans un mixeur ou un petit robot culinaire", "step_number": 1}, {"duration": null, "equipment": ["mélangeur"], "ingredients": ["Truffes"], "instruction": "Râpez la moitié des truffes dans le blender et gardez le reste pour les râper sur la salade en garniture.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["citron", "sel", "huile de cuisson"], "instruction": "Mélangez la vinaigrette jusqu’à ce qu’elle soit épaisse et crémeuse. Goûtez et ajustez le ratio sel et huile/citron selon votre goût.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["laitue"], "instruction": "Coupez, lavez et séchez la laitue.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "À lancer avec la robe et l’assiette.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["canard"], "instruction": "Ajoutez du canard si vous en consommez.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": ["Truffes"], "instruction": "Rasez les truffes restantes sur chaque assiette et servez.", "step_number": 7}]', 'https://img.spoonacular.com/recipes/635161-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.731897', '2026-01-19 18:23:17.731897', '{"vegan": false, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '635161');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('5da01b75-0470-44cb-98a7-a9ef98c3aa49', 'Salade de poulet sans produits laitiers', 'On ne mange jamais trop de recettes de plats principaux, alors essayez la salade de poulet sans produits laitiers. Cette recette sans gluten, sans produits laitiers, adaptée aux FODMAP et cétogène en sert 4 personnes et coûte 2,9 $ la portion. Une portion de ce plat contient environ 40 g de protéines, 33 g de matières grasses, et un total de 487 calories. De la préparation à l’assiette, cette recette prend environ 45 minutes. Deux personnes ont trouvé cette recette délicieuse et satisfaisante. Si vous avez du sel, des cornichons à l’aneth, du paprika et quelques autres ingrédients sous la main, vous pouvez en préparer. Il est présenté par Foodista. Tout bien considéré, nous avons décidé que cette recette mérite un score cuillère de 55 %. Cette partition est bonne. Des recettes similaires sont la salade de poulet chinoise sans gluten sans produits laitiers et sans sucre, la salade de poulet chinoise sans gluten sans produits laitiers et sans sucre, et la salade de poulet au chili et citron vert (paléo, sans gluten, sans produits laitiers + sans sucre raffiné).', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["poêle à frire"], "ingredients": ["huile d''olive", "poulet"], "instruction": "Décongelez le poulet si besoin. Ensuite, ajoutez l’huile d’olive dans une grande poêle et portez-la à feu moyen.", "step_number": 1}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["poulet", "paprika", "poivre", "sel"], "instruction": "Ajoutez le poulet à la poêle et assaisonnez avec du paprika, du sel et du poivre. Tournez toutes les quelques minutes et faites cuire jusqu’à ce que le poulet soit bien cuit et que les jus soient clairs.", "step_number": 2}, {"duration": null, "equipment": ["planche à découper", "bol"], "ingredients": ["poulet"], "instruction": "Retirez le poulet et placez-le sur une grande planche à découper. À l’aide de deux fourchettes, effilochez le poulet et placez-le dans un grand bol.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 7}, "equipment": ["Minuteur de cuisine", "pot"], "ingredients": ["eau", "œuf"], "instruction": "Si ce n’est pas déjà fait, faites bouillir les œufs. Vous voulez connaître la méthode parfaite pour faire bouillir des œufs ??? Il suffit de recouvrir les œufs d’eau froide dans une grande marmite. Ensuite, placez la casserole à feu moyen-vif. Dès que ça commence à bouillir, réglez votre minuterie à 7 minutes. C’est fait !", "step_number": 4}, {"duration": null, "equipment": ["bol"], "ingredients": ["shredded chicken", "œuf"], "instruction": "Épluchez et hachez vos œufs, puis placez-les dans le bol avec votre poulet râpé.", "step_number": 5}, {"duration": null, "equipment": ["bol"], "ingredients": ["cornichons à l’aneth"], "instruction": "Now chop up your dill pickles and throw them in the bowl as well.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": ["sel assaisonné", "jus de citron", "vegan mayonnaise"], "instruction": "Ajoutez la Veganaise, le jus de citron et le sel assaisonné. Lancer pour combiner.", "step_number": 7}, {"duration": null, "equipment": [], "ingredients": ["pain"], "instruction": "Servez avec votre pain préféré.", "step_number": 8}]', 'https://img.spoonacular.com/recipes/641200-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.734292', '2026-01-19 18:23:17.734292', '{"vegan": false, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '641200');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('3fa8903d-e921-4080-ba73-e7bfb2b9cdb0', 'Grilled Ham and Cheese French Toast For A Quick Weeknight Dinner', 'The recipe Grilled Ham and Cheese French Toast For A Quick Weeknight Dinner can be made in about 45 minutes. One portion of this dish contains approximately 31g of protein, 22g of fat, and a total of 432 calories. This recipe serves 4. For $1.34 per serving, this recipe covers 21% of your daily requirements of vitamins and minerals. Only a few people really liked this American dish. 3 people were glad they tried this recipe. The Fourth Of July will be even more special with this recipe. If you have turkey ham, jarlsberg cheese, smart balance heart right, and a few other ingredients on hand, you can make it. It works well as a main course. It is brought to you by Foodista. All things considered, we decided this recipe deserves a spoonacular score of 59%. This score is solid. Try Ham and Asparagus Frittata – A Quick & Easy Weeknight Dinner, Ham ’n Cheese French Toast, and Ham and Cheese Biscuit Panini PLUS More Quick Dinner Ideas for similar recipes.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Préchauffez le four à 350 degrés.", "step_number": 1}, {"duration": null, "equipment": ["fouet", "bol"], "ingredients": ["Au babeurre", "blancs d''œufs"], "instruction": "Dans un bol peu profond ou une assiette à tarte, fouetter ensemble le babeurre et les blancs d’œufs. Mets de côté.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["moutarde", "fromage", "étendue", "pain", "jambon"], "instruction": "Étalez de la moutarde d’un côté de chaque tranche de pain.  Ajoute 1 tranche de fromage sur 4 tranches.  Posez du jambon sur le fromage.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["moutarde", "cornichons", "pain"], "instruction": "Ajoutez à chacun 3 à 4 fines tranches de cornichon. Garnez de tranches de pain restantes, côté moutarde vers le bas.", "step_number": 4}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["Au babeurre", "beurre", "trempette"], "instruction": "Faites fondre 1 cuillère à soupe de beurre allégé dans une grande poêle antiadhésive à feu moyen.  Trempez 2 sandwiches dans un mélange de babeurre ; Retournez-le doucement et plongez-le de l’autre côté.  Ne trempe pas les sandwiches dans ce mélange. Il suffit de tremper légèrement et de retirer les sandwichs, en laissant l’excès de mélange au babeurre retomber dans le plat.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 8}, "equipment": ["spatule", "poêle à frire"], "ingredients": ["fromage"], "instruction": "Ajoutez les sandwichs dans la poêle ; Couvrir et cuire 3 à 5 minutes.  Découvrez, retournez les sandwichs, appuyez sur le dessus avec une spatule, couvrez et faites cuire pendant 2 à 3 minutes jusqu’à ce que doré et que le fromage soit fondu.", "step_number": 6}, {"duration": null, "equipment": ["plaque de cuisson", "four"], "ingredients": [], "instruction": "Retirez les sandwichs, placez-les sur une plaque de cuisson et gardez-les au chaud au four.", "step_number": 7}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Répétez les étapes 4 et 5 avec les 2 sandwiches restants.", "step_number": 8}, {"duration": null, "equipment": ["couteau"], "ingredients": [], "instruction": "Slice each sandwich in half and serve with a fork and knife.", "step_number": 9}]', 'https://img.spoonacular.com/recipes/645732-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.737573', '2026-01-19 18:23:17.737573', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '645732');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('77d73b87-24ed-4e46-a620-1ac9b05db789', 'Côtes de Bébé Fumées', 'Vous cherchez un plat principal sans gluten, sans produits laitiers et adapté aux FODMAP ? Les côtes levées fumées pourraient être une excellente recette à essayer. Cette recette en vaut 1 et coûte 12,43 $ la portion. Une portion de ce plat contient environ 223g de protéines, 221g de matières grasses et un total de 3457 calories. Une personne a essayé et aimé cette recette. Un mélange de côtes levées bébés, de cassonade, de pico de gallo et d’une poignée d’autres ingrédients suffit pour rendre cette recette aussi délicieuse. Il est présenté par Foodista. De la préparation à l’assiette, cette recette prend environ 45 minutes. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 86 %, ce qui est incroyable. Si vous aimez cette recette, vous pourriez aussi aimer des recettes comme les côtes levées de bébé fumées avec sauce barbecue au bourbon, les côtes levées 3-2-1 : les côtes levées fumées de bébé fumée à la chute de l’os, et les meilleures côtes levées de bébé.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 510}, "equipment": [], "ingredients": ["viande", "Côtes", "broyage sec"], "instruction": "Frottez les étagères de côtes de chaque côté avec un Special Dry Rub ; Laissez reposer à température ambiante pendant 30 minutes ou réfrigérez jusqu’à 8 heures, permettant ainsi à la viande de revenir à température ambiante avant la cuisson.", "step_number": 1}, {"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Chauffez le four à 375 degrés.", "step_number": 2}, {"duration": null, "equipment": ["torréfaction", "porte-fils"], "ingredients": ["Côtes"], "instruction": "Placez des grilles de côtes dans une seule couche sur une grille métallique dans un grand plat à rôtir peu profond.", "step_number": 3}, {"duration": null, "equipment": ["four", "poêle à frire"], "ingredients": ["eau"], "instruction": "Versez 1/2 pouce d’eau dans la poêle ; Placez soigneusement le plat au four.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 155}, "equipment": ["boîte à cuisson", "micro-ondes", "papier cire", "four", "grille"], "ingredients": ["frites", "eau", "Côtes"], "instruction": "Faites cuire 1 heure jusqu’à ce que les côtes ne soient plus roses au centre. Ou placer les côtes dans un plat de 3 pintes au micro-ondes, côté charnu, en chevauchant si besoin ; Cuis, recouvert de papier ciré, à haute température (100 %) pendant 5 minutes. On réarrange les côtes mais garde le côté charnu. Réduire le feu à moyen (70 %) ; Cuis, couvert, 40 minutes de plus, puis réarrangez les côtes après 20 minutes. En attendant, allumez le feu dans le barbecue. Faites tremper les copeaux de noyer dans de l’eau froide pour couvrir au moins 30 minutes. Lorsque les braises sont incandescentes, égouttez les copeaux ; Dispersez-vous sur les braises.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 6}, "equipment": ["grille"], "ingredients": ["Côtes"], "instruction": "Placez la grille à 15 cm au-dessus des braises ; Disposez les côtes sur un grillage. Faites cuire 6 à 7 minutes de chaque côté jusqu’à ce que les côtes soient légèrement grillées et cuites complètement.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": ["sauce barbecue"], "instruction": "Chauffe la sauce barbecue.", "step_number": 7}, {"duration": null, "equipment": [], "ingredients": ["Sauce piquante", "Côtes"], "instruction": "Découpez des grilles de côtes en morceaux individuels ; Disposez sur un plateau de service, en versant un peu de sauce piquante par-dessus.", "step_number": 8}, {"duration": {"unit": "minutes", "number": 3}, "equipment": ["poulet", "four"], "ingredients": ["Pico de Gallo", "fumée liquide", "eau", "Côtes", "broyage sec"], "instruction": "Servez accompagné du barbecue restant et du Pico de Gallo. Ça fait 4 portions. Vous pouvez aussi finir les côtes au four, avant d’ajouter un mélange de mélange de 2 cuillères à café de fumée naturelle aromatisée au hickory et 1 cuillère à soupe d’eau ; marinez comme indiqué. Cuisiner au four comme indiqué, puis chauffer le gril ; Grillez les côtes, à 10 à 15 cm de la source de chaleur, 3 à 5 minutes.", "step_number": 9}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servez comme on les a demandés.", "step_number": 10}]', 'https://img.spoonacular.com/recipes/660400-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.795487', '2026-01-19 18:23:17.795487', '{"vegan": false, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": false, "veryHealthy": true}', 'spoonacular', '660400');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('7ead5ab6-33d3-4fe5-aba6-d30df85c346f', 'Yaourt glacé en amaretto tourbillonné de dulce de leche', 'On n’a jamais trop de recettes de desserts, alors essayez le yaourt glacé Dulce de Leche Swirled Amaretto. Cette recette contient 4 portions avec 26 calories, 0g de protéines et 3g de matières grasses chacune. Pour 13 cents la portion, cette recette couvre 0 % de vos besoins quotidiens en vitamines et minéraux. Cette recette est appréciée par 5 passionnés de gastronomie et cuisiniers. Un mélange de yaourt à la vanille, de crème amaretto, de dulce de leche et de quelques autres ingrédients suffit pour rendre cette recette aussi savoureuse. Il est présenté par Foodista. De la préparation à l’assiette, cette recette prend environ 45 minutes. C’est une bonne option si vous suivez un régime végétarien sans gluten et lacto ovo. Dans l’ensemble, cette recette obtient un score cuillère amélioré de 8 %. Le gâteau gaufré russe au dulce de leche et le dulce de leche à la cafetière instantanée, le milkshake au dulce de leche (Dulce de Leche) et le yaourt glacé aux myrtilles tourbillonnées sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["yaourt"], "instruction": "J’ai égoutté le yaourt pendant la nuit", "step_number": 1}, {"duration": null, "equipment": ["machine à crème glacée"], "ingredients": ["glace", "Liqueur d’amaretto", "yaourt", "crème"], "instruction": "Mélangez la crème amaretto au yaourt et barattez dans votre machine à glaces selon les instructions du fabricant.", "step_number": 2}, {"duration": null, "equipment": ["micro-ondes"], "ingredients": ["dulce de leche", "caramel", "yaourt"], "instruction": "Réchauffez le dulce de leche, ou caramel, au micro-ondes pendant 30 secondes. Lorsque le yaourt est prêt, ajoutez des filets de dulce-leche dans le yaourt et conservez-le au congélateur.", "step_number": 3}]', 'https://img.spoonacular.com/recipes/641732-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.741992', '2026-01-19 18:23:17.741992', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '641732');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('2e738c85-4593-4174-8b81-a114e555abfd', 'Moules dans la sauce au curry', 'Les moules dans la sauce au curry pourraient être exactement le plat d’œuvre que vous cherchez. Tu fais attention à ta silhouette ? Cette recette végétarienne sans gluten et lacto ovo contient 291 calories, 2g de protéines et 24g de matières grasses par portion. Cette recette en fait 2. Pour 1,48 $ la portion, cette recette couvre 6 % de vos besoins quotidiens en vitamines et minéraux. Si vous avez du brandy de cerise clair – kirsch, deberad, crème fouettée, et quelques autres ingrédients – vous pouvez le préparer. Seules quelques personnes ont fait cette recette, et une dis-le a fait juste. Il est présenté par Foodista. C’est une recette plutôt peu coûteuse pour les amateurs de cuisine indienne. De la préparation à l’assiette, cette recette prend environ 45 minutes. Tout bien considéré, nous avons décidé que cette recette mérite un score cuillère de 20 %. Cette partition n’est pas très bonne. Les utilisateurs qui ont aimé cette recette ont également apprécié les moules dans la sauce crème au curry, les palourdes et moules dans la sauce au curry thaï, et les palourdes et moules dans la sauce au curry thaï.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 5}, "equipment": [], "ingredients": ["gousses d''ail entières", "eau"], "instruction": "Placez les gousses d’ail dans assez d’eau pour les couvrir et faites bouillir pendant 5 minutes pour blanchir.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["clou de girofle", "ail"], "instruction": "Retirez l’ail et coupez les gousses en deux.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["crème fouettée", "Poudre de curry", "beurre", "ail"], "instruction": "Mélangez de l’ail blanchi avec du beurre à température ambiante et mélangez jusqu’à obtenir une pâte. Mélangez de la crème fouettée et de la poudre de curry.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 5}, "equipment": ["poêle à frire"], "ingredients": ["moules", "Brandy", "beurre", "cerises"], "instruction": "Chauffez une grande poêle et ajoutez du beurre de curry, des moules et du brandy aux cerises. Couvrez et faites cuire pendant 4 à 5 minutes jusqu’à ce que les moules s’ouvrent.", "step_number": 4}, {"duration": null, "equipment": ["cuillère à fente", "bol"], "ingredients": ["moules"], "instruction": "Retirez les moules à l’aide d’une cuillère à fente et transférez-les dans des bols de portions. N’oubliez pas de jeter les moules non ouverts.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["pain croustillant"], "instruction": "Servez avec beaucoup de pain croustillant et profitez-en !", "step_number": 6}]', 'https://img.spoonacular.com/recipes/652754-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.74354', '2026-01-19 18:23:17.74354', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '652754');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('76046429-0391-43af-bf76-b166c0ce3928', 'Soufflé de carotte salé', 'On n’a jamais trop de recettes de hor-d’œuvre, alors essayez le soufflé de carotte salé. Cette recette en fait 6 et coûte 81 cents la portion. Une portion de ce plat contient environ 12 g de protéines, 23 g de matières grasses et un total de 332 calories. Deux personnes ont été impressionnées par cette recette. Rendez-vous au magasin et achetez du beurre, du lait, de la crème épaisse et quelques autres choses pour le préparer aujourd’hui. Peu de gens ont vraiment aimé ce plat méditerranéen. De la préparation à l’assiette, cette recette prend environ 45 minutes. Il est présenté par Foodista. Dans l’ensemble, cette recette obtient un bon score cuillère de 40 %. Des recettes similaires incluent le soufflé aux carottes salées, le soufflé aux pommes de terre salées et le soufflé de bacon salé à la courge musquée pour Thanksgiving.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["pot", "four"], "ingredients": ["parmesan", "crème lourde", "carotte", "beurre", "muscade", "farine de tous usages", "sauce", "eau", "lait", "sel"], "instruction": "Commencez par cuire les carottes dans de l’eau bouillante salée jusqu’à ce qu’elles soient tendres. Une fois tendre, égouttez toute l’eau et mélangez les carottes avec la moitié du lait jusqu’à ce qu’elles soient lisses. Mets de côté. Dans une petite casserole, commencez à cuire le reste du lait, de la crème épaisse, de la farine, du sel, du beurre, du parmesan et de la muscade. Remuez jusqu’à obtenir une consistance épaisse. Mets de côté pour refroidir. Commencez par préchauffer le four à 350 degrés Fahrenheit.", "step_number": 1}, {"duration": null, "equipment": ["fouet", "bol"], "ingredients": ["blancs d''œufs"], "instruction": "Fouettez/battez les blancs d’œufs dans un bol jusqu’à ce qu’ils soient bien concentrés. Mets de côté.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["Purée de carotte", "blancs d''œufs", "sauce", "jaune d''œuf"], "instruction": "Mélangez la purée de carottes et la sauce blanche (béchamel) et ajoutez les jaunes un par un, puis incorporez les blancs d’œufs fermes.", "step_number": 3}, {"duration": null, "equipment": ["Double chaudrie", "Ramequin"], "ingredients": ["eau"], "instruction": "Versez le mélange dans des ramequins pré-graissés et laissez reposer dans un bain-marie (bain-marie).", "step_number": 4}, {"duration": {"unit": "minutes", "number": 60}, "equipment": ["four"], "ingredients": [], "instruction": "Faites cuire pendant 1 heure.", "step_number": 5}]', 'https://img.spoonacular.com/recipes/659459-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.74555', '2026-01-19 18:23:17.74555', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '659459');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('9cff3f78-69c8-4bf4-9c04-0c17d280fb66', 'Trempette française râpée en mijoteuse', 'Le Crock Pot Shredded French Dip est un plat principal méditerranéen. Une portion contient 994 calories, 97 g de protéines et 53 g de matières grasses. Cette recette en fait 4. Pour 6,13 $ la portion, cette recette couvre 41 % de vos besoins quotidiens en vitamines et minéraux. Cette recette de Foodista nécessite de l’oignon, de l’ail, des petits pains et du poivre. Une personne était contente d’avoir essayé cette recette. Ce sera un succès lors de votre événement du Super Bowl. De la préparation à l’assiette, cette recette prend environ 7 heures et 30 minutes. C’est une bonne option si vous suivez un régime sans produits laitiers. Tout bien considéré, nous avons décidé que cette recette mérite un score cuillère de 77 %. Cette partition est bonne. Des recettes similaires incluent la sauce française effilochée à la mijoteuse, la sauce à mijoteuse et la sauce à mijoteuse Marie’s French Dip.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 450, '[{"duration": null, "equipment": ["cuisinière lente"], "ingredients": ["bœuf"], "instruction": "Placez le bœuf dans la mijoteuse.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 420}, "equipment": ["planche à découper", "cuisinière lente"], "ingredients": ["Assaisonnement italien", "Poudre de moutarde", "bouillon de bœuf", "au jus", "ail", "poivre", "bouillon", "oignon", "rouleau", "bœuf"], "instruction": "Ajoutez du bouillon de bœuf, de l’ail, de l’oignon, de l’assaisonnement italien, de la moutarde hachée et du poivre. Allumez le faible pendant 7 heures. À emporter et à placer sur une planche à découper. Avec une fourchette, déchiquetez le bœuf. Filtrez au jus (bouillon à mijoteuse) pour éviter les gros morceaux. Tranche roulée en deux.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["bœuf", "rouleau"], "instruction": "Place du bœuf sur chaque rouleau.", "step_number": 3}, {"duration": null, "equipment": ["bol"], "ingredients": ["au jus"], "instruction": "Placez l’au jus dans 4 petits bols individuels.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["au jus"], "instruction": "Servez sandwiches et au jus ensemble.", "step_number": 5}]', 'https://img.spoonacular.com/recipes/640869-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.747898', '2026-01-19 18:23:17.747898', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '640869');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('ad80d099-d921-4493-b89b-40c4b6002297', 'Quiche aux légumes préparée avec des tomates fraîches, des épinards, du basilic et du fromage de chèvre', 'La recette Quiche aux légumes préparée avec tomates fraîches, épinards, basilic et fromage de chèvre pourrait satisfaire votre envie méditerranéenne en environ 1 heure et 30 minutes. Cette recette contient 8 portions avec 69 calories, 5g de protéines et 4g de matières grasses chacune. Pour 70 cents la portion, cette recette couvre 6 % de vos besoins quotidiens en vitamines et minéraux. Cette recette de Foodista nécessite une pâte à tarte, de la farine, du basilic et de l’oignon vert. Seules quelques personnes ont vraiment aimé cette œuvre de théâtre. Une personne était contente d’avoir essayé cette recette. Tout bien considéré, nous avons décidé que cette recette méritait un score cuillère de 37 %. Cette note est plutôt mauvaise. Des recettes similaires sont la quiche au fromage de chèvre maïs et courgette avec citron et basilic, la quiche aux épinards et fromage de chèvre, et la quiche aux épinards, fromage de chèvre et ciboulette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 90, '[{"duration": {"unit": "minutes", "number": 8}, "equipment": ["feuille d''aluminium", "four"], "ingredients": ["croûte de tarte", "croûte"], "instruction": "Préchauffez le four à 450 degrés F pour la pâte à tarte. Tapisser une assiette à tarte de 20 cm de pâte.  Couvrez le dessous et le dessus de la pâte à tarte avec du papier aluminium et laissez cuire 8 minutes pour laisser la pâte cuire.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 4}, "equipment": ["four", "fouet", "bol", "feuille d''aluminium"], "ingredients": ["chèvre", "tomate", "épinard", "muscade", "poivre", "basilic", "croûte", "farine de tous usages", "oignon", "œuf", "chou", "lait", "sel"], "instruction": "Retirez le papier aluminium et laissez cuire encore 4 minutes. Pendant la cuisson de la pâte, fouetter ensemble le lait, le sel, le poivre, la muscade, la farine et les œufs dans un bol. Ajoutez ensuite les tomates, les épinards ou le chou frisé, l’oignon, le basilic et le fromage de chèvre.", "step_number": 2}, {"duration": null, "equipment": ["feuille d''aluminium", "four"], "ingredients": ["croûte de tarte", "légumes", "fromage", "croûte", "lait"], "instruction": "Retirez de la croûte du four. La croûte doit être brun clair sur les bords. Réduisez la température du four à 325 degrés F. Ajoutez maintenant le mélange de lait, légumes et fromage à la croûte cuite. Couvrez les bords de la pâte à tarte avec du papier aluminium.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 60}, "equipment": ["four"], "ingredients": [], "instruction": "Faites cuire au four jusqu’à ce que le milieu de la quiche soit prêt, environ 50 à 60 minutes.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 10}, "equipment": [], "ingredients": [], "instruction": "Laissez régler 10 minutes.", "step_number": 5}]', 'https://img.spoonacular.com/recipes/664585-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.750539', '2026-01-19 18:23:17.750539', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '664585');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('5404650b-1722-4b89-a44a-f04fb95aed49', 'Calzone à saucisse', 'Le Calzone à la saucisse prend environ 45 minutes du début à la fin. Cette recette en fait 4 et coûte 3,6 $ la portion. Une portion de ce plat contient environ 43 g de protéines, 59 g de matières grasses et un total de 934 calories. Une personne a essayé et aimé cette recette. Ça fonctionne bien comme plat principal. Cette recette de Foodista nécessite de l’origan, de la saucisse en vrac, de la sauce pizza et du pepperoni. Seules quelques personnes ont vraiment aimé ce plat méditerranéen. Globalement, cette recette obtient un solide score cuillère de 48 %. Essayez le Calzone à la saucisse, le Calzone à la saucisse et trois fromages, et le Calzone à la saucisse italienne pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["pepperoni", "saucisse", "viande"], "instruction": "Commencez par cuisiner votre saucisse. Quand votre saucisse est presque cuite, ajoutez le pepperoni et faites cuire encore une ou deux minutes jusqu’à ce que toute la viande soit bien cuite.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["origan", "ail", "basilic", "oignon"], "instruction": "Égoutte la graisse. Ajoutez maintenant l’ail, le basilic, l’origan et l’oignon, puis laissez cuire et chauffer.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 20}, "equipment": ["Pierre à pizza", "four"], "ingredients": ["blancs d''œufs", "croûte", "pâte", "rouleau"], "instruction": "Retirez le mélange du feu électrique. Prends ta boule de pâte, arrache un morceau de bonne taille et roule-le d’environ 1/4 d’épaisseur. Prenez votre garniture et ajoutez quelques cuillerées de bonne taille. Veillez à laisser assez d’espace pour plier et sceller les bords. Pliez la pâte sur votre garniture et scellez les bords. J’ai roulé mes bords dans le dessus pour le sceller. Veillez à découper quelques fentes sur le dessus du calzone pour que la vapeur puisse se libérer pendant la cuisson au four. Et c’est optionnel, mais j’ai aussi badigeonné un peu de blanc d’œuf sur le dessus de ces merveilles pour leur donner une belle couleur dorée au four. Mettez-les dans un four préchauffé à 425 degrés pendant 15 à 20 minutes ou jusqu’à ce que le dessus soit bien doré. J’ai cuisiné le mien sur une pierre à pizza préchauffée pour que le fond ait une croûte bien croustillante.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["Sauce pizza"], "instruction": "Servez avec de la sauce à pizza.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/659358-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.753608', '2026-01-19 18:23:17.753608', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '659358');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('5688bf7c-76b9-4a68-a857-0efb5b6586aa', 'Casserole de pizza au fromage facile', 'On n’a jamais trop de recettes méditerranéennes, alors essayez Easy Cheesy Pizza Casserole. Ce plat principal contient 902 calories, 57 g de protéines et 55 g de matières grasses par portion. Pour 3,95 $ la portion, cette recette couvre 37 % de vos besoins quotidiens en vitamines et minéraux. Cette recette en fait 6. L’automne sera encore plus spécial avec cette recette. 181 personnes ont été impressionnées par cette recette. De la préparation à l’assiette, cette recette prend environ 45 minutes. Cette recette de Foodista nécessite une quantité équivalente d’un mélange de bœuf haché et de saucisses en vrac, de lait, d’origan et de pepperoni. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 83 %, ce qui est spectaculaire. La Casserole de pizza au fromage facile, la casserole à pizza au fromage et la casserole de pizza au fromage 20 minutes sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["poêle à frire"], "ingredients": ["boeuf haché"], "instruction": "Bœuf haché brun dans la poêle ; Drainez les graisses.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["Sauce pizza", "poivre", "pâtes"], "instruction": "Mélangez des pâtes ou de la sauce à pizza et des flocons de poivre ; Mets de côté.", "step_number": 2}, {"duration": null, "equipment": ["bol"], "ingredients": ["Fromage ricotta", "parmesan", "herbes"], "instruction": "Mélangez la ricotta avec les herbes et le parmesan dans un bol séparé ; Mets de côté.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["biscuits"], "instruction": "Mélangez les ingrédients secs pour les biscuits.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["lait"], "instruction": "Ajoutez le lait et remuez jusqu’à ce que ce soit bien combiné.", "step_number": 5}, {"duration": null, "equipment": ["four", "poêle à frire"], "ingredients": ["Fromage ricotta", "biscuits", "boeuf haché", "pâte"], "instruction": "Préchauffez le four à 375 degrés.  Vaporisez un moule de 13 x 9 avec un spray antiadhésif.  Laissez tomber la pâte à biscuits par cuillères à café au fond du moule, en les espaceant uniformément.  Ce n’est pas grave s’il y a de l’espace entre la pâte — elle se dilatera en cuisant.  Ajoutez un mélange de bœuf haché et parsemez le mélange de ricotta.", "step_number": 6}, {"duration": {"unit": "minutes", "number": 20}, "equipment": ["four"], "ingredients": ["biscuits"], "instruction": "Faites cuire à 375 pendant environ 20 minutes ou jusqu’à ce que les biscuits soient gonflés et commencent à dorer.", "step_number": 7}, {"duration": {"unit": "minutes", "number": 10}, "equipment": ["four"], "ingredients": ["Tranches de pepperoni", "mozzarella", "Provolone"], "instruction": "Garnissez de mozzarella et de fromages provolone et répartissez les tranches de pepperoni uniformément par-dessus, augmentez la température du four à 425 degrés.  Retournez au four et cuissez jusqu’à ce que les fromages soient fondus et commencent à bouillonner.  Cela devrait prendre environ 10 minutes.", "step_number": 8}, {"duration": {"unit": "minutes", "number": 5}, "equipment": ["four"], "ingredients": ["parmesan"], "instruction": "Sortez-le du four et laissez reposer 5 minutes avant de trancher et servir.  On peut le garnir du parmesan supplémentaire.", "step_number": 9}]', 'https://img.spoonacular.com/recipes/641893-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.757299', '2026-01-19 18:23:17.757299', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '641893');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('899fc40b-39f9-4c58-bc2f-05b66efecd2a', 'Parfaits individuels de tiramisu', 'Les parfaits individuels au tiramisu sont un dessert méditerranéen. Une portion de ce plat contient environ 11 g de protéines, 36 g de matières grasses et un total de 569 calories. Cette recette en sert 4 et coûte 2,45 $ la portion. De la préparation à l’assiette, cette recette prend environ 45 minutes. Un mélange de vanille, de cacao en poudre, d’extrait de rhum et d’une poignée d’autres ingrédients suffit pour rendre cette recette aussi savoureuse. Cette recette est appréciée par un gourmet et des cuisiniers. Il est présenté par Foodista. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 32 %, ce qui est plutôt mauvais. Essayez Tiramisu individuel, tiramisu individuel et Trifles au tiramisu individuel pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["bol"], "ingredients": ["mascarpone", "crème fouettée", "crème lourde", "Extrait de rhum", "vanille", "sucre"], "instruction": "Dans un petit bol, battez la crème épaisse et l’extrait de rhum jusqu’à ce que des pics tendres se forment. Mets de côté. Dans un bol moyen, battez ensemble le mascarpone, le sucre et la vanille. Incorporez la crème fouettée.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["Ladyfingers", "expresso"], "instruction": "Coupe les ladyfingers en deux et trempe-les dans l’espresso.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["Ladyfingers", "baies", "fromage", "Poudre de cacao"], "instruction": "Placez une couche de ladyfingers au fond de 4 verres. Mettez la moitié du mélange de fromages sur les ladyfingers. Garnissez d’une autre couche de ladyfingers et du reste du mélange de fromage. Dessus avec les doigts restants. Tamisez le cacao sur le dessus et garnissez de baies.", "step_number": 3}]', 'https://img.spoonacular.com/recipes/647895-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.764539', '2026-01-19 18:23:17.764539', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '647895');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('dc396bee-5d7a-4460-a573-662c35cbacc3', 'Taquitos de poulet avec une salsa à l’avocat', 'Vous avez besoin d’un plat principal sans gluten ? Des taquitos au poulet avec une salsa d’avocat pourraient être une super recette à essayer. Pour 3,53 $ la portion, cette recette couvre 37 % de vos besoins quotidiens en vitamines et minéraux. Cette recette contient 4 portions avec 854 calories, 43g de protéines et 51g de matières grasses chacune. Cette recette de Foodista a 1 fan. Si vous avez de l’oignon, du blanc de poulet, des tomates et quelques autres ingrédients à portée de main, vous pouvez en faire. C’est une recette assez chère pour les amateurs de cuisine mexicaine. De la préparation à l’assiette, cette recette prend environ 35 minutes. Tout bien considéré, nous avons décidé que cette recette mérite un score cuillère de 85 %. Cette partition est géniale. Si vous aimez cette recette, vous pourriez aussi apprécier des recettes comme les Taquitos au poulet avec salsa verte, les Taquitos au poulet BBQ à la mijoteuse avec salsa de maïs de rue, et les Taquitos au poulet BBQ à la mijoteuse avec salsa de maïs de rue.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 35, '[{"duration": null, "equipment": [], "ingredients": ["poulet effiloché", "tortilla", "poulet", "eau"], "instruction": "Commencez par faire mijoter le poulet dans juste assez d’eau pour le couvrir. Une fois cuit à fond, laissez refroidir puis râpe. Mettez une cuillère à soupe de poulet râpé sur une tortilla.", "step_number": 1}, {"duration": null, "equipment": ["cure-dents"], "ingredients": ["tortilla", "rouleau"], "instruction": "Roule la tortilla bien serré. Utilisez un cure-dent pour empêcher la tortilla de se dérouler.", "step_number": 2}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["huile de cuisson"], "instruction": "Ajoutez les 2 tasses d’huile de cuisson dans une grande poêle. Préchauffe l’huile à température. Quand l’huile est chaude, ajoutez 4 à 6 taquitos dans la poêle. Ne les encombre pas. Tournez une fois pendant la cuisson. Faites cuire les taquitos jusqu’à ce qu’ils soient croustillants et dorés.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Retirez les taquitos et placez-les sur une assiette recouverte de papier pour évacuer la graisse. Répétez jusqu’à ce que tous les taquitos soient cuits.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["Crema mexicaine", "Queso fresco", "avocat", "salsa"], "instruction": "Placez quatre taquitos cuits dans une assiette. Mets une cuillère à café de crème mexicaine sur chacun. Ensuite, couvrez-les de salsa à l’avocat et saupoudrez de queso fresco râpé.", "step_number": 5}]', 'https://img.spoonacular.com/recipes/1096021-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.76797', '2026-01-19 18:23:17.76797', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '1096021');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('cebd7c89-b82d-4577-a6b7-afede8576c94', 'Tacos au poulet fumé', 'Les Tacos au poulet fumé sont une recette sans gluten en 8 portions. Une portion contient 424 calories, 15 g de protéines et 27 g de matières grasses. Pour 1,87 $ la portion, cette recette couvre 25 % de vos besoins quotidiens en vitamines et minéraux. Trois personnes ont fait cette recette et la referaient. Un mélange de tortillas de maïs, de coriandre, de poudre de piment et d’une poignée d’autres ingrédients suffit pour rendre cette recette aussi délicieuse. C’est une recette à prix raisonnable pour les amateurs de cuisine mexicaine. C’est le meilleur plat principal, et ça dure environ 45 minutes. Il est présenté par Foodista. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 79 %, ce qui est solide. Si vous aimez cette recette, vous pourriez aussi apprécier des recettes comme les Tacos au poulet fumé, les Tacos au poulet Tinga fumé et les Tacos au poulet Chipotle Fumé ~ - Un vrai bazar.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["four"], "ingredients": ["Poulet cuit", "poulet", "épices", "huile d''olive extra vierge", "citron vert"], "instruction": "Pour les tacos au poulet : préchauffez le four à 400 degrés. Enrobez le poulet de poulet délicieux et d’épices de chaque côté (sauf le citron vert pour le poulet cuit).", "step_number": 1}, {"duration": {"unit": "minutes", "number": 25}, "equipment": ["four"], "ingredients": [], "instruction": "Faites cuire à 400 degrés pendant 20 à 25 minutes ou jusqu’à ce que les jus soient bien cuits et que les jus soient clairs.", "step_number": 2}]', 'https://img.spoonacular.com/recipes/660406-556x370.', 'PUBLISHED', '2026-01-19 18:23:17.772658', '2026-01-19 18:23:17.772658', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '660406');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('7516a4dd-2b91-493b-8cb9-c4d65fc908db', 'Poulet épicé avec salsa aux haricots noirs et mangue', 'On n’a jamais trop de recettes mexicaines, alors essayez le Poulet Épicé avec Haricots Noirs et Mangue Salsan. Cette recette contient 4 portions avec 689 calories, 56g de protéines et 32g de matières grasses chacune. Pour 6,24 $ la portion, cette recette couvre 42 % de vos besoins quotidiens en vitamines et minéraux. Ça fonctionne bien comme plat principal coûteux. Cette recette est appréciée par un gourmet et des cuisiniers. C’est une bonne option si vous suivez un régime sans gluten ni produits laitiers. Un mélange d’oignon, de cumin moulu, de sel casher et d’une poignée d’autres ingrédients suffit pour rendre cette recette aussi savoureuse. Il est présenté par Foodista. De la préparation à l’assiette, cette recette prend environ 45 minutes. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 76 %, ce qui est solide. Des recettes similaires incluent la tilapia épicée avec salsa de haricots noirs et de mangue, QUICK AND EASY ET SUPER SKINNY : SAUMON ÉPICÉ DU SUD-OUEST AVEC SALSA DE HARICOTS NOIRS, CONCOMBRE ET MANGUE, et poulet grillé avec salsa de haricots noirs et mangue Skinnytaste.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Préchauffez le four à 375 degrés.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["poulet", "épices"], "instruction": "Dans une petite assiette, mélangez les épices séchées jusqu’à ce qu’elles soient bien mélangées et pressez les deux côtés du poulet dans les épices pour les enrober. Mets de côté.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 2}, "equipment": ["poêle à frire", "Poêle à grill", "cuisinière", "four"], "ingredients": ["huile d''olive", "poulet"], "instruction": "Versez un peu d’huile d’olive dans une poêle grillée ou une poêle à feu moyen-vif. Une fois chaud, saisir les deux côtés du poulet, environ 1 à 2 minutes de chaque côté. Glissez immédiatement la poêle dans le four.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 15}, "equipment": ["four"], "ingredients": [], "instruction": "Faites cuire pendant 10 à 15 minutes ou jusqu’à ce que les jus soient clairs.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["huile d''olive", "poulet", "salsa", "sel"], "instruction": "Pendant la cuisson du poulet, mélangez soigneusement les ingrédients pour la salsa, en ajoutant plus d’huile d’olive au goût. Salez à votre goût avant de servir avec le poulet.", "step_number": 5}]', 'https://img.spoonacular.com/recipes/660943-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.77838', '2026-01-19 18:23:17.77838', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '660943');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('9ddae9b7-65a3-48a3-a4c8-c017583451af', 'Chapeaux de champignons farcis en alouette®', 'On n’a jamais trop de recettes de hor d’œuvre, alors essayez les Chapeaux de champignons farcis Alouette®. Tu fais attention à ta silhouette ? Cette recette lacto-ovo-végétarienne et végane sans produits laitiers, contient 30 calories, 2g de protéines et 0g de matières grasses par portion. Cette recette en fait 8. Pour 1,5 $ la portion, cette recette couvre 11 % de vos besoins quotidiens en vitamines et minéraux. De la préparation à l’assiette, cette recette prend environ 45 minutes. Quelques personnes ont fait cette recette, et 11 diraient que dis-le parfait. Rendez-vous au magasin et achetez des chapelures assaisonnées, des champignons de champignon, des épinards alouettes et tartinées d’artichauts, ainsi que quelques autres choses pour le préparer aujourd’hui. Il est présenté par Foodista. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 96 %, ce qui est excellent. Essayez les chapeaux de champignons farcis, les chapeaux de champignons farcis et les chapeaux de champignons blancs farcis pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Préchauffez le four à 375 °F.", "step_number": 1}, {"duration": null, "equipment": ["plaque de cuisson"], "ingredients": ["champignons", "ail", "herbes"], "instruction": "Placez les chapeaux de champignon creux vers le haut sur une plaque à cuisson. Remplissez chaque bouchon de 1 cuillère à café d’ail et d’herbes alouette", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["miettes de pain assaisonnées", "Fromage tartinable"], "instruction": "Fromage tartinable et saupoudré de chapelure assaisonnée.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 15}, "equipment": ["four"], "ingredients": [], "instruction": "Faites cuire 12 à 15 minutes.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Garnissez et servez.", "step_number": 5}]', 'https://img.spoonacular.com/recipes/632252-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.78471', '2026-01-19 18:23:17.78471', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '632252');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('ec3f1c35-6a45-4700-b8e2-6af1ce8a651b', 'Roulade d’agneau et fromage de chèvre frais', 'La recette Roulade d’agneau et fromage de chèvre frais est prête en environ 45 minutes et constitue sans aucun doute une excellente option sans gluten pour les amateurs de cuisine européenne. Cette recette contient 6 portions avec 373 calories, 17g de protéines et 33g de matières grasses chacune. Pour 1,97 $ la portion, cette recette couvre 17 % de vos besoins quotidiens en vitamines et minéraux. Rendez-vous au magasin et achetez de l’huile de cuisson, du sel et du poivre pour assaisonner, de l’ail, et quelques autres choses pour le préparer aujourd’hui. 74 personnes étaient ravies d’avoir essayé cette recette. Il est présenté par Foodista. Ça fonctionne bien comme plat principal économique. Dans l’ensemble, cette recette obtient un bon score cuillère de 65 %. Si vous aimez cette recette, jetez un œil à ces recettes similaires : roulade de poulet farci au fromage de chèvre et herbes, roulade au poulet/patate douce avec sauce au fromage de chèvre, et burgers d’agneau au fromage de chèvre et tzatziki.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["poêle à frire"], "ingredients": ["huile d''olive"], "instruction": "Chauffez 2 cuillères à soupe d’huile d’olive dans une poêle à feu moyen-élevé.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["épinard", "ail"], "instruction": "Ajoutez l’ail et le sauteau pendant 10 secondes, puis ajoutez les épinards et faites le sauteau uniquement jusqu’à ce que les épinards fanent.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Mets de côté pour refroidir.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["Filet d’agneau"], "instruction": "Étalez le filet d’agneau et le papillon pour créer un morceau plat d’environ 15 cm de large.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["sel et poivre"], "instruction": "Assaisonnez le filet avec du sel et du poivre.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["Filet d’agneau", "épinard", "étendue", "eau"], "instruction": "Pressez l’excès d’eau des épinards et étalez-les uniformément sur le filet d’agneau.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": ["chèvre"], "instruction": "Coupez le fromage de chèvre en deux dans le sens de la longueur puis à nouveau en deux pour obtenir 4 quarts dans le sens de la longueur.", "step_number": 7}, {"duration": null, "equipment": [], "ingredients": ["Filet d’agneau"], "instruction": "Placez 2 quarts d’un bout à l’autre sur chaque filet d’agneau préparé.", "step_number": 8}, {"duration": null, "equipment": [], "ingredients": ["rouleau"], "instruction": "Roulez et attachez chaque reint préparé.", "step_number": 9}, {"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Préchauffe le four à 375°F.", "step_number": 10}, {"duration": {"unit": "minutes", "number": 4}, "equipment": ["poêle à frire"], "ingredients": ["huile de cuisson"], "instruction": "Dans une grande poêle à saut, chauffez l’huile de cuisson à feu moyen-vif et saisissez chaque reint pendant 3 à 4 minutes de tous côtés.", "step_number": 11}, {"duration": {"unit": "minutes", "number": 12}, "equipment": ["four"], "ingredients": ["agneau"], "instruction": "Faites rôtir les filets d’agneau au four pendant 10 à 12 minutes jusqu’à atteindre une température interne de 120°F.", "step_number": 12}, {"duration": {"unit": "minutes", "number": 10}, "equipment": ["four"], "ingredients": [], "instruction": "Sortez-le du four et laissez reposer 10 minutes.", "step_number": 13}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Retirez la ficelle et coupez en médaillons.", "step_number": 14}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Divisez en 2 assiettes et servez.", "step_number": 15}]', 'https://img.spoonacular.com/recipes/649183-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.786263', '2026-01-19 18:23:17.786263', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '649183');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('742d5e46-03d7-427d-ad32-521c46ade760', 'Salade d’accompagnement quinoa, tomate, oignon vert', 'Quinoa, tomate et oignon vert avec une salade d’accompagnement pourrait être une bonne recette pour enrichir votre boîte de recettes hor d’œuvre. Pour 1,39 $ la portion, cette recette couvre 23 % de vos besoins quotidiens en vitamines et minéraux. Une portion de ce plat contient environ 11 g de protéines, 18 g de matières grasses et un total de 396 calories. Cette recette en fait 2. Cette recette de Foodista a deux fans. Rendez-vous au magasin et achetez des oignons verts, de l’eau, du sel et du poivre, ainsi que quelques autres choses pour le préparer aujourd’hui. C’est une bonne option si vous suivez un régime sans gluten, sans produits laitiers, lacto-ovo-végétarien et végétalien. De la préparation à l’assiette, cette recette prend environ 45 minutes. Tout bien considéré, nous avons décidé que cette recette méritait un score cuillère de 93 %. Cette partition est incroyable. Les utilisateurs qui ont aimé cette recette ont également apprécié la salade concombre, tomate et oignon vert, les gâteaux couscous fetan et oignon vert sur la salade tomate-olive, et le gotsu tomate ou le kosthu Thakkali à l’oignon et tomate | Accompagnement pour l’idli dosa.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["poêle à frire"], "ingredients": ["quinoa", "eau"], "instruction": "Mettez votre quinoa et votre eau dans une casserole.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 15}, "equipment": ["bol"], "ingredients": ["oignons verts", "tomate", "quinoa", "jus", "citron", "graines", "eau"], "instruction": "Chauffez à feu moyen jusqu’à ce que ça bouille, puis couvrez et réduisez le feu à basse température. Faites cuire environ 15 minutes ou jusqu’à ce que toute l’eau soit absorbée. Pendant que votre quinoa cuit, sortez laver vos oignons verts et vos tomates. Coupez-les brutalement. Hachez un citron en deux et pressez un jus dans un bol, en retirant les graines.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["quinoa"], "instruction": "Laissez votre quinoa refroidir. Un peu de chaleur, ça me va.", "step_number": 3}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": ["oignons verts", "jus de citron", "huile d''olive", "tomate"], "instruction": "Ajoutez de l’huile d’olive, du jus de citron, ainsi que des tomates et des oignons verts dans la poêle. Remuez.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["sel et poivre"], "instruction": "Ajoutez du sel et du poivre à votre goût.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servir frais", "step_number": 6}]', 'https://img.spoonacular.com/recipes/657698-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.788685', '2026-01-19 18:23:17.788685', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": true}', 'spoonacular', '657698');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('180784cb-f4ad-4daa-b67a-b51eb41df9ce', 'Dip de légumes', 'La sauce aux légumes pourrait être exactement le petit atout que vous cherchez. Cette recette en fait 3. Tu fais attention à ta silhouette ? Cette recette végétarienne sans gluten, lacto ovo et primitive, contient 210 calories, 16 g de protéines et 4 g de matières grasses par portion. Pour 1,84 $ la portion, cette recette couvre 29 % de vos besoins quotidiens en vitamines et minéraux. Seules quelques personnes ont fait cette recette, et une dis-le a fait juste. Il est présenté par Foodista. De la préparation à l’assiette, cette recette prend environ 45 minutes. Ce sera un succès lors de votre événement du Super Bowl. Si vous avez des légumes, de l’oignon, du yaourt allégé et quelques autres ingrédients sous la main, vous pouvez le préparer. Dans l’ensemble, cette recette obtient un score spectaculaire de 96 % en cuillères. La sauce aux légumes, la sauce italienne aux légumes et la sauce aux légumes rôtis sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["bol"], "ingredients": ["légumes"], "instruction": "Dans un bol moyen, mélangez tous les ingrédients (sauf les légumes crus pour tremper). Couvrir et réfrigérer jusqu’à ce qu’il soit prêt à servir.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["légumes", "trempette"], "instruction": "Serrez-vous comme trempette pour les légumes crus. Ça fait environ 3 tasses.", "step_number": 2}]', 'https://img.spoonacular.com/recipes/664547-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.789997', '2026-01-19 18:23:17.789997', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": true}', 'spoonacular', '664547');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('720d6d0d-b874-4ec9-a467-87060d684563', 'Idlis de rava bio avec Sambar et Chutney', 'Si vous souhaitez ajouter plus de recettes du Sud à votre collection, Organic Ravan Idlis With Sambar & Chutney pourrait être une recette à essayer. Cette recette sans gluten, sans produits laitiers, lacto-ovo végétarienne et complète 30 en 30 servent 4 et coûtent 5 cents la portion. Cet accompagnement contient 11 calories, 0 g de protéines et 1 g de matières grasses par portion. Une personne a été impressionnée par cette recette. Il est présenté par Foodista. De la préparation à l’assiette, cette recette prend environ 45 minutes. Un mélange d’huile de cuisson, de noix de cajou grillées : quelques-unes, de purée d’épinards et d’une poignée d’autres ingrédients suffisent pour rendre cette recette aussi délicieuse. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 20 %, ce qui n’est pas si impressionnant. Des recettes similaires sont Sambar – Comment préparer un Sambar aux légumes | Sambar rapide, Sambar – Comment faire un Sambar aux légumes | Quick Sambar, et Kala Vatana Sambar : un sambar aux pois noirs Malvani.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["bol"], "ingredients": ["semoule", "yaourt", "sel"], "instruction": "Ajoutez des quantités mesurées de semoule (sooji), de sel et de yogurt/yoourt fouetté dans un bol.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 7}, "equipment": ["micro-ondes", "spatule", "bol"], "ingredients": ["Noix de cajou rôties", "Graines de moutarde", "Purée de tomates", "piment rouge", "noix de coco", "épinard", "tomate", "eau", "sel", "huile de cuisson"], "instruction": "Mélangez ces ingrédients délicatement pendant 1 minute avec une cuillère jusqu’à obtenir une pâte lisse et consistante. Divisez cette pâte en trois bols séparés. Préparation des idli : Nous allons maintenant ajouter différents ingrédients dans chaque bol pour obtenir trois couleurs et saveurs différentes idli.To préparer des idli verts frais, ajouter de la purée d’épinards et du sel d’éno dans le premier bol, mélanger délicatement. Pour les idlis rouges, ajoutez du poivron rouge, de la purée de tomates et de l’éno dans le deuxième bol, puis remuez rapidement. Pour les idlis blancs, ajoutez des noix de cajou rôties et de l’éno dans le troisième bol, mélangez encore une fois. Préparez les moules à idli en les badigeonnant légèrement avec de l’huile et versez une demi-tasse d’eau au fond du support pour idli. Utilisez une cuillère à soupe pour verser les pâtes séparées dans les moules à idli. Comme vous pouvez le voir sur la photo, j’ai ajouté une graine de moutarde sur chaque idli. Une fois la pâte terminée, couvrez la machine à idli avec le couvercle et mettez-la au micro-ondes. Pour les moules de taille normale, faites cuire au micro-ondes environ 4 minutes, et pour les mini-idlis faites cuire ~2 minutes. Une fois terminé, attendez quelques minutes, retirez le couvercle et retirez les Idli à l’aide d’une cuillère ou d’une spatule pour idli. Les idli brûlants sont prêts à être dégustés avec tomate maison, chutneys de noix de coco et sambhar... !!", "step_number": 2}]', 'https://img.spoonacular.com/recipes/654059-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.79132', '2026-01-19 18:23:17.79132', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '654059');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('3bb31dfb-8272-4064-87bf-181cca691dbf', 'California Tri-Tip, Santa Maria Style', 'California Tri-Tip, style Santa Maria, prend environ 45 minutes du début à la fin. Pour 2,1 $ la portion, cette recette couvre 15 % de vos besoins quotidiens en vitamines et minéraux. Ce plat principal contient 367 calories, 25 g de protéines et 21 g de matières grasses par portion. Cette recette en fait 8. Cette recette de Foodista nécessite du sel à l’ail, des copeaux de bois, de l’huile d’olive et du sel. Cette recette est appréciée par un gourmet et des cuisiniers. C’est une bonne option si vous suivez un régime sans gluten, sans produits laitiers et sans 30 ans. Avec un score cuillère de 43 %, ce plat est solide. Des recettes similaires incluent Santa Maria Style Tri Tip, Santa Maria Style Tri-Tip et Santa Maria Style Tri-Tip.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["serviettes en papier"], "ingredients": [], "instruction": "Sécher le rôti avec des essuie-tout. Avec une fourchette, piquez le rôti environ 20 fois de chaque côté.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 1500}, "equipment": ["enveloppe plastique"], "ingredients": ["ail", "sel", "enveloppe", "huile de cuisson", "broyage sec"], "instruction": "Mélangez l’ail, l’huile et le sel et frottez sur le rôti. Couvrez de film plastique et réfrigérez pendant 1 heure ou jusqu’à 24 heures.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 15}, "equipment": ["bol"], "ingredients": ["frites", "eau"], "instruction": "Faites tremper les copeaux de bois dans un bol d’eau pour les couvrir pendant 15 minutes.", "step_number": 3}, {"duration": null, "equipment": ["grille"], "ingredients": [], "instruction": "Ouvrez les bouches d’aération du bas sur le barbecue.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Un démarreur de grande cheminée allumé rempli de briquettes de charbon de bois (environ 100 braises) et brûle jusqu’à ce que le charbon soit recouvert de cendres fines grises.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 5}, "equipment": ["grille"], "ingredients": [], "instruction": "Verser des braises chaudes en couche uniforme sur la moitié du grill. Placez la grille de cuisson en place, couvrez, ouvrez complètement les bouchons d’aération du couvercle, et laissez chauffer le gril pendant 5 minutes. Gratter la grille de cuisson propre.", "step_number": 6}, {"duration": null, "equipment": ["serviettes en papier"], "ingredients": ["pâte d''ail"], "instruction": "Avec des essuie-tout, essuyez la pâte d’ail sur le rôti.", "step_number": 7}, {"duration": null, "equipment": [], "ingredients": ["sel d’ail", "poivre", "viande", "broyage sec"], "instruction": "Frottez du poivre et du sel à l’ail sur la viande.", "step_number": 8}, {"duration": {"unit": "minutes", "number": 5}, "equipment": ["grille"], "ingredients": [], "instruction": "Grillez directement sur des braises jusqu’à ce qu’elles soient bien dorées, environ 5 minutes de chaque côté.", "step_number": 9}, {"duration": null, "equipment": ["grille"], "ingredients": ["frites"], "instruction": "Retirez soigneusement le rôti et la grille de cuisson du gril et dispersez les copeaux de bois sur les braises.", "step_number": 10}, {"duration": null, "equipment": ["grille"], "ingredients": ["refroidisseur"], "instruction": "Remplacez la grille de cuisson et disposez le rôti sur le côté plus frais du grill.", "step_number": 11}, {"duration": {"unit": "minutes", "number": 20}, "equipment": [], "ingredients": ["viande"], "instruction": "Couvrez, positionnez les bouches d’aération du couvercle directement au-dessus de la viande, et faites cuire jusqu’à ce que le rôti atteigne environ 130 degrés (pour saignant à point), environ 20 minutes.", "step_number": 12}, {"duration": {"unit": "minutes", "number": 20}, "equipment": ["planche à découper", "feuille d''aluminium"], "ingredients": ["grains", "viande"], "instruction": "Transférez la viande sur une planche à découper, tendez légèrement avec du papier aluminium, puis laissez reposer 20 minutes. Tranchez finement dans le sens du fil.", "step_number": 13}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servez.", "step_number": 14}]', 'https://img.spoonacular.com/recipes/636799-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.797618', '2026-01-19 18:23:17.797618', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '636799');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('70311b95-103f-4c2a-8225-5a6c39310c40', 'Soupe toscane de haricots blancs avec huile d’olive et romarin', 'La soupe toscane de haricots blancs avec huile d’olive et romarin est une recette végétarienne sans gluten, sans produits laitiers, lacto ovo et végane, avec 6 portions. Ce plat principal contient 242 calories, 16 g de protéines et 1 g de matières grasses par portion. Pour 50 cents la portion, cette recette couvre 19 % de vos besoins quotidiens en vitamines et minéraux. Ce sera un carton lors de votre événement d’automne. 22 personnes ont trouvé cette recette savoureuse et satisfaisante. Rendez-vous au magasin et achetez de l’huile d’olive, du romarin, de l’ail et quelques autres choses pour le préparer aujourd’hui. Il est présenté par Foodista. De la préparation à l’assiette, cette recette prend environ 45 minutes. Avec un score cuillère de 79 %, ce plat est bon. Si vous aimez cette recette, jetez un œil à ces recettes similaires : Soupe aux haricots blancs avec filet de pâte et huile de romarin, Ragoût toscane de haricots blancs et fenouil à l’orange et au romarin, et Soupe aux haricots blancs toscans.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 480}, "equipment": ["cuisinière lente"], "ingredients": ["Feuilles de laurier", "ail", "haricots", "oignon", "eau"], "instruction": "Rincez bien les haricots et placez-les dans une mijoteuse de 7 litres avec l’eau, l’oignon, l’ail et la feuille de laurier. Couvrez et faites cuire à FAIBLE température pendant environ 8 heures, ou jusqu’à ce que les haricots soient bien tendres.", "step_number": 1}, {"duration": null, "equipment": ["mélangeur d''immersion"], "ingredients": ["Feuilles de laurier"], "instruction": "Enlève la feuille de laurier. À l’aide d’un mixeur plongeant à main, réduisez en purée les ingrédients restants jusqu’à la texture souhaitée.", "step_number": 2}, {"duration": null, "equipment": ["bol", "louche"], "ingredients": ["sel", "potage"], "instruction": "Ajoutez le sel à votre goût. Versez la soupe dans des bols.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["huile d''olive", "romarin"], "instruction": "Arrosez de l’huile d’olive, saupoudrez de romarin, puis servez.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/664147-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.800113', '2026-01-19 18:23:17.800113', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": true}', 'spoonacular', '664147');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('bd35e457-4ef8-4ff8-818c-0fd598d59dde', 'Natpapiers', 'Vous avez besoin d’un accompagnement végétarien lacto ovo ? Les Turnip Tots pourraient être une recette géniale à essayer. Pour 1,15 $ la portion, cette recette couvre 15 % de vos besoins quotidiens en vitamines et minéraux. Cette recette contient 1 portion contenant 275 calories, 6g de protéines et 13g de matières grasses chacune. Une personne était contente d’avoir essayé cette recette. Rendez-vous au magasin et achetez du sel et du poivre, du zeste de citron, des chapelure panko et quelques autres choses pour le préparer aujourd’hui. Il est présenté par Foodista. De la préparation à l’assiette, cette recette prend environ 45 minutes. Tout bien considéré, nous avons décidé que cette recette mérite un score cuillère de 44 %. Cette partition est solide. Essayez les feuilles de navet, le gratin de navet et le gratin de navet pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 10}, "equipment": ["casserole"], "ingredients": ["navet", "eau"], "instruction": "Dans une grande casserole d’eau bouillante, faites cuire les navets 10 minutes puis égouttez. Quand les navets sont assez froids pour être manipulés, coupez-les en quartiers.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 10}, "equipment": ["poêle à frire"], "ingredients": ["navet", "beurre"], "instruction": "Dans une grande poêle, cuire les navets dans du beurre à feu modéré, en remuant de temps en temps, jusqu’à ce qu’ils soient presque tendres et dorés sur les bords, environ 10 minutes.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 5}, "equipment": [], "ingredients": ["Panko", "sel et poivre", "navet", "menthe"], "instruction": "Incorporez la chapelure Panko, la menthe, le zeste, le sel et le poivre selon votre goût.  Faites cuire, en remuant de temps en temps, jusqu’à ce que les navets soient tendres, environ 5 minutes.  Assiette et profite !", "step_number": 3}]', 'https://img.spoonacular.com/recipes/664118-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.802247', '2026-01-19 18:23:17.802247', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '664118');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('fbc959d9-f1e9-487c-b94c-6f232e1a00e8', 'Salsa aux fruits rouges, blancs et bleus', 'Vous cherchez un plat d’œuvre sans gluten, sans produits laitiers, lacto ovo végétarien et compatible avec les FODMAP ? La salsa aux fruits rouges, blancs et bleus pourrait être une super recette à essayer. Cette recette en sert 12. Pour 75 cents la portion, cette recette couvre 4 % de vos besoins quotidiens en vitamines et minéraux. Une portion de ce plat contient environ 1 g de protéines, 3 g de matières grasses et un total de 84 calories. Cette recette de Foodista nécessite des myrtilles, des fraises, de la noix de coco et des chips Freedom. 5 personnes ont fait cette recette et la referaient. Peu de gens aimaient vraiment ce plat mexicain. De la préparation à l’assiette, cette recette prend environ 45 minutes. Dans l’ensemble, cette recette obtient un score cuillère assez mauvais de 21 %. Des recettes similaires incluent Watermelon Fruit Flag – Fruits rouges, blancs et bleus, salade de fruits rouges, blancs et bleus, ainsi que la pizza aux fruits rouges, blancs et bleus.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["bol"], "ingredients": ["baies", "noix de coco"], "instruction": "Mélangez les baies et la noix de coco dans un bol moyen.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["Confiture de fraises", "jus de chaux"], "instruction": "Ajoutez du jus de citron vert et de la confiture de fraises.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Couvrez et réfrigérez au moins une heure avant de servir.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["frites"], "instruction": "Servez en entrée avec des Freedom Chips.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/658129-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.804287', '2026-01-19 18:23:17.804287', '{"vegan": true, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '658129');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('45e3c691-008d-4f7b-be16-db90d4c14582', 'Ragoût de haricots blancs, chou frisé et tomate', 'On n’a jamais trop de recettes principales, alors essayez le ragoût de haricots blancs, de chou frisé et de tomate. Cette recette sans gluten sert 3 personnes et coûte 4,45 $ la portion. Une portion contient 2339 calories, 23 g de protéines et 235 g de matières grasses. Cette recette de Foodista contient du chou frisé, des gousses d’ail, des haricots et du bouillon de légumes. Cette recette est appréciée par un gourmet et des cuisiniers. De la préparation à l’assiette, cette recette prend environ 45 minutes. L’automne sera encore plus spécial avec cette recette. Tout bien considéré, nous avons décidé que cette recette méritait un score cuillère de 93 %. Cette partition est excellente. Essayez le ragoût de chou frisé et haricots blancs, le ragoût de haricots blancs et de haricots frisés, et le ragoût de chou frisé, courge et haricots blancs pour des recettes similaires.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 8}, "equipment": ["pot"], "ingredients": ["eau", "chou"], "instruction": "Remplissez une grande marmite à moitié avec de l’eau. Faites bouillir puis ajoutez les feuilles de chou kale. Réduisez le feu à mijoté et faites cuire pendant 6 à 8 minutes ou jusqu’à ce que les feuilles soient tendres (pas molles).", "step_number": 1}, {"duration": null, "equipment": ["colander"], "ingredients": [], "instruction": "Égouttez les feuilles dans une passoire.", "step_number": 2}, {"duration": null, "equipment": ["pot"], "ingredients": ["eau"], "instruction": "Essuyez l’excès d’eau du pot.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Remettez le feu sur le feu et mettez le feu moyen.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 1}, "equipment": [], "ingredients": ["piment rouge", "huile d''olive", "ail"], "instruction": "Ajoutez de l’huile d’olive, de l’ail et du poivron rouge, puis faites sauter pendant 1 minute en remuant de temps en temps.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["tomate"], "instruction": "Ajoutez les tomates et portez à ébullition.", "step_number": 6}, {"duration": {"unit": "minutes", "number": 3}, "equipment": [], "ingredients": ["haricots", "bouillon"], "instruction": "Ajoutez les haricots et le bouillon, puis remettez à ébullition. Faites cuire pendant 3 minutes, en remuant souvent.", "step_number": 7}, {"duration": {"unit": "minutes", "number": 5}, "equipment": [], "ingredients": ["sel et poivre", "chou"], "instruction": "Réduisez le feu à mijoté et ajoutez le chou kale. Faites cuire pendant 5 minutes. Assaisonnez avec du sel et du poivre selon votre goût.", "step_number": 8}, {"duration": null, "equipment": [], "ingredients": ["parmesan"], "instruction": "Garnir de Parmesan.", "step_number": 9}]', 'https://img.spoonacular.com/recipes/665150-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.806395', '2026-01-19 18:23:17.806395', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '665150');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('8a9a9efa-5d75-4c33-aec7-6c8abd5c542d', 'Panini aux fraises et pépites de chocolat', 'Le panini fraise et pépites de chocolat nécessite environ 45 minutes du début à la fin. Tu fais attention à ta silhouette ? Cette recette sans produits laitiers contient 523 calories, 15 g de protéines et 18 g de matières grasses par portion. Pour 2,74 $ la portion, vous obtenez un plat principal qui sert 1. Cette recette de Foodista nécessite des fraises, des pépites de chocolat - une poignée, du pain au levain, ainsi que de l’huile d’olive et du pinceau. Trois personnes ont été impressionnées par cette recette. On peut en profiter à tout moment, mais c’est particulièrement bon pour la fête des mères. Dans l’ensemble, cette recette obtient un solide score cuillère de 66 %. Des recettes similaires incluent les sandwichs au biscuit chocolat-pépites de chocolat et au gelato à la fraise, les cookies aux pépites de chocolat trempés de chocolat, et les scones aux pépites de chocolat et fraise.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["pain à la pâte"], "instruction": "Ouvre les tranches de pain au levain", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["huile d''olive"], "instruction": "Brossez-le de chaque côté avec un peu d’huile d’olive", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["croustilles de chocolat", "fraises"], "instruction": "Ajoutez une couche de fraises et de pépites de chocolat", "step_number": 3}, {"duration": null, "equipment": ["Presse Panini"], "ingredients": [], "instruction": "Mets-le dans la presse à panini !", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["baies"], "instruction": "Servez-le chaud avec un accompagnement de baies fraîches coupées !", "step_number": 5}]', 'https://img.spoonacular.com/recipes/661741-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.808459', '2026-01-19 18:23:17.808459', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '661741');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('1bd29bec-0c9d-46ce-b721-39c1add082ad', 'Pas de relish à la canneberge et à l’orange Cook', 'La relish No Cook Cranberry Orange pourrait être une bonne recette pour enrichir votre boîte de plats d’accompagnement. Cette recette contient 10 portions avec 136 calories, 1 g de protéines et 4 g de matières grasses chacune. Pour 45 cents la portion, cette recette couvre 3 % de vos besoins quotidiens en vitamines et minéraux. Deux personnes ont fait cette recette et la referaient. Un mélange de canneberges en emballage, d’orange, de pacanes et de quelques autres ingrédients suffit pour rendre cette recette aussi délicieuse. C’est une bonne option si vous suivez un régime sans gluten, sans produits laitiers, lacto-ovo-végétarien et compatible avec les FODMAP. Il est présenté par Foodista. De la préparation à l’assiette, cette recette prend environ 45 minutes. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 28 %, ce qui n’est pas si super. Des recettes similaires incluent la relish canneberge-orange, la relish canneberge-orange et la relish canneberge-orange.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["canneberges"], "instruction": "Fouillez les canneberges et enlevez les mauvaises défectueuses.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["orange", "graines"], "instruction": "Coupez l’orange en huit et retirez les graines.", "step_number": 2}, {"duration": null, "equipment": ["processeur alimentaire"], "ingredients": ["canneberges", "orange"], "instruction": "Placez la moitié des canneberges et l’autre moitié de l’orange dans un robot culinaire, équipé de la lame en acier, puis poussez jusqu’à ce que le mélange soit haché uniformément, sans être mixé.", "step_number": 3}, {"duration": null, "equipment": ["bol"], "ingredients": ["canneberges", "orange"], "instruction": "Transférez dans un bol moyen. Répétez avec les canneberges restantes et l’orange.", "step_number": 4}, {"duration": null, "equipment": ["bol"], "ingredients": ["sucre"], "instruction": "Mélangez tous les ingrédients dans le bol et incorporez le sucre.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Couvrez et réfrigérez pendant au moins 2 jours ou jusqu’à 2 semaines.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servez frais ou à température ambiante.", "step_number": 7}]', 'https://img.spoonacular.com/recipes/653149-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.810291', '2026-01-19 18:23:17.810291', '{"vegan": true, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '653149');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('9c4b483e-6463-40c2-a4af-376ca440253d', 'Fondez votre cœur', 'Si vous avez environ 45 minutes à passer en cuisine, Melt Your Heart pourrait être une excellente recette sans gluten, lacto-ovo végétarienne et primitive à essayer. Une portion de ce plat contient environ 4g de protéines, 4g de matières grasses et un total de 104 calories. Cette recette en fait 2. Pour 1,29 $ la portion, cette recette couvre 8 % de vos besoins quotidiens en vitamines et minéraux. Cette recette de Foodista a 1 fan. Seules quelques personnes ont vraiment aimé cette œuvre de théâtre. Rendez-vous au magasin et achetez du yaourt nature/aromatisé, des myrtilles, des fraises et quelques autres choses pour le préparer aujourd’hui. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 56 %, ce qui est solide. Des recettes similaires incluent Melt Your Heart Tuna Melt, Melt Your Heart Tuna Melt, et Heart to Heart : Lemon Coeur à la Crème avec compote d’orange sanguine.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["yaourt", "glace"], "instruction": "Remuez le yaourt et versez-le dans le petit bac à glaçons en forme de cœur.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 120}, "equipment": [], "ingredients": [], "instruction": "Congèle pendant au moins 2 heures ou plus jusqu’à ce que ça durcit. (Vous pouvez préparer cela un jour à l’avance).", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["fraises", "myrtilles", "fruits", "yaourt"], "instruction": "Rincez et coupez les fraises en deux, servez-les avec des myrtilles ou tout fruit de votre choix, accompagnés de quelques cubes de yaourt dans un verre court.", "step_number": 3}]', 'https://img.spoonacular.com/recipes/665823-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.811542', '2026-01-19 18:23:17.811542', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '665823');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('583622d7-3c5e-4c67-8a6a-5774df099d03', 'Fraises patriotiques', 'On n’a jamais trop de recettes de hor d’œuvre, alors essayez Patriotic Strawberries. Tu fais attention à ta silhouette ? Cette recette sans gluten ni produits laitiers contient 88 calories, 1 g de protéines et 5 g de matières grasses par portion. Cette recette en fait 24 et coûte 26 cents la portion. Un mélange de pépites de chocolat, de fraises, de sucre coloré et de quelques autres ingrédients suffit pour rendre cette recette aussi délicieuse. Cette recette de Foodista a 1 fan. De la préparation à l’assiette, cette recette prend environ 45 minutes. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 9 %, ce qui est très mauvais (mais toujours réparable). Les utilisateurs qui ont aimé cette recette ont également apprécié Patriotic Trifle, Patriotic Parfaits et Patriotic Cupcakes.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["Chocolat blanc", "raccourcissement", "chocolat", "vermicelles", "baies", "sucre", "trempette"], "instruction": "Faites fondre le chocolat blanc selon les instructions de l’emballage. Vous devrez peut-être ajouter environ 1 cuillère à café de graisse de graisse par chaque tasse de chocolat blanc. Une fois complètement fondues, trempez les baies dans du chocolat, environ à la moitié de la hauteur. Ensuite, trempez dans du sucre bleu ou des vermicelles bleues.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Laissez sécher.", "step_number": 2}]', 'https://img.spoonacular.com/recipes/655019-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.812729', '2026-01-19 18:23:17.812729', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '655019');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('256c7e99-44df-4ac0-af1a-0ef32735dfaa', 'Dessert sans problème : Poires au four avec crumble d’avoine', 'Dessert sans problème : Les poires cuites au four avec un crumble d’avoine nécessitent environ 45 minutes du début à la fin. Une portion contient 254 calories, 4g de protéines et 7g de matières grasses. Cette recette en fait 4. Pour 59 cents la portion, cette recette couvre 7 % de vos besoins quotidiens en vitamines et minéraux. Cette recette de Foodista nécessite du beurre, du gruau, du sucre cassoné et de la farine. Quelques personnes ont fait cette recette, et treize dis-le qu’elle a été juste. C’est une bonne option si vous suivez un régime lacto-ovo-végétarien. Ça marche bien comme dessert. Dans l’ensemble, cette recette obtient un score cuillère pas si spectaculaire de 26 %. Si vous aimez cette recette, vous pourriez aussi aimer des recettes comme le dessert aux poires au four, les barres de crumble aux prunes et au gruau | Desserts sans œufs, et dessert à la banane crumble cuite au four individuel.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Préchauffez votre four à 400 degrés F.", "step_number": 1}, {"duration": null, "equipment": ["bol"], "ingredients": ["sucre brun", "cannelle", "farine d''avoine", "farine de tous usages"], "instruction": "Dans un petit bol, mélangez le gruau, le sucre brun, la farine et la cannelle.", "step_number": 2}, {"duration": null, "equipment": ["boîte à cuisson"], "ingredients": ["poire"], "instruction": "Placez les poires coupées en deux dans un plat de cuisson.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["farine d''avoine", "poire"], "instruction": "Versez le mélange de gruau sur le dessus de chaque moitié de poire et tapotez pour former un petit tas.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["beurre", "poire"], "instruction": "Ponctuez chaque moitié de poire avec les morceaux de beurre.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 15}, "equipment": ["four"], "ingredients": ["poire"], "instruction": "Faites cuire à découvert pendant environ 15 minutes. Mettez le four au gril pour permettre à la garniture de dorer, juste pendant environ 30 secondes. Surveillez attentivement les poires à ce stade pour qu’elles ne brûlent pas.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": ["Glace à la vanille", "sauce caramel"], "instruction": "À servir avec une glace à la vanille, une sauce caramel ou nature.", "step_number": 7}]', 'https://img.spoonacular.com/recipes/641445-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.827498', '2026-01-19 18:23:17.827498', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '641445');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('1f50c06f-2fb4-41dd-aeab-3aab6696cd8f', 'Rhubarbe - Confiture de fraises', 'Rhubarbe - La confiture de fraises est un condiment qui peut servir 4 personnes. Pour 1,32 $ la portion, cette recette couvre 5 % de vos besoins quotidiens en vitamines et minéraux. Une portion de ce plat contient environ 2g de protéines, 1g de matières grasses et un total de 1355 calories. Cette recette est appréciée par un gourmet et des cuisiniers. C’est parfait pour la fête des mères. Si vous avez du sucre, des fraises, de la gelée à la fraise et quelques autres ingrédients à disposition, vous pouvez en préparer. Il est présenté par Foodista. C’est une bonne option si vous suivez un régime sans gluten, sans produits laitiers et compatible avec les FODMAP. De la préparation à l’assiette, cette recette prend environ 45 minutes. Tout bien considéré, nous avons décidé que cette recette mérite un score cuillère de 17 %. Ce score n’est pas si impressionnant. Confiture de fraise et rhubarbe, confiture de rhubarbe et fraise et confiture de rhubarbe sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["Rhubarbe", "sucre"], "instruction": "Mettez du sucre dans la rhubarbe et laissez reposer plusieurs heures ou toute la nuit.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 5}, "equipment": [], "ingredients": ["fraises"], "instruction": "Ajoutez les fraises et faites bouillir pendant 5 minutes.", "step_number": 2}, {"duration": null, "equipment": ["mélangeur"], "ingredients": [], "instruction": "Retirez du brûleur et ajoutez de la gelée. Remuez jusqu’à ce que ce soit dissous. Bats légèrement avec le batteur.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Versez dans des bocaux et scellez.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/658192-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.814378', '2026-01-19 18:23:17.814378', '{"vegan": false, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '658192');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('e995b5f9-c219-4bce-a6cb-7e9e23b4fa7a', 'Sorbet frais à la fraise', 'Le sorbet fraise frais est un dessert qui sert 1. Tu fais attention à ta silhouette ? Cette recette sans gluten, sans produits laitiers, lacto-ovo végétarien et compatible avec les FODMAP contient 991 calories, 8g de protéines et 4g de matières grasses par portion. Pour 12,58 $ la portion, cette recette couvre 30 % de vos besoins quotidiens en vitamines et minéraux. Une personne a trouvé cette recette délicieuse et satisfaisante. Rendez-vous au magasin et achetez du jus de citron, de l’eau, des fraises et quelques autres choses pour le préparer aujourd’hui. Ce sera un succès lors de votre événement de la fête des mères. De la préparation à l’assiette, cette recette prend environ 45 minutes. Il est présenté par Foodista. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 68 %, ce qui est plutôt bien. Si vous aimez cette recette, jetez un œil à ces recettes similaires : Sorbet fraise fraise, Sorbet fraise fraise avec biscuits sablés, et Sorbet à la mangue fraîche avec ananas.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["casserole"], "ingredients": ["sucre", "sirop", "eau"], "instruction": "Mélangez le sucre et l’eau dans une casserole à feu moyen-élevé, puis remuez jusqu’à ce que le sucre soit dissous. Juste avant que le sirop ne brûle, retirez du feu.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Cool et détendu.", "step_number": 2}, {"duration": null, "equipment": ["machine à crème glacée"], "ingredients": ["glace", "sirop"], "instruction": "Ajoutez du sirop aux ingrédients restants et mixez bien. Terminez dans une machine à glace ou au congélateur.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["Sauce fraise", "framboises"], "instruction": "Servir avec une sauce framboise-fraise.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/643613-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.81607', '2026-01-19 18:23:17.81607', '{"vegan": true, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '643613');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('0a2a7a62-abc4-4724-b046-35917913544f', 'Avocat Sweet Lassi - Comment faire un Avocado Lassi - Avocat indien', 'Avocat Sweet Lassi - Comment préparer un avocat lassi - L’avocat indien est une boisson végétarienne lacto-ovo sans gluten. Une portion de ce plat contient environ 2g de protéines, 5g de matières grasses et un total de 81 calories. Cette recette en fait 6. Pour 48 cents la portion, cette recette couvre 3 % de vos besoins quotidiens en vitamines et minéraux. De la préparation à l’assiette, cette recette prend environ 5 minutes. C’est une recette bon marché pour les amateurs de cuisine indienne. Une personne a essayé et aimé cette recette. Il vous est présenté par thecuisine.blogspot.com. Va au magasin et prends de l’avocat, du yaourt, 0,5 tasse d’eau, et quelques autres choses pour le préparer aujourd’hui. Tout bien considéré, nous avons décidé que cette recette mérite un score cuillère de 0 %. Ce score est très mauvais (mais toujours réparable). Des recettes similaires incluent le lassi, le doux lassi punjabi | Comment faire du lassi, du masala lassi, comment faire du masala lassi | douce lassi, et mangue lassi ou Aam ki Lassi, comment faire mangue lassi.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 5, '[{"duration": null, "equipment": ["mélangeur"], "ingredients": ["Poudre de cardamome", "avocat", "yaourt", "sucre"], "instruction": "Prenez l’avocat, le yaourt, la poudre de cardamome et le sucre dans un blender et mélangez jusqu’à ce que ce soit crémeux.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["eau"], "instruction": "Ajoutez de l’eau et mélangez jusqu’à ce que ce soit bien combiné.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["eau"], "instruction": "Si vous voulez une consistance fluide, ajustez la quantité d’eau.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["Glaçons"], "instruction": "Versez-le dans des verres et ajoutez des glaçons.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servir réfrigéré.", "step_number": 5}]', 'https://img.spoonacular.com/recipes/1681409-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.817389', '2026-01-19 18:23:17.817389', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '1681409');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('6e75c959-80ca-42c4-b90e-373f070193e5', 'Panini/sandwiches avocat tomate et mozzarella', 'Panini/sandwiches avocat tomate et mozzarella est un plat principal qui peut servir 4 personnes. Une portion de ce plat contient environ 18 g de protéines, 18 g de matières grasses et un total de 506 calories. Pour 1,73 $ la portion, cette recette couvre 21 % de vos besoins quotidiens en vitamines et minéraux. Trois personnes étaient ravies d’avoir essayé cette recette. C’est une bonne option si vous suivez un régime lacto-ovo-végétarien. Il est présenté par Foodista. De la préparation à l’assiette, cette recette prend environ 45 minutes. Un mélange d’avocat, de pain, de tomate et d’une poignée d’autres ingrédients suffit pour rendre cette recette aussi savoureuse. Dans l’ensemble, cette recette obtient un solide score cuillère de 61 %. Si vous aimez cette recette, jetez un œil à ces recettes similaires : Panini avocat tomate et mozzarella, Paninis mozzarella et dinde, et Panini tomate, mozzarella et basilic.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["Tranches d’avocat", "mozzarella", "tomate", "pain"], "instruction": "Ajoute une couche de mozzarella, de tomate, d’avocat et une autre couche de mozzarella.", "step_number": 1}, {"duration": null, "equipment": ["grille"], "ingredients": ["beurre", "fromage", "étendue", "pain"], "instruction": "Étalez un peu de beurre sur les deux côtés des sandwiches et grillez jusqu’à ce que le pain soit grillé et que le fromage soit fondu.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servez chaud et bon appétit !", "step_number": 3}]', 'https://img.spoonacular.com/recipes/633167-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.819218', '2026-01-19 18:23:17.819218', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '633167');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('2f023b63-9577-4fb9-9b4c-441d62f27df6', 'Panini avocat tomate et mozzarella', 'La recette Panini Avocat, Tomate et Mozzarella peut être préparée en environ 45 minutes. Une portion contient 506 calories, 18 g de protéines et 18 g de matières grasses. Pour 1,73 $ la portion, cette recette couvre 21 % de vos besoins quotidiens en vitamines et minéraux. Cette recette en fait 4. Cela fonctionne bien comme plat principal abordable. Cette recette est appréciée par un gourmet et des cuisiniers. Il est présenté par Foodista. Un mélange de beurre, de tomates, de mozzarella et d’une poignée d’autres ingrédients suffisent pour rendre cette recette aussi délicieuse. C’est une bonne option si vous suivez un régime lacto-ovo-végétarien. Dans l’ensemble, cette recette obtient un solide score cuillère de 57 %. Les utilisateurs qui ont aimé cette recette ont également apprécié les paninis à l’avocat tomate et mozzarella, les paninis à la tapenade, à la mozzarella et à la tomate, ainsi qu’aux paninis à la tomate rôtie et mozzarella.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["Tranches d’avocat", "mozzarella", "tomate", "pain"], "instruction": "Ajoute une couche de mozzarella, de tomate, d’avocat et une autre couche de mozzarella.", "step_number": 1}, {"duration": null, "equipment": ["grille"], "ingredients": ["beurre", "fromage", "étendue", "pain"], "instruction": "Étalez un peu de beurre sur les deux côtés des sandwiches et grillez jusqu’à ce que le pain soit grillé et que le fromage soit fondu.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servez chaud et bon appétit !", "step_number": 3}]', 'https://img.spoonacular.com/recipes/633165-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.820565', '2026-01-19 18:23:17.820565', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '633165');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('35c82569-865d-44f1-add0-615b61175c4f', 'Pudding banane-chocolat', 'Le pudding banane-chocolat prend environ 45 minutes du début à la fin. Tu fais attention à ta silhouette ? Cette recette sans gluten, sans produits laitiers, lacto-ovo végétarien et vegan contient 526 calories, 15 g de protéines et 34 g de matières grasses par portion. Pour 1,02 $ la portion, cette recette couvre 24 % de vos besoins quotidiens en vitamines et minéraux. Cette recette en fait 3. Cette recette de Foodista a 1 fan. Rendez-vous au magasin et achetez de l’avocat, des bananes, de la poudre de cacao et quelques autres choses pour le préparer aujourd’hui. Tout bien considéré, nous avons décidé que cette recette méritait un score cuillère de 88 %. Cette partition est géniale. Des recettes similaires sont le Pudding à la banane au chocolat, le Pudding à la banane au chocolat et le Pudding à la banane au chocolat.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["processeur alimentaire"], "ingredients": ["avocat", "banane"], "instruction": "Dans un robot culinaire, réduisez en purée des bananes et de l’avocat.", "step_number": 1}, {"duration": null, "equipment": ["bol"], "ingredients": ["beurre de cacahuète", "Poudre de cacao"], "instruction": "Ajoutez la poudre de cacao et le beurre de cacahuète... Réduire en purée jusqu’à ce que ce soit mélangé. Servez-le dans un bol ou un plat individuel. Détendez-vous et PROFITEZ-EN !!", "step_number": 2}]', 'https://img.spoonacular.com/recipes/634048-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.82196', '2026-01-19 18:23:17.82196', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '634048');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('07b57b6a-9559-4261-b22e-273055986bc4', 'Le guacamole de Jamie', 'La recette Jamie’s Guacamole est prête en environ 45 minutes et est sans aucun doute une excellente option végétarienne sans gluten, sans produits laitiers, paléolithique et lacto ovo pour les amateurs de cuisine mexicaine. Cette recette en fait 4 et coûte 44 cents la portion. Ce plat d’œuvre contient 87 calories, 1 g de protéines et 7 g de matières grasses par portion. Rendez-vous au magasin et achetez du sel et du poivre, du citron vert, de la tomate roma, et quelques autres choses pour la préparer aujourd’hui. Une personne a essayé et aimé cette recette. Il est présenté par Foodista. Tout bien considéré, nous avons décidé que cette recette mérite un score cuillère de 57 %. Cette partition est solide. Des recettes similaires sont le guacamole, comment faire du guacamole | guacamole mexicain, plantain vert frit avec guacamole et crevettes (Tostada de Plátano con Camarones y Guacamole), et Tostada de Plátano con Camarones y Guacamole (Tostada de Plátano con Camarones y Guacamole).', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["Écraseur de pommes de terre", "bol mélangeur", "couteau"], "ingredients": ["Moitiés d’avocat", "avocat", "pomme de terre", "tomate", "oignon"], "instruction": "Coupez l’avocat dans le sens de la coupe autour des graines. Sépare les deux côtés. Avec votre couteau, frappez la graine avec la lame et retirez la graine. Évidez les deux moitiés d’avocat avec une cuillère et placez-les dans un petit saladier. Avec un écraseur de pommes de terre ou une fourchette, écrasez l’avocat. Coupez l’oignon et la tomate en dés à votre goût. (Je les aime coupés très finement.)", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["avocat", "citron vert"], "instruction": "Mélangez à l’avocat. Pressez le citron vert pour obtenir le mélange.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 10}, "equipment": [], "ingredients": ["sel et poivre"], "instruction": "Ajoutez du sel et du poivre selon votre goût. Pour de meilleurs résultats, laissez reposer 10 minutes avant de servir.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["chips de tortilla"], "instruction": "Servez avec des chips de tortilla.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/648439-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.823045', '2026-01-19 18:23:17.823045', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '648439');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('1bee7000-d13c-4aa0-bf5d-03edcba98563', 'Votre petit-déjeuner basique pauvre en glucides', 'La recette « Votre petit-déjeuner basique faible en glucides » peut être préparée en environ 7 minutes. Ce petit-déjeuner contient 510 calories, 21g de protéines et 42g de matières grasses par portion. Cette recette en fait 1 et coûte 2,5 $ la portion. Si vous avez des fraises, du bacon signature Kirkland, de l’avocat et quelques autres ingrédients à portée de main, vous pouvez le préparer. Il est proposé par un utilisateur cuillère supersimplelowcarb. C’est une bonne option si vous suivez un régime sans gluten, sans produits laitiers, paléolithique et primal. Si vous aimez cette recette, vous pourriez aussi apprécier des recettes comme les muffins aux œufs méditerranéens au jambon {pauvre en glucides, faible en matières grasses, riche en protéines, faible en calories & sans gluten}, les muffins aux œufs méditerranéens au jambon {faible en glucides, faible en graisses, riche en protéines, faible en calories & sans gluten}, et les muffins méditerraneans au petit-déjeuner avec jambon {faible en glucides, faible en matières grasses, riche en protéines, faible en calories & sans gluten}.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 7, '[{"duration": null, "equipment": ["micro-ondes"], "ingredients": ["Bacon cuit", "œuf"], "instruction": "Faites cuire 2 œufs selon le style de votre goût. Faites passer au micro-ondes 2 tranches de bacon Kirkland Signature Full-Cut, jusqu’à ce que vous ayez le niveau de croustillance souhaité.", "step_number": 1}, {"duration": null, "equipment": ["tasse de mesure"], "ingredients": ["fraises", "avocat"], "instruction": "Coupez l’avocat en deux et retirez l’intérieur Coupez les fraises dans une demi-tasse doseuse Bon appétit !", "step_number": 2}]', 'https://img.spoonacular.com/recipes/1747693-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.824393', '2026-01-19 18:23:17.824393', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '1747693');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('f29734f3-87e3-4971-bdfe-8cb50730e643', 'Truffes au chocolat à l’avocat', 'Vous avez besoin d’un accompagnement sans gluten, sans produits laitiers, lacto ovo végétarien et végane ? Les truffes au chocolat à l’avocat pourraient être une recette incroyable à essayer. Cette recette en sert 12. Pour 37 cents la portion, cette recette couvre 3 % de vos besoins quotidiens en vitamines et minéraux. Une portion contient 80 calories, 1 g de protéines et 6 g de matières grasses. Cette recette de l’utilisateur cuillère mlubbe nécessite du chocolat, de la poudre de cacao, du cassonade et de l’essence de vanillane. De la préparation à l’assiette, cette recette prend environ 40 minutes. Des recettes similaires sont les Truffes au chocolat et avocat, les Truffes au chocolat et les Truffes au chocolat et avocat à deux ingrédients.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 40, '[{"duration": {"unit": "minutes", "number": 30}, "equipment": [], "ingredients": [], "instruction": "Note : il faut 30 minutes au réfrigérateur.", "step_number": 1}, {"duration": null, "equipment": ["Double chaudrie"], "ingredients": ["chocolat", "eau"], "instruction": "Faites bouillir une bouilloire d’eau pour faire fondre le chocolat à la marie-marie.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["avocat"], "instruction": "Mélangez l’avocat pour obtenir une consistance lisse.", "step_number": 3}, {"duration": null, "equipment": ["bol"], "ingredients": ["Farine d’amande", "noix de coco", "Poudre de cacao"], "instruction": "ENROBAGE : Préparez les ingrédients de l’enrobage dans un bol (cacao cru, noix de coco desséchée ou amandes moulues).", "step_number": 4}, {"duration": null, "equipment": ["papier cire"], "ingredients": [], "instruction": "Découpez du papier ciré pour le faire tenir dans un plateau ou une assiette.", "step_number": 5}, {"duration": null, "equipment": ["Double chaudrie"], "ingredients": ["chocolat"], "instruction": "CUISINIER : Casser le chocolat en plus petits morceaux et le faire fondre à la marie marie à feu doux.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": ["Vanilla artificielle", "sel"], "instruction": "Ajoutez l’essence de sel et de vanille.", "step_number": 7}, {"duration": null, "equipment": [], "ingredients": ["chocolat"], "instruction": "Retirez du feu une fois que le chocolat a fondu.", "step_number": 8}, {"duration": null, "equipment": ["mélangeur"], "ingredients": ["Poudre de cacao", "chocolat", "avocat"], "instruction": "Ajoutez le chocolat et la poudre de cacao au blender avec l’avocat.", "step_number": 9}, {"duration": null, "equipment": [], "ingredients": ["sucre brun"], "instruction": "Ajoutez du sucre cassona, selon votre goût.", "step_number": 10}, {"duration": null, "equipment": [], "ingredients": ["chocolat", "avocat"], "instruction": "Mélangez ou mélangez le mélange chocolat-avocat jusqu’à obtenir une consistance lisse, épaisse et ressemblant à un pudding.", "step_number": 11}, {"duration": {"unit": "minutes", "number": 30}, "equipment": ["processeur alimentaire", "bol"], "ingredients": [], "instruction": "Transférez le bol du robot culinaire au réfrigérateur pendant environ 30 minutes.", "step_number": 12}, {"duration": {"unit": "minutes", "number": 40}, "equipment": [], "ingredients": ["chocolat", "rouleau"], "instruction": "Après 30 minutes, vérifiez la consistance – si c’est encore trop mou pour être manipulé, mettez-le au réfrigérateur pendant encore 5 à 10 minutes. Quand c’est assez solide pour être manipulé, prenez un peu de chocolat durci avec une cuillère à café et roulez-le dans vos mains en une boule lisse.", "step_number": 13}, {"duration": null, "equipment": [], "ingredients": ["rouleau"], "instruction": "Transférez la bille sur le revêtement et roulez-la jusqu’à ce qu’elle soit complètement couverte.", "step_number": 14}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Placez la boule couverte sur un plateau ou une assiette.", "step_number": 15}, {"duration": null, "equipment": [], "ingredients": ["Truffes au chocolat"], "instruction": "Remettez les truffes au chocolat au réfrigérateur et gardez-les au frais jusqu’à ce qu’elles soient servies.", "step_number": 16}]', 'https://img.spoonacular.com/recipes/1697397-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.825936', '2026-01-19 18:23:17.825936', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '1697397');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('9b3da480-83fc-412f-96de-7b292d47d8b0', 'Oh Cocktail de Poire', 'Vous avez besoin d’une boisson sans produits laitiers ? Oh, le cocktail de poire pourrait être une recette exceptionnelle à essayer. Cette recette sert 1. Une portion contient 265 calories, 0g de protéines et 0g de matières grasses. Pour 4,82 $ la portion, cette recette couvre 1 % de vos besoins quotidiens en vitamines et minéraux. Trois personnes ont trouvé cette recette délicieuse et satisfaisante. Cette recette de Foodista nécessite une purée de poire bartlett usa, de drambuie, de glace et de liqueur de poire. De la préparation à l’assiette, cette recette prend environ 45 minutes. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 7 %, ce qui est améliorable. Si cette recette vous plaît, jetez un œil à ces recettes similaires : Cocktail de poire pétillante, Cocktail de poire et vodka, et Cocktail Poire et Canneberge.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["cocktail", "agiter", "glace"], "instruction": "Versez les ingrédients dans le shaker et remplissez de glace. Secouez bien pendant 30 secondes puis filtrez dans un verre à cocktail bien frais.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["Bartlett Pear"], "instruction": "Garnissez avec un quartier de poire Bartlett Red des États-Unis.", "step_number": 2}]', 'https://img.spoonacular.com/recipes/653521-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.829613', '2026-01-19 18:23:17.829613', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '653521');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('3a2b23aa-fe94-41ba-8b68-ca69d51e6ab9', 'Poire au gingembre au four', 'Si vous avez environ 45 minutes à passer en cuisine, la poire au gingembre au four pourrait être une recette végétarienne très sans gluten, sans produits laitiers, paléolithique et lacto ovo à essayer. Pour 1,32 $ la portion, cette recette couvre 6 % de vos besoins quotidiens en vitamines et minéraux. Cet accompagnement contient 255 calories, 1 g de protéines et 10 g de matières grasses par portion. Cette recette en fait 2. Un mélange de jus de citron, de miel, d’huile de coco et d’une poignée d’autres ingrédients suffit pour rendre cette recette aussi savoureuse. Une personne était contente d’avoir essayé cette recette. Il est présenté par Foodista. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 27 %, ce qui est plutôt mauvais. Gingembre pomme, poire, gruau croustillant, burger de dinde au gingembre et poire, tartinée au yaourt à la poire, et sauce poire au gingembre et cardamome (et beurre de poire) sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Préchauffe le four à 400°F (200°C).", "step_number": 1}, {"duration": null, "equipment": ["bol"], "ingredients": ["Poudre de gingembre", "Huile de coco", "jus de citron", "miel"], "instruction": "Mélangez le miel, l’huile de coco, la poudre de gingembre et le jus de citron dans un petit bol.", "step_number": 2}, {"duration": null, "equipment": ["boîte à cuisson"], "ingredients": ["poire"], "instruction": "Épluchez les poires et assurez-vous qu’elles peuvent se tenir seules sur une plaque de cuisson. Sinon, coupez une tranche au fond de la poire pour la rendre plate et qu’elle puisse tenir debout.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["poire"], "instruction": "Utilisez vos mains (ou une cuillère ou un pinceau) pour recouvrir les poires avec le mélange. Il suffit d’utiliser une très petite quantité de mélange pour recouvrir les poires (environ un quart du mélange).", "step_number": 4}, {"duration": {"unit": "minutes", "number": 60}, "equipment": ["feuille d''aluminium", "boîte à cuisson", "four"], "ingredients": ["poire"], "instruction": "Placez un papier aluminium sur une plaque de cuisson, posez les poires sur la plaque et faites cuire pendant une heure.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 75}, "equipment": ["four"], "ingredients": ["poire"], "instruction": "Après 15 minutes, utilisez une cuillère pour verser un peu plus de mélange sur chaque poire. Après 30 minutes au four, versez un peu plus de mélange sur chaque poire. Continuez à cuire pendant les 30 dernières minutes jusqu’à ce que la poire soit assez tendre (vous devriez pouvoir la couper à la cuillère).", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Gardez le reste du mélange pour servir.", "step_number": 7}]', 'https://img.spoonacular.com/recipes/1095690-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.832175', '2026-01-19 18:23:17.832175', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '1095690');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('15c10490-95ec-4fdc-9ba1-d706a0c11efd', 'Poires glaçues', 'Les poires glacées pourraient être exactement la recette sans gluten ni sans produits laitiers que vous cherchaiez. Pour 72 cents la portion, vous obtenez un accompagnement qui peut servir 4 personnes. Une portion de ce plat contient environ 1 g de protéines, 9 g de matières grasses et un total de 317 calories. Une personne a essayé et aimé cette recette. Rendez-vous au magasin et achetez du jus de citron, des poires Bartlett, du sucre et quelques autres choses pour le préparer aujourd’hui. Il est présenté par Foodista. De la préparation à l’assiette, cette recette prend environ 45 minutes. Tout bien considéré, nous avons décidé que cette recette méritait un score cuillère de 12 %. Cette partition n’est pas si spectaculaire. Si vous aimez cette recette, jetez un œil à ces recettes similaires : poulet glacé à l’orange avec poires, rôti de porc glacé avec carottes, panais et poires, et poulet glacé à l’érable avec oignons et poires caramélisés.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["pêche"], "instruction": "Pare, trogne et la moitié des pêches ; coupe chaque moitié en tiers dans le sens de la longueur.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 1}, "equipment": ["poêle à frire"], "ingredients": ["jus de citron", "beurre", "gelée", "poire", "sucre"], "instruction": "Chauffez du beurre dans une poêle à beavon ; Ajoutez les poires et faites cuire environ 1 à 2 minutes, en tournant une fois, jusqu’à ce que les tranches soient dorées et presque tendres. (Couvre en cuisinant.)Découvrir ; Mélangez du sucre, du jus de citron et de la confiture.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 5}, "equipment": [], "ingredients": ["poire", "sauce"], "instruction": "Chauffez doucement, en servant la sauce sur les poires. Faites cuire jusqu’à ce qu’elles soient tendres et glacées, environ 5 minutes.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["Gelée de pomme", "cannelle"], "instruction": "Servez chaud avec une garniture. Note : Si vous ne trouvez pas de gelée de pomme parfumée à la cannelle, utilisez de la gelée de pomme classique et ajoutez de la cannelle à votre goût.", "step_number": 4}]', 'https://img.spoonacular.com/recipes/644757-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.834411', '2026-01-19 18:23:17.834411', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '644757');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('22b15111-6343-4e0c-8221-d92233197f10', 'Poires rôties à l’érable et patates douces', 'Les poires rôties d’érable et patates douces sont un accompagnement qui peut servir 6 personnes. Une portion de ce plat contient environ 3 g de protéines, 12 g de matières grasses et un total de 443 calories. Pour 2,48 $ la portion, cette recette couvre 17 % de vos besoins quotidiens en vitamines et minéraux. Rendez-vous au magasin et achetez des poires anjou, du beurre, du sel casher et quelques autres choses pour le préparer aujourd’hui. Une personne a trouvé cette recette délicieuse et satisfaisante. Il est présenté par Foodista. De la préparation à l’assiette, cette recette prend environ 45 minutes. C’est une bonne option si vous suivez un régime sans gluten ni produits laitiers. Avec un score cuillère de 46 %, ce plat est très bon. Des recettes similaires incluent le poulet rôti avec patates douces et poires, les filets de porc rôti avec patates douces et poires, et les patates douces rôties à l’érable.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["feuille d''aluminium", "bol", "four", "poêle à frire", "pot"], "ingredients": ["patate douce", "margarine", "beurre", "gelée", "poire", "rouleau"], "instruction": "Préchauffe le four à 325°F. Pour un nettoyage facile, couvrez complètement un moule à gel avec du papier aluminium. Mets de côté. Pendant que vous coupez les poires et la patate douce, mettez-les dans un grand bol. Mets de côté. Dans une marmite moyenne, faites fondre le beurre ou la margarine à feu moyen.", "step_number": 1}, {"duration": null, "equipment": ["fouet"], "ingredients": ["sirop d''érable", "sel"], "instruction": "Fouetter dans le sirop d’érable et le sel. Faites cuire jusqu’à ce que ça commence à bouillonner.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Retirer du feu.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["patate douce", "poire"], "instruction": "Verse sur les poires et les patates douces. Jette pour le manteau.", "step_number": 4}, {"duration": null, "equipment": ["poêle à frire"], "ingredients": [], "instruction": "Transfert dans une poêle préparée", "step_number": 5}, {"duration": {"unit": "minutes", "number": 120}, "equipment": ["four"], "ingredients": [], "instruction": "Faites cuire à découvert pendant 1 heure et demie.", "step_number": 6}, {"duration": null, "equipment": ["bol"], "ingredients": [], "instruction": "Transférez dans un bol ou un plateau de service.", "step_number": 7}]', 'https://img.spoonacular.com/recipes/650919-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.836624', '2026-01-19 18:23:17.836624', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '650919');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('3b07fb43-8b4b-4722-8937-530f46372af6', 'Toasts à la poire grillée et prosciutto', 'La recette de poire grillée et prosciutto peut être préparée en environ 45 minutes. Une portion de ce plat contient environ 6 g de protéines, 21 g de matières grasses et un total de 261 calories. Pour 99 cents la portion, cette recette couvre 4 % de vos besoins quotidiens en vitamines et minéraux. Cette recette en fait 4. Rendez-vous au magasin et achetez de l’huile et du sel, de la poire, du fromage de chèvre crémeux et quelques autres choses pour le préparer aujourd’hui. Une personne a fait cette recette et la referait. Il est présenté par Foodista. Avec un score cuillère de 14 %, ce plat n’est pas si génial. Si vous aimez cette recette, vous pourriez aussi apprécier des recettes comme les toasts à la poire grillée et au prosciutto, les toasts à la poire grillée et au prosciutto, et les toasts à la ricotta-tomate grillés.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["poulet", "four"], "ingredients": [], "instruction": "Préchauffez le gril à haute température et placez la grille du four en position haute.", "step_number": 1}, {"duration": null, "equipment": ["plaque de cuisson"], "ingredients": ["poire"], "instruction": "Posez les tranches de poire sur une plaque de cuisson.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 4}, "equipment": [], "ingredients": ["poire", "sel", "huile de cuisson"], "instruction": "Badigeonnez-les d’huile des deux côtés et saupoudrez-les de sel. Faites griller les poires pendant 2 à 4 minutes — jusqu’à ce que les bords soient croustillants et la chair tendre.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["Muffin anglais", "fromage", "poire", "pain sandwich"], "instruction": "Étalez une cuillère à soupe de fromage moelleux et crémeux sur chaque moitié de muffin anglais. Une fois les poires tendres, déposez-en une sur chaque toast.", "step_number": 4}, {"duration": null, "equipment": ["plaque de cuisson"], "ingredients": ["prosciutto"], "instruction": "Placez les toasts sur la plaque de cuisson et garnissez chacun d’une tranche de prosciutto.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 4}, "equipment": [], "ingredients": ["prosciutto"], "instruction": "Grillez à nouveau pendant 2 à 4 minutes, jusqu’à ce que les bords du prosciutto et du muffin soient croustillants.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servez chaud !", "step_number": 7}]', 'https://img.spoonacular.com/recipes/636262-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.838356', '2026-01-19 18:23:17.838356', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '636262');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('ab2ee8bc-13f9-43f9-96eb-9bc1410c1769', 'Confiture aux myrtilles', 'La confiture de myrtilles prend environ 45 minutes du début à la fin. Cette recette en fait 1 et coûte 11,54 $ la portion. Une portion de ce plat contient environ 5 g de protéines, 12 g de matières grasses et un total de 9 760 calories. Une personne a trouvé cette recette délicieuse et satisfaisante. Il est présenté par Foodista. Seules quelques personnes ont vraiment aimé ce condiment. Rendez-vous au magasin et achetez des myrtilles, du beurre, du sucre et quelques autres choses pour le préparer dès aujourd’hui. C’est une bonne option si vous suivez un régime sans gluten, lacto-ovo végétarien et compatible avec les FODMAP. Avec un score cuillère de 52 %, ce plat est plutôt bon. Si vous aimez cette recette, vous pourriez aussi aimer des recettes comme les scones aux myrtilles avec confiture de myrtille et noix de coco, les donuts aux myrtilles avec confiture aux myrtilles et citron, et les muffins aux myrtilles avec confiture de myrtilles.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 10}, "equipment": ["pot"], "ingredients": ["baies", "eau"], "instruction": "Retirez les tiges et écrasez les baies avant de mesurer les 4 tasses. Faites bouillir les bocaux sur une grille dans une grande casserole remplie d’eau pendant 10 minutes.", "step_number": 1}, {"duration": null, "equipment": ["casserole"], "ingredients": ["eau"], "instruction": "Placez les couvercles plats dans une casserole avec de l’eau. Faites bouillir ; Retirer du feu.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["eau"], "instruction": "Laissez reposer dans de l’eau chaude jusqu’à ce qu’il soit prêt à se remplir.", "step_number": 3}, {"duration": null, "equipment": ["spatule", "bol", "pot"], "ingredients": ["myrtilles", "jus de citron", "sucre"], "instruction": "Égouttez bien. Dans une casserole de 8 litres, mélangez les myrtilles écrasées et le jus de citron. Mesurez le sucre dans un bol séparé. (Grattez le sucre supplémentaire de la tasse avec une spatule pour le niveler exactement.)", "step_number": 4}, {"duration": {"unit": "minutes", "number": 1}, "equipment": [], "ingredients": ["Pectine fruitée", "beurre", "fruits", "sucre"], "instruction": "Ajoutez la pectine et le beurre aux fruits. Portez le mélange à ébullition complète à feu vif, en remuant constamment. Ajoutez rapidement du sucre au mélange de fruits. Portez à ébullition à pleine vitesse et faites bouillir 1 minute, en remuant constamment.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 65}, "equipment": [], "ingredients": ["eau"], "instruction": "Retirez du feu. Écumez toute mousse. Remplissez rapidement tous les bocaux jusqu’à 1/8\" de dessus. Essuie les bords des bocaux. Couvrez rapidement avec des couvercles plats. Vissez bien les bandes. Inversez les bocaux pendant 5 minutes, puis montez droit. Après une heure, vérifiez les joints. Ou utilisez la méthode du bain-marie. Fait 5 tasses", "step_number": 6}]', 'https://img.spoonacular.com/recipes/635482-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.8413', '2026-01-19 18:23:17.8413', '{"vegan": false, "dairyFree": false, "lowFodmap": true, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '635482');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('fba16d7e-226f-448d-9fe8-d5a08e8cb866', 'Scones classiques', 'On n’a jamais trop de recettes européennes, alors essayez les scones classiques. Ce petit-déjeuner contient 398 calories, 9 g de protéines et 13 g de matières grasses par portion. Cette recette en fait 4 et coûte 51 cents la portion. 359 personnes étaient ravies d’avoir essayé cette recette. Il est présenté par Foodista. Rendez-vous au magasin et achetez du lait, de la farine auto-levée, de la confiture et de la crème de fraises, ainsi que quelques autres choses pour la préparer aujourd’hui. De la préparation à l’assiette, cette recette prend environ 45 minutes. C’est une bonne option si vous suivez un régime lacto-ovo-végétarien. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 41 %, ce qui est solide. Des recettes similaires sont les Classic Scones, les Classic Scones et les Classic Scones.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 15}, "equipment": ["papier à pâtisserie", "Couteau à beurre", "four", "spatule", "couteau", "bol"], "ingredients": ["fine chapelure", "beurre", "pâte", "farine de tous usages", "Base", "lait", "broyage sec"], "instruction": "Avec le bout des doigts, frottez du beurre dans la farine jusqu’à ce que le mélange ressemble à une fine chapelure. Faites un puits au centre des ingrédients secs et ajoutez le lait, en remuant avec une spatule en métal ou un couteau à beurre jusqu’à ce que le mélange se détache des parois du bol. Si le mélange est sec, ajoutez un peu plus de lait. Retournez le mélange sur un établi légèrement fariné et assemblez la pâte jusqu’à former une boule rugueuse. Ne pétrissez pas trop. Tapotez la pâte jusqu’à 2 cm d’épaisseur. Avec un couteau propre, coupez la pâte en quarts ou utilisez un coupe-coupe rond pour couper les ronds. Placez les scones sur une plaque tapissée de papier cuisson et laissez-les cuire à 220°C pendant 12-15 minutes jusqu’à ce qu’ils soient dorés et qu’ils sonnent creux lorsqu’on tapote légèrement la base.", "step_number": 1}, {"duration": null, "equipment": ["four"], "ingredients": ["crème", "confiture"], "instruction": "Servez des scones directement sortis du four avec de la confiture et de la crème.", "step_number": 2}]', 'https://img.spoonacular.com/recipes/639637-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.842896', '2026-01-19 18:23:17.842896', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '639637');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('cea48d42-f101-4eee-a84d-a99ec90a9d09', 'Confiture de aux myrtilles 5 minutes', 'La confiture de aux myrtilles en 5 minutes pourrait être une bonne recette pour enrichir votre boîte de condiments. Tu fais attention à ta silhouette ? Cette recette végétarienne sans gluten, sans produits laitiers, paléolithique et lacto ovo contient 81 calories, 1 g de protéines et 2 g de matières grasses par portion. Pour 76 cents la portion, cette recette couvre 5 % de vos besoins quotidiens en vitamines et minéraux. Cette recette en fait 4. Si vous avez de l’eau, des graines de, du miel/sirop d’érable, et quelques autres ingrédients à portée de main, vous pouvez le préparer. 35 personnes ont essayé et aimé cette recette. Il est présenté par Foodista. De la préparation à l’assiette, cette recette prend environ 45 minutes. Dans l’ensemble, cette recette obtient un score de cuillère pas très bon de 33 %. La confiture de graines de 10 minutes, la confiture de graines de à 10 minutes et la confiture de aux myrtilles sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["mélangeur"], "ingredients": ["eau"], "instruction": "Ajoutez tous les ingrédients dans votre blender avec assez d’eau pour qu’il puisse bien mélanger, puis mixez.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["confiture"], "instruction": "Versez la confiture dans un bocal en verre ou similaire. Conserver au frigo. Cela devrait durer environ 4 à 5 jours.", "step_number": 2}]', 'https://img.spoonacular.com/recipes/631880-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.844991', '2026-01-19 18:23:17.844991', '{"vegan": true, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '631880');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('11eea5ea-90d9-4962-bd6b-6f8f086bc7a6', 'Salade de fruits miel', 'La salade de fruits miel-dien est un ouvrage végétarien sans gluten, sans produits laitiers, paléolithique et lacto ovo. Pour 3,97 $ la portion, cette recette couvre 28 % de vos besoins quotidiens en vitamines et minéraux. Une portion contient 498 calories, 9g de protéines et 2g de matières grasses. Cette recette en fait 2. Trois personnes ont essayé et aimé cette recette. Un mélange de melon miell, pastèque, myrtilles et quelques autres ingrédients suffit pour rendre cette recette aussi délicieuse. De la préparation à l’assiette, cette recette prend environ 45 minutes. Il est présenté par Foodista. Tout bien considéré, nous avons décidé que cette recette méritait un score cuillère de 88 %. Cette partition est incroyable. Des recettes similaires sont la salade de fruits au miel, la salade de noix au miel et la salade au relish au miel.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["Melon miellé", "graines"], "instruction": "Prends le melon miel et coupe-le en deux. Gratter les graines.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["myrtilles", "pastèque", "Melon miellé"], "instruction": "Remplissez l’intérieur du miellat avec des tranches de pastèque et des myrtilles.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Servir avec une cuillère.", "step_number": 3}]', 'https://img.spoonacular.com/recipes/647333-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.846632', '2026-01-19 18:23:17.846632', '{"vegan": true, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '647333');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('fe96232f-8b4e-4406-a7a3-f193951d22e5', 'Flocons d’avoine coupés à l’acier de nuit', 'Le gruau coupé à l’acier pour la nuit pourrait être exactement le petit-déjeuner que vous recherchez. Une portion de ce plat contient environ 7 g de protéines, 6 g de matières grasses et un total de 189 calories. Cette recette sert 8 personnes et coûte 44 cents la portion. Trois personnes ont été impressionnées par cette recette. De la préparation à l’assiette, cette recette prend environ 45 minutes. Si vous avez de l’avoine coupée à l’acier, du beurre, des fruits et quelques autres ingrédients à portée de main, vous pouvez la préparer. Il est présenté par Foodista. C’est une bonne option si vous suivez un régime végétarien sans gluten et lacto ovo. Dans l’ensemble, cette recette obtient un score pas si super-cuillère de 12 %. Le gruau coupé à l’acier pour la nuit, le gruau coupé à l’acier pour la nuit et le gruau coupé à l’acier pour la nuit sont très similaires à cette recette.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 480}, "equipment": ["cuisinière lente"], "ingredients": ["épices", "lait"], "instruction": "Remuez tous les ingrédients ensemble dans une mijoteuse. Couvrez et faites cuire à basse température pendant 8 heures toute la nuit. Le matin, remuez bien et ajoutez du lait, des épices ou des garnitures supplémentaires selon votre préférence.", "step_number": 1}]', 'https://img.spoonacular.com/recipes/654274-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.848104', '2026-01-19 18:23:17.848104', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '654274');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('38be0b37-ea40-40e8-b34f-86c8b269fd13', 'Glaces glacées au yaourt aux baies', 'Si vous souhaitez ajouter plus de recettes sans gluten, sans produits laitiers, lacto ovo végétarienne et adaptées aux FODMAP à votre boîte de recettes, les glaces au yaourt aux baies glacées pourraient être une recette à essayer. Pour 63 cents la portion, cette recette couvre 3 % de vos besoins quotidiens en vitamines et minéraux. Une portion de ce plat contient environ 1 g de protéines, 2 g de matières grasses et un total de 64 calories. Cette recette en sert 10. Si vous avez du yaourt à la vanille, des framboises, des myrtilles et quelques autres ingrédients à portée de main, vous pouvez le préparer. Deux personnes ont fait cette recette et la referaient. Il est présenté par Foodista. De la préparation à l’assiette, cette recette prend environ 4 heures et 20 minutes. Avec un score cuillère de 28 %, ce plat est plutôt mauvais. Des recettes similaires sont les glaces au yaourt aux baies, les glaces au yaourt glacé framboise-érable, et les glaces au yaourt aux baies.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 260, '[{"duration": null, "equipment": ["processeur alimentaire", "Moules à glaces", "mélangeur"], "ingredients": ["Yaourt glacé à la vanille", "myrtilles", "framboises", "Yaourt glacé", "fruits"], "instruction": "Ajoutez le yaourt glacé à la vanille, 3 oz de framboises et 3 oz de myrtilles dans un robot culinaire ou un blender. Pulse environ 20 fois jusqu’à ce que le fruit soit brisé et que le mélange soit lisse. Versez 1 cuillère à soupe du mélange de yo-gaz congelé dans chacun de vos moules à popsicles. Mettez quelques myrtilles dans chaque moule.", "step_number": 1}, {"duration": {"unit": "minutes", "number": 240}, "equipment": [], "ingredients": ["myrtilles", "framboises", "Yaourt glacé", "eau"], "instruction": "Ajoutez une autre cuillère à soupe du mélange de yoyo-gaz congelé à chaque moule. Ajoutez maintenant quelques framboises. Ensuite, ajoutez une autre cuillère à soupe du mélange de yo-yos surgelé dans chaque moule et répétez avec les myrtilles, puis à nouveau avec les framboises (si vous avez de la place). Congelez les pops jusqu’à ce qu’ils soient solides, au moins 4 heures. Pour libérer les glaces, il suffit de faire passer les moules sous de l’eau très tiède pendant 10 à 15 secondes. Bouge et retire-toi ! Bonne lecture !", "step_number": 2}]', 'https://img.spoonacular.com/recipes/1098299-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.849372', '2026-01-19 18:23:17.849372', '{"vegan": false, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": true, "veryHealthy": false}', 'spoonacular', '1098299');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('1cf4d4c1-5c92-4adb-adc3-8ef89e037e45', 'Yorkshire Pudding', 'On n’a jamais trop de recettes d’accompagnement, alors essayez le Yorkshire Pudding. Cette recette en sert 12. Pour 32 cents la portion, cette recette couvre 4 % de vos besoins quotidiens en vitamines et minéraux. Une portion de ce plat contient environ 5 g de protéines, 2 g de matières grasses et un total de 74 calories. 11 personnes ont fait cette recette et la referaient. Rendez-vous au magasin et achetez des œufs, des perles de poêle de rôti de bœuf de préférence, du lait, et quelques autres choses pour le préparer aujourd’hui. De la préparation à l’assiette, cette recette prend environ 45 minutes. Il est présenté par Foodista. Avec un score cuillère de 22 %, ce plat est plutôt mauvais. Des recettes similaires incluent le Yorkshire Pudding, le Yorkshire Pudding et le Yorkshire Pudding.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["tamis", "bol", "four"], "ingredients": ["farine de tous usages", "œuf", "lait", "sel"], "instruction": "Préchauffez le four à 400-450°F selon votre four, une fois que vous aurez fait ces températures plusieurs fois, vous déterminerez la meilleure température. Passez la farine et le sel dans un tamis et mélangez, battez les œufs et le lait dans un bol séparé puis mélangez les deux", "step_number": 1}, {"duration": null, "equipment": ["Plateau à muffettes", "four"], "ingredients": ["cupcakes", "huile de cuisson"], "instruction": "Si vous ne dégoulinez pas dans votre plaque Yorkshire, un moule à muffins ou à cupcakes ferait probablement l’affaire aussi et mettez-la au four pour que l’huile chauffe bien. Sortez l’huile du four et versez quelques cuillères à soupe dans chaque section de votre moule.", "step_number": 2}, {"duration": {"unit": "minutes", "number": 20}, "equipment": ["four"], "ingredients": [], "instruction": "Remettez-le au four et laissez cuire environ 20 minutes. N’ouvrez pas le four une fois ajouté, c’est très important, si vous ne les laissez pas tranquilles, vous obtiendrez des puddings plats et en pâte.", "step_number": 3}]', 'https://img.spoonacular.com/recipes/665573-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.850119', '2026-01-19 18:23:17.850119', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '665573');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('56da1660-ea9c-4c44-aea5-d5402e4155be', 'Bière - Crevettes frites à la pâte', 'Bière - Les crevettes frites en pâte nécessitent environ 45 minutes du début à la fin. Cette recette sans gluten, sans produits laitiers, adaptée aux FODMAP et pescétarienne en fait 4 et coûte 4,16 $ la portion. Une portion contient 229 calories, 35 g de protéines et 4 g de matières grasses. Il est présenté par Foodista. C’est parfait pour la fête des pères. Ça fonctionne bien comme plat principal. Cette recette est appréciée par un gourmet et des cuisiniers. Un mélange de sauce tartare, d’huile, de crevettes et d’une poignée d’autres ingrédients suffit pour rendre cette recette aussi savoureuse. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 49 %, ce qui est plutôt bien. Si vous aimez cette recette, jetez un œil à ces recettes similaires : pâte à bière pour poisson frit, cornichons frits à la pâte à bière, et gombo frit à la pâte à bière.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": {"unit": "minutes", "number": 120}, "equipment": [], "ingredients": ["blancs d''œufs", "Base", "Bière"], "instruction": "Préparez la base de pâte à bière au moins 2 heures à l’avance. Avant d’utiliser, pliez le blanc d’œuf.", "step_number": 1}, {"duration": null, "equipment": ["poêle à frire", "wok"], "ingredients": ["huile de cuisson"], "instruction": "Chauffez l’huile dans une friteuse profonde, un wok ou une poêle à une température d’environ 350-360 degrés.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["crevettes", "huile de cuisson"], "instruction": "Ajoutez les crevettes à la pâte. Retirez une crevette à la fois de la pâte à l’aide des dents d’une fourchette à deux branches, puis ajoutez rapidement chaque crevette à l’huile. Les crevettes remonteront à la surface. Ne surchargez pas. Pendant la friture, prenez soin d’enlever et de jeter les morceaux de pâte dorés qui pourraient s’accumuler à cause des dégoulinants.", "step_number": 3}, {"duration": {"unit": "minutes", "number": 3}, "equipment": [], "ingredients": [], "instruction": "Laissez cuire une fournée, en remuant 2 ou 3 minutes jusqu’à ce qu’il soit doré et croustillant partout.", "step_number": 4}, {"duration": null, "equipment": ["serviettes en papier"], "ingredients": [], "instruction": "Égouttez les essuie-tout.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["Sauce tartare", "crevettes"], "instruction": "Servez chaud avec de la sauce tartare pour faire couler les frais. Donne 52 à 56 crevettes.", "step_number": 6}]', 'https://img.spoonacular.com/recipes/634726-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.852071', '2026-01-19 18:23:17.852071', '{"vegan": false, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '634726');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('84d33b8e-d7de-4ee7-bd18-6c5a6e3d808c', 'Yokshire Pudding', 'Le Yokshire Pudding nécessite environ 45 minutes du début à la fin. Cette recette contient 1 portion contenant 904 calories, 43 g de protéines et 32 g de matières grasses chacune. Pour 1,48 $ la portion, cette recette couvre 40 % de vos besoins quotidiens en vitamines et minéraux. Rendez-vous au magasin et achetez de la farine, du sel, des œufs et quelques autres choses pour le préparer aujourd’hui. Cette recette est appréciée par un gourmet et des cuisiniers. Il est présenté par Foodista. En tenant compte de tous les facteurs, cette recette obtient un score cuillère de 72 %, ce qui est solide. Des recettes similaires sont Pumpsy Ghostly Guzzle Pudding Shots - Mon Hommage aux Cups de Pudding d’Halloween, Pudding au chocolat sans œufs | Easy Pudding et pudding au pain caramel sans œufs, pudding au pain vapeur sans cuisson.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["cuillère en bois"], "ingredients": ["farine de tous usages", "sel", "œuf"], "instruction": "Mélangez la farine et le sel dans la bassine, faites un creux dans la centure et plongez dans l’œuf. Remuez avec une cuillère en bois et ajoutez le liquide progressivement, jusqu’à ce que toute la farine soit intégrée. Bats bien et ajoute le reste du liquide. Faites fondre la graisse dans une boîte peu profonde qui coule ou dans quatre petites boîtes.", "step_number": 1}, {"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Mettez-les au four jusqu’à ce que la brume apparaisse.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Versez la pâte dans le grand moule, ou remplissez à moitié les petits moules.", "step_number": 3}, {"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Cuire au four chaud (425/F à 450°F, gaz 7 à", "step_number": 4}, {"duration": {"unit": "minutes", "number": 20}, "equipment": [], "ingredients": [], "instruction": "Environ une demi-heure pour un grand pudding, 20 minutes pour les petits puddings.", "step_number": 5}, {"duration": null, "equipment": [], "ingredients": ["oignon"], "instruction": "Pour faire un pudding déferlent, vous pouvez ajouter des oignons hachés à la pâte ou les hurbs mixtes sont bien.", "step_number": 6}]', 'https://img.spoonacular.com/recipes/665574-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.85382', '2026-01-19 18:23:17.85382', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '665574');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('5a375984-a683-4caf-a775-1d88dc439689', 'Citrons farcis au four', 'Stuffed Lemons in the Four est un accompagnement sans gluten, sans produits laitiers, paléolithique et primitif. Cette recette en fait 4. Une portion de ce plat contient environ 1 g de protéines, 0 g de matières grasses et un total de 20 calories. Pour 41 cents la portion, cette recette couvre 3 % de vos besoins quotidiens en vitamines et minéraux. 20 personnes étaient ravies d’avoir essayé cette recette. Si vous avez du sel et du poivre, des feuilles de basilic, de l’anchois et quelques autres ingrédients sous la main, vous pouvez le préparer. De la préparation à l’assiette, cette recette prend environ 45 minutes. Il est présenté par Foodista. Globalement, cette recette obtient un bon score cuillère de 64 %. Les utilisateurs qui ont aimé cette recette ont également apprécié les citrons cuits au four, le poivre poblano farci au four, et les champignons farcis à la friteuse à air ou au four.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["four"], "ingredients": [], "instruction": "Préchauffez votre four à 400 °F / 215 °C", "step_number": 1}, {"duration": null, "equipment": ["bol"], "ingredients": ["citron"], "instruction": "Enlevez les extrémités des citrons et jetez-les (ne coupez pas trop profondément – il faut garder un fond fermé). Ensuite, coupez les citrons en deux en travers, obtenant de petits bols de citron.", "step_number": 2}, {"duration": null, "equipment": ["bol", "couteau"], "ingredients": ["peau de citron", "citron"], "instruction": "À l’aide d’un petit couteau, retirez la chair de citron, ne vous laissant que 4 bols creux de coulure de citron. (Encore une fois, il ne faut pas forcer la peau)", "step_number": 3}, {"duration": null, "equipment": ["bol"], "ingredients": ["Filets d’anchois", "Tomate cerise", "sel et poivre", "basilic frais", "mozzarella", "huile d''olive", "citron"], "instruction": "Coupez un morceau de mozzarella pour qu’il rentre à l’intérieur, puis posez une feuille de basilic, un demi-filet d’anchois et une demi-tomate cerise par-dessus, avec une pincée de sel et de poivre et un petit filet d’huile d’olive bonne. Mettez une autre tranche de mozzarella sur le dessus – le citron doit maintenant être rassasié. Faites de même avec les autres bols de citron.", "step_number": 4}, {"duration": {"unit": "minutes", "number": 15}, "equipment": ["plaque de cuisson", "four"], "ingredients": [], "instruction": "Placez sur une plaque de cuisson et faites cuire dans un four préchauffé pendant 10 à 15 minutes, jusqu’à ce qu’il dore et bouillonne.", "step_number": 5}, {"duration": null, "equipment": ["four"], "ingredients": ["mozzarella", "pain"], "instruction": "Sortez-le du four et servez immédiatement. Pour manger : sors la mozzarella et mange avec le pain pour absorber les jus !", "step_number": 6}]', 'https://img.spoonacular.com/recipes/662038-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.85579', '2026-01-19 18:23:17.85579', '{"vegan": false, "dairyFree": true, "lowFodmap": true, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '662038');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('2203a45d-c08e-49b1-9ddf-675a7c2104da', 'Sauce aux anchois et noix de Skye Gyngell', 'La sauce aux anchois et aux noix de Skye Gyngell pourrait être exactement le goût que vous cherchez. Cette recette en sert 4 et coûte 83 cents la portion. Une portion contient 58 calories, 2g de protéines et 5g de matières grasses. Une personne a essayé et aimé cette recette. Si vous avez des anchois, de l’ail, du persil à feuilles plates et quelques autres ingrédients à portée de main, vous pouvez le préparer. Il est présenté par Foodista. C’est une bonne option si vous suivez un régime sans gluten, sans produits laitiers, paléolithique et primal. De la préparation à l’assiette, cette recette prend environ 45 minutes. Dans l’ensemble, cette recette obtient un excellent score cuillère de 83 %. Les utilisateurs qui ont aimé cette recette ont également apprécié les pâtes à la sauce noix et anchois, les pâtes à l’anchois et aux noix, et les pâtes à la sauce anchois-noix.', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": ["Mortier et pilon"], "ingredients": ["légumes", "brocoli", "épinard", "Bette de Carde", "huile de cuisson"], "instruction": "Pilez tous les ingrédients sauf l’huile dans un pilon et un mortier jusqu’à ce que ce soit lisse, puis versez l’huile et remuez bien pour mélanger. Ajoutez une cuillère sur tout légume vert légèrement cuit, comme le brocoli, les épinards ou la bette à carde.", "step_number": 1}]', 'https://img.spoonacular.com/recipes/660237-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.857305', '2026-01-19 18:23:17.857305', '{"vegan": false, "dairyFree": true, "lowFodmap": false, "glutenFree": true, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '660237');
INSERT INTO public.recipe (id, title, summary, parent_id, author_id, preparation_minutes, step_by_step_instructions, image_url, status, created_at, updated_at, dietary_flag, source, external_id) VALUES ('c6ba5560-9df5-4670-b460-3b825bcf7dc4', 'Rouleau de Œufs Taco', 'Le Taco Egg Roll pourrait être exactement la recette chinoise que vous recherchez. Une portion contient 191 calories, 11g de protéines et 12g de matières grasses. Cette recette en fait 8 et coûte 67 cents la portion. Une personne a essayé et aimé cette recette. Cette recette de Foodista nécessite du bœuf haché, de l’assaisonnement pour tacos, des emballages de rouleaux de printemps et du fromage mexicain. Il fonctionne bien comme un ouvrage peu coûteux. De la préparation à l’assiette, cette recette prend environ 45 minutes. Dans l’ensemble, cette recette obtient un score de cuillère pas très bon de 29 %. Des recettes similaires incluent le sauté de rouleaux de œuf (aussi appelé rouleau de printemps dans un bol), le sauté de rouleaux de rouleaux de œuf (aussi appelé rouleau de œuf dans un bol), et le sauté de rouleaux de œuf (aussi appelé rouleau d’œuf dans un bol).', NULL, 'aa322657-2d6d-4e7b-a2fa-1a4cbe75178c', 45, '[{"duration": null, "equipment": [], "ingredients": ["boeuf haché"], "instruction": "Faites dorer et égoutter le bœuf haché.", "step_number": 1}, {"duration": null, "equipment": [], "ingredients": ["Mélange d’assaisonnement pour tacos"], "instruction": "Assaisonnez selon les instructions d’assaisonnement pour tacos.", "step_number": 2}, {"duration": null, "equipment": [], "ingredients": ["Fromage râpé", "viande"], "instruction": "Éteignez le feu et mélangez du fromage râpé avec de la viande à taco.", "step_number": 3}, {"duration": null, "equipment": [], "ingredients": ["Emballages de rouleaux de œufs"], "instruction": "Remplissez les emballages de rouleaux de œufs.", "step_number": 4}, {"duration": null, "equipment": [], "ingredients": ["huile d''olive", "rouleau", "œuf"], "instruction": "Badigeonnez les rouleaux d’œufs avec de l’huile d’olive.", "step_number": 5}, {"duration": {"unit": "minutes", "number": 23}, "equipment": ["four"], "ingredients": ["rouleau", "œuf"], "instruction": "Faites cuire à 375 pendant 15 minutes, en retournant les rouleaux de poule à 8 minutes.", "step_number": 6}, {"duration": null, "equipment": [], "ingredients": ["crème fraîche"], "instruction": "Servez-le chaud avec de la crème fraîche !", "step_number": 7}, {"duration": null, "equipment": [], "ingredients": [], "instruction": "Expérimentez avec ces choses !", "step_number": 8}, {"duration": null, "equipment": [], "ingredients": ["haricots frits", "poivrons", "riz"], "instruction": "Ajoutez des poivrons, du riz ou des haricots frits. Fais-les veux.", "step_number": 9}]', 'https://img.spoonacular.com/recipes/662744-556x370.jpg', 'PUBLISHED', '2026-01-19 18:23:17.858375', '2026-01-19 18:23:17.858375', '{"vegan": false, "dairyFree": false, "lowFodmap": false, "glutenFree": false, "vegetarian": false, "veryHealthy": false}', 'spoonacular', '662744');
